#  
#  LOGGING HELPER  (thread-safe, writes to file and a queue for the GUI)
#  

import queue as _queue
import threading as _threading

class PipelineLogger:
    """Thread-safe logger - writes to file + exposes a queue for the GUI."""

    def __init__(self, log_dir: Path):
        log_dir.mkdir(parents=True, exist_ok=True)
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        self.log_path = log_dir / f"pipeline_{ts}.log"
        self._q: _queue.Queue = _queue.Queue()
        self._lock = _threading.Lock()
        self._fh = open(self.log_path, "w", buffering=1, encoding="utf-8")

    # public API
    def info   (self, m): self._w("INFO",    m)
    def step   (self, m): self._w("STEP",    m)
    def warn   (self, m): self._w("WARN",    m)
    def error  (self, m): self._w("ERROR",   m)
    def success(self, m): self._w("SUCCESS", m)
    def __call__(self, m): self._w("INFO", str(m))   # drop-in for print()

    def _w(self, level, msg):
        ts   = datetime.now().strftime("%H:%M:%S")
        line = f"[{ts}] [{level:7s}]  {msg}"
        with self._lock:
            try:
                self._fh.write(line + "\n")
                self._fh.flush()
            except Exception:
                # File handle closed out from under a still-running background
                # thread (e.g. the GUI swapped self._logger to a new file
                # while this one's owning step was mid-run) used to make this
                # log line vanish with zero trace anywhere. Falling back to
                # stderr means a step's output is at worst hard to find, never
                # completely lost -- confirmed against a real run where an
                # entire 3D DLC Phase 3/4 (quad-video generation onward) left
                # no record at all of what happened for ~3 hours.
                try:
                    import sys as _sys
                    print(f"[PipelineLogger:closed-file-fallback] {line}",
                          file=_sys.stderr)
                except Exception:
                    pass
        self._q.put((level, msg, ts))

    def close(self):
        try: self._fh.close()
        except Exception: pass


#  
#  COLOUR HELPERS
