#  DLC PRE-PROCESSING  (from General_DLC_2_BSOID_DAMIEN_v5)
#  

BSOID_OUTPUT_ROOT   = "BSOID_Project_Ready"
BSOID_H5_SUBDIR     = "h5"
BSOID_CSV_SUBDIR    = "csv"
BSOID_VIDEO_SUBDIR  = "videos"
BSOID_ANALYSIS_SUBDIR = "output"
BSOID_SCORER_NAME   = "DLC_SuperAnimal"
MIN_BODYPART_CONFIDENCE = 0.35

#
#  UNIFIED PER-RUN OUTPUT ROOT  — "CUBE results <date>_<time>"
#
# See C:\Users\param\.claude\plans\modular-purring-raven.md for the full
# design. Lives here (not in cube.py) so cube_3d_dlc.py can use it too
# without a cube_3d_dlc.py -> cube.py import (this codebase's cross-module
# dependency direction is strictly cube.py -> {cube_core.py, cube_3d_dlc.py},
# cube_3d_dlc.py -> cube_core.py -- never the reverse). Session-agnostic by
# design (plain args, not a SessionState) matching this module's existing
# style (run_bsoid_prep, etc.) -- callers own reading/writing whatever
# session key persists the result.
#
# Step 0 (D:\3D DLC\bonsai_video_corrector.py) is a genuinely separate app
# with no shared SessionState -- it may create this same folder before
# cube.py/cube_3d_dlc.py ever run. The prefix/glob/timestamp format and the
# newest-wins matching rule below are kept byte-for-byte identical to that
# app's own _resolve_or_create_run_root() so the two converge on one folder
# regardless of which runs first.
#

CUBE_RUN_ROOT_PREFIX = "CUBE results"
CUBE_RUN_ROOT_GLOB = f"{CUBE_RUN_ROOT_PREFIX}*"
_RUN_ROOT_TS_FMT = "%Y-%m-%d_%H-%M-%S"


def find_existing_cube_run_root(source_folders, log_fn=None) -> "Path | None":
    """
    Scan source_folders (non-recursive) for an already-existing
    'CUBE results *' folder. Newest-by-embedded-timestamp wins on multiple
    matches (falls back to mtime if a candidate's suffix doesn't parse).
    Returns None if no candidate is found under any source folder.
    """
    candidates: list = []
    for sf in source_folders or []:
        p = Path(sf)
        if p.is_dir():
            candidates.extend(x for x in p.glob(CUBE_RUN_ROOT_GLOB) if x.is_dir())
    if not candidates:
        return None

    def _sort_key(p):
        suffix = p.name[len(CUBE_RUN_ROOT_PREFIX):].strip()
        try:
            return (0, datetime.strptime(suffix, _RUN_ROOT_TS_FMT))
        except ValueError:
            return (0, datetime.fromtimestamp(p.stat().st_mtime))

    candidates = sorted(set(candidates), key=_sort_key)
    chosen = candidates[-1]
    if len(candidates) > 1 and log_fn is not None:
        others = ", ".join(str(c) for c in candidates[:-1])
        log_fn(f"  [WARN] Multiple existing 'CUBE results *' roots found "
               f"under the source folder(s); using newest ({chosen}); "
               f"ignoring: {others}")
    return chosen


