def infer_skeleton(bps: list, logger=None) -> list:
    """
    Build skeleton connections from DLC-style body-part names. Falls back
    to sequential nearest-neighbour if names are not recognised.

    Identical logic to cube_3d_dlc.py's original _infer_skeleton() (now a
    thin wrapper calling this), extracted here so it's usable without a
    cube_core -> cube_3d_dlc import.
    """
    KNOWN_CHAINS = [
        ["nose", "neck", "spine1", "spine2", "spine3", "tailbase", "tail1", "tail2"],
        ["left_ear", "neck"],
        ["right_ear", "neck"],
        ["left_forelegroot", "left_foreleg1", "left_foreleg2", "left_foreleg3"],
        ["right_forelegroot", "right_foreleg1", "right_foreleg2", "right_foreleg3"],
        ["left_hindlegroot", "left_hindleg1", "left_hindleg2", "left_hindleg3"],
        ["right_hindlegroot", "right_hindleg1", "right_hindleg2", "right_hindleg3"],
        ["neck", "left_forelegroot"],
        ["neck", "right_forelegroot"],
        ["tailbase", "left_hindlegroot"],
        ["tailbase", "right_hindlegroot"],
    ]
    bp_set = set(b.lower() for b in bps)
    bp_map = {b.lower(): b for b in bps}

    edges = []
    for chain_set in (SUPERANIMAL_QUADRUPED_CHAINS, KNOWN_CHAINS):
        for chain in chain_set:
            present = [b for b in chain if b in bp_set]
            for a, b in zip(present, present[1:]):
                edges.append((bp_map[a], bp_map[b]))
        if edges:
            break

    if not edges:
        msg = (f"infer_skeleton: no known chain set matched {len(bps)} bodyparts "
               f"({', '.join(bps[:3])}...) — falling back to sequential list-order "
               "chain, which is anatomically meaningless")
        if logger is not None:
            logger.warn(msg)
        else:
            print(f"[WARN] {msg}")
        for a, b in zip(bps, bps[1:]):
            edges.append((a, b))

    return edges


def collapse_skeleton_graph(full_edges: list, keep_nodes: set) -> list:
    """
    Contract a skeleton graph down to `keep_nodes`, connecting two kept
    nodes with a direct edge whenever the only path between them in the
    original graph runs through excluded nodes (BFS from each kept node,
    expanding through excluded nodes only, stopping at the first kept node
    reached in each direction).

    Needed because SUPERANIMAL_QUADRUPED_CHAINS stores every anatomical
    link as its OWN separate 2-element entry (e.g. ["back_end",
    "back_left_thai"], ["back_left_thai", "back_left_knee"] are two
    independent entries, not one 3-element list) — so a naive
    `infer_skeleton(reduced_bps)` call does NOT actually collapse through
    a dropped intermediate joint the way its "present = [b for b in chain
    if b in bp_set]" logic suggests; each entry only ever contributes an
    edge when BOTH its exact endpoints survive. Confirmed on real data
    (2026-08-28, cube_3d_dlc.py's outline skeleton video): dropping
    `back_left_thai`/`back_right_thai` left `back_left_knee`/
    `back_right_knee` completely disconnected floating segments, still
    attached to their paw but severed from `back_end` — the naive
    per-entry approach silently produces a broken skeleton instead of the
    intended "collapse past the missing joint" behavior. This graph-BFS
    version works correctly for both this 2-element-pair schema and the
    multi-element sequential KNOWN_CHAINS (mouse/maDLC) schema, since both
    reduce to the same underlying graph-adjacency problem.

    Originally lived only in cube_3d_dlc.py (as `_collapse_skeleton_graph`,
    kept there as a thin re-export for backward compatibility); moved here
    2026-09-10 so `_compute_cluster_posture_data`'s cluster-trajectory
    plots can use the exact same correct collapse cube_3d_dlc.py's
    make_skeleton_video() already used — the trajectory plot's own
    `infer_skeleton(kept_bps)`-only construction had this identical bug,
    confirmed as the cause of a real "forelimb attachment looks off, one
    side barely visible" complaint on rendered panels.
    """
    from collections import defaultdict, deque
    adj = defaultdict(set)
    for a, b in full_edges:
        adj[a].add(b)
        adj[b].add(a)

    result = set()
    for start in keep_nodes:
        visited = {start}
        dq = deque(adj[start])
        visited.update(adj[start])
        while dq:
            node = dq.popleft()
            if node in keep_nodes:
                if node != start:
                    result.add(frozenset((start, node)))
                continue  # don't expand past a kept node
            for nxt in adj[node]:
                if nxt not in visited:
                    visited.add(nxt)
                    dq.append(nxt)
    return [tuple(e) for e in result]


def parse_doric_filename(path) -> "dict | None":
    """
    Parse a Doric/Bonsai Step-0-corrected video filename of the form
    ``{cam_label}_{session_id}_corrected.<ext>`` (produced by
    bonsai_video_corrector.py for both Bonsai- and Doric-sourced rigs,
    regardless of camera count).

    Returns ``{"cam_label": str, "session_id": str}``, or ``None`` if
    *path* does not match the convention (ordinary single-camera
    filenames, or a "calibration" session_id, both yield ``None``).

    Shared by cube_3d_dlc.py's find_step0_sessions() and Step 1a's
    multi-camera sidecar writer so both use identical parsing.
    """
    stem = Path(path).stem
    if not stem.endswith("_corrected"):
        return None
    stem = stem[: -len("_corrected")]
    parts = stem.split("_", 1)
    if len(parts) < 2:
        return None
    cam_label, session_id = parts[0], parts[1]
    if "calibration" in session_id.lower():
        return None
    return {"cam_label": cam_label, "session_id": session_id}


# ─────────────────────────────────────────────────────────────────────────────
#  Two/three-camera fusion — floor-plane homography (Phase 2, no fusion logic
#  yet; see TwoCam_Homography_BoneConstraint_Fusion_Plan.md §4/Phase 2)
# ─────────────────────────────────────────────────────────────────────────────

HOMOGRAPHY_CACHE_DIR = Path(__file__).resolve().parent / "homography_cache"


def fit_floor_homography(points_src, points_dst, method: int = 0,
                          ransac_reproj_threshold: float = 5.0) -> dict:
    """
    Fit a planar homography mapping pixel coordinates in one camera view
    (*points_src*) to the corresponding pixel coordinates of the SAME
    real-world floor-plane point in another camera view (*points_dst*).

    points_src, points_dst : sequences of (x, y) pixel coordinates, same
        length, each points_src[i]/points_dst[i] pair being one physical
        reference point clicked in both views (see plan §4 -- arena floor
        corners plus a wall/height point, across 3-5 frames).

    method, ransac_reproj_threshold : passed straight to cv2.findHomography.
        Default method=0 (plain DLT) is byte-identical to this function's
        original behavior -- correct for a manual-click session (a
        handful of human-verified points, no real outliers expected). The
        automatic pose-based estimator (estimate_homography_from_poses())
        passes cv2.RANSAC instead, since pooling hundreds of real DLC
        keypoint correspondences can include genuine outliers (e.g. a
        symmetric-bodypart ID swap) that manual clicks never have to
        contend with -- ransac_reproj_threshold is ignored by OpenCV when
        method=0.

    Returns a dict:
        {"H": 3x3 nested list (points_src -> points_dst),
         "H_inv": 3x3 nested list (points_dst -> points_src),
         "reproj_error_px": float,   # RMS reprojection error (see below)
         "max_error_px": float,      # worst reprojection error (see below)
         "n_points": int,            # total input point pairs (unchanged meaning)
         "n_inliers": int}           # points the quality metrics were computed over

    reproj_error_px/max_error_px are computed over RANSAC's own inlier mask
    when method != 0 (i.e. n_inliers <= n_points), not over every pooled
    point -- computing them over the full set (including points RANSAC
    itself already rejected as outliers) systematically overstates error
    and can even score a robust RANSAC fit as WORSE than an unconstrained
    plain-DLT fit, since a real, wide spread of legitimately-varying
    correspondence data (e.g. genuine perspective/parallax variation
    across an arena) gets scored as "outliers" against whatever tight
    local subset RANSAC's threshold accepted. Found via a real-data check
    against a genuinely difficult (orthogonal-camera) rig, where the old
    behavior made RANSAC score ~7x worse than plain DLT on the exact same
    data. method=0 (manual-click path) is unaffected -- cv2.findHomography
    returns an all-ones mask for that method, so n_inliers == n_points and
    behavior is byte-identical to before this fix.

    Raises ValueError if fewer than 4 point pairs are given, the two
    sequences have different lengths, or OpenCV fails to find a homography
    (e.g. degenerate/collinear points).
    """
    import cv2

    src = np.asarray(points_src, dtype=np.float64)
    dst = np.asarray(points_dst, dtype=np.float64)
    if src.shape != dst.shape or src.ndim != 2 or src.shape[1] != 2:
        raise ValueError(
            f"points_src and points_dst must be equal-length sequences of "
            f"(x, y) pairs; got shapes {src.shape} and {dst.shape}")
    if len(src) < 4:
        raise ValueError(f"Need at least 4 point pairs to fit a homography, got {len(src)}")

    H, mask = cv2.findHomography(src, dst, method=method,
                                  ransacReprojThreshold=ransac_reproj_threshold)
    if H is None:
        raise ValueError("cv2.findHomography failed to find a homography "
                          "for the given points (degenerate/collinear input?)")

    projected = cv2.perspectiveTransform(src.reshape(-1, 1, 2), H).reshape(-1, 2)
    errors = np.linalg.norm(projected - dst, axis=1)

    inlier = mask.ravel().astype(bool) if mask is not None else np.ones(len(src), dtype=bool)
    if not np.any(inlier):
        inlier = np.ones(len(src), dtype=bool)  # degenerate mask -- fall back to all points
    scored_errors = errors[inlier]

    return {
        "H": H.tolist(),
        "H_inv": np.linalg.inv(H).tolist(),
        "reproj_error_px": float(np.sqrt(np.mean(scored_errors ** 2))),
        "max_error_px": float(np.max(scored_errors)),
        "n_points": int(len(src)),
        "n_inliers": int(np.sum(inlier)),
    }


def estimate_homography_from_poses(cam_a_h5s: list, cam_b_h5s: list,
                                    cam_a: str, cam_b: str,
                                    min_likelihood: float = 0.8,
                                    max_points: int = 2000,
                                    min_points: int = 20,
                                    log_fn=print) -> "dict | None":
    """
    Automatically estimate a floor-plane homography between two cameras
    from real, already-tracked DLC keypoints instead of manually-clicked
    reference points — the primary calibration path for CUBE's
    Two/Three-Camera Homography Fusion fallback (see
    C:\\Users\\param\\.claude\\plans\\woolly-cuddling-goose.md), with
    manual clicking (cube_homography_calibrator.py) as a fallback only
    for a pair with too little qualifying tracked data.

    Reuses calibration_refine_poses.collect_pose_correspondences()
    UNMODIFIED — the same pooling logic the full 3D calibrated pipeline's
    pose-based calibration refinement already uses (any bodypart visible
    at >= min_likelihood in BOTH cameras, across every session/frame,
    subsampled to max_points) — that function is already camera-count-
    agnostic (works for exactly 2 cameras) and has zero dependency on
    cube_core/cube_3d_dlc, so there's no circular-import risk pulling it
    in here.

    cam_a_h5s, cam_b_h5s : per-session DLC H5 paths for each camera,
        index-aligned (cam_a_h5s[i] and cam_b_h5s[i] must be the same
        session) — same convention collect_pose_correspondences expects.

    Returns fit_floor_homography()'s result dict (with an added
    ``"method": "pose_auto"`` key, purely additive metadata) fit via
    cv2.RANSAC rather than plain DLT, since pooling hundreds of real
    tracked keypoints can include genuine outliers (a symmetric-bodypart
    ID swap, an occlusion-driven bad detection) that a handful of manual,
    human-verified clicks never have to contend with. Returns None
    (already logged by collect_pose_correspondences) if fewer than
    min_points qualifying correspondence points are found.

    Deliberately fits/refines the homography from real bodypart positions
    rather than literal floor points: bodyparts sit at a range of heights
    above the true floor plane, so this is an approximation of an exact
    floor-plane mapping — but the SAME approximation the manual click
    workflow already accepts (its own "wall/height point" already breaks
    strict planarity), and one that optimizes for exactly the data this
    homography will actually be applied to during fusion (mouse bodypart
    positions), rather than floor corners the animal never stands on.
    """
    import cv2
    from calibration_refine_poses import collect_pose_correspondences

    result = collect_pose_correspondences(
        {cam_a: cam_a_h5s, cam_b: cam_b_h5s}, [cam_a, cam_b],
        min_likelihood=min_likelihood, max_points=max_points,
        min_points=min_points, log_fn=log_fn)
    if result is None:
        return None

    p2ds, cam_order = result
    idx_a, idx_b = cam_order.index(cam_a), cam_order.index(cam_b)
    fit = fit_floor_homography(p2ds[idx_a], p2ds[idx_b],
                                method=cv2.RANSAC, ransac_reproj_threshold=5.0)
    fit["method"] = "pose_auto"
    return fit


def _homography_cache_path(rig_id: str, cache_dir=None) -> Path:
    cache_dir = Path(cache_dir) if cache_dir is not None else HOMOGRAPHY_CACHE_DIR
    safe_rig_id = re.sub(r'[^A-Za-z0-9_.-]', '_', str(rig_id))
    return cache_dir / f"{safe_rig_id}.json"


def camera_pair_rig_id(cam_a: str, cam_b: str) -> str:
    """
    Deterministic cache key for a homography between two cameras, order-
    independent (cam0/cam1 gives the same id as cam1/cam0). Per the plan's
    documented rig_id caveat (TwoCam_Homography_BoneConstraint_Fusion_Plan.md
    Phase 4 scope note): stable within one Step 0 scan (bonsai_video_
    corrector.py's serial_to_cam assigns camN globally per invocation), not
    guaranteed stable across separate scans over different camera subsets --
    the simplest honest option given no "Doric rig/config identity" concept
    exists anywhere else in the codebase.
    """
    return "__".join(sorted([str(cam_a), str(cam_b)]))


def resolve_fusion_homography(cached_result: "dict | None", source_cam: str,
                               target_cam: str) -> "np.ndarray | None":
    """
    Given a cached homography result (from save_cached_homography(), which
    now also stores which physical camera was "src"/"dst" at calibration
    time -- see cube_homography_calibrator.py), return the matrix mapping
    *source_cam* pixels to *target_cam* pixels, choosing H or H_inv as
    needed. Returns None if *cached_result* is None or doesn't carry
    "cam_src"/"cam_dst" metadata matching this camera pair at all (never
    guesses a direction).
    """
    if cached_result is None:
        return None
    cam_src = cached_result.get("cam_src")
    cam_dst = cached_result.get("cam_dst")
    if cam_src == source_cam and cam_dst == target_cam:
        return np.asarray(cached_result["H"])
    if cam_src == target_cam and cam_dst == source_cam:
        return np.asarray(cached_result["H_inv"])
    return None


def save_cached_homography(rig_id: str, homography_result: dict, cache_dir=None) -> Path:
    """
    Persist *homography_result* (as returned by fit_floor_homography(), plus
    any caller-added metadata e.g. camera pair labels) to the on-disk cache
    for *rig_id*, so every future session recorded on that same physical rig
    can reuse it without re-asking the user for reference points (plan §4,
    "one-time per rig"). Returns the path written.
    """
    path = _homography_cache_path(rig_id, cache_dir)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(homography_result, indent=2))
    return path


def load_cached_homography(rig_id: str, cache_dir=None) -> "dict | None":
    """
    Load a previously cached homography for *rig_id*, or None if no cache
    exists yet for this rig (e.g. never calibrated, or cache_dir cleared).
    """
    path = _homography_cache_path(rig_id, cache_dir)
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text())
    except Exception:
        return None


# ─────────────────────────────────────────────────────────────────────────────
#  Two/three-camera fusion — self-consistency check + bone-constraint
#  fallback (Phase 3: algorithm only, not wired into Step 2 yet; see
#  TwoCam_Homography_BoneConstraint_Fusion_Plan.md §3/Phase 3)
#
#  Reuse note (documented here rather than silently deviating from the plan
#  text): the plan's Phase 3 originally said to reuse cube_3d_dlc.py's
#  "existing bone_constraints machinery". That machinery
#  (CameraGroup.optim_points() from aniposelib) is a full calibrated-3D
#  bundle-adjustment constraint solver that requires a real calibration.toml
#  -- fundamentally unavailable for this plan's target rigs (2/3-camera
#  Doric setups with NO calibration ever captured). What IS reused, because
#  it's calibration-independent, is cube_3d_dlc._infer_skeleton() for
#  anatomically-plausible bodypart-pair topology. The "bone-constraint IK
#  lift" below is therefore a simplified 2D-only technique appropriate for
#  this plan's own stated scope ("not claiming publication-grade 3D
#  kinematics... improved 2D coverage for clustering"): it transfers the
#  LIMB DIRECTION observed in the confident camera onto the already-resolved
#  parent joint's position in the target camera, at that target camera's own
#  session-learned bone length -- not a 3D inverse-kinematics solve.
# ─────────────────────────────────────────────────────────────────────────────

def apply_homography(H, points) -> "np.ndarray":
    """
    Apply a 3x3 homography *H* (as returned in fit_floor_homography()'s
    "H"/"H_inv") to one or more (x, y) pixel points.

    points : a single (x, y) pair, or an (N, 2) sequence of pairs.
    Returns an array of the same shape as the input (2,) or (N, 2).
    """
    import cv2
    H = np.asarray(H, dtype=np.float64)
    pts = np.asarray(points, dtype=np.float64)
    single = (pts.ndim == 1)
    if single:
        pts = pts.reshape(1, 2)
    projected = cv2.perspectiveTransform(pts.reshape(-1, 1, 2), H).reshape(-1, 2)
    return projected[0] if single else projected


def compute_bone_length_stats(positions: dict, confidences: dict,
                               skeleton_edges, conf_threshold: float = 0.6,
                               min_samples: int = 10) -> dict:
    """
    Learn per-bodypart-pair ("bone") length statistics for ONE camera's own
    pixel space, from frames where BOTH bodyparts in the pair are
    confidently observed -- the plan's "free calibration check": per-
    bodypart tolerance learned per-session from the (plentiful) bins where
    tracking is good, no hand-tuned constant.

    positions    : {bodypart: (n_frames, 2) array} for this camera.
    confidences  : {bodypart: (n_frames,) array} for this camera.
    skeleton_edges : iterable of (parent, child) bodypart-name pairs, e.g.
        cube_3d_dlc._infer_skeleton(bodyparts)'s output.

    Returns {(parent, child): {"mean": float, "std": float, "n": int}} --
    an edge is omitted if fewer than *min_samples* dual-confident frames are
    available (too little evidence to trust a learned tolerance for it).
    """
    stats = {}
    for parent, child in skeleton_edges:
        if parent not in positions or child not in positions:
            continue
        conf_p = confidences.get(parent)
        conf_c = confidences.get(child)
        if conf_p is None or conf_c is None:
            continue
        both_confident = (np.asarray(conf_p) >= conf_threshold) & (np.asarray(conf_c) >= conf_threshold)
        n = int(np.sum(both_confident))
        if n < min_samples:
            continue
        p_pos = np.asarray(positions[parent])[both_confident]
        c_pos = np.asarray(positions[child])[both_confident]
        lengths = np.linalg.norm(c_pos - p_pos, axis=1)
        stats[(parent, child)] = {
            "mean": float(np.mean(lengths)),
            "std": float(np.std(lengths)),
            "n": n,
        }
    return stats


# Floor for the learned bone-length std: with very consistent tracking the
# sample std can be near-zero, which would make the consistency check reject
# almost any real measurement noise. A small pixel floor keeps the check
# meaningful without needing a hand-tuned per-rig constant.
_MIN_BONE_LENGTH_STD_PX = 2.0


def check_bone_length_consistency(candidate_pos, parent_pos, bone_stats: dict,
                                   tolerance_n_std: float = 3.0) -> bool:
    """
    Return True iff the distance from *candidate_pos* to *parent_pos* is
    within *tolerance_n_std* standard deviations of the learned bone-length
    mean in *bone_stats* (as returned by compute_bone_length_stats() for
    this specific edge) -- the plan's §3 step-3 self-consistency check on a
    homography-lifted point. If *bone_stats* is None (no learned tolerance
    for this edge, e.g. too few dual-confident frames), there is nothing to
    validate against, so the homography lift is trusted by default.
    """
    if bone_stats is None:
        return True
    dist = float(np.linalg.norm(np.asarray(candidate_pos) - np.asarray(parent_pos)))
    tolerance = tolerance_n_std * max(bone_stats["std"], _MIN_BONE_LENGTH_STD_PX)
    return abs(dist - bone_stats["mean"]) <= tolerance


def bone_constraint_lift(parent_pos_target, child_pos_source, parent_pos_source,
                          target_bone_length: float):
    """
    Reconstruct a bodypart's position in the TARGET camera's pixel space
    when the homography lift failed its self-consistency check (plan §3
    step 3), using the SOURCE camera's own directly-observed limb direction
    (see the module-level "Reuse note" above for why this is a 2D direction
    transfer rather than a 3D IK solve): the unit vector from the source
    camera's parent joint to its child bodypart is applied to the target
    camera's own already-resolved parent position, at the target camera's
    own session-learned bone length.

    Returns None if the source camera's parent-child segment has ~zero
    length (degenerate direction, e.g. parent and child coincide) -- the
    caller should fall back to temporal interpolation in that case, per the
    plan's step 4.
    """
    parent_pos_target = np.asarray(parent_pos_target, dtype=float)
    child_pos_source = np.asarray(child_pos_source, dtype=float)
    parent_pos_source = np.asarray(parent_pos_source, dtype=float)

    direction = child_pos_source - parent_pos_source
    norm = np.linalg.norm(direction)
    if norm < 1e-9:
        return None
    unit_direction = direction / norm
    return parent_pos_target + unit_direction * target_bone_length


def route_bodypart_fusion(target_conf: float, source_conf: float,
                           source_pos, H_source_to_target,
                           target_parent_pos, source_parent_pos,
                           bone_stats: "dict | None",
                           interpolated_fallback=None,
                           conf_threshold: float = 0.6,
                           tolerance_n_std: float = 3.0) -> tuple:
    """
    Decide a target camera's position for one bodypart at one frame, per
    the plan's §3 four-branch routing (this function implements branches
    2-4; branch 1 -- both cameras already confident -- is the caller's own
    existing conserved-bodyparts logic and doesn't need this function at
    all, since there's nothing to lift).

    target_conf, source_conf : this frame's likelihood for the target/source
        camera (source is the OTHER camera, whose view may be usable when
        the target camera itself is not confident).
    source_pos                : (x, y) in the source camera's own pixel space.
    H_source_to_target        : homography mapping source -> target pixel space.
    target_parent_pos, source_parent_pos : (x, y) or None -- this bodypart's
        already-resolved parent joint position in each camera, or None if
        the parent itself is unresolved this frame (also occluded).
    bone_stats                : compute_bone_length_stats() entry for this
        (parent, child) edge in the TARGET camera, or None.
    interpolated_fallback      : precomputed (x, y) temporal-interpolation
        value for the target camera at this frame, or None if unavailable.

    Returns (position_xy_or_None, provenance) where provenance is one of
    "homography", "bone_constraint", "interpolated", or "unresolved".
    """
    if source_conf < conf_threshold:
        if interpolated_fallback is not None:
            return np.asarray(interpolated_fallback, dtype=float), "interpolated"
        return None, "unresolved"

    lifted = apply_homography(H_source_to_target, source_pos)

    if target_parent_pos is None or bone_stats is None:
        # Nothing to validate the lift against -- trust it (matches
        # check_bone_length_consistency's own no-tolerance-available default).
        return lifted, "homography"

    if check_bone_length_consistency(lifted, target_parent_pos, bone_stats, tolerance_n_std):
        return lifted, "homography"

    if source_parent_pos is not None:
        bone_lifted = bone_constraint_lift(
            target_parent_pos, source_pos, source_parent_pos, bone_stats["mean"])
        if bone_lifted is not None:
            return bone_lifted, "bone_constraint"

    if interpolated_fallback is not None:
        return np.asarray(interpolated_fallback, dtype=float), "interpolated"
    return None, "unresolved"


def fuse_bodypart_trajectory(target_pos, target_conf, source_pos, source_conf,
                              H_source_to_target,
                              target_parent_pos=None, source_parent_pos=None,
                              bone_stats: "dict | None" = None,
                              interpolated_fallback=None,
                              conf_threshold: float = 0.6,
                              tolerance_n_std: float = 3.0) -> dict:
    """
    Session-level orchestration of route_bodypart_fusion() across every
    frame of ONE bodypart's trajectory for the TARGET camera -- the plan's
    "one pure function operating on a single session's per-camera 2D
    arrays + likelihoods, fully unit-testable without touching Step 2 at
    all" (Phase 3).

    target_pos, source_pos       : (n_frames, 2) arrays, this camera's own
        directly-observed pixel positions for this bodypart.
    target_conf, source_conf     : (n_frames,) likelihood arrays.
    H_source_to_target           : homography mapping source -> target.
    target_parent_pos, source_parent_pos : (n_frames, 2) arrays of this
        bodypart's already-resolved parent joint, or None if unavailable
        for the whole session (treated as unresolved every frame).
    bone_stats                   : compute_bone_length_stats() entry for
        this edge in the TARGET camera, or None.
    interpolated_fallback        : (n_frames, 2) array of precomputed
        temporal-interpolation fallback values for the target camera, or
        None.

    Returns {"positions": (n_frames, 2) array, "provenance": list[str]} --
    provenance[i] is "direct" where the target camera was already
    confident this frame (source untouched), else one of
    route_bodypart_fusion()'s return values.
    """
    target_pos = np.asarray(target_pos, dtype=float)
    target_conf = np.asarray(target_conf, dtype=float)
    source_pos = np.asarray(source_pos, dtype=float)
    source_conf = np.asarray(source_conf, dtype=float)
    n_frames = len(target_pos)

    out_positions = target_pos.copy()
    provenance = ["direct"] * n_frames

    for i in range(n_frames):
        if target_conf[i] >= conf_threshold:
            continue
        t_parent = target_parent_pos[i] if target_parent_pos is not None else None
        s_parent = source_parent_pos[i] if source_parent_pos is not None else None
        interp = interpolated_fallback[i] if interpolated_fallback is not None else None
        pos, prov = route_bodypart_fusion(
            target_conf[i], source_conf[i], source_pos[i], H_source_to_target,
            t_parent, s_parent, bone_stats, interp, conf_threshold, tolerance_n_std)
        provenance[i] = prov
        if pos is not None:
            out_positions[i] = pos

    return {"positions": out_positions, "provenance": provenance}


# ─────────────────────────────────────────────────────────────────────────────
#  Two/three-camera fusion — multi-camera group orchestration (Phase 4 core:
#  pure fusion logic only; see TwoCam_Homography_BoneConstraint_Fusion_Plan.md
#  §2.2/Phase 4 for the still-outstanding Step 2 file-I/O and GUI
#  auto-trigger wiring, deliberately scoped out of this pass -- see that
#  section's "Phase 4 scope note" for why).
# ─────────────────────────────────────────────────────────────────────────────

def select_primary_camera(cam_confidences: dict) -> "str | None":
    """
    Pick the camera with the highest mean confidence across all of its own
    tracked bodyparts, to serve as fuse_camera_group_to_primary()'s output
    pixel-coordinate frame (the plan doesn't mandate a specific selection
    rule -- this one is simple, deterministic, and favors already-good
    tracking as the base to lift INTO, minimizing how much fusion work is
    needed).

    cam_confidences : {cam_label: {bodypart: (n_frames,) array}}
    Returns the best cam_label, or None if cam_confidences is empty.
    """
    best_cam, best_score = None, -1.0
    for cam, bp_conf in cam_confidences.items():
        if not bp_conf:
            continue
        score = float(np.mean([np.mean(c) for c in bp_conf.values()]))
        if score > best_score:
            best_score, best_cam = score, cam
    return best_cam


def build_parent_map(skeleton_edges) -> dict:
    """{child: parent} from (parent, child) skeleton edges (e.g.
    cube_3d_dlc._infer_skeleton()'s output). First edge wins if a bodypart
    is ever listed as a child more than once."""
    parent_map = {}
    for parent, child in skeleton_edges:
        parent_map.setdefault(child, parent)
    return parent_map


def topological_bodypart_order(skeleton_edges, bodyparts) -> list:
    """
    Order *bodyparts* so every parent (per build_parent_map()) comes before
    its children -- fuse_camera_group_to_primary() needs this so a child
    bodypart's consistency check can validate against its parent's own
    ALREADY-FUSED position, not just the primary camera's raw (possibly
    unresolved) one. Bodyparts with no skeleton connection at all are
    appended at the end in their input order (nothing to order them by).
    """
    parent_map = build_parent_map(skeleton_edges)
    children_map = {}
    for parent, child in skeleton_edges:
        children_map.setdefault(parent, []).append(child)

    bodyparts_set = set(bodyparts)
    visited = set()
    order = []

    def visit(bp):
        if bp in visited or bp not in bodyparts_set:
            return
        visited.add(bp)
        order.append(bp)
        for child in children_map.get(bp, []):
            visit(child)

    roots = [bp for bp in bodyparts if bp not in parent_map]
    for r in roots:
        visit(r)
    for bp in bodyparts:
        if bp not in visited:
            visit(bp)
    return order


def fuse_camera_group_to_primary(cam_positions: dict, cam_confidences: dict,
                                  primary_cam: str, homographies: dict,
                                  skeleton_edges,
                                  interpolated_fallback: "dict | None" = None,
                                  conf_threshold: float = 0.6,
                                  tolerance_n_std: float = 3.0) -> dict:
    """
    Fuse a 2- or 3-camera Doric group's per-camera bodypart trajectories
    into ONE output trajectory set in *primary_cam*'s own pixel space,
    applying route_bodypart_fusion() (Phase 3) to every bodypart the
    primary camera isn't confidently tracking, trying each secondary
    camera in *cam_positions* iteration order until one resolves it.

    cam_positions, cam_confidences : {cam_label: {bodypart: array}} --
        (n_frames, 2) position arrays / (n_frames,) confidence arrays. Not
        every camera needs to track every bodypart.
    homographies : {(source_cam, primary_cam): H} -- a homography for each
        non-primary camera that should be tried as a fusion source. A
        secondary camera with no entry here is skipped for every bodypart
        (e.g. a 3-camera rig where only 2 pairs were calibrated).
    skeleton_edges : (parent, child) bodypart-name pairs (e.g.
        cube_3d_dlc._infer_skeleton()'s output) -- used both to learn
        per-edge bone-length tolerance from primary_cam's own dual-
        confident frames, and to fuse bodyparts in parent-before-child
        order (topological_bodypart_order()).
    interpolated_fallback : optional {bodypart: (n_frames, 2) array} of
        precomputed temporal-interpolation values in primary_cam's frame,
        used when no camera can resolve a bodypart via homography/bone-
        constraint (Phase 3's branch 4).

    Returns {"primary_cam": str, "positions": {bp: array}, "confidences":
    {bp: array}, "provenance": {bp: list[str]}}. A frame's provenance is
    "direct" wherever the primary camera was already confident there.
    """
    all_bodyparts = sorted(set().union(*(set(pos.keys()) for pos in cam_positions.values())))
    order = topological_bodypart_order(skeleton_edges, all_bodyparts)
    parent_map = build_parent_map(skeleton_edges)
    secondary_cams = [c for c in cam_positions if c != primary_cam]

    n_frames = None
    for cam in (primary_cam, *secondary_cams):
        for pos in cam_positions.get(cam, {}).values():
            n_frames = len(pos)
            break
        if n_frames is not None:
            break
    if n_frames is None:
        return {"primary_cam": primary_cam, "positions": {}, "confidences": {}, "provenance": {}}

    bone_stats_by_edge = compute_bone_length_stats(
        cam_positions.get(primary_cam, {}), cam_confidences.get(primary_cam, {}),
        skeleton_edges, conf_threshold=conf_threshold)

    # Reverse of parent_map: a root bodypart (e.g. "nose") has no upstream
    # parent to validate a homography lift against, so
    # check_bone_length_consistency() unconditionally trusted it -- real-
    # data validation (F:\DAM EXP3 GQ, genuinely orthogonal cam0/cam1)
    # found this is a real gap: nose/upper_jaw (nose's own child, whose own
    # check partly inherits nose's error) were the only bodyparts, of 24,
    # where "homography"-provenance positions ever landed outside the
    # camera's real observed pixel range (3.9%/3.7%; every other bodypart
    # was 0%). Fixed with a synthetic anchor: validate a root bodypart's
    # lift against whichever of ITS OWN children is directly confident in
    # the PRIMARY camera at that exact frame, reusing the same bone_stats
    # entry compute_bone_length_stats() already computed for that
    # (root, child) edge -- no new bone-length learning needed. This is
    # resolved per-frame (not once per session), since which child is
    # confidently observed varies frame to frame.
    children_map: dict = {}
    for _parent, _child in skeleton_edges:
        children_map.setdefault(_parent, []).append(_child)

    fused_positions, fused_confidences, fused_provenance = {}, {}, {}

    for bp in order:
        parent = parent_map.get(bp)
        target_parent_pos = fused_positions.get(parent) if parent else None
        bone_stats = bone_stats_by_edge.get((parent, bp)) if parent else None

        # Root bodypart (no parent): candidate children usable as a
        # synthetic validation anchor, restricted to ones the primary
        # camera actually tracks and that have a learned bone-length edge.
        root_anchor_candidates = None
        if parent is None:
            root_anchor_candidates = [
                (c, bone_stats_by_edge[(bp, c)]) for c in children_map.get(bp, [])
                if c in cam_positions.get(primary_cam, {}) and (bp, c) in bone_stats_by_edge]

        if bp in cam_positions.get(primary_cam, {}):
            target_pos = np.asarray(cam_positions[primary_cam][bp], dtype=float).copy()
            target_conf = np.asarray(cam_confidences[primary_cam][bp], dtype=float).copy()
        else:
            target_pos = np.full((n_frames, 2), np.nan)
            target_conf = np.zeros(n_frames)

        provenance = ["direct"] * n_frames
        interp = interpolated_fallback.get(bp) if interpolated_fallback else None

        for sec_cam in secondary_cams:
            if bp not in cam_positions.get(sec_cam, {}):
                continue
            H = homographies.get((sec_cam, primary_cam))
            if H is None:
                continue
            still_needed = np.nonzero(target_conf < conf_threshold)[0]
            if len(still_needed) == 0:
                break
            source_pos = np.asarray(cam_positions[sec_cam][bp], dtype=float)
            source_conf = np.asarray(cam_confidences[sec_cam][bp], dtype=float)
            source_parent_pos = (np.asarray(cam_positions[sec_cam][parent], dtype=float)
                                  if parent and parent in cam_positions.get(sec_cam, {}) else None)

            for i in still_needed:
                if root_anchor_candidates:
                    t_parent, bone_stats_i = None, None
                    for c, c_bone_stats in root_anchor_candidates:
                        c_conf = cam_confidences[primary_cam][c]
                        if i < len(c_conf) and c_conf[i] >= conf_threshold:
                            t_parent = cam_positions[primary_cam][c][i]
                            bone_stats_i = c_bone_stats
                            break
                else:
                    t_parent = target_parent_pos[i] if target_parent_pos is not None else None
                    bone_stats_i = bone_stats
                # s_parent stays keyed on the real skeletal parent (always
                # None here for a root bodypart, since `parent` is None) --
                # never the synthetic child-based anchor above, so
                # bone_constraint_lift (which needs the SAME anatomical
                # joint in both camera views) is never handed mismatched
                # references; a root bodypart's failed check falls straight
                # to interpolation instead, exactly as before this fix.
                s_parent = source_parent_pos[i] if source_parent_pos is not None else None
                interp_i = interp[i] if interp is not None else None
                pos, prov = route_bodypart_fusion(
                    target_conf[i], source_conf[i], source_pos[i], H,
                    t_parent, s_parent, bone_stats_i, interp_i, conf_threshold, tolerance_n_std)
                if pos is not None:
                    target_pos[i] = pos
                    # Confidence written for a lifted frame must stay honest,
                    # not clamp to a single flat value regardless of source
                    # quality or method -- an earlier version of this function
                    # did exactly that (every lifted frame got an identical
                    # conf_threshold confidence), which is precisely the
                    # "silent accuracy degradation" risk the plan's §6 calls
                    # out: downstream code (detect_turned_away_bins, the
                    # conserved-bodyparts pass-rate check, MIN_BODYPART_
                    # CONFIDENCE-based exclusion) would then treat a
                    # cross-camera-lifted estimate as indistinguishable from
                    # a genuine high-confidence direct detection. A
                    # homography lift transfers the OTHER camera's own
                    # actual confidence (already known >= conf_threshold, or
                    # route_bodypart_fusion wouldn't have attempted it) --
                    # honest, not inflated. A bone-constraint lift is a
                    # strictly lower-fidelity fallback (direction-transfer
                    # heuristic, not a real detection in either view) and is
                    # damped below the homography case so the two remain
                    # distinguishable to any downstream consumer that wants
                    # to weight or threshold on confidence.
                    if prov == "homography":
                        target_conf[i] = float(source_conf[i])
                    elif prov == "bone_constraint":
                        target_conf[i] = max(conf_threshold, float(source_conf[i]) * 0.75)
                    provenance[i] = prov

        # Frames still below threshold here never reached route_bodypart_fusion
        # at all (e.g. every secondary camera lacked a homography entry or
        # didn't track this bodypart) -- fall back to interpolation if
        # available, else mark them honestly as unresolved rather than
        # leaving the stale "direct" default label on an unresolved frame.
        still_unresolved = np.nonzero(target_conf < conf_threshold)[0]
        for i in still_unresolved:
            if interp is not None:
                target_pos[i] = interp[i]
                provenance[i] = "interpolated"
            else:
                provenance[i] = "unresolved"

        fused_positions[bp] = target_pos
        fused_confidences[bp] = target_conf
        fused_provenance[bp] = provenance

    return {"primary_cam": primary_cam, "positions": fused_positions,
            "confidences": fused_confidences, "provenance": fused_provenance}


def resolve_cube_run_root(existing_run_root: str, source_folders, output_root: str = "",
                           fallback_base=None, log_fn=None) -> "Path":
    """
    Resolve (creating if necessary) the single 'CUBE results <date>_<time>'
    run-root folder for the current pipeline run.

    existing_run_root : the caller's current session["cube_run_root"] value
                         (empty string if unset) -- reused verbatim if it
                         still exists on disk.
    source_folders     : folders being processed this run.
    output_root         : explicit output folder the user set anywhere in the
                         GUI (empty string if none) -- highest-priority base
                         for a FRESH root.
    fallback_base       : Path to use as the base when source_folders has more
                         than one entry and output_root is empty (the
                         caller's own multi-folder workspace-root logic,
                         e.g. cube.py's _resolve_work_dir()); if None, falls
                         back to a "CUBE_Pipeline" folder next to this file.
    log_fn               : optional callable(str), used for info/warn messages
                         (matches this module's existing log_fn convention).

    Returns the resolved Path. Does NOT write back into any session object
    -- the caller stores the result (e.g. session["cube_run_root"] = str(...)).
    """
    existing_run_root = (existing_run_root or "").strip()
    if existing_run_root:
        p = Path(existing_run_root)
        if p.is_dir():
            return p

    found = find_existing_cube_run_root(source_folders, log_fn)
    if found is not None:
        if log_fn is not None:
            log_fn(f"  Reusing existing run root created by Step 0: {found}")
        return found

    source_folders = list(source_folders or [])
    output_root = (output_root or "").strip()
    if output_root:
        base = Path(output_root)
    elif len(source_folders) == 1:
        base = Path(source_folders[0])
    elif fallback_base is not None:
        base = Path(fallback_base)
    else:
        base = Path(__file__).resolve().parent / "CUBE_Pipeline"

    run_root = base / f"{CUBE_RUN_ROOT_PREFIX} {datetime.now().strftime(_RUN_ROOT_TS_FMT)}"
    run_root.mkdir(parents=True, exist_ok=True)
    return run_root


def analyze_session_confidence(h5_path: Path) -> dict | None:
    """Returns {bodypart: {mean, median}} or None on failure."""
    try:
        df = pd.read_hdf(str(h5_path))
        df = _normalise_dlc_df(df)
        bparts = df.columns.get_level_values("bodyparts").unique()
        stats  = {}
        for bp in bparts:
            sub = df.xs(bp, level="bodyparts", axis=1)
            if sub.columns.nlevels > 1:
                sub.columns = sub.columns.get_level_values(-1)
            llh = pd.to_numeric(
                sub.get("likelihood", pd.Series(np.nan, index=df.index)),
                errors="coerce")
            stats[bp] = {"mean": float(llh.mean()), "median": float(llh.median())}
        return stats
    except Exception as e:
        print(f"  [WARN] Could not analyze {h5_path.name}: {e}")
        return None


def save_bsoid_h5_csv(df: pd.DataFrame, h5_dst: Path,
                       csv_dst: Path, bodyparts_to_keep: list):
    """Filter to conserved bodyparts and save H5 + CSV in B-SOiD format.

    Preserves the z coord column when the input is a 3D triangulated H5
    (coords = [x, y, z, likelihood]) so that BSoidEngine._h5_has_z() can
    detect 3D format downstream.  2D H5s (coords = [x, y, likelihood]) are
    written identically to before.
    """
    df = df.loc[:, (slice(None), bodyparts_to_keep, slice(None))]
    # Detect 3D format: 4 coords per bodypart including 'z'
    all_coords = df.columns.get_level_values("coords").unique().tolist()
    _has_z     = "z" in all_coords
    coords_out = ["x", "y", "z", "likelihood"] if _has_z else ["x", "y", "likelihood"]
    new_cols = pd.MultiIndex.from_product(
        [[BSOID_SCORER_NAME], bodyparts_to_keep, coords_out],
        names=["scorer", "bodyparts", "coords"],
    )
    df = df.copy()
    df.columns = new_cols
    df.index   = range(len(df))
    h5_dst.parent.mkdir(parents=True, exist_ok=True)
    df.to_hdf(str(h5_dst), key="df_with_missing", mode="w", format="fixed")
    csv_dst.parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(str(csv_dst))


def bsoid_short_name(h5_path: Path, folder_name: str,
                      max_folder_len: int = 28) -> str:
    """
    Build a short, filesystem-safe session name.
    Caps folder_name at max_folder_len characters to prevent Windows MAX_PATH
    (260-char) errors caused by long cage/condition folder names.
    Format: <truncated_folder>_<YYYYMMDD_HHMMSS>
    """
    m  = _TS_RE.search(h5_path.stem)
    ts = m.group(1) if m else ""
    short_folder = folder_name[:max_folder_len].rstrip("_- ")
    if ts:
        return f"{short_folder}_{ts}"
    # No YYYYMMDD_HHMMSS found — use the session stem so every file gets a unique name
    stem = h5_path.stem
    if stem.endswith("_filtered"):
        stem = stem[:-len("_filtered")]
    return stem[:80] if stem else short_folder


def cleanup_video_byproducts(results_folder: Path, log_fn=print):
    """
    Incremental cleanup: delete pseudo_* folders and DLC-generated .json files
    from a single video's _results folder immediately after inference completes.
    Call once per video inside the DLC loop to keep disk usage low and avoid
    Windows MAX_PATH errors from long pseudo_resized_* directory names.
    """
    rf = Path(results_folder)
    if not rf.exists():
        return
    pseudo_n = json_n = 0
    for entry in sorted(rf.iterdir()):
        if entry.is_dir() and entry.name.startswith("pseudo_"):
            try:
                shutil.rmtree(str(entry))
                log_fn(f"  [cleanup] Removed: {entry.name}")
                pseudo_n += 1
            except Exception as e:
                log_fn(f"  [cleanup] Could not remove {entry.name}: {e}")
    for jf in sorted(rf.glob("*.json")):
        try:
            jf.unlink()
            json_n += 1
        except Exception:
            pass
    if pseudo_n or json_n:
        log_fn(f"  [cleanup] {pseudo_n} pseudo dir(s), {json_n} JSON(s) removed "
               f"from {rf.name}.")


def cleanup_dlc_byproducts(root_path: Path, log_fn=print):
    """Global cleanup: delete pseudo_* folders and .json files left by DLC."""
    pseudo_count = json_count = 0
    search_dirs  = {root_path.resolve()}
    for item in root_path.rglob("*"):
        if item.is_dir() and item.name.endswith("_results"):
            search_dirs.add(item.resolve())
    for folder in sorted(search_dirs):
        if not folder.exists():
            continue
        for entry in sorted(folder.iterdir()):
            if entry.is_dir() and entry.name.startswith("pseudo_"):
                try:
                    shutil.rmtree(str(entry))
                    log_fn(f"  [cleanup] Deleted pseudo folder: {entry.name}")
                    pseudo_count += 1
                except Exception as e:
                    log_fn(f"  [cleanup] Could not delete {entry.name}: {e}")
        for jf in sorted(folder.glob("*.json")):
            try:
                jf.unlink()
                json_count += 1
            except Exception:
                pass
    log_fn(f"  [cleanup] {pseudo_count} pseudo folder(s), {json_count} JSON file(s) removed.")


def _skew(v: np.ndarray) -> np.ndarray:
    """3x3 cross-product (skew-symmetric) matrix, so that _skew(v) @ w == v x w."""
    x, y, z = v
    return np.array([[0.0, -z,  y],
                      [z,   0.0, -x],
                      [-y,  x,  0.0]])


def _triangulate_weighted_dlt(p2d: np.ndarray, sc: np.ndarray, cgroup,
                               log_fn=print) -> np.ndarray:
    """
    LOST (Linear Optimal Sine Triangulation) — Christian & D'Souza, "Absolute
    Triangulation Algorithms for Space Exploration" (arXiv:2205.12197), as
    adopted into GTSAM (gtsam::triangulateLOST,
    gtsam/geometry/triangulation.cpp:87-147, BSD-licensed). Transcribed from
    that reference implementation and translated to aniposelib's world->camera
    (R, t) convention exactly as derived in
    D:\\3D DLC\\POSE_CALIBRATION_REFINEMENT.md Part 2.

    Non-iterative, linear weighted-least-squares triangulation, proven by the
    source paper to match the two-view-optimal Hartley-Sturm solution and to
    generalize losslessly to N cameras (Hartley-Sturm's degree-6 polynomial is
    two-view-only). This strictly supersedes the scalar-sqrt(likelihood)-weighted
    plain DLT this function used to implement: the GTSAM source notes
    "Setting q_i = 1.0 gives same results as DLT", i.e. plain DLT is LOST's
    q_i=1 special case — LOST's own geometric ("sine") weight, derived from ray
    directions and camera-center baselines, is what's new here.

    Confidence-weighting extension (CUBE's own, faithful to the paper's
    derivation — LOST supports per-observation noise sigma_i; GTSAM's public API
    just happens to expose only one shared sigma per call): DLC's per-camera
    likelihood is folded in as sigma_i = 1 / max(sqrt(likelihood_i), eps), so a
    low-likelihood camera is treated as higher-noise and down-weighted, composed
    with (not replacing) LOST's own geometric weighting.

    Reference-selection extension (also CUBE's own): a low-likelihood camera's
    sigma_i only discounts *its own* row, but LOST's q_i is computed from a
    cyclic reference camera's ray (wZj) — so a corrupted view can still leak
    into a good camera's row by being picked as its reference. The candidate
    search below tries higher-confidence valid cameras before lower-confidence
    ones (falling back to GTSAM's plain cyclic order on ties, e.g. the uniform-
    confidence case), so that leak is avoided whenever a better reference
    exists.

    Aniposelib 0.8.0 has no scores/weights parameter anywhere in its
    triangulate* methods, so — as before — this is a local implementation built
    on plain aniposelib Camera/CameraGroup methods (undistort_points,
    get_extrinsics_mat), not a change to the installed package.

    Parameters
    ----------
    p2d : (N_cams, N_frames, 2) — pixel x/y per camera, post ll_gate NaN-masking
    sc  : (N_cams, N_frames)    — DLC likelihood per camera, post ll_gate zeroing
    cgroup : loaded aniposelib.cameras.CameraGroup

    Returns
    -------
    (N_frames, 3) — zero-filled for frames with fewer than 2 valid cameras, no
    non-degenerate reference camera for any contributing view, or a
    rank-deficient system (mirrors this codebase's zero-fill-on-failure
    convention rather than GTSAM's exception-throwing one).
    """
    N_cams, N_frames, _ = p2d.shape
    EPS = 1e-3

    # Undistorted normalized rays [x, y, 1] per camera (K already divided out).
    und = np.empty_like(p2d)
    for c, cam in enumerate(cgroup.cameras):
        und[c] = cam.undistort_points(np.copy(p2d[c]))
    rays = np.dstack([und, np.ones((N_cams, N_frames, 1))])  # (N_cams, N_frames, 3)

    # world->camera (R, t) per aniposelib's own convention (make_M / get_extrinsics_mat).
    R_mats = np.stack([cam.get_extrinsics_mat()[:3, :3] for cam in cgroup.cameras])
    t_vecs = np.stack([cam.get_extrinsics_mat()[:3, 3] for cam in cgroup.cameras])
    # Camera centers in world coords: C_i = -R_i.T @ t_i.
    C_world = np.stack([-R_mats[c].T @ t_vecs[c] for c in range(N_cams)])

    valid_mask = ~np.isnan(p2d[:, :, 0])  # (N_cams, N_frames)

    out = np.zeros((N_frames, 3), dtype=np.float64)
    for f in range(N_frames):
        valid_cams = np.where(valid_mask[:, f])[0]
        nv = valid_cams.size
        if nv < 2:
            continue

        A_rows = []
        b_rows = []
        for idx, c in enumerate(valid_cams):
            ray_i = rays[c, f]
            R_i = R_mats[c]
            C_i = C_world[c]
            w_i = sc[c, f]
            sigma_i = 1.0 / max(np.sqrt(w_i) if w_i > 0 else 0.0, EPS)

            # Reference candidate order: cyclic-next first (GTSAM: j = (i+1) % m),
            # but re-sorted to try higher-confidence valid cameras before lower-
            # confidence ones (ties broken by cyclic distance, so the uniform-
            # confidence case is unaffected and reduces to plain GTSAM order).
            # This is CUBE's own extension on top of GTSAM's degenerate-pair
            # fallback: a low-likelihood camera can still be *used as* someone
            # else's reference (its own sigma_i only discounts its own row), so
            # without this a corrupted view can leak into a good camera's q_i
            # via a contaminated wZj even though that camera's own ray is fine.
            # Preferring a higher-confidence reference when one is available
            # (falling back to lower-confidence/cyclic order only if needed)
            # keeps that contamination from happening whenever an alternative
            # exists, without changing the per-row math at all.
            candidates = sorted(range(1, nv),
                                 key=lambda step: (-sc[valid_cams[(idx + step) % nv], f], step))

            found = False
            num_i = den_i = 0.0
            for step in candidates:
                d = valid_cams[(idx + step) % nv]
                wZi = R_i.T @ ray_i
                wZj = R_mats[d].T @ rays[d, f]
                d_ij = C_world[d] - C_i
                num_i = np.linalg.norm(np.cross(wZi, wZj))
                den_i = np.linalg.norm(np.cross(d_ij, wZj))
                if num_i > 1e-9 and den_i > 1e-9:
                    found = True
                    break

            if not found:
                continue  # no usable reference camera — drop this row for this frame

            q_i = (num_i / den_i) / sigma_i
            coeff = q_i * (_skew(ray_i)[:2, :] @ R_i)
            A_rows.append(coeff)
            b_rows.append(coeff @ C_i)

        if len(A_rows) < 2:
            continue  # cannot reach rank >= 3 with fewer than 2 contributing cameras

        A = np.vstack(A_rows)
        b = np.concatenate(b_rows)
        if np.linalg.matrix_rank(A) < 3:
            continue

        sol, *_ = np.linalg.lstsq(A, b, rcond=None)
        out[f] = sol

    return out


def camera_world_positions(cgroup) -> np.ndarray:
    """
    World-space camera centers for every camera in a loaded aniposelib
    CameraGroup, in `cgroup.cameras` order.

    Reuses the exact convention already used inside this file's own
    triangulation code (world->camera R/t via get_extrinsics_mat(), camera
    center C_i = -R_i.T @ t_i) rather than a new derivation, so this can't
    silently disagree with how every other part of the pipeline interprets
    calibration.toml's extrinsics.

    Returns (N_cams, 3).
    """
    R_mats = np.stack([cam.get_extrinsics_mat()[:3, :3] for cam in cgroup.cameras])
    t_vecs = np.stack([cam.get_extrinsics_mat()[:3, 3] for cam in cgroup.cameras])
    return np.stack([-R_mats[c].T @ t_vecs[c] for c in range(len(cgroup.cameras))])


def _all_perfect_pairings(indices: list):
    """
    Yield every way to partition a list of (even-length) indices into
    len(indices)/2 unordered pairs — the standard "always pair the first
    remaining element with each possible partner, recurse on the rest"
    construction. len(indices)=4 -> 3 pairings, 6 -> 15, 8 -> 105 (double
    factorial growth), trivial to enumerate for any camera count this
    codebase targets (CLAUDE.md: "generalizes... up to 6 cameras").
    """
    if not indices:
        yield []
        return
    first, rest = indices[0], indices[1:]
    for i in range(len(rest)):
        partner = rest[i]
        remaining = rest[:i] + rest[i + 1:]
        for sub in _all_perfect_pairings(remaining):
            yield [(first, partner)] + sub


def _detect_opposite_camera_pairs(cgroup, min_angle_deg: float = 120.0):
    """
    Auto-detect a rig built as N/2 opposite-facing camera pairs (e.g. CUBE's
    current 4-camera "2 orthogonal pairs" layout — see D:\\3D DLC\\CLAUDE.md,
    the 2026-08-27 "geometric conditioning" investigation this feeds).
    Camera count is read from the calibration itself (len(cgroup.cameras)),
    the same way every other part of this pipeline infers camera count —
    no hardcoded assumption about how many cameras a rig has, matching the
    documented "generalizes... up to 6 cameras without code changes" design.

    Only meaningful for an even number of cameras (an odd count has no
    perfect pairing at all). Tries every way to partition the cameras into
    N/2 pairs (_all_perfect_pairings) and picks whichever partition
    maximizes the *worst* pair's forward-axis angle — i.e. EVERY pair in the
    chosen partition must genuinely face its partner, not just the best one.
    Returns None — not a guess — for any rig this wasn't derived from: odd
    camera count, or no partition where every pair clears min_angle_deg
    (default 120 degrees; the CUBE rig measured 154-162 degrees on its
    refined calibration).

    Returns
    -------
    dict[int, int] mapping camera index -> its opposite-pair partner's index,
    or None if no clean opposite-pairs layout was found.
    """
    n = len(cgroup.cameras)
    if n < 4 or n % 2 != 0:
        return None
    fwd = np.stack([cam.get_extrinsics_mat()[:3, :3].T @ np.array([0.0, 0.0, 1.0])
                     for cam in cgroup.cameras])

    best_score = -1.0
    best_map = None
    for pairing in _all_perfect_pairings(list(range(n))):
        angles = [np.degrees(np.arccos(np.clip(np.dot(fwd[a], fwd[b]), -1, 1)))
                  for a, b in pairing]
        score = min(angles)  # every pair must face its partner, not just the best one
        if score > best_score:
            best_score = score
            best_map = {}
            for a, b in pairing:
                best_map[a] = b
                best_map[b] = a
    if best_score < min_angle_deg:
        return None
    return best_map


def _triangulate_gdop_weighted_dlt(p2d: np.ndarray, sc: np.ndarray, cgroup,
                                    pair_map: "dict | None", log_fn=print) -> np.ndarray:
    """
    Weighted DLT that adds a geometric-conditioning weight on top of the
    usual sqrt(likelihood) weight (a plain, LOST-free DLT structure), targeting
    a *different* error source than confidence weighting can: on the CUBE rig's two
    opposite-facing camera pairs (cam0<->cam2, cam1<->cam3 at the time this
    was derived; auto-detected per-rig by _detect_opposite_camera_pairs, not
    hardcoded), triangulating with either pair ALONE lands 8-27mm apart
    depending on bodypart, present even on high-confidence gate-passing
    frames (D:\\3D DLC\\CLAUDE.md, 2026-08-27 "two orthogonal opposite-facing
    camera pairs" investigation). This isn't a detection or calibration
    problem — the offset direction isn't a fixed vector (rules out a rigid
    miscalibration) and its magnitude tracks distance from the rig's
    geometric center (rules in conditioning): a near-180-degree pair's own
    2-camera depth estimate is well-conditioned for a point near the rig
    center and degrades as the point moves toward either camera along that
    pair's baseline axis. DLC likelihood has no way to see this — both
    cameras in a poorly-conditioned pair can be, and usually are, highly
    confident.

    This weights each camera's row pair by how well-conditioned ITS pair's
    baseline currently is for the point being triangulated: close to 1.0
    when the (rough, unweighted) estimated point is off that pair's baseline
    axis, down to a floor of 0.08 when the point sits nearly on it. Two
    passes: an initial unweighted DLT locates the point roughly, then the
    conditioning weight is computed from that estimate and a second
    (weighted) DLT solves the final position — the weight needs *some*
    rough position estimate to know which axis the point is near, and a
    single frame's own unweighted solve is already available at essentially
    no extra cost.

    Real-data validation (both real sessions, nose + upper_jaw, full-session
    scale via reprojection error against every gate-passing camera): median
    per-frame reprojection error dropped 15-46%, at a real but small cost of
    +6-10% frame-to-frame jitter and +1-5% p90 (worst-case tail)
    reprojection error. See D:\\3D DLC\\CLAUDE.md for the full real-data
    table this is built from, and D:\\CUBE\\test_gdop_triangulation.py for
    the end-to-end _triangulate_session()-path re-validation with real
    bone-constraint refinement.

    Falls back to plain sqrt(likelihood)-weighted DLT (pair_map=None, or a
    camera whose opposite partner isn't itself a gated-in view this frame)
    rather than guessing — this method should never fire on a rig
    _detect_opposite_camera_pairs() didn't confirm is genuinely built as two
    opposite pairs.

    Parameters
    ----------
    p2d : (N_cams, N_frames, 2) — pixel x/y per camera, post ll_gate NaN-masking
    sc  : (N_cams, N_frames)    — DLC likelihood per camera, post ll_gate zeroing
    cgroup : loaded aniposelib.cameras.CameraGroup
    pair_map : dict[int,int] from _detect_opposite_camera_pairs(), or None

    Returns
    -------
    (N_frames, 3) — zero-filled for frames with fewer than 2 valid cameras or
    a rank-deficient system, matching this codebase's zero-fill-on-failure
    convention.
    """
    N_cams, N_frames, _ = p2d.shape

    und = np.empty_like(p2d)
    for c, cam in enumerate(cgroup.cameras):
        und[c] = cam.undistort_points(np.copy(p2d[c]))
    P_mats = np.stack([cam.get_extrinsics_mat()[:3] for cam in cgroup.cameras])  # (N_cams, 3, 4)

    R_mats = np.stack([cam.get_extrinsics_mat()[:3, :3] for cam in cgroup.cameras])
    t_vecs = np.stack([cam.get_extrinsics_mat()[:3, 3] for cam in cgroup.cameras])
    C_world = np.stack([-R_mats[c].T @ t_vecs[c] for c in range(N_cams)])

    axis_by_pair = {}
    if pair_map:
        for a, b in pair_map.items():
            key = frozenset((a, b))
            if key not in axis_by_pair:
                axis_by_pair[key] = C_world[b] - C_world[a]

    valid_mask = ~np.isnan(p2d[:, :, 0])
    out = np.zeros((N_frames, 3), dtype=np.float64)

    for f in range(N_frames):
        valid_cams = np.where(valid_mask[:, f])[0]
        nv = valid_cams.size
        if nv < 2:
            continue

        def _solve(weights):
            rows = []
            for k, c in enumerate(valid_cams):
                x, y = und[c, f]
                P = P_mats[c]
                w = weights[k]
                rows.append(w * (x * P[2] - P[0]))
                rows.append(w * (y * P[2] - P[1]))
            A = np.vstack(rows)
            if np.linalg.matrix_rank(A) < 3:
                return None
            _, _, vh = np.linalg.svd(A)
            p4 = vh[-1]
            if abs(p4[3]) < 1e-9:
                return None
            return p4[:3] / p4[3]

        ll_weights = [np.sqrt(max(sc[c, f], 1e-6)) for c in valid_cams]

        X0 = _solve(ll_weights)
        if X0 is None:
            continue

        if pair_map is not None:
            gdop_weights = []
            for c in valid_cams:
                partner = pair_map.get(int(c))
                w_gdop = 1.0
                if partner is not None and partner in valid_cams:
                    axis = axis_by_pair[frozenset((c, partner))]
                    axis_n = axis / (np.linalg.norm(axis) + 1e-9)
                    view = X0 - C_world[c]
                    view_n = view / (np.linalg.norm(view) + 1e-9)
                    cos_a = np.clip(abs(np.dot(view_n, axis_n)), 0.0, 1.0)
                    w_gdop = max(np.sqrt(1.0 - cos_a ** 2), 0.08)
                gdop_weights.append(w_gdop)
            combined = [l * g for l, g in zip(ll_weights, gdop_weights)]
            X1 = _solve(combined)
            if X1 is not None:
                out[f] = X1
                continue

        out[f] = X0

    return out


def triangulate_cameras(pts2d: np.ndarray,
                        scores: np.ndarray,
                        calib_toml,
                        use_ransac: bool = False,
                        ransac_threshold: float = 0.5,
                        confidence_weighted: bool = False,
                        gdop_weighted: bool = False,
                        gdop_weighted_bp_idx: "set | None" = None,
                        ll_gate: float = 0.6,
                        median_window: int = 3,
                        log_fn=print) -> np.ndarray:
    """
    Triangulate 2D keypoints from N cameras into 3D world coordinates.

    Parameters
    ----------
    pts2d            : (N_cams, N_frames, N_bp, 2)  — pixel x/y per camera
    scores           : (N_cams, N_frames, N_bp)     — DLC likelihood per keypoint
    calib_toml       : path to aniposelib calibration.toml
    use_ransac       : use RANSAC-based triangulation (robust for occluded keypoints)
    ransac_threshold : reprojection error threshold in pixels for RANSAC inlier test
    confidence_weighted : use a locally-implemented weighted-DLT (LOST) that scales
                       each camera's contribution by its DLC likelihood AND LOST's own
                       geometric weight, instead of trusting every (non-gated) camera
                       equally. Takes precedence over gdop_weighted and use_ransac when
                       more than one is True.
    gdop_weighted    : geometric-conditioning-weighted DLT (_triangulate_gdop_weighted_dlt) —
                       on top of the usual sqrt(likelihood) weight, downweights a camera when
                       the point being triangulated sits near its opposite-pair partner's
                       baseline axis (poorly-conditioned two-view depth direction for a rig
                       built as two near-180-degree camera pairs, auto-detected via
                       _detect_opposite_camera_pairs — never assumed). Targets a different,
                       independent error source than confidence_weighted/RANSAC: real-data
                       validation (D:\\3D DLC\\CLAUDE.md, 2026-08-27) found the two other
                       methods don't help precisely because likelihood has no signal for this
                       conditioning effect, while this weighting cut median full-session
                       reprojection error 15-46% (nose/upper_jaw, both real sessions) at a
                       real but small +6-10% jitter / +1-5% p90-tail cost. Falls back
                       automatically to plain sqrt(likelihood) weighting on any rig
                       _detect_opposite_camera_pairs() doesn't confirm as two opposite pairs.
                       Takes precedence over use_ransac, but not over confidence_weighted,
                       when more than one is True.
    gdop_weighted_bp_idx : optional set of bodypart indices (into pts2d/scores' bp axis) to
                       restrict gdop_weighted to. None (default) = all bodyparts. Real-data
                       validation (D:\\3D DLC\\CLAUDE.md, 2026-08-27) found applying this to
                       every bodypart through the real bone-constraint-refined production path
                       is session-dependent — a big win on one session, a big regression on the
                       other, concentrated in sparse/lateral bodyparts (earbase, thigh) where
                       the weight's own rough position bootstrap is least reliable, and able to
                       leak into connected bodyparts via the shared bone-constraint chain.
                       Scoping to just the validated bodyparts (nose/upper_jaw) avoids both.
    ll_gate          : pre-triangulation drop-gate; any camera view with DLC likelihood
                       below this value is excluded from triangulation (0.0 = off)
    median_window    : kernel size for post-triangulation temporal median filter applied
                       per bodypart per axis to remove single-frame 3D jitter; must be
                       odd; 0 or 1 = off
    log_fn           : callable for log messages

    Returns
    -------
    (N_frames, N_bp, 3)  — X, Y, Z in calibration world space
    """
    try:
        from aniposelib.cameras import CameraGroup
    except ImportError:
        raise ImportError(
            "aniposelib is required for 3D triangulation.\n"
            "Install with: pip install aniposelib")

    cgroup = CameraGroup.load(str(calib_toml))
    _gdop_pair_map = _detect_opposite_camera_pairs(cgroup) if gdop_weighted else None
    if gdop_weighted and _gdop_pair_map is None:
        log_fn("  [WARN] gdop_weighted requested but no opposite-camera-pair rig detected "
               "(need exactly 4 cameras with 2 near-180-degree-facing pairs) — "
               "falling back to plain sqrt(likelihood) weighting")

    N_cams, N_frames, N_bp, _ = pts2d.shape
    if scores.shape != (N_cams, N_frames, N_bp):
        raise ValueError(
            f"scores shape {scores.shape} does not match "
            f"pts2d shape {pts2d.shape[:3]}")

    pts3d = np.zeros((N_frames, N_bp, 3), dtype=np.float64)
    for bp_i in range(N_bp):
        p2d = pts2d[:, :, bp_i, :]   # (N_cams, N_frames, 2)
        sc  = scores[:, :, bp_i]      # (N_cams, N_frames)

        # Pre-triangulation drop-gate: NaN out the pixel coords (not just the score)
        # for any camera view whose DLC likelihood falls below ll_gate, so aniposelib's
        # own NaN-based valid-mask mechanism excludes that view from triangulation
        # (its scores= kwarg silently no-ops — see triangulate() TypeError handling below).
        if ll_gate > 0.0:
            sc = sc.copy()
            gated = sc < ll_gate
            sc[gated] = 0.0
            if np.any(gated):
                p2d = p2d.copy()
                p2d[gated] = np.nan

        p3  = None

        if confidence_weighted:
            try:
                p3 = _triangulate_weighted_dlt(p2d, sc, cgroup, log_fn=log_fn)
            except Exception as e:
                log_fn(f"  [WARN] weighted-DLT triangulate bp {bp_i}: {e}")
                p3 = np.zeros((N_frames, 3), dtype=np.float64)

        if p3 is None and gdop_weighted and (gdop_weighted_bp_idx is None or bp_i in gdop_weighted_bp_idx):
            try:
                p3 = _triangulate_gdop_weighted_dlt(p2d, sc, cgroup, _gdop_pair_map, log_fn=log_fn)
            except Exception as e:
                log_fn(f"  [WARN] gdop-weighted-DLT triangulate bp {bp_i}: {e}")
                p3 = np.zeros((N_frames, 3), dtype=np.float64)

        if p3 is None and use_ransac:
            try:
                # This aniposelib install's triangulate_ransac() just returns
                # self.triangulate_possible(...)'s full 4-tuple
                # (out, picked_vals, points_2d, errors) despite its own
                # docstring claiming an Nx3 array — confirmed by reading the
                # installed cameras.py. Unwrap defensively so this keeps
                # working if a future aniposelib version genuinely returns
                # just the array.
                def _ransac_points(pts, **kw):
                    res = cgroup.triangulate_ransac(pts, **kw)
                    return res[0] if isinstance(res, tuple) else res

                # aniposelib's triangulate_possible() crashes (jnp.stack on an
                # empty per-camera list) for any frame with 0 valid views left
                # after ll_gate NaN-masking — confirmed on real data (2026-08-27,
                # every bodypart in a 4-camera/1500-frame test hit this). Such
                # frames are already this codebase's documented zero-fill-on-
                # failure case (same bucket as <2 valid cams), so they're pulled
                # out of the RANSAC call and zero-filled directly here instead of
                # letting one bad frame's crash zero-fill the ENTIRE bodypart
                # (all frames, including otherwise-good ones) via the generic
                # except below. Frames with >=1 valid camera are passed through
                # to aniposelib unchanged, so this has no effect on any frame
                # that wouldn't already have crashed.
                #
                # IMPORTANT: p3 must stay unassigned (None) until
                # _ransac_points() actually succeeds. An earlier version
                # pre-assigned p3 = zeros(...) here before calling
                # _ransac_points(), so when this aniposelib install's
                # triangulate_ransac() raised its usual TypeError (no
                # scores= kwarg support — the same TypeError the
                # `except (AttributeError, TypeError): pass` below is
                # designed to swallow so this falls through to plain
                # triangulate() further down), p3 was already a real
                # (all-zero) array, not None — so the `if p3 is None`
                # fallback check below was skipped and the ENTIRE bodypart
                # silently zero-filled instead of falling through to plain
                # triangulate as intended. Confirmed on real data
                # (2026-08-27 RANSAC/LOST retest, session
                # 439158_3_48C_0000): every one of 24 bodyparts came back
                # 100% degenerate under use_ransac=True. Fixed by computing
                # the RANSAC result into a local first and only building p3
                # once it succeeds, so any exception leaves p3 as None and
                # the existing fallback logic below behaves as documented.
                zero_cam_frames = np.all(np.isnan(p2d[:, :, 0]), axis=0)
                ok_frames = ~zero_cam_frames
                if np.any(ok_frames):
                    _ransac_out = _ransac_points(
                        p2d[:, ok_frames, :], scores=sc[:, ok_frames],
                        threshold=ransac_threshold,
                        progress=False)
                    p3 = np.zeros((N_frames, 3), dtype=np.float64)
                    p3[ok_frames] = _ransac_out
                else:
                    p3 = np.zeros((N_frames, 3), dtype=np.float64)
            except (AttributeError, TypeError):
                pass          # fall through to standard triangulate below
            except Exception as e:
                log_fn(f"  [WARN] triangulate_ransac bp {bp_i}: {e}")
                p3 = np.zeros((N_frames, 3), dtype=np.float64)

        if p3 is None:
            try:
                p3 = cgroup.triangulate(p2d, scores=sc, progress=False)
            except TypeError:
                # older aniposelib may not accept scores kwarg
                try:
                    p3 = cgroup.triangulate(p2d, progress=False)
                except Exception as e:
                    log_fn(f"  [WARN] triangulate bp {bp_i}: {e}")
                    p3 = np.zeros((N_frames, 3), dtype=np.float64)
            except Exception as e:
                log_fn(f"  [WARN] triangulate bp {bp_i}: {e}")
                p3 = np.zeros((N_frames, 3), dtype=np.float64)

        if p3 is None or p3.shape != (N_frames, 3):
            if p3 is not None:
                log_fn(f"  [WARN] triangulate bp {bp_i}: unexpected shape {p3.shape}, "
                       f"expected ({N_frames}, 3) — zeroing bodypart")
            p3 = np.zeros((N_frames, 3), dtype=np.float64)
        pts3d[:, bp_i, :] = p3

    # Post-triangulation temporal median filter: removes single-frame 3D jitter
    # caused by momentary tracking artifacts that survive RANSAC spatial filtering.
    _mw = int(median_window)
    if _mw > 1:
        if _mw % 2 == 0:
            _mw += 1  # enforce odd kernel
        from scipy.signal import medfilt
        for bp_i in range(N_bp):
            for ax in range(3):
                pts3d[:, bp_i, ax] = medfilt(pts3d[:, bp_i, ax], kernel_size=_mw)

    return pts3d


# Floor for the hind-paw floor-pin's "still on the ground" band: with very
# consistent stance-phase tracking the robust spread can be near-zero, which
# would make the plausible-lift test flag ordinary positional noise as a
# "lift". A small mm floor keeps the band meaningful without a hand-tuned
# per-rig constant -- same role _MIN_BONE_LENGTH_STD_PX plays for bone-length
# consistency checking.
_MIN_FLOOR_BAND_MM = 5.0


def hindpaw_bp_indices(bodyparts: list) -> list:
    """
    Indices of hind-paw/hind-foot bodyparts in *bodyparts*, for use with
    pin_hindpaw_to_floor(). Uses group_bodyparts_by_region()'s Hindlimbs
    classification narrowed to "paw"/"foot" keypoints -- deliberately
    excludes hind knee/ankle/thigh keypoints (also classified as
    Hindlimbs) that do NOT stay planted on the ground, mirroring the same
    restrictive match already used for floor-Z estimation in the cluster
    trajectory plots (see estimate_floor_z_from_paws's caller, which
    prefers bodyparts whose name both starts with a hind-side prefix and
    contains "paw").
    """
    hind = set(group_bodyparts_by_region(bodyparts).get("Hindlimbs", []))
    return [i for i, bp in enumerate(bodyparts)
            if bp in hind and ("paw" in bp.lower() or "foot" in bp.lower())]


def pin_hindpaw_to_floor(pts3d: np.ndarray, scores: np.ndarray,
                          hindpaw_bp_idx: list, fps: float,
                          valid_mask: "np.ndarray | None" = None,
                          ll_gate: float = 0.6, max_lift_s: float = 10.0,
                          max_dual_lift_s: float = 0.2,
                          sid: str = "", log_fn=print
                          ) -> "tuple[np.ndarray, float | None]":
    """
    Soft floor-plane regularizer for hind-paw bodyparts in already-
    triangulated 3D output (world coords, mm -- same convention as
    _apply_displacement_clamp's d_max).

    A mouse's hind paws are essentially always in ground contact; a real
    lift (a step, a brief weight shift, occasional rearing) does not stay
    airborne for more than roughly max_lift_s seconds before the paw is
    back down. A hind-paw Z trajectory that stays elevated LONGER than
    that is far more likely to be a triangulation error (bad calibration
    geometry, occlusion, camera disagreement) than a genuinely sustained
    real lift, so such over-long runs are corrected toward the floor;
    everything else -- short excursions, real steps, brief rears -- is
    left untouched, since this is a plausibility backstop, not a hard
    z=0 clamp.

    max_dual_lift_s: maximum duration (seconds) that BOTH hind paws may
    simultaneously be airborne above floor margin. In normal locomotion,
    at least one hind foot is planted (stance phase); dual-airborne flight
    phases only occur in rare vertical hops (< 0.15s). Any run where ALL
    hind paws remain elevated simultaneously for longer than max_dual_lift_s
    pulls the lower of the hind paws down to floor_z on those frames.

    pts3d          : (N_frames, N_bp, 3), as returned by triangulate_cameras()
    scores         : (N_cams, N_frames, N_bp) DLC likelihood, same array
                     passed into triangulate_cameras()
    hindpaw_bp_idx : bodypart indices (into pts3d's bp axis) to constrain,
                     e.g. from hindpaw_bp_indices(common_bps)
    fps            : session frame rate, to convert max_lift_s to frames
    valid_mask     : optional (N_frames, N_bp) bool, True where that
                     (frame, bodypart) is a real, non-degenerate
                     triangulation (e.g. ~degenerate_mask from the caller's
                     own zero-fill/NaN bookkeeping). Degenerate frames are
                     excluded from both the floor estimate and the
                     plausible-lift run detection -- they're already
                     handled by the caller's own recovery/interpolation
                     path, not real evidence of anything. None = treat
                     every frame as valid.
    ll_gate        : per-camera likelihood gate; a hind-paw (frame, bp) is
                     "confidently observed" if its best camera view clears
                     this -- same convention triangulate_cameras() uses for
                     its own view gating
    max_lift_s     : longest plausible continuous real single hind-paw lift
    max_dual_lift_s: longest plausible continuous simultaneous lift of all
                     hind paws (default 0.2s)

    Returns (new_pts3d, floor_z) -- input is not modified; floor_z is None
    if there was no confidently-observed hind-paw data to estimate it from
    (caller should skip / log, not treat 0.0 as a real floor height).
    """
    out = pts3d.copy()
    hindpaw_bp_idx = list(hindpaw_bp_idx or [])
    if not hindpaw_bp_idx:
        return out, None

    conf = np.max(scores[:, :, hindpaw_bp_idx], axis=0)   # (n_frames, n_hind)
    z = out[:, hindpaw_bp_idx, 2]                          # (n_frames, n_hind)
    if valid_mask is not None:
        v = np.asarray(valid_mask)[:, hindpaw_bp_idx]
    else:
        v = np.ones_like(z, dtype=bool)

    confident = (conf >= ll_gate) & v
    pooled_z = z[confident]
    floor_z = estimate_floor_z_from_paws(pooled_z)
    if floor_z is None:
        log_fn(f"  [{sid}] Hind-paw floor pin: no confidently-observed "
               f"hind-paw frames, skipping")
        return out, None

    # Robust stance-phase spread around the floor mode, to size a "still on
    # the ground" band without assuming any fixed real-world unit scale
    # beyond what estimate_floor_z_from_paws already committed to (mm).
    stance_like = pooled_z[pooled_z <= np.percentile(pooled_z, 60)]
    if stance_like.size >= 10:
        mad = np.median(np.abs(stance_like - np.median(stance_like)))
        stance_std = 1.4826 * mad
    else:
        stance_std = float(np.std(stance_like)) if stance_like.size > 1 else 0.0
    margin = max(3.0 * stance_std, _MIN_FLOOR_BAND_MM)
    ceiling = floor_z + margin

    # Pass 1: Dual simultaneous hind-paw lift constraint.
    # In quadrupeds, at least one hind paw is grounded during normal gaits.
    # If all hind paws are lifted above margin simultaneously for > max_dual_lift_s,
    # pull the lower hind paw to floor_z on those frames.
    n_dual_pinned = 0
    if len(hindpaw_bp_idx) >= 2 and max_dual_lift_s is not None and max_dual_lift_s > 0:
        max_dual_frames = max(1, int(round(max_dual_lift_s * fps)))
        lifted_all = np.ones(out.shape[0], dtype=bool)
        for j, bp_i in enumerate(hindpaw_bp_idx):
            lifted_all &= ((out[:, bp_i, 2] - floor_z) > margin) & v[:, j]
        edges = np.diff(np.r_[0, lifted_all.astype(np.int8), 0])
        starts = np.flatnonzero(edges == 1)
        ends = np.flatnonzero(edges == -1)
        for start, end in zip(starts, ends):
            if (end - start) <= max_dual_frames:
                continue
            for f in range(start, end):
                zs = [out[f, bp_i, 2] for bp_i in hindpaw_bp_idx]
                lower_bp_i = hindpaw_bp_idx[int(np.argmin(zs))]
                out[f, lower_bp_i, 2] = floor_z
            n_dual_pinned += int(end - start)
        if n_dual_pinned:
            log_fn(f"  [{sid}] Hind-paw floor pin: {n_dual_pinned} frame(s) "
                   f"exceeded simultaneous dual-hind-paw lift ceiling "
                   f"({max_dual_lift_s:.2f}s) and lower paw was grounded to floor")

    # Pass 2: Single-paw sustained lift constraint (max_lift_s).
    max_lift_frames = max(1, int(round(max_lift_s * fps)))
    n_pinned_frames = 0
    for j, bp_i in enumerate(hindpaw_bp_idx):
        bp_z = out[:, bp_i, 2]
        bp_conf = conf[:, j]
        bp_valid = v[:, j]
        lifted = ((bp_z - floor_z) > margin) & bp_valid
        # Contiguous True runs of `lifted` -> (start, end) index pairs, end exclusive.
        edges = np.diff(np.r_[0, lifted.astype(np.int8), 0])
        starts = np.flatnonzero(edges == 1)
        ends = np.flatnonzero(edges == -1)
        for start, end in zip(starts, ends):
            if (end - start) <= max_lift_frames:
                continue   # plausible real lift -- leave the triangulated value alone
            seg_conf = bp_conf[start:end]
            seg_z = bp_z[start:end].copy()
            low_conf = seg_conf < ll_gate
            seg_z[low_conf] = floor_z
            seg_z[~low_conf] = np.minimum(seg_z[~low_conf], ceiling)
            out[start:end, bp_i, 2] = seg_z
            n_pinned_frames += int(end - start)

    if n_pinned_frames:
        log_fn(f"  [{sid}] Hind-paw floor pin: floor_z={floor_z:.1f}mm, "
               f"{n_pinned_frames} frame(s) across {len(hindpaw_bp_idx)} "
               f"hind-paw bodypart(s) exceeded the {max_lift_s:.0f}s "
               f"plausible-lift ceiling and were pulled toward the floor")
    return out, floor_z


def _find_group_camera_h5(results_dir: Path) -> "Path | None":
    """
    Find the H5 file inside one camera's {stem}_results/ folder for Doric-
    group fusion -- same preference (prefer *_filtered.h5) as the NESTED-
    layout session scan below, factored out so both share one selection
    rule.
    """
    results_dir = Path(results_dir)
    cands = [h for h in results_dir.rglob("*.h5") if _is_bsoid_ready_h5(h)]
    if not cands:
        cands = [h for h in results_dir.rglob("*.h5") if _is_any_dlc_h5(h)]
    if not cands:
        return None
    cands.sort(key=lambda p: (1 if p.stem.endswith("_filtered") else 0), reverse=True)
    return cands[0]


def load_camera_for_fusion(h5_path: Path, likelihood_thresh: float = 0.3) -> "dict | None":
    """
    Load one camera's H5 for Doric-group fusion (fuse_camera_group_to_
    primary()'s per-camera input shape). Returns None on failure.

    "positions" and "interpolated" start out as the SAME values -- load_dlc_
    file() already temporally-interpolates each bodypart's own low-
    confidence frames (plan Phase 3's "reuses the existing low-likelihood
    interpolation already in the 2D pipeline"), so that output doubles as
    both this camera's own position estimate AND the natural per-bodypart
    fallback when cross-camera fusion also can't resolve a frame.
    "confidences" are the RAW pre-interpolation per-frame likelihoods
    (needed to decide when cross-camera fusion should even be attempted).
    """
    try:
        xy, bodyparts, fps_hint, ll_fracs, flat_held, ll = load_dlc_file(
            h5_path, likelihood_thresh=likelihood_thresh, return_quality=True)
    except Exception:
        return None
    positions = {bp: xy[:, 2 * i:2 * i + 2] for i, bp in enumerate(bodyparts)}
    confidences = {bp: ll[:, i] for i, bp in enumerate(bodyparts)}
    return {
        "positions": positions,
        "confidences": confidences,
        "interpolated": {bp: arr.copy() for bp, arr in positions.items()},
        "bodyparts": bodyparts,
        "fps": fps_hint or 30.0,
    }


def fuse_doric_group_and_write_h5(cam_entries: list, out_h5_path: Path,
                                   conf_threshold: float = 0.6,
                                   tolerance_n_std: float = 3.0,
                                   log_fn=print) -> "Path | None":
    """
    Fuse one Doric 2-4-camera group's H5s (as grouped by
    group_doric_camera_sessions()) into ONE H5 in the same DLC-standard
    MultiIndex format load_dlc_file()/analyze_session_confidence() already
    read (see save_bsoid_h5_csv's format), so it slots into the existing
    conserved-bodyparts/export pipeline exactly like any single-camera
    session's H5.

    Restricted to well-tracked bodyparts only
    (SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS) -- fusing a bodypart already
    known to be untrackable regardless of camera would just produce
    confident-looking noise, worse than leaving it out (see that
    constant's docstring for the real-data validation behind the list).

    Returns None (having logged why) on any failure -- missing H5, unloadable
    H5, no usable primary camera, or no well-tracked bodyparts survive the
    filter. Per cube.py's "block and prompt" flow (ensure_camera_pairs_
    calibrated(), called from cube_3d_dlc.py's Phase 3 homography-fallback
    branch), the caller is
    expected to have already ensured a cached homography exists for this
    group before calling this; a camera with no cached homography for the
    primary pair is simply not used as a fusion source (logged, not fatal)
    -- the group still fuses using whichever camera(s) DO have one.
    """
    cam_data = {}
    for entry in cam_entries:
        h5_path = _find_group_camera_h5(entry["results_dir"])
        if h5_path is None:
            log_fn(f"  [multi-cam] No H5 found in {entry['results_dir']} — skipping fusion for this group")
            return None
        loaded = load_camera_for_fusion(h5_path)
        if loaded is None:
            log_fn(f"  [multi-cam] Could not load {h5_path} — skipping fusion for this group")
            return None
        cam_data[entry["cam_label"]] = loaded

    # Real-world cameras rarely start/stop on the exact same frame -- even a
    # few frames of sync drift between two independently-recording cameras
    # is common (confirmed on real F:\NPY2R_CNTRLS_GCAMP8S\HOTPLATE_12_1
    # data: an 8-frame difference between two cameras of the same session).
    # fuse_camera_group_to_primary() indexes every camera's arrays by the
    # PRIMARY camera's own frame count, so a shorter secondary camera would
    # otherwise raise an IndexError on the trailing frames -- reproduced and
    # confirmed as a real crash against that exact data before this guard
    # was added. Truncate every camera to the shortest one's frame count
    # (cameras are assumed roughly aligned from frame 0 -- true for a
    # trigger-synchronized multi-camera rig; only the tail end drifts).
    frame_counts = {cam: (len(next(iter(d["confidences"].values())))
                          if d["confidences"] else 0)
                    for cam, d in cam_data.items()}
    n_common = min(frame_counts.values()) if frame_counts else 0
    if len(set(frame_counts.values())) > 1:
        log_fn(f"  [multi-cam] Camera frame counts differ ({frame_counts}) -- "
               f"truncating all cameras to the shortest ({n_common} frames) "
               f"before fusion.")
    for d in cam_data.values():
        d["positions"] = {bp: arr[:n_common] for bp, arr in d["positions"].items()}
        d["confidences"] = {bp: arr[:n_common] for bp, arr in d["confidences"].items()}
        d["interpolated"] = {bp: arr[:n_common] for bp, arr in d["interpolated"].items()}

    cam_confidences = {cam: d["confidences"] for cam, d in cam_data.items()}
    primary_cam = select_primary_camera(cam_confidences)
    if primary_cam is None:
        log_fn("  [multi-cam] Could not select a primary camera (no confidence data) — skipping fusion")
        return None

    homographies = {}
    for cam in cam_data:
        if cam == primary_cam:
            continue
        cached = load_cached_homography(camera_pair_rig_id(cam, primary_cam))
        H = resolve_fusion_homography(cached, source_cam=cam, target_cam=primary_cam)
        if H is not None:
            homographies[(cam, primary_cam)] = H
        else:
            log_fn(f"  [multi-cam] No cached homography for {cam}<->{primary_cam} — "
                   f"that camera won't be used as a fusion source for this group")

    all_bps = set()
    for d in cam_data.values():
        all_bps.update(d["bodyparts"])
    well_tracked_bps = sorted(bp for bp in all_bps
                               if bp not in SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS)
    if not well_tracked_bps:
        log_fn("  [multi-cam] No well-tracked bodyparts remain after exclusion filter — skipping fusion")
        return None

    cam_positions = {cam: {bp: d["positions"][bp] for bp in well_tracked_bps if bp in d["positions"]}
                      for cam, d in cam_data.items()}
    cam_confidences_f = {cam: {bp: d["confidences"][bp] for bp in well_tracked_bps if bp in d["confidences"]}
                          for cam, d in cam_data.items()}
    interpolated_fallback = {bp: cam_data[primary_cam]["interpolated"][bp]
                              for bp in well_tracked_bps
                              if bp in cam_data[primary_cam]["interpolated"]}

    skeleton_edges = infer_skeleton(well_tracked_bps)
    fused = fuse_camera_group_to_primary(
        cam_positions, cam_confidences_f, primary_cam, homographies, skeleton_edges,
        interpolated_fallback=interpolated_fallback,
        conf_threshold=conf_threshold, tolerance_n_std=tolerance_n_std)

    bodyparts_out = [bp for bp in well_tracked_bps if bp in fused["positions"]]
    if not bodyparts_out:
        log_fn("  [multi-cam] Fusion produced no usable bodyparts — skipping")
        return None

    n_frames = len(fused["positions"][bodyparts_out[0]])
    cols = pd.MultiIndex.from_product(
        [[BSOID_SCORER_NAME], bodyparts_out, ["x", "y", "likelihood"]],
        names=["scorer", "bodyparts", "coords"])
    data = np.zeros((n_frames, len(bodyparts_out) * 3), dtype=float)
    for i, bp in enumerate(bodyparts_out):
        data[:, 3 * i:3 * i + 2] = fused["positions"][bp]
        data[:, 3 * i + 2] = fused["confidences"][bp]
    df = pd.DataFrame(data, columns=cols)
    out_h5_path = Path(out_h5_path)
    out_h5_path.parent.mkdir(parents=True, exist_ok=True)
    df.to_hdf(str(out_h5_path), key="df_with_missing", mode="w", format="fixed")

    log_fn(f"  [multi-cam] Fused {len(cam_entries)} camera(s) -> {out_h5_path.name} "
           f"({len(bodyparts_out)} bodyparts, primary={primary_cam})")
    return out_h5_path


def _bsoid_prep_discover_and_analyze(source_folder, log_fn=print, export_root=None):
    """
    Discover *_filtered.h5 sessions in source_folder and compute per-bodypart
    confidence stats for each (factored out of run_bsoid_prep so the batch
    variant below can pool stats across several folders before deciding
    which bodyparts to keep).

    export_root: when given, bsoid_root is rooted at
    export_root/folder_name/BSOID_OUTPUT_ROOT instead of
    source_folder/BSOID_OUTPUT_ROOT -- lets every input folder's export land
    under one shared parent (e.g. this run's "CUBE 2 - Preclustering files/")
    instead of nested back inside source_folder itself. Discovery/scanning
    of source_folder for H5s is entirely unaffected either way.

    Returns (folder_name, bsoid_root, all_stats) where
    all_stats = {session_name: (h5_path, {bodypart: {mean, median}})},
    or None if no valid sessions were found (already logged).
    """
    root_path   = Path(source_folder)
    folder_name = root_path.name
    bsoid_root  = (Path(export_root) / folder_name / BSOID_OUTPUT_ROOT
                   if export_root is not None else root_path / BSOID_OUTPUT_ROOT)

    for sd in [BSOID_H5_SUBDIR, BSOID_CSV_SUBDIR,
               BSOID_VIDEO_SUBDIR, BSOID_ANALYSIS_SUBDIR]:
        (bsoid_root / sd).mkdir(parents=True, exist_ok=True)

    # Collect H5 sessions — prefer *_filtered.h5, fall back to any DLC H5
    sessions = []
    # Layout A: flat files in root
    flat = [p for p in sorted(root_path.glob("*.h5"))
            if _is_bsoid_ready_h5(p)]
    if not flat:
        flat = [p for p in sorted(root_path.glob("*.h5"))
                if _is_any_dlc_h5(p)]
    if flat:
        sessions = [(p.stem, p) for p in flat]
        log_fn(f"  Layout: FLAT - {len(sessions)} H5 file(s)")
    else:
        # Layout B: nested *_results/
        # Exclude "3d_adapt_workspace" — the 3D pipeline's DLC-Zoo adaptation
        # cache (cube_3d_dlc.py, adapt_work), not a recording session. It
        # nests per-camera adaptation subfolders (adapt_cam0/, adapt_cam3/,
        # ...) holding raw 2D per-camera H5s alongside the real session
        # subfolders' 3D _3d_filtered.h5 outputs; picking those up as
        # additional "sessions" pooled 2D pixel-space files with 3D
        # world-space files under one conserved-bodyparts list and crashed
        # BSoidEngine.run() downstream on a column-count mismatch.
        # Also exclude "_prep" — both Step 1a and Step 1b's own per-camera
        # DLC inference working directory (one camN_..._results/ subfolder
        # per camera per session, holding the raw per-camera H5s Phase 2
        # produces before triangulation). rglob("*.h5") on this single
        # sibling directory sees every camera's H5 for every session at
        # once and picks one arbitrary file as if "_prep" were itself one
        # session — masking the real per-session subfolders (which have no
        # H5 of their own whenever triangulation hasn't produced
        # {session_id}_3d_filtered.h5 yet) and silently collapsing an
        # entire multi-session run down to a single bogus 2D pseudo-session.
        # Two/three-camera Doric homography fusion is no longer auto-
        # triggered from here — it now runs only via the unified 3D DLC
        # pipeline's fallback path (cube_3d_dlc.py Phase 3, for
        # uncalibrated <=3-camera rigs), which writes its fused output as
        # a normal {session_id}_3d_filtered.h5 discoverable by the plain
        # scan below like any other session. See
        # C:\Users\param\.claude\plans\woolly-cuddling-goose.md.
        for sub in sorted(f for f in root_path.iterdir()
                          if f.is_dir() and f.name != BSOID_OUTPUT_ROOT
                          and f.name != "3d_adapt_workspace"
                          and f.name != "_prep"):
            cands = [h for h in sub.rglob("*.h5") if _is_bsoid_ready_h5(h)]
            if not cands:
                cands = [h for h in sub.rglob("*.h5") if _is_any_dlc_h5(h)]
            if cands:
                cands.sort(key=lambda p: (1 if p.stem.endswith("_filtered") else 0),
                           reverse=True)
                sessions.append((sub.name, cands[0]))
        if sessions:
            log_fn(f"  Layout: NESTED - {len(sessions)} H5 file(s)")

    if not sessions:
        log_fn("  ERROR: No *_filtered.h5 files found.")
        return None

    # A 3D-DLC session's own output folder isn't the only place a leftover
    # per-camera 2D H5 can surface as a spurious "session" here — e.g. Step
    # 0's "CUBE 0" output folder (present in every 3D pipeline run) also
    # nests one camN_..._filtered.h5 per camera per real session one level
    # down, and the nested-layout scan above treats "CUBE 0" itself as one
    # more session subdirectory. Rather than enumerate every non-session
    # folder name by hand (the 3d_adapt_workspace exclusion above only
    # catches one specific case), filter by modality directly: a pixel-space
    # 2D H5 can't share a feature space with world-space 3D H5s (different
    # column count per bodypart), so whichever modality is the minority here
    # is never a real additional session and would otherwise crash
    # BSoidEngine.run() downstream on a column-count mismatch.
    _sess_is_3d = [(sname, h5p, _h5_has_z(h5p)) for sname, h5p in sessions]
    if any(z for _, _, z in _sess_is_3d) and not all(z for _, _, z in _sess_is_3d):
        _dropped = [sname for sname, _, z in _sess_is_3d if not z]
        log_fn(f"  [WARN] {len(_dropped)} discovered session(s) are 2D "
              f"(pixel-space, per-camera) and cannot be pooled with the 3D "
              f"(world-space) sessions found alongside them — likely a "
              f"leftover per-camera DLC file rather than a real additional "
              f"session; excluding: {', '.join(_dropped)}")
        sessions = [(sname, h5p) for sname, h5p, z in _sess_is_3d if z]

    # Analyze confidence
    all_stats = {}
    for sname, h5p in sessions:
        s = analyze_session_confidence(h5p)
        if s:
            all_stats[sname] = (h5p, s)
            log_fn(f"  Analyzed: {h5p.name}")

    if not all_stats:
        log_fn("  ERROR: All H5 files failed to parse.")
        return None

    return folder_name, bsoid_root, all_stats


def _bsoid_prep_determine_conserved(all_stats: dict, min_confidence: float,
                                     conf_metric: str, min_session_frac: float,
                                     min_keep: int, log_fn=print) -> list:
    """
    Shared conserved-bodyparts determination (factored out of run_bsoid_prep).
    Works identically on a single folder's all_stats or on a dict pooled
    across multiple folders — the caller decides the scope; this function
    just applies the same "confidence >= min_confidence in >= min_session_frac
    of sessions" rule to whatever sessions it's given.
    """
    # Universe of bodyparts = union across sessions, preserving first-session
    # order then appending any extras, so a stable column order is kept.
    all_bps_seen: list = []
    for _, ss in all_stats.values():
        for bp in ss.keys():
            if bp not in all_bps_seen:
                all_bps_seen.append(bp)
    n_sessions = len(all_stats)
    _metric = "median" if str(conf_metric).lower().startswith("med") else "mean"

    def _pass_frac(bp: str) -> float:
        n_pass = sum(1 for _, ss in all_stats.values()
                     if bp in ss and ss[bp][_metric] >= min_confidence)
        return n_pass / max(1, n_sessions)

    conserved = [bp for bp in all_bps_seen
                 if _pass_frac(bp) >= float(min_session_frac)]

    # Floor: never collapse below min_keep usable keypoints.  If the threshold
    # rule leaves too few, fall back to the top-N bodyparts ranked by mean
    # per-session confidence so the analysis keeps a workable feature set.
    if len(conserved) < int(min_keep) and all_bps_seen:
        def _mean_conf(bp: str) -> float:
            vals = [ss[bp][_metric] for _, ss in all_stats.values() if bp in ss]
            return float(np.mean(vals)) if vals else 0.0
        ranked = sorted(all_bps_seen, key=_mean_conf, reverse=True)
        target_n = max(int(min_keep), len(conserved))
        conserved = ranked[:target_n]
        log_fn(f"  [VALID-WARN] Only {sum(1 for bp in all_bps_seen if _pass_frac(bp) >= float(min_session_frac))} "
               f"bodypart(s) passed {_metric} >= {min_confidence} in "
               f">= {float(min_session_frac):.0%} of sessions; falling back to "
               f"top-{len(conserved)} by confidence to keep a usable feature set.")

    log_fn(f"  Conserved bodyparts ({len(conserved)}/{len(all_bps_seen)}; "
           f"metric={_metric}, thresh={min_confidence}, "
           f"min_sess_frac={float(min_session_frac):.0%}): {conserved}")

    if not conserved:
        log_fn(f"  ERROR: No bodyparts passed threshold {min_confidence}.")
    return conserved


def _bsoid_prep_locate_video(h5_src: Path) -> "Path | None":
    """Search chain for the video belonging to one H5's session, given the
    ORIGINAL (pre-BSOID-Project_Ready-copy) h5 path -- factored out of
    _bsoid_prep_export() (2026-09-08) so backfill_missing_bsoid_videos() can
    retry the identical search later without duplicating it.
    Priority: labeled/after_adapt -> inference copy in _results/ -> 3D quad
    composite -> any MP4 in the session folder -> original source video ->
    widest same-name-prefix fallback in the source folder's parent.
    Returns None if nothing matches (caller decides how to log/handle that).
    """
    m = _TS_RE.search(h5_src.stem)
    video_src = None
    if m:
        ts = m.group(1)
        for pattern in [f"*{ts}*after_adapt*.mp4",
                        f"*{ts}*labeled*.mp4"]:
            video_src = next(h5_src.parent.glob(pattern), None)
            if video_src:
                break
    if not video_src:
        video_src = (next(h5_src.parent.glob("*after_adapt*.mp4"), None) or
                     next(h5_src.parent.glob("*_labeled.mp4"), None))
    if not video_src:
        # Inference copy: resized_<stem>.mp4 or <stem>.mp4 inside _results/
        base_stem = h5_src.stem.replace("_filtered", "")
        for pat in (f"resized_{base_stem}.mp4", f"{base_stem}.mp4"):
            p = h5_src.parent / pat
            if p.is_file():
                video_src = p
                break
    if not video_src:
        # 3D mode: prefer the quad composite video explicitly
        quad_cands = sorted(h5_src.parent.glob("*_quad.mp4"))
        if quad_cands:
            video_src = quad_cands[0]
    if not video_src:
        # Any MP4 in the session folder (skip pseudo/before_adapt artifacts)
        for p in sorted(h5_src.parent.glob("*.mp4")):
            if not any(x in p.name for x in ("before_adapt", "pseudo")):
                video_src = p
                break
    if not video_src:
        # Original source video in the parent of the _results folder
        base_stem = h5_src.stem.replace("_filtered", "")
        parent_dir = h5_src.parent.parent
        for ext in VIDEO_EXTS:
            p = parent_dir / (base_stem + ext)
            if p.is_file():
                video_src = p
                break
    if not video_src:
        # Widest fallback: any video in the source folder root
        parent_dir = h5_src.parent.parent
        for p in sorted(parent_dir.glob("*")):
            if p.suffix.lower() in VIDEO_EXTS and not p.name.startswith("resized_"):
                video_src = p
                break
    return video_src


def backfill_missing_bsoid_videos(bsoid_root: Path, extra_search_dirs: "list | None" = None,
                                   log_fn=print) -> int:
    """Retry the video-copy step for any already-prepped session in
    `bsoid_root` (a BSOID_Project_Ready folder) that still has no video.

    Why this exists (2026-09-08): _bsoid_prep_export()'s video-copy is a
    ONE-SHOT best-effort at prep time -- if a session's video (e.g. a 3D DLC
    quad composite) had not been rendered yet when prep ran, prep completes
    anyway and every video-dependent output (example clips, labeled videos)
    silently comes up empty later, with no automatic retry. Confirmed as a
    real occurrence on a real dataset (F:\\DAM EXP3 GQ\\CUBE results
    2026-09-07_18-31-17, found 2026-09-08): BSOID prep for 21 of 22 sessions
    completed HOURS before their quad videos were actually rendered.

    Safe to call on any BSOID_Project_Ready folder, any number of times --
    a session already holding a video is always skipped untouched (same
    exists-check _bsoid_prep_export's own copy step uses); this never
    deletes or overwrites anything, only fills gaps.

    Two search passes per still-missing session, in order:
      1. `_bsoid_prep_locate_video()`'s own chain, treating the ALREADY-
         PREPPED h5 (bsoid_root/h5/{short}.h5) as if it were h5_src -- cheap,
         covers the case where a video has since appeared right next to the
         prepped copy itself.
      2. If `extra_search_dirs` is given (e.g. session["video_folders"] from
         the calling GUI session -- for a 3D DLC run this already points at
         each session's own CUBE 1b - 3D DLC output folder, exactly where a
         quad composite video lands): for each dir, look for a subfolder
         whose name matches the session's short name (stripping a trailing
         "_3d" the BSOID short-name convention adds but the 3D DLC per-
         session folder name does not carry), then run the same locate-chain
         rooted there.

    Returns the number of videos actually recovered.
    """
    bsoid_root = Path(bsoid_root)
    h5_dir = bsoid_root / BSOID_H5_SUBDIR
    video_dir = bsoid_root / BSOID_VIDEO_SUBDIR
    if not h5_dir.is_dir():
        return 0
    video_dir.mkdir(parents=True, exist_ok=True)
    extra_search_dirs = [Path(d) for d in (extra_search_dirs or []) if d and Path(d).is_dir()]

    n_recovered = 0
    for h5_dst in sorted(h5_dir.glob("*.h5")):
        short = h5_dst.stem
        video_dst = video_dir / f"{short}.mp4"
        if video_dst.exists():
            continue

        video_src = _bsoid_prep_locate_video(h5_dst)
        if not video_src:
            for d in extra_search_dirs:
                for cand_name in (short, short[:-3] if short.endswith("_3d") else short):
                    cand_dir = d / cand_name
                    if cand_dir.is_dir():
                        video_src = next(cand_dir.glob("*_quad.mp4"), None)
                        if not video_src:
                            video_src = next((p for p in sorted(cand_dir.glob("*.mp4"))
                                               if not any(x in p.name for x in ("before_adapt", "pseudo"))), None)
                    if video_src:
                        break
                if video_src:
                    break
        if not video_src:
            continue

        try:
            shutil.copy2(str(video_src), str(video_dst))
            n_recovered += 1
            log_fn(f"  [backfill] Video recovered: {video_dst.name}  (source: {video_src.name})")
        except Exception as e:
            log_fn(f"  [WARN] [backfill] Could not copy video for {short}: {e}")

    if n_recovered:
        log_fn(f"  [backfill] {n_recovered} previously-missing video(s) recovered in {bsoid_root}.")
    return n_recovered


def _bsoid_prep_export(root_path: Path, folder_name: str, bsoid_root: Path,
                        all_stats: dict, conserved: list, log_fn=print) -> Path:
    """
    Export conserved-bodypart H5/CSV + copy videos + write the confidence
    report for one folder, given an already-determined `conserved` bodypart
    list (factored out of run_bsoid_prep so the same export logic works
    whether `conserved` was computed on this folder alone or pooled across
    several folders for cross-group comparability).
    """
    _n_sessions  = len(all_stats)
    _n_no_video  = 0
    for sname, (h5_src, _) in all_stats.items():
        short = bsoid_short_name(h5_src, folder_name)
        h5_dst  = bsoid_root / BSOID_H5_SUBDIR  / f"{short}.h5"
        csv_dst = bsoid_root / BSOID_CSV_SUBDIR / f"{short}.csv"
        try:
            df = pd.read_hdf(str(h5_src))
            df = _normalise_dlc_df(df)
            save_bsoid_h5_csv(df, h5_dst, csv_dst, conserved)
            log_fn(f"  Exported: {short}")
        except Exception as e:
            log_fn(f"  ERROR exporting {h5_src.name}: {e}")
            continue

        # Copy video for example-clip generation (search chain factored out
        # into _bsoid_prep_locate_video() so backfill_missing_bsoid_videos()
        # below can reuse the exact same logic on a later retry).
        video_src = _bsoid_prep_locate_video(h5_src)
        if video_src:
            dst = bsoid_root / BSOID_VIDEO_SUBDIR / f"{short}.mp4"
            if not dst.exists():
                try:
                    shutil.copy2(str(video_src), str(dst))
                    log_fn(f"  Video copied: {dst.name}  (source: {video_src.name})")
                except Exception as _e:
                    log_fn(f"  [WARN] Could not copy video {video_src.name}: {_e}")
            else:
                log_fn(f"  Video already present: {dst.name}")
        else:
            _n_no_video += 1
            log_fn(f"  [WARN] No video found for {short} — example clips will be skipped")

    if _n_sessions and _n_no_video == _n_sessions:
        # Every session in this folder has no source video -- example clips
        # and labeled videos will be silently skipped for the ENTIRE folder
        # downstream in Step 3, with no further signal there beyond a
        # "0 video(s), 0 paired" discovery line easy to miss in a long log.
        # Loud on purpose: confirmed as a real failure mode (2026-09-07,
        # F:\DAM EXP3 GQ) where a 3D DLC quad-video export never completed
        # for any of 22 sessions (a separate GUI logger-swap bug, now
        # fixed) and this stage then finished "successfully" giving no
        # indication that every video-dependent output would be empty.
        log_fn(f"  [WARN] *** {folder_name}: 0 of {_n_sessions} session(s) "
               f"have a source video — example clips and labeled videos "
               f"will be MISSING for this entire folder. If this is "
               f"unexpected, check that the upstream DLC/3D step actually "
               f"produced its video output (e.g. the per-session quad "
               f"composite for a 3D DLC run) before it was collected here. ***")

    # Confidence report
    rows = []
    for sname, (h5_src, sess_stats) in all_stats.items():
        short = bsoid_short_name(h5_src, folder_name)
        row   = {"Session": short}
        for bp in conserved:
            # A pooled "conserved" bodypart (determined ACROSS every pooled
            # session, e.g. via run_bsoid_prep_batch()) is not guaranteed to
            # be present in every INDIVIDUAL session's own stats — most
            # likely when pooling groups with genuinely different bodypart
            # schemas (e.g. a homography-fused ≤3-camera session's bodypart
            # set, a union across only its own cameras, vs. a calibrated
            # 4-camera triangulated session's set) — .get() avoids a
            # KeyError that would otherwise abort the whole batch export
            # over one session's confidence-report row.
            bp_stats = sess_stats.get(bp)
            row[f"{bp}_mean"]   = bp_stats["mean"]   if bp_stats else float("nan")
            row[f"{bp}_median"] = bp_stats["median"] if bp_stats else float("nan")
        rows.append(row)
    pd.DataFrame(rows).to_csv(
        str(bsoid_root / "bodypart_confidence_report.csv"), index=False)

    cleanup_dlc_byproducts(root_path, log_fn)
    log_fn(f"  B-SOiD prep complete -> {bsoid_root}")
    return bsoid_root


def group_doric_camera_sessions(prep_root, log_fn=None) -> dict:
    """
    Scan *prep_root* (a Step 1a "_prep" folder, one level above every
    video's ``{stem}_results/`` output) for ``session_meta.json`` sidecars
    and group them by ``session_id``.

    Returns ``{session_id: [{"cam_label": str, "results_dir": Path,
    "source_video": str}, ...]}`` -- entries within each session_id are
    sorted by cam_label. Folders without a sidecar (ordinary single-camera
    results) are not represented here at all; the caller's existing logic
    for those is completely unaffected.

    **No longer called from run_bsoid_prep_batch()** (removed 2026-09-07
    consolidation, C:\\Users\\param\\.claude\\plans\\
    woolly-cuddling-goose.md) -- Two/Three-Camera Homography Fusion is now
    reachable only via cube_3d_dlc.py's Phase 3 fallback
    (_fuse_session_homography), which builds its own cam_entries directly
    from Phase 2's known per-camera H5 paths rather than sidecar files,
    and doesn't need this function at all. This is a pure, read-only query
    function, kept for its own unit tests (the 2-to-4-camera grouping and
    the 5+-camera diagnostic below) and as reusable infrastructure should
    a sidecar-based discovery path ever be needed again -- nothing in
    production writes session_meta.json sidecars any more.

    For any session_id with 5 or more grouped cameras (this function does
    not itself check for calibration -- the plan's Step 1b calibrated path
    is the existing, unrelated way to handle a real calibrated rig), logs a
    non-blocking diagnostic via *log_fn* directing the user to Step 1b, per
    the plan's §2.2 default behavior for that case. 4-camera groups ARE
    fused by this path (2026-09-07 scope extension, per user request,
    following real-data validation on a real 4-camera rig -- see the plan
    doc's "Camera-geometry validation" section) when no calibration exists
    for that rig; a 4-camera rig that DOES have a calibration.toml should
    still prefer Step 1b's real triangulation, which this function has no
    way to know about -- the caller (Step 2's grouping/prompting logic) is
    responsible for that choice, not this pure discovery function.
    """
    prep_root = Path(prep_root)
    sessions: dict[str, list] = {}
    for meta_path in sorted(prep_root.glob("*_results/session_meta.json")):
        try:
            meta = json.loads(meta_path.read_text())
        except Exception:
            continue
        session_id = meta.get("session_id")
        cam_label = meta.get("cam_label")
        if not session_id or not cam_label:
            continue
        sessions.setdefault(session_id, []).append({
            "cam_label": cam_label,
            "results_dir": meta_path.parent,
            "source_video": meta.get("source_video", ""),
        })

    for session_id, cams in sessions.items():
        cams.sort(key=lambda c: c["cam_label"])
        if len(cams) >= 5 and log_fn is not None:
            log_fn(
                f"  [multi-cam] Session '{session_id}' has {len(cams)} cameras -- "
                f"5+-camera Doric rigs are not handled by the 2-4-camera fusion "
                f"path. Use Step 1b (calibrated 3D DLC) for this rig instead.")

    return sessions


def run_bsoid_prep(source_folder, log_fn=print,
                   min_confidence: float = MIN_BODYPART_CONFIDENCE,
                   conf_metric: str = "median",
                   min_session_frac: float = 0.85,
                   min_keep: int = 6,
                   export_root=None) -> Path | None:
    """
    Scan source_folder for *_filtered.h5 files, filter to conserved bodyparts,
    export BSOID_Project_Ready/ structure.

    Bodypart conservation policy (single-view-camera friendly)
    ----------------------------------------------------------
    A bodypart is conserved if its per-session confidence (``conf_metric``,
    "median" or "mean") is >= ``min_confidence`` in at least ``min_session_frac``
    of the folder's sessions — NOT in every session.  This prevents one
    poorly-tracked recording from deleting a keypoint for the whole group, which
    is common with single-view setups where occlusion transiently tanks the mean.
    If fewer than ``min_keep`` bodyparts pass, the top-N keypoints by confidence
    are kept instead (with a warning) so the feature space never silently
    collapses to a handful of points.

    NOTE: when pre-processing several folders that will later be combined into
    one cross-group analysis (e.g. multiple experimental groups/conditions),
    prefer run_bsoid_prep_batch() instead — it makes this same decision ONCE,
    pooled across every folder's sessions, rather than each folder choosing its
    own conserved set independently and relying on a later intersection to
    reconcile them (which compounds three separately-conservative cuts into one
    overly aggressive one). This function is kept as-is for single-folder use.

    Returns path to BSOID_Project_Ready or None on failure.
    """
    discovered = _bsoid_prep_discover_and_analyze(source_folder, log_fn, export_root=export_root)
    if discovered is None:
        return None
    folder_name, bsoid_root, all_stats = discovered

    conserved = _bsoid_prep_determine_conserved(
        all_stats, min_confidence, conf_metric, min_session_frac, min_keep, log_fn)
    if not conserved:
        return None

    return _bsoid_prep_export(Path(source_folder), folder_name, bsoid_root,
                               all_stats, conserved, log_fn)


def run_bsoid_prep_batch(source_folders: list, log_fn=print,
                         min_confidence: float = MIN_BODYPART_CONFIDENCE,
                         conf_metric: str = "median",
                         min_session_frac: float = 0.85,
                         min_keep: int = 6,
                         export_root=None) -> list:
    """
    Pre-process multiple source folders (e.g. one per experimental
    group/condition that will be combined into a single cross-group CUBE
    analysis) with ONE shared conserved-bodyparts list, computed once from
    every session across every folder pooled together.

    Why (Aug 2026): the per-folder run_bsoid_prep() + a later cross-group
    bodypart intersection (in BSoidEngine.run(), Step 2) both individually
    make sense, but composed they compound. On a real 3-group dataset (7
    sessions/group), each folder's independent 60%-of-its-own-sessions cut
    kept 27/27/24 bodyparts; intersecting those three already-conservative
    sets left only 22 shared. Pooling the identical rule across all 21
    sessions in one pass avoids that compounding -- but at the original 60%
    threshold it then pooled in 6 bodyparts (up to 71% bad frames in some
    sessions) that individual folders had correctly excluded, and which
    measurably hurt clustering (DBCV 0.370->0.164, mean seed-stability ARI
    0.620->0.427 in real testing). Raising min_session_frac's default to
    0.85 keeps the pooling fix (still ONE shared list, comparability
    unaffected either way) while excluding those specific bodyparts again,
    recovering DBCV/ARI. Tune per-dataset via the GUI's "BP keep if passes
    >=" (Advanced Settings, DLC & Prep) if your data's tracking quality
    differs.

    export_root: when given, every folder's bsoid_root is rooted at
    export_root/{folder_name}/BSOID_Project_Ready instead of nested inside
    that folder itself -- lets all N input folders' exports land under one
    shared parent (e.g. this run's "CUBE 2 - Preclustering files/") instead
    of scattered back inside each of their own source locations.

    Returns [bsoid_root, ...], one per folder that had valid sessions
    (in source_folders order; folders that failed discovery are omitted,
    matching run_bsoid_prep's None-on-failure convention for a single
    folder).
    """
    discovered = []
    for folder in source_folders:
        log_fn(f"  Scanning: {Path(folder).name}")
        d = _bsoid_prep_discover_and_analyze(folder, log_fn, export_root=export_root)
        if d is not None:
            discovered.append((folder, *d))
    if not discovered:
        return []

    # Pool every session's stats across all folders for a single, shared
    # conserved-bodyparts determination. Keyed by (folder_name, session) so
    # identically-named sessions in different groups can't collide.
    pooled_stats: dict = {}
    for folder, folder_name, bsoid_root, all_stats in discovered:
        for sname, entry in all_stats.items():
            pooled_stats[f"{folder_name}::{sname}"] = entry

    log_fn(f"\n  Pooling {len(pooled_stats)} session(s) across "
           f"{len(discovered)} folder(s) for a single shared "
           f"conserved-bodyparts determination (guarantees cross-group "
           f"comparability without compounding independent per-folder cuts):")
    conserved = _bsoid_prep_determine_conserved(
        pooled_stats, min_confidence, conf_metric, min_session_frac, min_keep,
        log_fn)
    if not conserved:
        return []

    roots = []
    for folder, folder_name, bsoid_root, all_stats in discovered:
        log_fn(f"\n  Exporting: {folder_name}")
        r = _bsoid_prep_export(Path(folder), folder_name, bsoid_root,
                               all_stats, conserved, log_fn)
        if r:
            roots.append(r)
    return roots


def reorganize_plots_folder(plots_dir, logger=None) -> None:
    """Sort every file directly under plots_dir into topic subfolders.

    Called once at the very end of BSoidEngine.run() (after every plot has
    been written) so a run's plots/ folder reads as a handful of labeled
    subfolders instead of 20-30 PNGs/HTMLs thrown in flat. Pure file-move --
    never touches plot-generation code, so a disabled/failed reorganize pass
    leaves the pre-existing flat layout intact (fail-soft, not fail-open).

    Two tiers:

    1. Per-session plots (one file per recording, e.g. "ethogram_OFT_11.png",
       "hmm_ethogram_OFT_11.png", "cluster_durations_OFT_11.png",
       "cluster_stats_OFT_11.png") dominate a typical multi-session run --
       4 files x N sessions can be 50+ files on their own. Lumping them into
       one topic bucket wouldn't actually be cleaner, so each goes to
       per_session/<session_name>/<original filename> instead, keeping one
       session's whole diagnostic set together.
    2. Everything else (population-level: UMAP, transitions, HMM summary,
       classifier, QC, kinetics, validation) is bucketed by filename
       substring, checked in order below (first match wins, more specific
       before generic). Anything unmatched lands in misc/ rather than being
       silently skipped, so a future plot filename this list hasn't been
       taught about is still findable, just not perfectly sorted.
    """
    log = logger or (lambda *a, **k: None)
    plots_dir = Path(plots_dir)
    if not plots_dir.is_dir():
        return

    # Longest/most-specific prefix first -- "hmm_ethogram_" must be tested
    # before "ethogram_" or it would never match.
    _PER_SESSION_PREFIXES = [
        "hmm_ethogram_",
        "ethogram_",
        "cluster_durations_",
        "cluster_stats_",
    ]

    # (substring, subfolder) -- order matters, first match wins.
    _CATEGORY_RULES = [
        ("hmm_",                 "hmm"),
        ("dwell_time",           "hmm"),
        ("umap",                 "umap"),
        ("transition",           "transitions"),
        ("sankey",               "transitions"),
        ("state_space",          "transitions"),
        ("confusion_matrix",     "classifier"),
        ("cv_accuracy",          "classifier"),
        ("likelihood_qc",        "qc"),
        ("feature_quality",      "qc"),
        ("kinetic",              "kinetics"),
        ("cluster",              "clustering"),
        ("split_merge",          "clustering"),
        ("validation_dashboard", "validation"),
        ("publication_metrics",  "validation"),
    ]

    moved, failed = 0, 0
    for entry in list(plots_dir.iterdir()):
        if entry.is_dir():
            continue  # a previous run's subfolders (or anything else) stay put

        session_name = None
        for prefix in _PER_SESSION_PREFIXES:
            if entry.name.startswith(prefix):
                session_name = entry.stem[len(prefix):]
                break

        if session_name:
            dest_dir = plots_dir / "per_session" / session_name
        else:
            name_lower = entry.name.lower()
            dest_sub = "misc"
            for substr, sub in _CATEGORY_RULES:
                if substr in name_lower:
                    dest_sub = sub
                    break
            dest_dir = plots_dir / dest_sub

        try:
            dest_dir.mkdir(parents=True, exist_ok=True)
            shutil.move(str(entry), str(dest_dir / entry.name))
            moved += 1
        except Exception:
            failed += 1
            log(f"  [WARN] reorganize_plots_folder: could not move "
                f"{entry.name}: {traceback.format_exc()}")

    if moved or failed:
        log(f"  [plots] Reorganized {moved} file(s) into subfolders"
            f"{f' ({failed} failed)' if failed else ''}")


#
#  MAIN ENGINE CLASS
#

class _DebugCaptureAbort(Exception):
    """Raised only when cfg["_debug_capture_abort"] is explicitly set
    alongside cfg["_debug_capture_path"] -- see the capture hook inside
    BSoidEngine.run() (right after feats_sc is built, before UMAP) for what
    it saves. Lets an exploration script reach "the real training-stage
    feature matrix, exactly as this dataset+cfg would produce it" without
    paying for UMAP/HDBSCAN/consensus/MLP/HMM/export on every call -- built
    Sep 2026 after repeatedly hand-rolling the equivalent as a throwaway
    monkeypatch-and-abort script per investigation (see the EPM Head-Dip
    fragmentation investigation). A caller should catch this specific
    exception, not a bare Exception, so a genuine mid-run failure elsewhere
    is never mistaken for a successful capture."""
    pass


class BSoidEngine:
    """
    Programmatic B-SOiD pipeline - no GUI required.

    Parameters
    ----------
    csv_folder   : folder with BSOID-ready CSV or H5 files
    video_folder : folder with source videos (matched by stem/timestamp)
    output_dir   : all outputs written here
    fps          : recording FPS (if None: guessed from filename or 30)
    logger       : PipelineLogger or any callable(str)
    progress_cb  : callable(current: int, total: int) - optional
    cfg          : dict of hyperparameter overrides
    """

    # ── Defaults ───────────────────────────────────────────────────────────────
    # Where CUBE follows B-SOiD (Hsu A.I. & Yttri E.A., 2021, Nat. Commun.
    # 12:5188) the reference value is used (likelihood_thresh, umap_n_neighbors,
    # umap_n_components, mlp_hidden, train_frac).  CUBE-specific parameters
    # (V2 multi-scale/angular features, umap_min_dist, the HDBSCAN sweep, the
    # post-hoc HMM) are intentional extensions — see the run() [AUDIT] block,
    # which reports them separately rather than claiming exact faithfulness.
    # Only min_epoch_dur_s / max_epoch_dur_s are intended as primary user inputs.
    # This is the canonical default set; the GUI (cube.py) derives from it.
    DEFAULTS = dict(
        # ── Guided labelling (GUIDED_LABELLING_PLAN.md, P4) ───────────────────────
        # guided_labels_path: path to a guided/user_labels.json written by the Guided labelling tab ("" = none =
        #   a blind run, byte-identical to before). Set by the tab's "Use my labels in the next CUBE run" option
        #   (never found by silent file discovery). A missing/corrupt/inconsistent file logs a WARN and runs blind.
        # guided_constraints_enabled: kill switch. False = ignore any attached labels (exactly the blind run).
        #   With labels attached the constraints only ever VETO (prune / merge / split / reclaim) or add split
        #   candidates the normal gates must still accept; they never force a change.
        # guided_min_labelled_bins: user-labelled bins of one behaviour a cluster needs before the labels count as
        #   evidence there (protect from pruning, block merges, judge splits, guard reclaim).
        # guided_split_purity_gain: minimum rise in user-label purity a split of a mixed cluster must deliver.
        guided_labels_path          = "",
        guided_constraints_enabled  = True,
        guided_min_labelled_bins    = 5,
        guided_split_purity_gain    = 0.05,
        # guided_rescue_turned_away: a user-labelled bin inside a turned-away stretch is ground truth: it is
        #   clustered like any other bin instead of being excluded and relabelled "Turned Away". Needs labels
        #   attached; inert otherwise. False = keep the old exclusion even for labelled bins.
        guided_rescue_turned_away   = True,
        # guided_min_labelled_frac / guided_pure_thresh: a behaviour only counts as evidence in a cluster when it
        #   has at least max(guided_min_labelled_bins, this fraction of the cluster) labelled bins (so five labels
        #   cannot vouch for a 5000-bin cluster); a cluster is "user-pure" (never split) at this label purity.
        guided_min_labelled_frac    = 0.005,
        guided_pure_thresh          = 0.9,
        # guided_dynamics_enabled: the user's labelled bout lengths and behaviour->behaviour transitions inform the
        #   HMM transition prior (self-transition pulled toward the labelled median bout length, observed
        #   transitions made likelier). A behaviour needs >= guided_min_bouts labelled bouts to count; the blend /
        #   boost strengths are modest. Also writes model/guided_dynamics.json (labelled vs final bout lengths and
        #   whether labelled behaviour changes coincide with label changes / feature-space "cliffs"). Inert
        #   without labels.
        guided_dynamics_enabled     = True,
        guided_min_bouts            = 5,
        guided_dynamics_blend       = 0.5,
        guided_transition_boost     = 1.0,
        # guided_poor_recluster_enabled: poorly tracked bins (originally turned-away, or in the lowest
        #   guided_poor_quantile of per-bin likelihood) are reclustered AMONG THEMSELVES; a sub-cluster becomes a
        #   cluster only if the user's labels prove it pure. A behaviour may then be made of several clusters.
        guided_poor_recluster_enabled = True,
        # guided_labelled_plots_enabled: with labels attached, name every cluster by the user's behaviour on the
        #   hierarchy / trajectory plots (a behaviour of several clusters is bracketed), add per-behaviour
        #   trajectories under plots/guided/, and write cluster_behaviour_mapping.tsv + behaviour_groups.json
        #   for the Behaviour Analyser. Inert without labels.
        guided_labelled_plots_enabled = True,
        # guided_behaviour_export_enabled: with labels attached, also classify the user's behaviours DIRECTLY from the
        #   labels (random forest on windowed features, turned-away bins included) and write 'CUBE 3b - Guided
        #   behaviours' next to this folder: a behaviour per time bin plus sub-type clusters inside each behaviour, in
        #   the Behaviour Analyser's format. Inert without labels. See cube_guided_behaviour.py.
        guided_behaviour_export_enabled = True,
        # guided_behaviour_min_confidence: a bin only gets one of your behaviours when the classifier is at least this
        #   sure (else "Other" = it keeps CUBE's own cluster). Lower = more coverage, more leakage. 0.5 default.
        guided_behaviour_min_confidence = 0.5,
        # guided_cluster_gate_*: opt-in cluster-evidence gate on the guided behaviours (cube_guided_gate.py): a behaviour is
        # vetoed in blind clusters whose labels say it is something else. strength = exponent on the cluster factor,
        # prior = shrinkage towards 'no information' for clusters with few labels.
        guided_cluster_gate_enabled = False,
        guided_cluster_gate_strength = 1.0,
        guided_cluster_gate_prior = 5.0,
        guided_poor_quantile        = 0.2,
        likelihood_thresh     = 0.3,    # DLC confidence threshold (pub. default)
        max_interp_gap_sec    = 0.5,    # occlusions longer than this are held
                                        # flat, not ramped (0 = legacy interp)
        feature_bad_bp_thresh = 0.40,   # drop bodyparts whose mean bad-frame
                                        # fraction (< likelihood_thresh) across
                                        # all sessions meets or exceeds this
                                        # value.  0 = disabled.  Single-camera
                                        # rigs occlude/degrade a bodypart's
                                        # tracking for up to ~20% of a session
                                        # in practice (measured via real
                                        # bodypart_confidence_report data and
                                        # the visibility-feature turned-away
                                        # detector, Aug 2026 -- not the 40-70%
                                        # figure this comment previously cited,
                                        # which overstated typical occlusion
                                        # frequency); excluding chronically
                                        # occluded bodyparts keeps the feature
                                        # space clean and prevents HDBSCAN
                                        # noise inflation.
        feature_bad_bp_thresh_with_visibility = 0.70,
                                        # Governs bodypart dropping INSTEAD of
                                        # feature_bad_bp_thresh above, whenever
                                        # visibility_features_enabled=True (the
                                        # default). Real confidence-report data
                                        # (bodypart_confidence_report, Aug 2026)
                                        # showed limb-joint keypoints (thigh/
                                        # knee) and neck/throat/back-middle
                                        # regularly average 0.27-0.41 confidence
                                        # per session -- close to or under the
                                        # plain 0.40 threshold even in normal
                                        # tracking, while head/mouth keypoints
                                        # stayed >=0.45 even in the worst
                                        # session. Dropping a limb joint
                                        # permanently removes real behavioural
                                        # signal from every well-tracked frame
                                        # too, directly undermining bodypart_
                                        # weights up-weighting of that same
                                        # region. With visibility features on,
                                        # low-confidence bins (occlusion, animal
                                        # turned away) are instead isolated into
                                        # their own cluster (see compute_
                                        # visibility_features) rather than
                                        # requiring the bodypart's removal, so
                                        # only near-unusable bodyparts (>=70%
                                        # bad) need dropping here. Set equal to
                                        # feature_bad_bp_thresh to restore the
                                        # stricter legacy drop behaviour even
                                        # with visibility features on.
        feature_dedup_jitter  = 1e-4,   # tiny Gaussian noise added to the UMAP
                                        # training subsample (raw feature units)
                                        # BEFORE standardisation.  Breaks any
                                        # exact-duplicate feature vectors so
                                        # HDBSCAN's mutual-reachability graph
                                        # stays non-degenerate.
                                        # 1e-4 raw units → ~2e-6 post-scaling
                                        # for typical distance features — fully
                                        # imperceptible to cluster geometry.
        flat_held_bp_frac_thresh = 0.5, # fraction of kept bodyparts that must be
                                        # simultaneously flat-held in a 100 ms bin
                                        # before that bin is excluded from UMAP /
                                        # HDBSCAN training.  0.5 = majority occlusion
                                        # (whole-animal dropout).  Set to 0.0 to
                                        # disable exclusion entirely.  Single-camera
                                        # recordings with natural individual-bodypart
                                        # occlusion rarely exceed 0.15–0.25, so the
                                        # 0.5 default leaves those bins in training.
                                        # 0 = disabled.
        boxcar_win_sec        = 0.07,   # 70 ms boxcar smoothing (pub. default)
        train_frac            = 0.75,   # fraction of bins for UMAP when N > threshold.
                                        # Changed from 0.3 (2026-09-04, HEAD_DIP_FEATURE_
                                        # EMBEDDING_INVESTIGATION_2026-09-03.md Experiments
                                        # 8-9/13): real-data validated as the best combined
                                        # operating point with hdbscan_selection_mode=
                                        # "occurrence_persistence" (self-selects pct=4 there,
                                        # +28% over standard B-SOiD's own raw HDBSCAN
                                        # partition) -- raising train_frac further (0.7, 1.0)
                                        # was tested and found non-monotonic/worse.
        subsample_strategy    = "iid",  # "iid" (today's exact rng.choice behavior) or
                                        # "block" (contiguous-block bootstrap -- see
                                        # BLOCK_BOOTSTRAP_SUBSAMPLING_PLAN.md). Only
                                        # consulted when n_good > umap_full_thresh.
                                        # Opt-in only: never flips automatically, must
                                        # be set explicitly by the caller/GUI.
        subsample_block_len_bins = 17,  # contiguous block length (bins) for
                                        # subsample_strategy="block" -- sized around
                                        # this codebase's own validated short-bout
                                        # range (14-18 bins: Head Dip, Rearing, Stretch).
        umap_full_thresh      = 10_000, # use full data for UMAP when N <= this
        umap_n_neighbors      = 0,      # 0 = auto (scales with recording length); >0 = fixed
        umap_n_components     = 3,      # 3-D UMAP embedding (pub. default)
        umap_min_dist         = 0.1,    # UMAP/B-SOiD convention. (<0.05 packs points so
                                        # tightly that HDBSCAN's DBCV becomes non-finite —
                                        # see the degenerate-DBCV fallback in run_hdbscan.
                                        # compat_mode="legacy_v2" restores the old 0.0.)
        umap_random_state     = 42,     # reproducibility seed
        hdbscan_metric        = "euclidean",  # (pub. default)
        # hdbscan_method: "leaf" (changed from "both" 2026-09-04). Real EPM
        #   evidence (Head Dip rare-behavior investigation): "eom" collapsed
        #   to 2-3 degenerate giant clusters across the ENTIRE tested
        #   min_cluster_size range (pct 2-50 of bins) on this dataset's own
        #   embedding -- never once produced a usable multi-cluster
        #   partition. Every real multi-cluster candidate CUBE has ever
        #   selected on this dataset came from "leaf". Forcing "leaf" only
        #   also roughly halves the sweep cost (40 candidates instead of 80).
        #   CAVEAT, stated plainly: validated on ONE dataset (EPM) only --
        #   not yet checked whether "eom" is dead weight on Damien or any
        #   other dataset the way it is here. If "eom" turns out to matter
        #   elsewhere, this default should be revisited per-dataset, not
        #   assumed universal from this one result. Set to "both" to restore
        #   the pre-2026-09-04 behavior exactly.
        hdbscan_method        = "leaf",
        # mlp_classifier: "random_forest" (default since 2026-09-07, was "mlp")
        #   -- RandomForestClassifier(class_weight=rf_class_weight) in place
        #   of MLPClassifier in train_mlp(). Real-data validated on OFT:
        #   sklearn's MLPClassifier has no class_weight/sample_weight support
        #   at all, so it can't down-weight majority clusters -- real OFT
        #   training data has 70.6x class imbalance between the largest and
        #   smallest cluster. RandomForest(balanced) gave a real, standalone
        #   Coverage/Leakage/Ratio improvement (median Ratio 0.1980->0.2357,
        #   ~19% relative) at statistically the same CV accuracy (~0.89 both
        #   ways) -- the gain redistributes which behavior benefits rather
        #   than being "a better classifier overall" (see per-behavior tables,
        #   BSOID_IMPROVEMENT_BASELINE_AND_EXPERIMENT_PLAN.md §5.6). Set to
        #   "mlp" to restore the old MLPClassifier behavior exactly.
        mlp_classifier        = "random_forest",
        rf_n_estimators       = 300,
        rf_class_weight       = "balanced",    # None (or "") -> unweighted RandomForest
        mlp_hidden            = "100,50",     # 2-layer MLP (pub. default) -- only used
                                        # when mlp_classifier="mlp"
        mlp_activation        = "logistic",   # B-SoiD's own tuned default (see train_mlp
                                        # docstring); only used when mlp_classifier="mlp"
        mlp_max_iter          = 1000,          # only used when mlp_classifier="mlp"
        mlp_confidence_thresh = 0.0,    # 0 = always assign; >0 = low-confidence
                                        # bins become -1 (unclassified) at inference
        cv_folds              = 5,
        # ── HDBSCAN options ───────────────────────────────────────────────────
        hdbscan_methods_to_try = "eom,leaf",  # both tried; selection logic picks best
        # hdbscan_tree_reuse_enabled (Option 3, HDBSCAN sweep perf, Aug 2026):
        #   True (default) reuses the single-linkage tree/MST across every
        #   swept candidate sharing the same min_samples bucket, instead of
        #   rebuilding it from scratch per candidate -- tree construction
        #   depends only on min_samples/metric, never on min_cluster_size/
        #   cluster_selection_method. Only the winning candidate is ever
        #   refit into a real HDBSCAN object; output is equivalence-tested
        #   to be identical to the pre-change behaviour. Set False to use
        #   the verbatim pre-change per-candidate full-refit path
        #   (_fit_one_legacy) as an escape hatch.
        hdbscan_tree_reuse_enabled = True,
        # ── Cluster count guidance ────────────────────────────────────────────
        target_n_clusters     = 0,    # 0 = auto; >0 = user-requested cluster count
        preferred_clusters_lo = 15,   # auto-mode: prefer cluster count ≥ this
        preferred_clusters_hi = 25,   # auto-mode: prefer cluster count ≤ this
        # ── Rare-cluster pruning ──────────────────────────────────────────────
        # Clusters whose share of total analysis time is below this threshold
        # are merged into noise before MLP training.  Prevents fragment clusters
        # driven by a handful of frames from polluting the behaviour space.
        # Expressed as a percentage of total bins (0.2 = 0.2 %).  Set to 0 to disable.
        min_cluster_freq      = 0.2,
        # ── HDBSCAN sweep tuning ──────────────────────────────────────────────
        # hdbscan_pct_lo : lower bound for the min_cluster_size sweep, in units
        #   of 0.1%-of-bins.  0 = auto (≥ 0.2% of bins).  Increase to 5 to restore
        #   the original 0.5%-of-bins floor if too many noise-clusters appear.
        # hdbscan_pct_hi : upper bound (5.0% of bins).  Rarely needs adjustment.
        # hdbscan_dbcv_thresh : candidates must have DBCV ≥ this fraction of the
        #   best observed DBCV.  Lower = more cluster-diversity tolerated (0.65),
        #   higher = stricter quality gate (0.75 was the original hardcoded value).
        # hdbscan_diversity_bonus : weight added to DBCV when ranking solutions that
        #   have heterogeneous cluster sizes.  0.10 gives a 10% bonus per unit of
        #   size CV, rewarding solutions that include both brief and sustained clusters.
        hdbscan_pct_lo          = 0,    # 0 = auto; >0 overrides (0.1%-of-bins units)
        hdbscan_pct_hi          = 50,   # 5.0% of bins
        hdbscan_dbcv_thresh     = 0.65, # DBCV fraction — was hardcoded 0.75
        hdbscan_diversity_bonus = 0.10, # cluster-size CV reward weight
        # hdbscan_consistency_weight (opt-in, Sep 2026): additive bonus in
        #   run_hdbscan()'s _sel_score(), same pattern as hdbscan_diversity_
        #   bonus/hdbscan_fine_bias above -- weight * _cluster_consistency_
        #   score(labels), where consistency is a PURE within-cluster
        #   cohesion measure: per-CLUSTER mean distance from each point to
        #   its own cluster's centroid in the swept embedding (normalized by
        #   the embedding's own per-axis std, inverted so higher = tighter),
        #   then the MEDIAN of that per-cluster value ACROSS clusters --
        #   deliberately not a point- or size-weighted mean across the whole
        #   partition. A mean lets a handful of oversized/degenerate
        #   clusters dominate the number either way; the median instead asks
        #   "how good is a typical cluster in this partition," so a
        #   partition with many internally-consistent clusters and one weak
        #   one isn't penalized as if every cluster were mediocre, and one
        #   very strong cluster can't mask several weak ones either. Also
        #   deliberately NOT DBCV/silhouette, which both reward separation
        #   as well as cohesion. Motivated by real user testing (also behind
        #   consensus_intra_weight above): a cluster's own internal
        #   consistency is the stronger predictor of "is this a real
        #   behavior" than how well-separated it is from its neighbors.
        #   Only ever evaluated for candidates already inside
        #   _sel_score's caller's own filtered set (floor_ok/in_range/
        #   qualified -- i.e. already within hdbscan_dbcv_thresh of the best
        #   DBCV, or already clearing preferred_clusters_lo), so this is a
        #   secondary ranking signal among already-qualified candidates, not
        #   a replacement for the DBCV floor itself; target_n mode (a
        #   different selection path, sorts by distance-to-target then raw
        #   DBCV) is unaffected. A small value (e.g. 0.02-0.05) approximates
        #   a tie-breaker that only matters when candidates are close in
        #   DBCV; a larger value lets consistency dominate ranking outright
        #   -- one knob spans both framings rather than two separate modes.
        #   0.0 (default) is a true no-op: _cluster_consistency_score() is
        #   never even computed, zero perf cost, byte-identical output to
        #   before this key existed. Off by default pending real-data
        #   validation -- same convention as consensus_adaptive_enabled/
        #   consensus_cut_selection_mode above; do not flip to a nonzero
        #   default without checking real cluster-quality impact first.
        hdbscan_consistency_weight = 0.0,
        # hdbscan_selection_mode : "legacy" keeps the old two-branch
        #   in-range/boundary-fallback rule, which can discontinuously jump to
        #   a structurally different rule when no swept candidate falls inside
        #   [preferred_clusters_lo, preferred_clusters_hi].  "floor_soft_cap"
        #   (default Aug-Sep 2026) replaced it with one continuous ranking
        #   pass: a hard floor at preferred_clusters_lo plus a soft linear
        #   penalty (hdbscan_overshoot_penalty) above preferred_clusters_hi.
        #   "occurrence_persistence" (default since 2026-09-04, see
        #   run_hdbscan()'s own docstring and HEAD_DIP_FEATURE_EMBEDDING_
        #   INVESTIGATION_2026-09-03.md Experiments 12-13) replaces DBCV-based
        #   scoring entirely with a prospective rare-bout-survival test,
        #   applying the same already-tuned criterion _prune_rare_clusters()
        #   uses post-hoc, but as the sweep's own selection score -- real-data
        #   validated to beat floor_soft_cap by +41% and standard B-SOiD's own
        #   raw HDBSCAN partition by +28% (combined with train_frac=0.5) on
        #   the investigation's Coverage%/Leakage%/Ratio metric. Falls back to
        #   floor_soft_cap automatically (with a WARN log) for any
        #   run_hdbscan() call site not yet wired up with feats_sc_T/fps/
        #   win100 -- see that function's docstring for which call sites are.
        # hdbscan_overshoot_penalty : only active under "floor_soft_cap". Score
        #   penalty per cluster above preferred_clusters_hi (0 = no ceiling).
        # Default changed 2026-09-19 (from "floor_soft_cap") after real use
        # showed plain "occurrence_persistence" (evaluated, not adopted, the
        # same day) has no cluster-count term at all and can collapse to far
        # fewer clusters than preferred_clusters_hi allows with no way to
        # raise it -- see that mode's own docstring/entry above.
        # "occurrence_persistence_ranged" keeps occurrence_persistence's
        # real-bout-survival scoring (validated: +41% vs. floor_soft_cap,
        # +28% vs. raw B-SOiD on Coverage%/Leakage%/Ratio, EPM dataset) while
        # respecting preferred_clusters_lo/hi the same way floor_soft_cap
        # respects them for DBCV. Falls back to floor_soft_cap automatically
        # (WARN logged) for any call site not wired up with feats_sc_T/fps/
        # win100 -- see run_hdbscan()'s docstring.
        hdbscan_selection_mode    = "occurrence_persistence_ranged",  # "legacy" | "floor_soft_cap" | "occurrence_persistence" | "occurrence_persistence_ranged"
        # hdbscan_occurrence_persistence_shortlist_topn : speed optimization
        #   for "occurrence_persistence" mode -- 0 (full scan, every swept
        #   candidate gets the expensive per-candidate check) unless real-data
        #   testing confirms a nonzero top-N-by-DBCV shortlist causes zero
        #   Coverage%/Leakage%/Ratio degradation (see the investigation doc's
        #   "Two-stage shortlist" experiment).
        hdbscan_occurrence_persistence_shortlist_topn = 0,
                                        # Promoted Aug 2026 (real 3-group,
                                        # 8-seed sweep: legacy collapsed 5/8
                                        # seeds to 3 clusters, floor_soft_cap
                                        # collapsed 0/8; mean ARI 0.345→0.589;
                                        # zero quality regression on the
                                        # deterministic primary run).  See
                                        # CLUSTER_SELECTION_SIMPLIFICATION_PLAN_2026-08.md
                                        # changelog.
        hdbscan_overshoot_penalty = 0.01,
        # cluster_hierarchy_enabled : dendrogram of the production clustering
        #   result's cluster centroids in feature space -- supports manual
        #   post-hoc cluster merging. Additive-only output, safe to default on.
        cluster_hierarchy_enabled = True,
        cluster_hierarchy_linkage = "ward",   # "ward" | "average" | "complete"
        # ── Feature options ───────────────────────────────────────────────────
        body_normalise        = False,  # normalise by nose-to-tailbase length
        long_lag_drift        = False,  # add 2-s and 3-s lag drift offsets (freeze/guarding detection)
        long_scale_bins       = False,  # add 500-ms and 1000-ms coarse temporal bins (off by default)
        pca_pre_reduce        = "auto", # auto/on/off — reduce dims before UMAP
        # pca_n_components_mode: "heuristic" (default, current sample-size-
        #   driven formula, unchanged) | "mle" (Minka 2000 automatic
        #   dimensionality estimation via probabilistic-PCA model selection
        #   on the data's own eigenvalue spectrum -- data-driven, no manual
        #   threshold). Opt-in, off by default pending real-data validation
        #   (see D:\3D DLC\CLAUDE.md, 2026-09-03 PCA sizing investigation).
        pca_n_components_mode = "heuristic",
        # ── Primary user inputs (bout duration filter) ────────────────────────
        # Changed 2026-08-31 from 0.0/1e9 (effectively off) to match cube.py's
        # real, always-applied GUI default (the "Bout Duration Filter" front-
        # panel widget, cube.py's self._bd_min/self._bd_max) -- found while
        # auditing a headless BSoidEngine test batch that had silently run
        # with NO bout-duration filtering at all because it used these raw
        # engine defaults directly instead of going through the GUI, which
        # always force-injects 0.3/10.0 into cfg on every real run regardless
        # of the Advanced Settings window. Every actual CUBE user has always
        # run with 0.3s/10.0s in practice; the old 0.0/1e9 values were never
        # real production behavior for anyone using the GUI, only a trap for
        # direct/headless BSoidEngine callers (scripts, future API use).
        min_epoch_dur_s       = 0.3,    # minimum cluster bout duration (seconds)
        max_epoch_dur_s       = 10.0,   # maximum cluster bout duration (seconds)
        # bout_gap_bridging_enabled: DEFAULT CHANGED TO TRUE 2026-09-24 as
        #   part of same-label gap bridging becoming the standard CUBE
        #   default. Many genuinely real, temporally coherent behaviours
        #   (e.g. licking) are naturally bursty -- a real bout is many brief
        #   on/off sub-events (lick-pause-lick-pause-lick), each individually
        #   well under min_epoch_dur_s. The hard per-blip duration filter in
        #   bouts_to_epochs() used to shred these into noise and discard
        #   nearly all of them, even though the overall burst is a completely
        #   real, coherent bout when looked at as a whole. bridge_short_bouts()
        #   fixes this by merging same-label runs separated by a short
        #   (<= bout_gap_bridging_max_gap_s) interrupting run of any other
        #   label BEFORE the min-duration floor is ever applied, filling the
        #   gap with the surrounding label. Validated on real data
        #   (D:\Dam_Xenium\CUBE results 2026-09-18_00-16-18, cluster 19):
        #   only 8 bouts survived the 0.3s floor unbridged; same-label
        #   bridging at that same 0.3s gap tolerance recovered 32 bouts (4x).
        #   Extending bridging to kinematically-similar-but-different
        #   clusters (not just literal same-label) was also tested and found
        #   to add only marginal extra value (32->33) -- not worth the added
        #   complexity/risk, so same-label bridging alone is what ships here.
        #   Applied once, early, directly to the per-session display label
        #   array (both the raw MLP and HMM-decoded paths) right before that
        #   array is bout-ified, so every downstream consumer (bout/epoch
        #   CSVs, ethograms, example-clip selection, kinetic_coherence.csv,
        #   sankey_sequences.png, cube_analyser.py's stats) automatically
        #   sees bridged, less-fragmented bouts with no further changes.
        #   Applied AFTER the turned-away/auto-impure display overrides,
        #   which is intentional: a brief (<= the gap tolerance) turned-away
        #   or low-quality blip sitting inside an otherwise-coherent real
        #   bout gets legitimately subsumed back into that bout, while a
        #   genuinely long turned-away segment is correctly left unbridged.
        #   Set False to restore the pre-2026-09-24 baseline (every
        #   sub-floor blip simply dropped, no bridging).
        bout_gap_bridging_enabled = True,
        # bout_gap_bridging_max_gap_s: the gap tolerance in seconds, per
        #   session converted to frames via max(1, round(value * file_fps)).
        #   0.3s is the exact value validated above (the real-data 8->32
        #   bout recovery on cluster 19 used this figure) -- do not change
        #   this default without re-validating on real data. Inert while
        #   bout_gap_bridging_enabled is False.
        bout_gap_bridging_max_gap_s = 0.3,
        # ── Output options ────────────────────────────────────────────────────
        output_fps            = 15,
        max_clips_per_cluster = 3,
        umap_evolution_n      = 1,      # side-by-side UMAP-evolution videos to
                                        # auto-export after clustering (0 = off)
        save_plots            = True,
        organize_plots_enabled = True,  # sort plots/ into topic subfolders at
                                        # end of run (see reorganize_plots_folder)
        save_videos           = True,
        save_example_clips    = True,
        save_labeled_video    = True,
        delete_labeled_videos = True,   # delete labeled_videos/ folder after run
        # video_export_n_jobs (2026-08-31): parallelizes the per-session
        #   create_labeled_video() export across sessions -- each session's
        #   labeled video is a fully independent cv2 VideoCapture/VideoWriter
        #   round-trip (own input/output file, no shared mutable state), and
        #   cv2's C++ decode/encode releases the GIL during the heavy work,
        #   so a thread pool parallelizes real wall-clock time safely. Reuses
        #   the SAME resolve_n_jobs()/compute_adaptive_n_jobs() memory-aware
        #   auto-management every other *_n_jobs key in this module already
        #   uses (-1 = auto, scaled to available RAM/cores) rather than a new
        #   ad hoc cap. Deliberately does NOT extend to create_example_clips()
        #   (shares a mutable clips_per_cluster quota dict across calls by
        #   design -- parallelizing it would race that quota) or
        #   create_umap_evolution_video() (matplotlib Agg per-frame 3D
        #   rendering -- concurrent matplotlib+BLAS rendering is a documented
        #   real native-crash risk on this machine, see D:\3D DLC\CLAUDE.md's
        #   BLAS-thread-contention Crash Protection entries for
        #   make_skeleton_video(); only one evolution video is made per run
        #   by default anyway, so there is nothing to parallelize there).
        video_export_n_jobs   = -1,
        # labeled_video_keypoint_overlay (2026-08-31): draw DLC keypoint dots
        #   onto the 2D labeled video, using bodypart_rainbow_colors() -- the
        #   SAME per-bodypart color convention the 3D pipeline's
        #   overlay_keypoints_on_video()/skeleton video already use. Closes a
        #   real asymmetry: the 3D pipeline has shown tracked keypoints on
        #   its per-camera/skeleton videos for a while, but the 2D labeled
        #   video only ever showed a plain "C{lbl}" cluster-id box with no
        #   pose overlay at all. Dots only (no skeleton lines) -- the 2D
        #   pipeline has no equivalent of cube_3d_dlc.py's _infer_skeleton()/
        #   KNOWN_CHAINS available to cube_core.py without a cross-module
        #   import cube_3d_dlc.py doesn't currently need in the other
        #   direction; scoped to dots for now rather than risk that.
        labeled_video_keypoint_overlay = True,
        # labeled_video_keypoint_dot_radius: matches the 3D overlay's default
        #   (deliberately small so dots don't obscure the animal).
        labeled_video_keypoint_dot_radius = 3,
        # video_export_max_parallel (2026-08-31, real-data fix): hard ceiling
        #   applied to video_export_n_jobs' auto-resolved worker count,
        #   independent of compute_adaptive_n_jobs()'s CPU/RAM-based
        #   heuristic. Real-data evidence: an auto-resolved 20 concurrent
        #   workers (each an isolated process running its own h264_nvenc
        #   ffmpeg encode) caused 17/21 labeled videos to time out on a real
        #   21-session run -- consistent with exceeding the GPU driver's
        #   concurrent NVENC session limit (commonly 2-5 on consumer NVIDIA
        #   cards), which general CPU/RAM headroom detection has no way to
        #   know about. 4 is a conservative default that stayed well under
        #   the failure point while still meaningfully parallelizing over
        #   sequential (1). Only applies when video_export_n_jobs itself is
        #   left at -1 (auto) -- an explicit positive value is a deliberate
        #   user choice and is honoured uncapped.
        video_export_max_parallel = 4,
        # ── Plot appearance ───────────────────────────────────────────────────
        plot_theme            = "light",  # "dark" or "light"
        # ── HMM post-hoc smoothing ────────────────────────────────────────────
        hmm_enabled           = True,    # wrap MLP output with Multinomial HMM
        hmm_n_states          = 0,       # 0/None → n_clusters (smoothing-only mode)
        hmm_n_iter            = 100,     # Baum-Welch EM iterations
        hmm_random_state      = 42,      # seeds CategoricalHMM/GaussianHMM startprob_
                                        #   init so train_hmm/train_hmm_soft are
                                        #   reproducible across identical-input calls
        hmm_min_prob          = 0.05,    # min edge probability in syntax network plot
        # hmm_transition_prior: "per_cluster" (default since Aug 2026, was
        #   "global" pre-Aug-2026) derives each cluster's own self-transition
        #   prior from its mean observed bout duration (see
        #   _compute_cluster_self_trans / train_hmm docstring) instead of a
        #   flat 90%/10% self/spread prior for every state -- validated on
        #   real data (A.4/B.6 test suite, Aug 2026) to avoid over-smoothing
        #   naturally brief behaviours. Set to "global" to restore the old
        #   flat-prior behavior exactly.
        hmm_transition_prior  = "per_cluster",
        # hmm_transmat_prior_strength (2026-09-18): pseudo-observation count
        #   anchoring Baum-Welch's transition-matrix M-step toward
        #   _transmat_init (the hmm_transition_prior-derived matrix above)
        #   via hmmlearn's transmat_prior, instead of leaving it as pure
        #   unconstrained MLE (hmmlearn's own default). Without this, EM is
        #   free to converge every state's self-transition probability
        #   toward the label sequence's empirical switching rate regardless
        #   of how different the per-cluster priors started -- the fix for
        #   "most clusters end up with the same learned bout duration" (see
        #   train_hmm docstring). 0 restores the old unregularized-MLE
        #   behavior exactly.
        hmm_transmat_prior_strength = 10.0,
        # hmm_smoothing_level: "bin" (default since Aug 2026, was "frame"
        #   pre-Aug-2026) trains/decodes the HMM on the underlying per-bin
        #   sequence (1/win the length of the frame-repeated sequence), then
        #   expands the decoded bin-level states back to frame resolution
        #   the same way predict_labels() expands raw bin labels -- avoids
        #   diluting the learned transition matrix with trivial within-bin
        #   self-transitions, and is faster (fewer sequence elements for
        #   Baum-Welch/Viterbi). Only takes effect when hmm_emission_mode
        #   is "categorical" -- "soft" emissions already operate at bin
        #   resolution unconditionally (see train_hmm_soft). Set to "frame"
        #   to restore the old frame-repeated behavior exactly.
        hmm_smoothing_level   = "bin",
        # hmm_emission_mode: "soft" (default since Aug 2026, was
        #   "categorical" pre-Aug-2026) fits a GaussianHMM on the MLP's
        #   per-bin class-probability vectors instead of a CategoricalHMM on
        #   hard argmax labels (see train_hmm_soft docstring) -- lets frames
        #   the MLP was uncertain about get less-confident smoothing than
        #   frames it was near-100% sure of. Set to "categorical" to restore
        #   the old hard-label HMM behavior exactly.
        hmm_emission_mode     = "soft",
        # ── Reproducibility / methodology (v2.1) ──────────────────────────────
        # compat_mode: "current" uses the v2.1 corrected behaviour; "legacy_v2"
        #   restores pre-2.1 numeric defaults (see _LEGACY_V2_DEFAULTS) so an old
        #   run can be reproduced exactly.  Only keys the user did NOT pass
        #   explicitly are reverted.
        compat_mode           = "current",
        # hdbscan_mcs_anchor: "embedding" sizes min_cluster_size against the
        #   points actually clustered (correct when UMAP runs on a subsample);
        #   "full" anchors against the full bin count (pre-2.1 behaviour).
        hdbscan_mcs_anchor    = "embedding",
        # angular_fallback: when no spine landmarks match by keyword, True uses
        #   evenly-spaced bodypart indices (pre-2.1; can yield meaningless angles),
        #   False skips the angular block entirely (v2.1 default).
        angular_fallback      = False,
        # seed_sweep_n: if >0, re-run UMAP+HDBSCAN over this many random seeds to
        #   assess cluster-count / partition stability (plots cluster_stability.png).
        #   0 = off. Default 6 -- adds runtime but stability is worth checking
        #   on every run rather than only when the user remembers to enable it.
        seed_sweep_n          = 6,
        # seed_sweep_n_jobs: dispatch of seed_sweep_stability()'s per-seed
        #   UMAP+HDBSCAN(+refinement) fits via joblib (thread-based pool,
        #   same choice as hdbscan_split_n_jobs). Default 1 (sequential)
        #   since Aug 2026, after a real run hit a Windows heap-corruption
        #   fault (0xc0000374, inside ntdll.dll's allocator -- not
        #   reproducible on demand, so a safety margin rather than a
        #   pinned-down fix). Measured cost of going sequential: none --
        #   the per-worker numba/BLAS single-threading already in effect
        #   (see _numba_single_thread/_blas_single_thread_for_dispatch)
        #   left little real parallel throughput to lose; a real 6-seed
        #   sweep timed marginally FASTER sequential (490s) than parallel
        #   (503s). -1 = auto-managed (System Resources block below);
        #   >1 = pin an exact worker count.
        # 2026-09-18: reverted to -1 (auto) at explicit user request, same
        # as hdbscan_sweep_n_jobs above -- accepting the crash risk for
        # full parallelism.
        seed_sweep_n_jobs      = -1,
        # seed_sweep_min_valid_clusters: a per-seed partition with fewer than
        #   this many real clusters is treated as degenerate (a collapsed/
        #   under-fit fit, not a meaningful partition to compare against
        #   others) and excluded from the mean pairwise ARI in BOTH
        #   seed_sweep_stability() and consensus_cluster()'s own per-seed
        #   stability stats. Comparing a degenerate partition (e.g. 1
        #   cluster) against a well-formed one is guaranteed near-zero ARI
        #   regardless of whether the genuine structure is actually stable,
        #   so leaving them in systematically drags the mean down and can
        #   spuriously trip consensus_auto_threshold. Default 6 (a partition
        #   with fewer than 6 clusters is not a trustworthy comparison point
        #   for datasets in this pipeline's typical 8-30 preferred-cluster
        #   range). Degenerate seeds are still logged and counted, just
        #   excluded from the ARI mean itself.
        seed_sweep_min_valid_clusters = 6,
        # seed_sweep_train_frac (Option 5, HDBSCAN sweep perf, Aug 2026): 1.0
        #   (default) = today's full-array behaviour for every existing user,
        #   zero change unless opted into. When < 1.0, seed_sweep_stability()
        #   draws ONE shared subsample of bins (deterministically from
        #   umap_random_state), and every seed in the sweep clusters that
        #   SAME subsample -- only umap_random_state varies per seed, exactly
        #   as today, cutting UMAP+HDBSCAN cost by ~this fraction. This is
        #   NOT the same thing as seed_sweep_stability_bootstrap() (a
        #   separate, standalone diagnostic that draws a FRESH subsample per
        #   seed to measure combined subsample+seed variance) -- do not
        #   conflate the two; this key has zero effect on that function.
        seed_sweep_train_frac = 1.0,
        # ── Consensus/co-association clustering (opt-in, Aug 2026) ────────────
        # consensus_clustering_enabled: False (default) = current behavior,
        #   the primary run_hdbscan() fit on umap_random_state's single seed
        #   is used unchanged. True replaces it with a partition built from
        #   agreement across consensus_n_seeds independent seeds (see
        #   consensus_cluster()'s docstring) -- the general fix for datasets
        #   where seed_sweep_stability reports low mean_ari (UMAP embedding
        #   topology itself is seed-unstable, not just HDBSCAN's selection).
        #   Costs roughly consensus_n_seeds x the primary UMAP+HDBSCAN
        #   runtime, so it's opt-in rather than a new default for everyone.
        # consensus_n_seeds: how many seeds to build the co-association
        #   matrix from. 8 balances a sturdier consensus against runtime;
        #   the validated test used 12.
        # consensus_n_jobs: dispatch of consensus_cluster()'s per-seed
        #   UMAP+HDBSCAN fits via joblib (thread-based pool, same choice as
        #   seed_sweep_n_jobs/hdbscan_split_n_jobs). Default 1 (sequential)
        #   alongside seed_sweep_n_jobs -- same Aug 2026 safety margin
        #   (see seed_sweep_n_jobs above for the full rationale). Also
        #   measured at no real cost: an 8-seed consensus run timed 668s
        #   sequential vs 692s parallel. -1 = auto-managed (System
        #   Resources block below); >1 = pin an exact worker count.
        # consensus_linkage: "ward" (default; validated -- gave well-
        #   separated, balanced clusters). "average" and "complete" were
        #   both tested and collapsed to a single giant cluster on real data
        #   (they chain through the noisy co-association matrix) -- avoid.
        consensus_clustering_enabled = False,
        consensus_n_seeds            = 8,
        # 2026-09-18: reverted to -1 (auto) at explicit user request, same
        # as hdbscan_sweep_n_jobs/seed_sweep_n_jobs above.
        consensus_n_jobs             = -1,
        consensus_linkage            = "ward",
        # consensus_max_memory_gb: safety guard on the O(n_training_bins^2)
        #   co-association matrix (float32) -- ~200MB at 7,000 bins, ~1.6GB at
        #   20,000, ~10GB at 50,000. Checked BEFORE the n_seeds x UMAP+HDBSCAN
        #   loop runs, so an oversized dataset aborts immediately (falls back
        #   to the primary single-seed result) instead of burning that
        #   runtime and only then failing at allocation. 0 = no limit.
        consensus_max_memory_gb      = 4.0,
        # consensus_refine_enabled: ON by default (Aug 2026) -- when
        #   consensus clustering runs, the PRIMARY path's split/merge
        #   refinement pass is unconditionally skipped for its output (its
        #   split step assumes hdb_clf/embedding come from the same fit as
        #   the labels being refined, which isn't true for consensus; see
        #   the _consensus_used branch in run()). Without this on, consensus
        #   labels get NO impurity screening at all -- confirmed on a real
        #   run to leave a large (3,142-bin), badly-separated catch-all
        #   cluster completely unsplit. When True, consensus_cluster()'s
        #   output instead goes through refine_consensus_clusters() -- split
        #   reuses split_impure_clusters() unchanged
        #   (hdbscan_split_silhouette_thresh/recluster_max_iterations, same
        #   keys as the primary path); merge uses merge_by_coassociation()
        #   (consensus_merge_coassoc_thresh) instead of
        #   merge_similar_clusters() (needs a condensed_tree_, which
        #   consensus partitions don't have). See consensus_cluster()'s
        #   docstring (Aug 2026). Costs an extra split/merge pass on top of
        #   consensus's own n_seeds x UMAP+HDBSCAN runtime; set False to
        #   restore the old "consensus output taken as-is" behavior.
        consensus_refine_enabled     = True,
        # consensus_merge_coassoc_thresh: mean cross-cluster co-association
        #   (fraction of the n_seeds that grouped two clusters' bins together)
        #   above which merge_by_coassociation() merges them. Only active
        #   when consensus_refine_enabled=True. 0.5 is a reasoned starting
        #   value ("more than half the seeds agreed"), not yet empirically
        #   calibrated -- same status hdbscan_overshoot_penalty had at
        #   ship time. <= 0 disables the merge half specifically (split can
        #   still run on its own).
        consensus_merge_coassoc_thresh = 0.5,
        # consensus_auto_threshold: if seed_sweep_n>=2 (on by default) and the
        #   resulting mean_ari falls below this, consensus clustering is
        #   auto-enabled even though consensus_clustering_enabled defaults to
        #   False -- UNLESS the caller explicitly set
        #   consensus_clustering_enabled=False (always respected as a
        #   deliberate opt-out). Set to 0 to disable auto-triggering entirely
        #   (matches "warn only, never auto-switch" behavior); consensus
        #   clustering remains available via consensus_clustering_enabled=True.
        #   Re-enabled at 0.55 (Aug 2026): briefly disabled after
        #   hdbscan_selection_mode="floor_soft_cap" (see
        #   CLUSTER_SELECTION_SIMPLIFICATION_PLAN) fixed catastrophic
        #   undershoot, on the theory that seed-sweep ARI would now be
        #   consistently stable enough not to need it. A real 4-config
        #   A/B test on a 21-session combined dataset (baseline / down-
        #   weighted bodyparts / umap_n_neighbors=60 / both) showed mean ARI
        #   still landing in 0.18-0.29 across every config -- nowhere close
        #   to stable. 0.55 sits just under the old 0.6 bar (itself
        #   calibrated against a real mean_ari=0.512 case that needed to
        #   trigger) with a small margin so runs already close to reliable
        #   don't pay consensus's ~n_seeds x runtime cost unnecessarily.
        #   Consensus itself is now also less risky to auto-fire than when
        #   0.6 was chosen: it gained its own opt-in post-hoc split/merge
        #   refinement (consensus_refine_enabled) and always reports
        #   feature-space DBCV/silhouette directly comparable to the primary
        #   path's, instead of being a refinement/validation-free black box
        #   scored only by separation_ratio.
        consensus_auto_threshold     = 0.55,
        # ── Adaptive consensus seed count (Sep 2026, default ON) ───────────────
        # consensus_adaptive_enabled: when True, consensus_cluster() first runs
        #   only consensus_adaptive_min_seeds seeds (default 3) instead of the
        #   full consensus_n_seeds (default 8), and only pays for the
        #   remaining seeds if the 3-seed result's own quality doesn't already
        #   clear consensus_adaptive_escalate_threshold -- see
        #   consensus_adaptive_escalate_threshold/consensus_intra_weight
        #   below for the decision itself. False = today's pre-Sep-2026
        #   behavior, always runs the full consensus_n_seeds up front,
        #   byte-identical output.
        #
        #   DEFAULT CHANGED TO True (2026-09-03) on real-data evidence, not a
        #   reasoned-but-unvalidated guess: captured the REAL feats_sc_T
        #   (7,012 training bins x 766 PCA-reduced dims) mid-run from the
        #   already-on-disk full-production consensus run against the
        #   21-session Damien DLC dataset (D:\CUBE_Pipeline\Time_CUBE\
        #   out_consensus, mean_ari=0.360, auto-triggers), then called the
        #   REAL consensus_cluster() directly against it, adaptive vs. fixed-
        #   8-seed baseline. Result: the 3-seed batch's cohesion score
        #   (0.715) cleared consensus_adaptive_escalate_threshold=0.5 and
        #   stopped early, for a measured 50% wall-clock reduction on the
        #   seed-dispatch-dominated cost (60s vs 121s) -- directly
        #   demonstrating the time-saving this key exists for, on a real
        #   dataset, not a synthetic one.
        #
        #   This is NOT a free win, and the trade is deliberately kept, not
        #   hidden: stopping at 3 seeds gave a DIFFERENT partition from the
        #   8-seed baseline (ARI=0.607, 21 vs 17 clusters) with BETTER
        #   per-cluster cohesion (intra_median 0.608 vs 0.488) and slightly
        #   better feature-space DBCV/silhouette, but nearly 3x the noise
        #   fraction (7.1% vs 2.4%) -- fewer seeds' worth of co-association
        #   evidence pulls fewer borderline points into a confident cluster.
        #   Given this project's explicit priority (saving run time matters,
        #   and the delivered partition's own quality signals were not
        #   worse), the default was flipped on this evidence rather than
        #   held to a stricter "must match the 8-seed result" bar.
        #
        #   OPEN GAP, honestly flagged: the escalate-to-8 half of this
        #   mechanism was NOT exercised by this validation -- the 3-seed
        #   cohesion score cleared 0.5 comfortably (0.715-0.837 across two
        #   cut-selection modes tried) every time on this dataset, so
        #   consensus_adaptive_escalate_threshold=0.5 currently behaves
        #   closer to "always stop at 3" than a genuine two-way gate on data
        #   like this. A stricter threshold was NOT tried/tuned against this
        #   evidence -- 0.5 is kept exactly as already documented below
        #   ("reasoned starting value, not yet empirically calibrated").
        #   Revisit if a dataset is ever found where escalation actually
        #   fires, to confirm that path also behaves well.
        consensus_adaptive_enabled            = True,
        # consensus_adaptive_min_seeds: seeds to run before the first
        #   escalate/stop check. 3 is the smallest count that still yields
        #   more than one pairwise co-association contribution. This read is
        #   still noisier than the 6-seed standalone sweep (seed_sweep_n)
        #   that decided consensus needs to run at all in the first place --
        #   which is exactly why fewer than 3 of these seeds producing a
        #   usable (non-degenerate) partition forces escalation regardless
        #   of the quality score below, the same "sweep collapsed entirely"
        #   guard medoid_escalation_threshold's own doc describes.
        consensus_adaptive_min_seeds          = 3,
        # consensus_intra_weight: how much the escalate/stop decision AND
        #   (when consensus_cut_selection_mode="cohesion_weighted") the Ward
        #   cut picker weight pure within-cluster co-association (intra)
        #   against between-cluster co-association (inter), combined as
        #   intra_weight*intra + (1-intra_weight)*(1-inter). Both terms are
        #   already fractions in [0,1] (co-association is a fraction of
        #   seeds agreeing on a pair), so this is a genuine absolute [0,1]
        #   score, not one normalized relative to a single run's own
        #   candidate spread. IMPORTANT: intra/inter here are each the
        #   MEDIAN of a PER-CLUSTER value across clusters (see
        #   _per_cluster_cohesion()), never a single pooled mean over all
        #   sampled point pairs -- a pooled mean lets one large or one badly
        #   -behaved cluster dominate the whole partition's score either
        #   way. The median instead reflects the typical cluster's own
        #   agreement, so a partition with many well-agreed clusters and one
        #   weak one isn't penalized as though every cluster were mediocre,
        #   and a single very strong cluster can't mask several weak ones.
        #   0.7 deliberately keeps inter/separation a real (30%) contributor
        #   rather than zeroing it out: real user testing found a cluster's
        #   own internal consistency is the stronger predictor of "is this a
        #   real behavior," not that separation is irrelevant -- it should
        #   stay a strong influence, not the only one. Must stay in [0, 1].
        consensus_intra_weight                = 0.7,
        # consensus_adaptive_escalate_threshold: the blended cohesion score
        #   (see consensus_intra_weight) of the consensus_adaptive_min_seeds
        #   -seed result's chosen cut must clear this to stop early; below
        #   it, the remaining seeds (up to consensus_n_seeds) are run too
        #   and the full-seed result is used instead. 0.5 is a reasoned
        #   starting value, explicitly NOT YET empirically calibrated --
        #   same ship-time status medoid_escalation_threshold/consensus_
        #   merge_coassoc_thresh both had.
        consensus_adaptive_escalate_threshold = 0.5,
        # consensus_reuse_seed_sweep_fits (Sep 2026): when True, the standalone
        #   diagnostic seed sweep (seed_sweep_n) retains every seed's own
        #   fitted UMAP+HDBSCAN result for the rest of this run() call, and if
        #   consensus clustering subsequently triggers (auto or via medoid
        #   escalation) on that SAME feats_sc_T/cfg, consensus_cluster()
        #   reuses whichever of its own seeds the sweep already fit instead of
        #   re-fitting them from scratch -- generalizes the existing single-
        #   seed "Free Seed Zero" reuse (primary_fit, always on) to every
        #   seed the sweep covers, since seed_sweep_stability() and
        #   consensus_cluster() use the identical seed list
        #   (base_seed..base_seed+n-1). Skips UMAP+HDBSCAN entirely for those
        #   seeds -- the seed-dispatch loop is consensus's single most
        #   expensive stage.
        #
        #   False (default) is byte-identical to today's behavior in every
        #   respect: the sweep discards each non-medoid seed's model/
        #   embedding/clf as it always has, and consensus re-fits every seed
        #   except the one base_seed already covered by primary_fit. Kept off
        #   by default pending real-data validation of the wall-clock saving,
        #   matching this codebase's own standing convention for a new
        #   mechanism (see consensus_adaptive_enabled's own history above).
        #
        #   Reuse is additionally gated (in run()'s _run_consensus_remedy, not
        #   here) on hdbscan_membership_confidence_floor<=0, seed_sweep_
        #   train_frac>=1.0, and hdbscan_seed_sweep_n_steps ==
        #   hdbscan_consensus_sweep_n_steps -- any seed whose sweep-time fit
        #   could genuinely differ from a fresh consensus-time fit (a floor
        #   applied, a different training subsample, a different sweep
        #   density) is never reused, regardless of this flag; only a
        #   verified-identical fit is ever substituted for a real one.
        consensus_reuse_seed_sweep_fits       = False,
        # consensus_cut_selection_mode: "separation_ratio" (default,
        #   byte-identical to pre-Sep-2026 behavior) picks the Ward-linkage
        #   cut (n_target) that maximizes median-per-cluster intra / median-
        #   per-cluster inter. "cohesion_weighted" instead maximizes the
        #   SAME blended score the escalate decision uses (consensus_intra_
        #   weight*intra + (1-consensus_intra_weight)*(1-inter), both
        #   median-per-cluster) -- weights internal consistency more heavily
        #   while still letting separation break ties, rather than ranking
        #   purely by the intra/inter ratio. Opt-in pending real-data
        #   validation, same convention as consensus_adaptive_enabled above.
        consensus_cut_selection_mode          = "separation_ratio",
        # consensus_overshoot_search_margin / consensus_overshoot_penalty
        #   (soft cap, mirrors hdbscan_selection_mode="floor_soft_cap" for
        #   the primary/medoid sweep -- see its own DEFAULTS doc above):
        #   without these, the Ward-cut candidate list below is a HARD
        #   ceiling at preferred_clusters_hi -- consensus can never return
        #   more clusters than that even when the medoid/primary sweep
        #   (which only soft-penalizes overshoot, never hard-caps it) finds
        #   real structure above it. consensus_overshoot_search_margin
        #   extends the searched cut range to
        #   [preferred_clusters_lo, preferred_clusters_hi + margin] instead
        #   of stopping at preferred_clusters_hi; consensus_overshoot_penalty
        #   is then subtracted from each overshooting candidate's rank_key
        #   (separation_ratio or cohesion_weighted score, whichever
        #   consensus_cut_selection_mode picked) once per cluster above
        #   preferred_clusters_hi, same "hard floor, soft ceiling" shape as
        #   the primary sweep's own overshoot_w. margin=0 keeps the old
        #   hard-capped behavior byte-identical; set it >0 to let consensus
        #   reach medoid-comparable cluster counts. Default raised from 0 to
        #   5 (2026-09-08, paired with the consensus_undershoot_penalty
        #   default change below) so a candidate above preferred_clusters_hi
        #   is at least reachable when the undershoot penalty pushes the
        #   ranking away from preferred_clusters_lo -- 0 would leave no
        #   headroom above the ceiling for that push to land on.
        consensus_overshoot_search_margin     = 5,
        consensus_overshoot_penalty           = 0.01,
        # consensus_undershoot_penalty: the mirror-image problem to the
        #   overshoot pair above, and the one actually observed on real
        #   data first (medoid=21 clusters, consensus=12 -- exactly
        #   preferred_clusters_lo, the hard floor of the search range, not
        #   preferred_clusters_hi). separation_ratio (intra_pooled /
        #   inter_pooled co-association) can be monotonically higher for
        #   COARSER cuts on some datasets -- merging keeps intra-cluster
        #   co-association high while shrinking the number of cross-cluster
        #   pairs dragging inter down -- so the unmodified ranking simply
        #   collapses to pref_lo every time, regardless of
        #   consensus_overshoot_search_margin (which only ever adds
        #   candidates ABOVE pref_hi; it can't stop pref_lo from winning).
        #   Set >0 to subtract
        #   consensus_undershoot_penalty * max(0, preferred_clusters_hi -
        #   n_target) from every candidate's rank_key -- same shape as
        #   consensus_overshoot_penalty but pulling AWAY from pref_lo
        #   instead of away from exceeding pref_hi, so the two together
        #   turn preferred_clusters_hi into a soft attractor rather than a
        #   hard ceiling. Tune jointly with consensus_overshoot_search_
        #   margin/consensus_overshoot_penalty when consensus is
        #   systematically undershooting the medoid/primary sweep's own
        #   cluster count. Default raised from 0.0 (true no-op) to 0.02
        #   (2026-09-08) -- 0.0 left consensus collapsing to preferred_
        #   clusters_lo on real data (separation_ratio favors coarser cuts)
        #   with no way for a higher preferred_clusters_hi ceiling to ever
        #   matter, since the ranking never tried to climb toward it.
        consensus_undershoot_penalty          = 0.02,
        # partition_remedy_method (MEDOID_CONSENSUS_SELECTION_PLAN.md, Aug
        #   2026): once EITHER consensus_clustering_enabled=True OR the
        #   consensus_auto_threshold auto-trigger above decides a remedy is
        #   needed for the primary partition, this selects WHICH algorithm
        #   runs. "medoid" (new default): adopt the seed_sweep_stability()
        #   seed with the highest mean ARI to the other stable seeds --
        #   selects for agreement with the rest of the sweep, not a
        #   separation-favoring metric like DBCV, matching this codebase's
        #   documented priority (internally-cohesive clusters a human can
        #   consolidate later, not maximal separation). Escalates to full
        #   consensus (see medoid_escalation_threshold) if the medoid seed's
        #   own agreement is itself too low, or the sweep collapsed
        #   entirely (fewer than 2 stable seeds). "consensus": always runs
        #   the existing, more expensive but more principled co-association
        #   method unconditionally, no escalation logic -- an escape hatch,
        #   byte-identical to this codebase's pre-medoid behavior forever.
        #   INTENTIONAL DEFAULT-BEHAVIOR CHANGE: an old session predating
        #   this key (saved before Aug 2026) that crosses
        #   consensus_auto_threshold will now get medoid-first instead of
        #   straight consensus on its next run. Set explicitly to
        #   "consensus" to reproduce the old behavior exactly.
        partition_remedy_method      = "medoid",
        # medoid_escalation_threshold: the medoid seed's OWN row-mean ARI to
        #   the other stable seeds (not the sweep's overall mean_ari, which
        #   is already known to be below consensus_auto_threshold by the
        #   time this is checked -- reusing that same bar here would
        #   escalate essentially every time) must be at least this high to
        #   be adopted; below it, medoid isn't trustworthy either and CUBE
        #   escalates to full consensus. 0.35 is a reasoned starting value
        #   (meaningfully below consensus_auto_threshold=0.55, giving medoid
        #   real room to be tried before falling back), explicitly NOT YET
        #   empirically calibrated -- same status consensus_merge_coassoc_
        #   thresh had at ship time. See Phase 5 of the plan above for the
        #   first real-data check of this value.
        medoid_escalation_threshold = 0.35,
        # MEDOID_CONSENSUS_COMPOSITE_METRIC (2026-09-06): medoid_escalation_
        #   threshold alone is exactly the single-metric risk this codebase
        #   already built a compensating gate for elsewhere --
        #   embedding_stability_retry's own accept condition explicitly
        #   distrusts ARI alone ("over-smoothing... can RAISE seed agreement
        #   by leaving independent seeds less real structure to disagree
        #   about") and pairs it with a feature-space DBCV non-regression
        #   check before accepting. medoid_escalation_threshold's ARI-only
        #   gate had no equivalent second check. medoid_dbcv_tolerance adds
        #   one, reusing the SAME already-validated pattern (an AND-gate of
        #   independent conditions, not a blended score -- a weighted sum
        #   would let a very high ARI mask a very low cohesion score, which
        #   is exactly the failure mode being guarded against) rather than
        #   inventing a new methodology. Adoption now additionally requires
        #   the medoid candidate's own feature-space DBCV
        #   (_dbcv_feature_space(), the SAME function consensus_cluster()
        #   already computes for its own reporting) not to regress by more
        #   than this tolerance relative to the PRE-remedy primary
        #   partition's own feature-space DBCV. When either DBCV value is
        #   non-finite (insufficient real clusters, hdbscan.validity
        #   unavailable, etc.), or n_samp is below medoid_dbcv_min_samples,
        #   this check is skipped -- degrades to the pre-existing ARI-only
        #   decision, never blocks adoption on an unmeasurable or unreliable
        #   quantity, matching embedding_stability_retry's own
        #   _dbcv_both_finite convention.
        #   VALUE HISTORY (2026-09-06): an initial 0.05 -- directly borrowed
        #   from embedding_stability_retry_quality_tolerance -- was tried
        #   first and immediately falsified by this repo's own integration
        #   test suite: a real (non-synthetic-forced) 3-seed sweep on a
        #   small fixture showed per-seed feature-space DBCV of 0.241/0.312/
        #   0.615 from RANDOM SEED ALONE, no reweighting or over-smoothing
        #   involved at all. That's the wrong comparison to calibrate
        #   against -- embedding_stability_retry compares the SAME fit
        #   before/after a small perturbation (inherently low variance);
        #   this compares DIFFERENT SEEDS' independent fits, which is
        #   structurally noisier by construction (this is precisely WHY
        #   seed-sweep/medoid/consensus exist at all -- if different seeds
        #   agreed tightly on quality as well as partition, none of this
        #   machinery would be needed). Raised to 0.15 -- still a reasoned,
        #   NOT yet dedicated-real-data-validated starting value (same
        #   ship-time status as medoid_escalation_threshold's own 0.35 when
        #   it first shipped) -- comfortably wider than normal cross-seed
        #   noise on richer/real feature spaces while still catching a
        #   genuinely large regression.
        medoid_dbcv_tolerance = 0.15,
        # medoid_dbcv_min_samples: below this many bins, feature-space DBCV
        #   (an MST-based statistic) is too unstable on too little data to
        #   trust as a second condition at all -- the composite gate falls
        #   back to the pre-existing ARI-only decision entirely rather than
        #   computing a comparison that's more noise than signal. 500 is a
        #   reasoned floor (DBCV's own MST step needs enough points for a
        #   meaningful density estimate), not yet validated against a
        #   specific real dataset -- flagged here for the same follow-up
        #   validation pass as medoid_dbcv_tolerance.
        medoid_dbcv_min_samples = 500,
        # ── Cluster-quality improvements (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md,
        #   Aug 2026): split relaxation, rare-behavior survival, confidence
        #   floor, seed pruning, adaptive embedding-stability retry. Every key
        #   below defaults to a value that reproduces pre-plan output
        #   byte-for-byte, until real-data validated (see the plan's Phase 6). ──
        # hdbscan_split_accept_partial_noise: when True, _attempt_split()
        #   accepts a local re-cluster result with exactly 1 non-noise
        #   sub-cluster (previously always rejected, requiring >=2) as long as
        #   the resulting noise fraction clears
        #   hdbscan_split_min_noise_frac_for_partial -- a real "peeled off junk"
        #   win, not just relabeling everything as the same one cluster.
        #   Default changed to True (2026-08-31): a real consensus run
        #   (D:\CUBE_Pipeline\Time_CUBE\out_consensus, 21-session pooled
        #   dataset) left two giant diffuse "dump" clusters (#13: n=1110,
        #   embedding-space silhouette -0.574; #17: n=639, -0.276 -- both far
        #   past hdbscan_split_silhouette_thresh=0.2) completely unsplit even
        #   with consensus_refine_enabled=True (also on by default) actively
        #   screening them as candidates -- model/split_merge_log.json was
        #   entirely absent from that run, confirming zero split events ever
        #   fired. Root cause: a genuinely diffuse dump cluster's local
        #   re-cluster very typically resolves to "1 real coherent core +
        #   scattered noise," which the old False default rejected outright
        #   as a non-win instead of peeling the coherent core off. See
        #   CLAUDE.md's Cluster-Quality-Improvements entry for the mechanism.
        hdbscan_split_accept_partial_noise = True,
        # hdbscan_split_min_noise_frac_for_partial: minimum noise fraction (of
        #   the local re-cluster) required for a 1-subcluster result to be
        #   accepted under hdbscan_split_accept_partial_noise. Inert while that
        #   flag is False. Not yet empirically calibrated.
        hdbscan_split_min_noise_frac_for_partial = 0.15,
        # hdbscan_split_min_occurrences (2026-08-30 decision): a 1-subcluster
        #   partial-split result is ALSO accepted (independent OR against the
        #   noise-fraction floor above) when the winning sub-cluster recurs
        #   as >= this many discrete bouts (>=2-bin runs of this candidate's
        #   own original bin positions) -- protects a high-FREQUENCY,
        #   low-DURATION real behavior (sneezing, shaking) that a plain
        #   noise-fraction gate would wrongly reject since each bout is
        #   brief even though it recurs often. Reuses the same min_occurrences
        #   spirit as the Cluster-Quality plan's occurrence_persistence
        #   criteria, but a separate key (bout counting here doesn't have
        #   fps/session_boundaries threaded through the local-split dispatch
        #   layer -- see the inline comment at _attempt_split's occurrence
        #   count for why). Inert while hdbscan_split_accept_partial_noise is
        #   False. Not yet empirically calibrated.
        hdbscan_split_min_occurrences = 3,
        # hdbscan_split_direct_embedding_fallback (2026-08-31): when the
        #   normal local-recluster path (re-run UMAP fresh on just the
        #   candidate cluster's own points, then HDBSCAN) finds "no stable
        #   local sub-structure" -- a candidate is left completely unrefined
        #   even with hdbscan_split_accept_partial_noise on -- try ONE more
        #   thing before giving up: run HDBSCAN directly on the slice of the
        #   ALREADY-COMPUTED GLOBAL embedding for this candidate's points,
        #   with no re-embedding at all. Root-caused on a real 21-session
        #   consensus run (D:\CROSS-CLUSTER RECLAIN\CONSENSUS_FIXED): cluster
        #   #17 (n=2253, embedding-space silhouette -0.667) visibly separates
        #   into clean sub-groups in the global 3D UMAP plot, but the
        #   pipeline's own local re-embed found nothing every time. Directly
        #   verified: re-embedding an isolated ~2000-point subset from
        #   scratch does NOT reproduce the same manifold as viewing those
        #   points within the full dataset -- the density/distance
        #   calibration that made the sub-groups separable in context gets
        #   renormalized away once the subset is the whole input to UMAP.
        #   Clustering directly on the pre-existing global coordinates
        #   sidesteps this: HDBSCAN on cluster #17's global-embedding slice
        #   found 4 sub-clusters at silhouette 0.52 (mcs=50) -- comparable to
        #   the run's best cluster (#0, 0.50) -- where the re-embed path
        #   found zero. Only ever attempted as a FALLBACK after the re-embed
        #   path fails (never replaces it, never runs when re-embed already
        #   succeeds) -- lower risk of regressing a case that already works,
        #   and the log always records which path produced an accepted
        #   split. Applies uniformly wherever _local_recluster_and_assign()
        #   is used -- split_impure_clusters() (primary + consensus refine),
        #   split_region_impure_clusters(), and
        #   split_kinetically_incoherent_clusters() -- and to both the 2D and
        #   3D feature pipelines equally, since none of this touches feature
        #   extraction. Default True after this real-data check.
        hdbscan_split_direct_embedding_fallback = True,
        # hdbscan_split_direct_max_subclusters: local acceptance ceiling used
        #   ONLY for the direct-global-embedding fallback path above (kept
        #   separate from hdbscan_split_max_subclusters, which still governs
        #   the normal re-embed path) -- real data showed the re-embed cap of
        #   3 is one below what a real, well-separated result needed (4
        #   sub-clusters at silhouette 0.52); a lower cap here would have
        #   rejected exactly the validated real win. Kept modest (not raised
        #   further) so a fallback split still resolves a handful of
        #   distinct sub-behaviours rather than fragmenting -- consistent
        #   with this codebase's standing "don't balloon total cluster count"
        #   design goal for every local-split mechanism.
        hdbscan_split_direct_max_subclusters = 4,
        # hdbscan_split_min_dbcv (2026-08-31, recalibrated 2026-08-31): the
        #   quality floor a split candidate's local DBCV must clear to be
        #   accepted -- applied via _evaluate_and_merge(), which is SHARED by
        #   both the normal re-embed path and the direct-global-embedding
        #   fallback, so this is now symmetric: a weak result is judged the
        #   same way regardless of which method produced it (there is no
        #   principled reason a candidate's own DBCV score should be trusted
        #   differently based on which method computed it -- an earlier
        #   version of this fix mistakenly scoped the floor to the fallback
        #   path ONLY, via a separate hdbscan_split_direct_min_dbcv key; that
        #   asymmetry itself, not just the specific value, was the bug).
        #   Real data motivated both the floor's existence and its value:
        #   the fallback's 0.036 result (D:\CUBE_SPLIT_VALIDATION_2026_08_31,
        #   run 04, cluster #14) was essentially noise -- cross-cluster
        #   reclaim moved 33% of those bins elsewhere, but the two surviving
        #   pieces (1475 of 2356 bins) remained the two worst-separated
        #   clusters in the entire final partition (mean silhouette
        #   -0.368/-0.520 vs a partition mean of +0.170). But a NAIVE uniform
        #   floor of 0.15 (this fix's first attempt) would have rejected a
        #   GENUINELY GOOD result found later on the same cluster once
        #   hdbscan_split_adaptive_max_subclusters gave the NORMAL path room
        #   to find real structure: DBCV=0.142, part of the best-performing
        #   config tested (23 clusters, no catastrophic cluster, partition
        #   mean silhouette 0.242 -- the best of every variant tried). 0.08
        #   sits between the two real observations (0.036 bad, 0.142 good),
        #   clearing the noise case while still admitting both good splits
        #   observed so far (0.142 and the original 0.381). Not yet
        #   independently calibrated across multiple datasets -- revisit if
        #   a future real split lands close to this boundary either way.
        hdbscan_split_min_dbcv = 0.08,
        # hdbscan_split_min_balance_frac (2026-09-25): requires EVERY
        #   sub-cluster of an accepted (n_sub_cl>=2) split to hold at least
        #   this fraction of the candidate's assigned points -- see
        #   _evaluate_and_merge()'s own comment for the real, traced
        #   motivation (nn20 cluster #14's PCA-direct-fit split was a
        #   1.2%/98.8% sliver that cleared every other bar). 0.0 (default)
        #   is a true no-op. 0.10 is a reasoned starting value (not yet
        #   independently calibrated against multiple real splits the way
        #   hdbscan_split_min_dbcv was) -- pending its own real-data check
        #   before defaulting on.
        hdbscan_split_min_balance_frac = 0.0,
        # hdbscan_split_direct_min_dbcv: OPTIONAL additional floor applied
        #   only AFTER the shared hdbscan_split_min_dbcv gate above, scoped to
        #   ONLY the fallback path -- for a user who wants the fallback held
        #   to a stricter bar than the normal path once real evidence
        #   justifies that asymmetry (none does yet). 0.0 = true no-op.
        hdbscan_split_direct_min_dbcv = 0.0,
        # hdbscan_split_adaptive_max_subclusters (2026-08-31): a "dump"
        #   cluster flagged for splitting is sometimes MUCH larger than a
        #   typical cluster in the same partition (run 04: the candidate was
        #   2822 bins vs this partition's median non-noise cluster size of
        #   ~379 -- roughly 7.4x) -- forcing that much material into the same
        #   flat cap (3 normal / 4 fallback) used for an ordinary-sized
        #   candidate may itself be why the local structure found was so weak
        #   (0.036 DBCV): a genuinely heterogeneous 7x-oversized blob may
        #   contain more than 3-4 real sub-behaviours. When True, a
        #   candidate's own preferred_clusters_hi (normal path) /
        #   hdbscan_split_direct_max_subclusters (fallback path) is scaled up
        #   -- see _adaptive_subcluster_cap() -- based on its size relative to
        #   the partition's median non-noise cluster size, capped at
        #   hdbscan_split_adaptive_cap_ceiling. Default False pending a real
        #   A/B re-run on this exact cluster #14 case to confirm scaling the
        #   cap actually improves (not just changes) the result -- ship
        #   default-off, evidence-gathering-first, matching this codebase's
        #   standing convention for every other not-yet-validated mechanism.
        hdbscan_split_adaptive_max_subclusters = False,
        # hdbscan_split_adaptive_size_ratio: a candidate must be at least this
        #   many times the partition's median non-noise cluster size before
        #   its cap is scaled up at all (below this, the flat 3/4 base caps
        #   apply unchanged, byte-identical to adaptive-off behavior).
        hdbscan_split_adaptive_size_ratio = 3.0,
        # hdbscan_split_adaptive_cap_ceiling: hard ceiling on the scaled cap
        #   regardless of how large the size ratio gets -- keeps this
        #   mechanism from ever producing the "balloon total cluster count"
        #   outcome the direct-embedding fallback's own max-subclusters cap
        #   was originally created to prevent (see hdbscan_selection_mode
        #   note above).
        hdbscan_split_adaptive_cap_ceiling = 8,
        # ── Cross-cluster reclaim (2026-08-31) ──────────────────────────────
        #   Complementary to hdbscan_split_accept_partial_noise above: that
        #   flag lets a diffuse dump cluster peel off a coherent LOCAL
        #   sub-cluster of its own. It does nothing for a point that isn't
        #   part of any coherent local sub-structure at all, but that
        #   genuinely resembles a DIFFERENT, already-existing cluster --
        #   direct video review of clusters #13/#17 in the same real
        #   consensus run (D:\CUBE_Pipeline\Time_CUBE\out_consensus)
        #   confirmed exactly this: some of their points are leaked
        #   behaviors from other clusters, not a real 13th/17th behavior.
        #   reclaim_leaked_points() reassigns such a point directly to
        #   whichever OTHER existing cluster it best matches -- modeled on
        #   Evidence Accumulation Clustering (Fred & Jain 2005, already the
        #   basis of consensus_cluster()'s own co-association matrix) for
        #   consensus-mode runs, generalized to a feature-space
        #   nearest-centroid method for every other partition-remedy path.
        #   hdbscan_membership_vectors were deliberately NOT used for the
        #   non-consensus case: confirmed hdb_clf is stale relative to the
        #   truly final pre-MLP hdb_labels in every mode (consensus, medoid,
        #   AND primary-with-refinement whenever a split/merge actually
        #   fired), so its membership vectors can't safely be trusted here.
        # cluster_reclaim_enabled: default changed to True 2026-08-31, after
        #   a code review pass fixed two implementation issues found before
        #   flipping this on: (1) the centroid-distance computation
        #   materialized a full (n_samp, K, n_feat) broadcast tensor --
        #   replaced with the standard squared-distance expansion
        #   (||x-c||^2 = ||x||^2 - 2x.c + ||c||^2), whose peak memory is
        #   O(n_samp*K) instead of O(n_samp*K*n_feat), verified numerically
        #   identical to the old formula (max diff ~1e-13); (2)
        #   cluster_reclaim_max_frac_per_cluster<=0 previously meant
        #   "uncapped" (backward from what a "max fraction" parameter should
        #   mean at 0) -- fixed so 0 now means "cap of zero," the intuitive
        #   reading; the shipped default (0.5) is unaffected either way.
        #   Applies identically to the 2D and 3D pipelines (this insertion
        #   point in run() has no _is_3d branch -- it operates on the
        #   already-unified feats_sc/hdb_labels regardless of which feature
        #   extractor produced them) and to every partition-remedy path
        #   (primary, medoid, consensus -- method="auto" picks "coassoc"
        #   when consensus's co-association matrix is available, else
        #   "centroid"). False was the prior default (true no-op,
        #   byte-identical output preserved when off).
        cluster_reclaim_enabled = True,
        # cluster_reclaim_method: "auto" picks "coassoc" when this run
        #   actually used consensus clustering, else "centroid" (the only
        #   method available outside consensus mode, since the
        #   co-association matrix only exists there). Explicit "coassoc"
        #   falls back to "centroid" with a WARN if consensus wasn't used.
        cluster_reclaim_method = "auto",
        # cluster_reclaim_margin: required relative improvement of the best
        #   OTHER cluster's score over a point's own cluster's score before
        #   reassigning -- prevents boundary nibbling on points that are only
        #   marginally closer to another cluster. Reasoned starting value
        #   (matches this codebase's convention for other not-yet-calibrated
        #   thresholds, e.g. medoid_escalation_threshold=0.35), not yet
        #   empirically calibrated.
        cluster_reclaim_margin = 0.20,
        # cluster_reclaim_max_frac_per_cluster: safety cap -- never reassign
        #   more than this fraction of any single cluster's points in one
        #   pass. If more points qualify, only the strongest-margin ones (up
        #   to the cap) are reassigned; the rest are left in place and logged
        #   as held back. Guards against a genuinely coherent-but-unlucky
        #   cluster being dissolved wholesale into its neighbors.
        cluster_reclaim_max_frac_per_cluster = 0.5,
        # cluster_reclaim_flow_weight (Phase 4, ORDER_AWARE_DISCARD_HANDOFF_
        #   2026-09-01.md section 7.1 step 3): "centroid" reclaim method
        #   only -- discounts a point's own-cluster and best-other-cluster
        #   distances by how well its own per-bin velocity (computed
        #   directly in reclaim_leaked_points()'s own feature space, never
        #   reusing the kinetic flow field's velocity array, which lives in
        #   a different, often pre-PCA feature space) aligns with the
        #   direction toward that respective centroid: dist_eff = dist *
        #   (1 - w * relu(cos_sim(velocity, centroid - point))). 0.0 is a
        #   hard no-op -- the whole block is skipped, not just multiplied
        #   by a no-op factor, so own_dist/best_other_dist/qualifies stay
        #   byte-identical to pre-Phase-4 output. Requires kinetic_flow_
        #   field_enabled=True too (still off by default) -- so this
        #   default only takes effect once a caller has already opted into
        #   the kinetic flow-field apparatus; it changes nothing for the
        #   common case.
        #
        #   Default changed 0.0 -> 1.0 (2026-09-01) on real-data evidence: a
        #   weight sweep (0.0/0.5/1.0, medoid mode, small-scale smoke runs,
        #   D:\CUBE_SPLIT_VALIDATION_2026_08_31\QUICK_MEDOID_RECLAIM_FLOW_
        #   W00/W05/W10) found a real, monotonic effect -- reassigned-point
        #   count rose 46->46->56 (0.0->0.5->1.0) across more source
        #   clusters (5->7->8) -- with noise rate and final cluster count
        #   completely unchanged (reclaim only moves points BETWEEN already-
        #   real clusters, never in/out of noise) and DBCV/silhouette
        #   flat within this dataset's own run-to-run noise (-0.339/-0.337/
        #   -0.345 DBCV, ~0.091 silhouette throughout). No sweet spot found;
        #   full strength (1.0) is kept as the default given the modest,
        #   real, quality-neutral improvement. Explicit user decision to
        #   flip on this evidence, ahead of Phase 5's own mandatory video
        #   review of real example clips -- revisit if that review surfaces
        #   a concern.
        cluster_reclaim_flow_weight = 1.0,
        # consensus_prune_degenerate_seeds: when True, consensus_cluster()
        #   excludes any seed whose own cluster count falls below
        #   seed_sweep_min_valid_clusters (the same threshold
        #   seed_sweep_stability() already uses) before building the
        #   co-association matrix. Falls back to using all seeds, with a WARN,
        #   if fewer than 2 seeds survive pruning. Default False = today's
        #   behavior (all seeds used), unchanged.
        consensus_prune_degenerate_seeds = False,
        # rare_cluster_survival_criteria (2026-08-31, default flipped to
        #   "occurrence_persistence" after real-data calibration + a manual
        #   video-review decision -- see min_occurrence_persistence below for
        #   the full evidence trail). "population_fraction" is kept available
        #   as the pre-existing byte-identical min_cluster_freq logic, an
        #   escape hatch, never deleted.
        rare_cluster_survival_criteria = "occurrence_persistence",
        # min_occurrences: minimum discrete-bout count required under
        #   "occurrence_persistence". Confirmed a genuine no-op on both real
        #   calibration datasets below (every real cluster cleared even
        #   min_occurrences=5 by a wide margin -- the weakest cluster still
        #   had 17 qualifying bouts) -- kept at 3 as a cheap safety net for a
        #   future dataset with a truly singleton-driven cluster, not because
        #   3 itself was exercised by any real decision so far.
        min_occurrences = 3,
        # min_occurrence_persistence: feature-space per-cluster silhouette
        #   floor required under "occurrence_persistence". CALIBRATED
        #   2026-08-31 against two real 2D consensus runs on the same 21-
        #   session dataset (04_ADAPTIVECAP_SPLITFIX_RETEST, umap_n_neighbors
        #   auto; and its n_neighbors=60 sibling) plus a direct video review
        #   of the candidate clusters (10 example clips each, both runs) --
        #   see D:\3D DLC\CLAUDE.md's "Cluster-Quality Improvements" section
        #   for the fuller history and the CAVEAT below.
        #
        #   Per-cluster embedding-space silhouette on the auto-n run: 5=-0.199,
        #   21=-0.172, 22=-0.145, 16=-0.006, next-lowest (2/14) >=0.044,
        #   everything else 0.16-0.89. On the n=60 run: 15=-0.387, 1=-0.125,
        #   14=-0.264, everything else >=0.109. After video review, the user
        #   confirmed clusters 5/21/22 (auto-n) and 1/14/15 (n=60) should be
        #   pruned, but 16 should NOT -- despite its silhouette (-0.006) being
        #   worse than 0.0, independent internal-consistency checks (embedding
        #   radius 1.27x the partition median -- tighter than 5 OTHER non-
        #   pruned clusters; bout-duration CV 0.57, the TIGHTEST of the whole
        #   candidate group and below the 0.77 dataset median; zero inbound
        #   cross-cluster reclaim traffic) all pointed at 16 being a real,
        #   merely-adjacent behavior rather than an incoherent dump -- unlike
        #   cluster 5, independently confirmed as a genuine reclaim sink
        #   (received 125 points from 5 different other clusters via
        #   consensus co-association) and cluster 15, by far the most diffuse
        #   cluster in its entire partition (2.92x the median radius).
        #   -0.1 sits strictly between 16 (-0.006, survives) and the weakest
        #   confirmed-prune cluster on the auto-n run (22, -0.145) -- it
        #   reproduces the user's exact real decision on BOTH calibration
        #   runs (prunes {5,21,22} and {1,14,15}, keeps 16) with margin on
        #   both sides, not a boundary-hugging fit.
        #   CAVEAT: this was calibrated against UMAP-EMBEDDING-space
        #   silhouette (cheaply available from already-completed runs,
        #   without re-deriving the scaled feature matrix outside the
        #   pipeline) as a proxy for the feature-space silhouette this gate
        #   actually applies at runtime -- the two are known to diverge on
        #   some real data (see the 57.9%-dump-cluster case referenced in
        #   CLAUDE.md, where embedding-space and feature-space silhouette
        #   disagreed by ~0.58). The calibration is grounded by real video
        #   review, not silhouette alone, which is why it was adopted despite
        #   this gap -- but the exact -0.1 cutoff should be revisited once a
        #   live run with this criteria enabled reports real feature-space
        #   numbers for these same clusters.
        min_occurrence_persistence = -0.1,
        # min_occurrence_persistence_mode (2026-09-09, additive, default
        #   "fixed" = today's exact behavior, byte-identical): the -0.1 floor
        #   above was calibrated against ONE real dataset's embedding-space
        #   silhouettes (see its own comment) and doesn't adapt to a
        #   differently-conditioned dataset -- confirmed on real data to be
        #   far too aggressive on at least one run (16 of 21 candidate
        #   clusters pruned in one real consensus pass, most failing the
        #   fixed -0.1 floor by a wide margin even though several had
        #   plenty of real recurring bouts). "adaptive_zscore": derive the
        #   floor from THIS run's own per-cluster silhouette distribution
        #   (mean - min_occurrence_persistence_sd_mult * std, computed over
        #   whichever clusters have a finite silhouette in this partition)
        #   instead of importing a fixed cross-dataset number -- the same
        #   "z-score against this run's own data" pattern already used by
        #   _kinetic_coherence_composite_z() for the kinetic split-trigger.
        #   "composite_zscore": additionally blends bout_count (recurrence)
        #   into the same z-scored index alongside silhouette
        #   (occurrence_persistence_composite_sil_weight below), rather than
        #   judging persistence on silhouette alone -- silhouette by itself
        #   can read as "bad" from a small/awkwardly-shaped-in-feature-space
        #   cluster that nonetheless recurs reliably, which is exactly the
        #   kind of single-metric blind spot _kinetic_coherence_composite_z's
        #   own docstring already documents for the kinetic-coherence score.
        #   Every mode falls back one level (composite_zscore -> plain
        #   silhouette vs. the fixed floor; adaptive_zscore -> the fixed
        #   floor) with a logged WARN when too few clusters
        #   (min_occurrence_persistence_adaptive_min_clusters) are available
        #   to compute a meaningful mean/std. A cluster that fails the hard
        #   min_occurrences bout floor is never rescued by either adaptive
        #   mode -- zero real recurrence isn't a persistence-scoring
        #   question, matching "fixed" mode's own existing behavior.
        # 2026-09-18: default changed "fixed" -> "occurrence_only" after
        #   direct real-data evidence (see min_occurrence_persistence's own
        #   comment for the triggering case) plus a direct user correction:
        #   extensive testing has shown feature-space silhouette is not a
        #   reliable indicator of genuine behavioral-cluster quality here --
        #   "fixed"/"adaptive_zscore"/"composite_zscore" all still gate
        #   survival on it (composite_zscore only softens the gate, at a
        #   0.7 silhouette weight by default). "occurrence_only" drops
        #   silhouette from the survival decision entirely -- a cluster
        #   survives purely on recurrence (bout_ok: >= min_occurrences
        #   discrete bouts of >= min_epoch_dur_s each). Silhouette is still
        #   computed and logged in survival_detail for visibility, just
        #   never used to prune. The older modes are kept, unremoved, as
        #   opt-in alternatives -- not deleted, since they may still be
        #   useful diagnostically or on a dataset where silhouette turns out
        #   to behave better.
        min_occurrence_persistence_mode = "occurrence_only",  # "occurrence_only" | "fixed" | "adaptive_zscore" | "composite_zscore"
        # min_occurrence_persistence_sd_mult: how many standard deviations
        #   below this run's own mean (silhouette alone under
        #   adaptive_zscore, or the blended composite index under
        #   composite_zscore) a cluster must fall to be pruned. 2.0 is the
        #   conventional "clear statistical outlier" bar; only used when
        #   min_occurrence_persistence_mode is not "fixed".
        min_occurrence_persistence_sd_mult = 2.0,
        # min_occurrence_persistence_adaptive_min_clusters: minimum number of
        #   eligible clusters needed before either adaptive mode trusts its
        #   own computed mean/std (below this, falls back with a WARN --
        #   mean/std aren't meaningful statistics on 1-2 points). Matches
        #   _kinetic_coherence_composite_z()'s own floor of 3.
        min_occurrence_persistence_adaptive_min_clusters = 3,
        # occurrence_persistence_composite_sil_weight: only used under
        #   "composite_zscore" -- blend weight for z-scored silhouette vs.
        #   z-scored bout_count (1 - this) in the composite index. 0.7
        #   keeps silhouette as the dominant signal (it's the more direct
        #   separation/quality measure) while still letting a cluster's own
        #   recurrence frequency pull it back from being pruned on
        #   silhouette alone -- not yet real-data calibrated; revisit once a
        #   live run with this mode enabled reports real composite values.
        occurrence_persistence_composite_sil_weight = 0.7,
        # rare_cluster_frequency_carveout_enabled (2026-09-03): "occurrence_
        #   persistence" prunes a cluster if it fails bout-count OR
        #   silhouette (see _prune_rare_clusters()'s "not bout_ok or not
        #   sil_ok" check) -- meaning a genuinely small, brief-but-real
        #   behavior (a shake, a scratch bout -- the exact case
        #   occurrence_persistence's bout-count leg was originally designed
        #   to protect) can still be pruned purely for a low feature-space
        #   silhouette, e.g. because a short, high-frequency behavior is
        #   naturally noisier per-bin than a long dwelling one. When True, a
        #   cluster whose bout_count clears
        #   rare_cluster_frequency_carveout_min_bouts survives despite
        #   failing sil_ok -- BUT ONLY if it is also small
        #   (rare_cluster_frequency_carveout_max_frac, below). This is
        #   deliberately NOT a general silhouette override: a large, diffuse
        #   cluster (the real 57.9%-of-dataset "dump cluster" documented in
        #   D:\3D DLC\CLAUDE.md's Phase 6 real-data validation, which failed
        #   feature-space silhouette -0.234 despite looking fine in
        #   embedding space) must remain fully prunable regardless of how
        #   many bouts it racks up -- being huge and frequent is not evidence
        #   of being a real, coherent short behavior, it's the opposite
        #   signal. The size ceiling is what keeps this carve-out scoped to
        #   its intended target (small clusters of short behaviors) instead
        #   of accidentally re-opening the dump-cluster loophole this
        #   criteria was calibrated to close. bout_ok is still required
        #   independently -- frequency alone never overrides genuine
        #   sparsity. Default False: today's "not bout_ok or not sil_ok"
        #   behavior is unchanged unless explicitly opted into. Only read
        #   when rare_cluster_survival_criteria == "occurrence_persistence";
        #   inert (and inert-by-construction, never read) otherwise.
        rare_cluster_frequency_carveout_enabled = False,
        # rare_cluster_frequency_carveout_min_bouts_per_video: the bout-count
        #   bar for the carve-out above, expressed PER VIDEO/SESSION and
        #   scaled by n_videos (= number of session_boundaries segments; a
        #   standalone caller with no session_boundaries is treated as one
        #   video) rather than a flat total count -- "if something happens
        #   less than 2 or 3 times per video, it's probably noise" is the
        #   rule of thumb this implements. A flat absolute bout-count bar
        #   would either over-protect on a large pooled multi-session dataset
        #   (a behavior seen only once or twice per video, but pooled across
        #   dozens of videos, could clear a flat count of 20 while still
        #   being noise per-video) or under-protect on a small one (a
        #   genuinely real, frequent short behavior in a single-video run
        #   could never reach a flat count of 20 at all) -- neither of which
        #   matches the actual "is this real per video" question the
        #   carve-out is meant to answer. 2.5 sits between the "2 or 3 times"
        #   rule of thumb. Effective threshold = max(min_occurrences,
        #   ceil(this * n_videos)) -- see _prune_rare_clusters(). Not yet
        #   calibrated against real data -- a reasoned starting value, same
        #   status min_occurrence_persistence had before its own real-data
        #   calibration pass.
        rare_cluster_frequency_carveout_min_bouts_per_video = 2.5,
        # rare_cluster_frequency_carveout_max_frac: population-fraction
        #   ceiling (of n_samp, 0-1) for the carve-out above -- a cluster
        #   larger than this is NEVER eligible, no matter its bout_count.
        #   This is the mechanism that keeps the carve-out targeted at small
        #   clusters of short behaviors and excludes large diffuse clusters
        #   (see rare_cluster_frequency_carveout_enabled's docstring for why
        #   "big and frequent" must not be treated as protective). 0.05 (5%
        #   of bins) is a reasoned starting point -- comfortably below the
        #   real 57.9% dump-cluster case that motivated this feature's
        #   guardrail, and in the range genuinely "rare" behaviors occupy in
        #   this codebase's own real calibration data. Not yet calibrated
        #   against real data.
        rare_cluster_frequency_carveout_max_frac = 0.05,
        # consensus_coassoc_noise_floor: after consensus_cluster()'s fcluster
        #   maxclust cut, demote any point whose mean co-association to the
        #   other members of its own assigned cluster falls below this floor
        #   to noise (-1). Applied before consensus_refine_enabled's
        #   split/merge pass and before rare-cluster pruning. 0.0 = off
        #   (today's behavior, unchanged).
        consensus_coassoc_noise_floor = 0.0,
        # ── Quality-gated consensus noise recovery (opt-in) ─────────────────
        #   Standalone diagnostic (real data, NOT integrated into this
        #   pipeline) found HDBSCAN/consensus noise points can sometimes be
        #   usefully recovered into a real cluster using co-association
        #   confidence, but ONLY if the bar required to join scales with the
        #   RECEIVING cluster's own current tightness (mean own-cluster
        #   co-association) -- a flat threshold measurably diluted tight
        #   clusters; the adaptive version achieved a clean result (zero
        #   receiving clusters got worse) for consensus mode specifically.
        #   Recovered fraction was small (1-6% of noise) either way -- a
        #   quality nibble, not a fix for the pipeline's overall noise rate.
        #   consensus mode ONLY: co_assoc is a consensus-only artifact (same
        #   scoping reclaim_leaked_points()'s "coassoc" method already has).
        #   False (default) = today's behavior, unchanged.
        consensus_noise_recovery_enabled = False,
        # consensus_noise_recovery_base_score: co-association confidence
        #   required for a noise point to join the MOST DIFFUSE real cluster
        #   (quality-normalized score 0.0). Diagnostic-validated range
        #   ~0.2-0.3; not yet calibrated inside this pipeline itself.
        consensus_noise_recovery_base_score = 0.3,
        # consensus_noise_recovery_cap_score: co-association confidence
        #   required for a noise point to join the TIGHTEST real cluster
        #   (quality-normalized score 1.0). Diagnostic-validated ~0.9.
        consensus_noise_recovery_cap_score = 0.9,
        # consensus_noise_recovery_margin: winning cluster's mean
        #   co-association score must beat the runner-up cluster's by at
        #   least this much, in addition to clearing the quality-scaled
        #   score floor above -- prevents recovering a point that is only
        #   ambiguously closer to one cluster over another. Diagnostic-
        #   validated ~0.15.
        consensus_noise_recovery_margin = 0.15,
        # consensus_noise_recovery_max_frac_per_cluster: safety cap -- never
        #   recover more than this fraction of any one cluster's CURRENT
        #   size from noise in a single pass. Deliberately smaller than
        #   cluster_reclaim_max_frac_per_cluster's 0.5 default: these are
        #   noise-origin points (already rejected once by every mechanism
        #   upstream), not already-clustered points reclaim_leaked_points()
        #   is already vouching for -- a tighter leash is warranted. Not yet
        #   calibrated inside this pipeline; 0.15 is a reasoned starting
        #   value pending real-run validation.
        consensus_noise_recovery_max_frac_per_cluster = 0.15,
        # hdbscan_membership_confidence_floor: after run_hdbscan() produces
        #   hdb_labels, demote any point whose own-cluster membership
        #   probability (hdbscan.all_points_membership_vectors) falls below
        #   this floor to noise (-1). Applied identically regardless of which
        #   path produced hdb_labels (primary, medoid-adopted, or a
        #   seed-sweep per-seed fit). 0.0 = off (today's behavior, unchanged).
        hdbscan_membership_confidence_floor = 0.0,
        # embedding_stability_retry_enabled: when True and the standalone
        #   diagnostic seed sweep's mean_ari falls below
        #   embedding_stability_retry_threshold, re-runs run_umap()+
        #   run_hdbscan() exactly once with a boosted umap_n_neighbors (see
        #   the plan's Phase 5.1 cap formula) and re-runs seed_sweep_stability
        #   on the new embedding. The retry is kept only if it passes a
        #   three-part accept gate (real ARI improvement AND no feature-space
        #   DBCV regression AND no rare-cluster-survivor-count regression) --
        #   mean_ari alone is not a sufficient accept criterion (over-
        #   smoothing can raise seed agreement by erasing genuine structure).
        #   Exactly one retry per run(), ever. Default False = today's
        #   behavior, unchanged.
        embedding_stability_retry_enabled = False,
        # embedding_stability_retry_threshold: mean_ari trigger floor for the
        #   retry above. Mirrors consensus_auto_threshold's default -- not yet
        #   independently calibrated.
        embedding_stability_retry_threshold = 0.55,
        # embedding_stability_retry_boost_factor: multiplier applied to the
        #   current umap_n_neighbors when retrying. The real, documented
        #   16->30 n_neighbors bump this mirrors was ~1.9x.
        embedding_stability_retry_boost_factor = 2.0,
        # embedding_stability_retry_frac_of_n_samp: fraction of training bins
        #   used to derive the retry's n_neighbors cap (frac_cap). Not yet
        #   calibrated.
        embedding_stability_retry_frac_of_n_samp = 0.03,
        # embedding_stability_retry_absolute_floor: minimum frac_cap value --
        #   CUBE's own smallest common umap_n_neighbors default.
        embedding_stability_retry_absolute_floor = 15,
        # embedding_stability_retry_n_neighbors_cap: manual override for the
        #   retry's n_neighbors cap. 0 = auto-derive per the Phase 5 formula
        #   (min of frac_cap and bout_cap); >0 = use this value directly.
        embedding_stability_retry_n_neighbors_cap = 0,
        # embedding_stability_retry_bout_safety_multiple: multiplier on
        #   (min_epoch_dur_s-in-bins * min_occurrences) used to derive the
        #   retry's bout_cap -- the only quality-motivated ceiling on the
        #   boosted n_neighbors (n_neighbors should never approach the total
        #   occurrence footprint of the smallest real behavior CUBE is
        #   configured to preserve). Not yet calibrated.
        embedding_stability_retry_bout_safety_multiple = 2.5,
        # embedding_stability_retry_quality_tolerance: maximum allowed
        #   feature-space DBCV regression (post-retry vs. pre-retry) before
        #   the retry is rejected on criterion (ii). Not yet calibrated.
        embedding_stability_retry_quality_tolerance = 0.05,
        # ── Trajectory-shape + kinetic-flow (TRAJECTORY_SHAPE_AND_KINETIC_
        #   FLOW_PLAN.md, Aug 2026): order-sensitive shape features and
        #   flow-informed cluster boundaries. Every key below defaults to a
        #   value that reproduces pre-plan output byte-for-byte, until
        #   real-data validated (see the plan's Phase 8). ──
        # order_shape_features_enabled: master switch for Phase 2's
        #   order-sensitive trajectory-shape feature block appended to
        #   extract_features_v2/_3d. DEFAULT CHANGED TO TRUE 2026-09-02 as
        #   part of "temporal-aware clustering" becoming the standard CUBE
        #   default (real 4-condition validation, 2026-09-01, Damien DLC
        #   21-session 2D pool: consensus improved -- mean silhouette
        #   0.262->0.267, Calinski-Harabasz 3055->3236, cluster-size CV
        #   0.745->0.564; medoid regressed on the same metrics -- silhouette
        #   0.523->0.454, CH 4582->2981. Flipped for BOTH remedy paths per
        #   explicit user decision after being shown this asymmetry, not
        #   because medoid's regression was resolved. See
        #   D:\CUBE\Clustering Comparison Experiment.md and
        #   D:\CUBE\ORDER_AWARE_DISCARD_HANDOFF_2026-09-01.md.). Set False to
        #   run "temporally-aware CUBE off" (the pre-2026-09-02 baseline).
        order_shape_features_enabled = True,
        # order_shape_window_mode: "fixed_short" (default) uses
        #   order_shape_window_ms directly; "bout_calibrated" sizes the
        #   window from a prior partition's observed bout-duration
        #   distribution on a re-run, falling back to fixed_short (logged)
        #   on a first-ever run with no prior partition; "fps_adaptive"
        #   (2026-08-30 decision) computes max(50, ceil(10000/fps))ms -- a
        #   10-raw-frame minimum window (frame-count-first, not ms-first:
        #   fewer frames can't reliably establish real order vs. noise),
        #   with 50ms as a hard floor for now. At CUBE's real ~30fps this
        #   resolves to 333ms, not the untested 100ms fixed_short default.
        order_shape_window_mode = "fixed_short",
        # order_shape_window_ms: window length for the order-sensitive
        #   shape terms, in milliseconds -- matches CUBE's existing
        #   shortest engineered scale. Deliberately short per the plan's
        #   safety invariant (a window spanning too much history can blend
        #   two real behaviors into one feature). Not yet calibrated.
        order_shape_window_ms = 100,
        # order_shape_channel_set: which reduced channel subset feeds the
        #   order-sensitive shape terms. "limb_velocity_direction" (default)
        #   reuses the per-bodypart velocity vectors extract_features_v2/_3d
        #   already compute internally, restricted to a small limb subset
        #   (schema-resolved per 2D/3D) to keep the depth-2 cross-term count
        #   bounded.
        order_shape_channel_set = "limb_velocity_direction",
        # order_shape_depth: fixed at 2 (depth-1 net displacement + depth-2
        #   signed pairwise cross terms). Not exposed as freely tunable --
        #   higher depth risks combinatorial blowup with no established
        #   need.
        order_shape_depth = 2,
        # kinetic_coherence_enabled: master switch for Phase 3's diagnostic
        #   kinetic-coherence score (transition-matrix + velocity-kernel
        #   components). Purely additive/diagnostic when on -- no label
        #   array is ever modified by this flag alone. DEFAULT CHANGED TO
        #   TRUE 2026-09-02, part of the "temporal-aware clustering" default
        #   flip -- see order_shape_features_enabled's comment above for the
        #   real-data evidence and rationale. Set False for "temporally-aware
        #   CUBE off".
        kinetic_coherence_enabled = True,
        # kinetic_coherence_lag_bins: lag-1 (default) transition matrix,
        #   matching the bin resolution extract_features_v2/_3d already use.
        kinetic_coherence_lag_bins = 1,
        # kinetic_split_trigger_enabled (Phase 4): when True (and
        #   kinetic_coherence_enabled is also True), a cluster whose kinetic-
        #   coherence score falls below kinetic_split_trigger_threshold is
        #   additionally sent to _local_recluster_and_assign(). Inert while
        #   kinetic_coherence_enabled is False. DEFAULT CHANGED TO TRUE
        #   2026-09-02, part of the "temporal-aware clustering" default flip
        #   -- see order_shape_features_enabled's comment above. Set False
        #   for "temporally-aware CUBE off".
        kinetic_split_trigger_enabled = True,
        # kinetic_split_trigger_threshold: calibrated 2026-09-01 via a
        #   biologically-framed user choice ("Moderate") on the validation
        #   dataset. DEFAULT CHANGED FROM 0.0 TO 0.25 2026-09-02, part of the
        #   "temporal-aware clustering" default flip. Set back to 0.0 for
        #   "temporally-aware CUBE off" (though inert there regardless, since
        #   kinetic_split_trigger_enabled is also False in that state).
        kinetic_split_trigger_threshold = 0.25,
        # kinetic_split_trigger_auto_baseline (2026-09-07): when True
        #   (default), candidate selection uses _kinetic_coherence_composite_z()
        #   instead of the fixed kinetic_split_trigger_threshold -- z-scores
        #   destination_entropy, interior_velocity_cv, and bout_count against
        #   THIS RUN's own valid-cluster distribution (clusters with
        #   bout_count >= kinetic_split_trigger_min_bout_count) and combines
        #   them into one composite index, so the effective baseline adapts
        #   per-dataset instead of comparing every run to a constant
        #   calibrated on one specific dataset. Falls back to the fixed
        #   kinetic_split_trigger_threshold if fewer than 3 clusters pass the
        #   bout-count floor (too little data to compute a meaningful
        #   mean/std this run). Set False to always use the fixed threshold.
        kinetic_split_trigger_auto_baseline = True,
        # kinetic_split_trigger_min_bout_count: data-sufficiency floor for the
        #   auto baseline above -- a cluster below this bout_count is excluded
        #   from the composite-z distribution entirely (not scored, not used
        #   to compute the mean/std) since sparse clusters can score a
        #   spurious 0.0 destination_entropy from having too few transitions
        #   to estimate, not from real heterogeneity (see kinetic_coherence.png
        #   analysis, clusters with 3-12 bouts). Deliberately above
        #   _KINETIC_COHERENCE_RECURRENCE_NORM_TARGET (5) -- that constant
        #   only defines "fully recurrent" for the score's own normalization,
        #   not "enough data to trust this cluster's statistics" for gating.
        kinetic_split_trigger_min_bout_count = 10,
        # kinetic_split_trigger_zscore_cutoff: standard-deviation cutoff for
        #   the auto composite baseline -- a cluster more than this many SDs
        #   below its run's own mean composite index is a split candidate.
        #   -1.0 SD is a standard statistical convention, not a value tuned
        #   on any one dataset -- the actual baseline (each component's
        #   mean/std) is recomputed from that run's own data every time.
        kinetic_split_trigger_zscore_cutoff = -1.0,
        # embedding_stability_retry_kinetic_gate_enabled (Phase 5): adds a
        #   fourth accept/reject condition (kinetic-coherence non-regression)
        #   to the existing three-part embedding_stability_retry gate.
        #   Inert unless embedding_stability_retry_enabled is also True.
        embedding_stability_retry_kinetic_gate_enabled = False,
        # embedding_stability_retry_kinetic_tolerance (2026-08-30 decision):
        #   dedicated acceptable-regression deadband for condition (iv)
        #   above -- NOT shared with embedding_stability_retry_quality_
        #   tolerance (DBCV's tolerance), since coherence and DBCV measure
        #   different things. Starting value only, not yet independently
        #   calibrated. Inert unless embedding_stability_retry_kinetic_gate_
        #   enabled is also True.
        embedding_stability_retry_kinetic_tolerance = 0.05,
        # kinetic_flow_field_enabled (Phase 6): master switch for the
        #   continuous kinetic flow field over the embedding + per-boundary
        #   alignment diagnostic. Diagnostic-only in isolation -- changes no
        #   cluster label by itself; Phase 7 is what acts on it. DEFAULT
        #   CHANGED TO TRUE 2026-09-02, part of the "temporal-aware
        #   clustering" default flip -- see order_shape_features_enabled's
        #   comment above. Set False for "temporally-aware CUBE off".
        kinetic_flow_field_enabled = True,
        # kinetic_flow_field_exclude_order_shape_terms: LEGACY hard-exclusion
        #   override. Default False now that kinetic_flow_field_order_shape_
        #   weight (below) is the primary control -- explicit True still
        #   fully excludes order-shape columns from the flow field's
        #   velocity-differencing channel set (equivalent to weight=0.0,
        #   exact: a column scaled to zero contributes zero to both the
        #   differenced velocity vector and its norm), kept for saved
        #   session JSON predating the weight dial. Inert (no effect either
        #   way) when order_shape_features_enabled is False.
        kinetic_flow_field_exclude_order_shape_terms = False,
        # kinetic_flow_field_order_shape_weight (2026-08-30, supersedes the
        #   old hard exclude/include binary above): scales Phase 2's order-
        #   sensitive shape-term columns before they enter the flow field's
        #   velocity-differencing channel set. 0.0 = fully excluded (old
        #   exclude=True); 1.0 = fully included at native scale (old
        #   exclude=False). DEFAULT IS SMALL BUT NON-ZERO (0.1), NOT 0.0 --
        #   a deliberate choice, not a placeholder: order-shape terms are an
        #   already-derivative-like quantity (a discrete Levy-area cross
        #   term), so differencing them again to build "velocity" risks
        #   stacking two noise-amplifying transforms (the documented reason
        #   the old default was full exclusion) -- but a small non-zero
        #   weight lets a user experiment with genuine order-sequence
        #   sensitivity in Tier 3b's boundary reshaping (reach-then-retract
        #   vs. retract-then-reach) without either gambling on the full-
        #   inclusion extreme or losing the signal entirely, and can be
        #   raised per-experiment if a real analysis needs more of it.
        #   Inert (no effect) when order_shape_features_enabled is False or
        #   the legacy exclude flag above is explicitly True.
        kinetic_flow_field_order_shape_weight = 0.1,
        # kinetic_flow_field_order_shape_presmooth_window: bins; a heavier,
        #   dedicated boxcar smoothing pass applied ONLY to the (weighted)
        #   order-shape columns before differencing -- independent of the
        #   general kinetic_flow_field_presmooth_enabled/window below, which
        #   if also on still applies afterward to every channel including
        #   these. Default (7) deliberately favors missing a real fast
        #   order-reversal over reacting to tracking-jitter noise (an
        #   accepted risk for most data, per 2026-08-30 discussion) -- a
        #   startle-flinch-then-recoil under ~230ms at 30fps could be
        #   smoothed away; Experiment Plan Section A's real bout-length data
        #   should refine this value, not just this placeholder reasoning.
        #   0 = no dedicated presmoothing (raw weighted columns differenced
        #   directly). Inert under the same conditions as the weight above.
        kinetic_flow_field_order_shape_presmooth_window = 7,
        # kinetic_flow_field_presmooth_enabled: documented fallback, not the
        #   default -- a short boxcar/median smoothing pass applied to the
        #   flow field's input channels before differencing. Only worth
        #   enabling if Phase 8 real-data validation finds the flow field
        #   still too noisy with the exclusion above already on.
        kinetic_flow_field_presmooth_enabled = False,
        # kinetic_flow_field_presmooth_window: bins; not yet calibrated --
        #   inert while kinetic_flow_field_presmooth_enabled is False.
        kinetic_flow_field_presmooth_window = 3,
        # kinetic_reweight_strength (Phase 7): 0.0 = d_kinetic == d_spatial
        #   exactly, byte-identical to spatial-only clustering. Continuous,
        #   not binary -- inert unless kinetic_flow_field_enabled is also
        #   True. This was the single most consequential default in this
        #   plan (directly reshapes real cluster boundaries); it was a FIXED
        #   1.0 from 2026-09-02 (calibrated via a biologically-framed user
        #   choice, "Modest reweight," on ONE validation dataset) until
        #   2026-09-07, when it was changed to the string "auto" (see
        #   _kinetic_reweighted_hdbscan_auto() below) -- a fixed constant
        #   calibrated on one dataset has no reason to suit every dataset's
        #   own flow-field evidence (confirmed on a real run: boundary-
        #   alignment scores that were almost all >0.8 -- little evidence of
        #   any spurious cut -- still produced 28.8% of ALL points
        #   reassigned and one cluster losing 78% of itself at strength=1.0,
        #   a disruption the boundary evidence didn't obviously justify).
        #   "auto" derives a per-dataset starting strength from that same
        #   run's own boundary-alignment diagnostic, then checks the actual
        #   reassigned fraction against what that evidence would justify and
        #   backs off (halves, refits once) if it overshoots -- see
        #   _resolve_auto_kinetic_reweight_strength()'s docstring for the
        #   exact mapping. An explicit numeric value here (0.0, 1.0, or anything
        #   else) always overrides "auto" and is used exactly as given,
        #   unmodified -- same "explicit wins" convention compat_mode
        #   already follows elsewhere in DEFAULTS. Set to 0.0 for
        #   "temporally-aware CUBE off".
        kinetic_reweight_strength = "auto",
        # kinetic_reweight_fn: the f(alignment) modulation form. Fixed at
        #   "multiplicative" for this plan's first landing, not exposed as
        #   freely pluggable.
        kinetic_reweight_fn = "multiplicative",
        # kinetic_reweight_log_assignment_diff: unconditional logging of the
        #   before/after per-point cluster-assignment diff whenever
        #   kinetic_reweight_strength > 0 -- the auditability mitigation for
        #   a continuous reweighting scheme.
        kinetic_reweight_log_assignment_diff = True,
        # kinetic_reweight_restability_pct (2026-08-30, supersedes the old
        #   kinetic_reweight_restability_frac global-fraction-of-dataset
        #   check -- dropped entirely per that day's decision, not kept as
        #   a hybrid): percent of an INDIVIDUAL affected cluster's own
        #   points that must be reassigned before seed_sweep_stability() is
        #   re-run on the post-reweight partition (so _auto_triggered never
        #   reads stale pre-reweight sweep statistics when the reweighting
        #   genuinely mattered for some cluster). A flat percentage of the
        #   WHOLE dataset was a poor proxy -- a large cluster losing a
        #   large fraction of itself could look small against the total
        #   point count. Not yet independently calibrated.
        kinetic_reweight_restability_pct = 25.0,
        # kinetic_reweight_restability_resweep_enabled (Sep 2026): gates the
        #   re-sweep the paragraph above describes. False (default) means a
        #   restability trip is still logged, but _sweep is left as-is
        #   (whichever remedy path produced it -- primary standalone sweep,
        #   medoid's own sweep, or consensus's derived stats) rather than
        #   paying for a fresh seed_sweep_stability() call. This re-sweep
        #   NEVER changes hdb_labels/n_cl/which clustering wins -- by the
        #   time it runs, medoid/consensus/reweight have already decided the
        #   final partition; its only consumers are cluster_stability.png
        #   and _validation["cluster_stability"]'s reported mean_ari/dbcv/
        #   pass-warn status, i.e. it is pure reporting freshness, not
        #   correctness. Off by default so that freshness is opt-in rather
        #   than an unconditional extra ~seed_sweep_n-seed UMAP+HDBSCAN pass
        #   every time a reweight happens to move >= kinetic_reweight_
        #   restability_pct of some cluster. Set True to restore the
        #   pre-Sep-2026 always-re-sweep-when-tripped behavior.
        kinetic_reweight_restability_resweep_enabled = False,
        # kinetic_reweight_min_f / kinetic_reweight_max_f: clamp bounds on
        #   f(alignment) -- prevents d_kinetic collapsing toward zero
        #   (mutual-reachability degeneracy) or exploding unboundedly.
        kinetic_reweight_min_f = 0.25,
        kinetic_reweight_max_f = 4.0,
        # kinetic_reweight_seed_memory_gb (Phase 2, ORDER_AWARE_DISCARD_
        #   HANDOFF_2026-09-01.md section 7.6): fast fail-early memory guard
        #   for the NEW per-seed flow-field/reweighted-fit cost Option C
        #   adds to seed_sweep_stability()/consensus_cluster()'s per-seed
        #   dispatch (_kinetic_reweight_seed_memory_check()) -- sized off
        #   graph edge count (~n_samp * umap_n_neighbors), a different,
        #   cheaper scaling law than consensus_max_memory_gb's own
        #   O(n_samp^2) co-association-matrix guard. <= 0 disables the
        #   guard entirely (unbounded). Exceeding it degrades to running
        #   every seed WITHOUT the kinetic reweight for that call, rather
        #   than aborting the sweep/consensus pass -- true no-op whenever
        #   kinetic_flow_field_enabled is off (the guard's own estimate is
        #   never even computed in that case).
        kinetic_reweight_seed_memory_gb = 4.0,
        # consensus_merge_flow_weight (Phase 3, ORDER_AWARE_DISCARD_HANDOFF_
        #   2026-09-01.md section 7.1 step 2 / section 7.5 Phase 3): power-
        #   dial in [0, 1] rescaling refine_consensus_clusters()'s existing
        #   co-association merge score by a flow-aware term for that
        #   candidate cluster pair -- boundary_alignment is recomputed
        #   against consensus's own Ward-linkage label space each refinement
        #   iteration by reusing the SAME flow-field graph edges Option C
        #   already builds (the "borrow the graph, score these labels"
        #   pattern), never rebuilt from scratch. combined = co_assoc *
        #   (1-boundary_alignment)**w -- section 6.10/7.1's exact reference
        #   formula (merge_score = co_assoc * (1-boundary_alignment)) is the
        #   w=1.0 endpoint precisely; at w=0.0 (default), (1-boundary_
        #   alignment)**0 == 1, so combined == co_assoc exactly, meaning
        #   merge_by_coassociation()'s behavior (both which pair sorts first
        #   and the thresh cutoff) is byte-identical to pre-Phase-3 output.
        #   A candidate pair with no flow-graph adjacency at all (no edges
        #   connect the two clusters in umap_model.graph_) also falls back
        #   to plain co_assoc regardless of w, since there is no flow
        #   evidence to blend in for that pair. True no-op unless BOTH this
        #   is > 0 AND kinetic_flow_field_enabled is True AND consensus_
        #   refine_enabled is True (merge scoring only runs inside
        #   refine_consensus_clusters()) -- the whole flow-field build for
        #   this purpose is skipped (not just the blend) when this is <= 0,
        #   so leaving it at 0.0 costs nothing extra even with kinetic_
        #   flow_field_enabled on for Option C. DEFAULT CHANGED FROM 0.0 TO
        #   1.0 2026-09-02, part of the "temporal-aware clustering" default
        #   flip (consensus-only effect by construction -- see
        #   order_shape_features_enabled's comment above; inert for medoid
        #   regardless of this value, since merge scoring only runs inside
        #   refine_consensus_clusters()). Set back to 0.0 for "temporally-
        #   aware CUBE off".
        consensus_merge_flow_weight = 1.0,
        # kinematic_directedness_enabled (v6 K2, Kinematic_Transition_v6_
        #   Implementation_Plan.md): off by default, opt-in only. When True,
        #   writes an additional per-session sidecar CSV,
        #   <stem>_bout_lengths_hmm_enriched.csv, alongside the canonical
        #   *_bout_lengths_hmm.csv -- the canonical 3-column B-SOiD-format
        #   file plus five new per-bout directedness columns from
        #   compute_bout_directedness() (net_displacement_px, path_length_px,
        #   straightness_ratio, mean_speed_px_s, heading_consistency). The
        #   canonical bout CSV itself is never touched, in either state of
        #   this flag -- when False (default), no sidecar is written at all
        #   (not written empty), and every existing output file is
        #   byte-identical to pre-v6 output.
        kinematic_directedness_enabled = False,
        # ── Environmental context & object interaction (v6 part 2) ─────────────
        # env_features_enabled: master switch, off by default.  With it False
        #   (the default) none of the following ever runs: no EnvContextWindow
        #   invitation in the GUI, all_env_cfg is populated with None for every
        #   session, compute_session_env_context() is never called,
        #   session_env_context.json is never written (not even empty), and
        #   the Step 6/7 bout-CSV enrichment / approach-avoid detection are
        #   both skipped entirely. See Environmental_Context_v6_Implementation
        #   _Plan.md's "Opt-in guarantee" section -- this flag being False
        #   must reproduce byte-identical output to a pre-this-feature run.
        env_features_enabled = False,
        # env_arena_cfg: None (default) = no shapes traced for any session.
        #   When set, schema is:
        #     {"schema_version": 3, "paradigm": <enum str>,
        #      "reference_stem": str, "coord_space": "post_crop",
        #      "reference_shapes": {"boundary": {...}|None,
        #                           "regions": [...], "objects": [...]},
        #      "per_video": {"<stem>": {"mode": "transform"|"override", ...,
        #                               "role_overrides": {...}|None}}}
        #   See Environmental_Context_v6_Implementation_Plan.md Step 1 for the
        #   full shape/role vocabulary.  Turning env_features_enabled on with
        #   env_arena_cfg left at None (or with no traced shapes for a given
        #   session) must still be a no-op -- empty summaries, no crash.
        env_arena_cfg = None,
        # env_interaction_threshold: pixel distance under which the animal is
        #   considered "interacting" with an object, for object_interaction
        #   _bouts/total_interaction_time_sec bout detection.  None (default)
        #   = auto-computed per-session as a small multiple of the animal's
        #   own tracked spine length (see compute_session_env_context()),
        #   giving a physically meaningful, arena-independent default instead
        #   of an arbitrary raw pixel number the user would have to guess.
        #   Still overridable by an explicit user-supplied pixel value.
        env_interaction_threshold = None,
        # ── Body-region feature weighting (issue 1b) ──────────────────────────
        # bodypart_weights: {bodypart_name: multiplier}.  {} (default) = every
        #   multiplier is exactly 1.0 -> bit-identical output to unweighted
        #   behaviour.  Off by default: unlike issue 2's visibility features,
        #   this requires domain judgment about which regions matter and must
        #   not silently change existing runs.
        bodypart_weights       = {},
        # auto_bodypart_weighting: data-driven, automatic COMPLEMENT to the
        #   manual bodypart_weights above.  ON by default (unlike manual
        #   weighting) -- this doesn't require domain judgment, it purely
        #   reads each bodypart's own aggregate bad-frame fraction across
        #   sessions and tapers its weight down continuously for bodyparts
        #   that are chronically unreliable but not bad enough to hard-drop
        #   -- those otherwise enter feature extraction at full weight,
        #   contributing flat-interpolated near-duplicate vectors that
        #   inflate HDBSCAN noise and push DBCV toward degenerate.  An
        #   explicit entry in bodypart_weights for a given bodypart always
        #   wins over the auto-computed one. False reverts to pre-existing
        #   behaviour (manual weights only, or uniform if none set).
        auto_bodypart_weighting = True,
        # auto_bp_weight_session_thresh: per-session bad-frame-fraction
        #   threshold above which that session counts as "affected" for a
        #   bodypart (reuses the same 0.3 convention as the DLC-quality
        #   warning gate). auto_bp_weight_lo/_hi (below) then taper on the
        #   FRACTION OF SESSIONS affected, not a magnitude statistic --
        #   robust to both failure modes seen on real data: a mean-based
        #   stat dilutes a bodypart bad (42-67%) in only 5 of 21 sessions
        #   down to mean=0.157 (missed entirely), while a magnitude
        #   percentile/max-based stat over-corrects, since with ~20 sessions
        #   almost every bodypart has at least one session with a bad-frame
        #   spike (confirmed: 16 of 22 bodyparts flagged, mostly jaws/paws
        #   driven by a single high-turned-away session). Counting sessions
        #   affected catches the former (5/21 = 24% of sessions, well above
        #   auto_bp_weight_lo) without over-triggering on the latter (a
        #   single fluke session stays under auto_bp_weight_lo). The
        #   turned-away-driven confound itself is separately handled by
        #   turned_away_exclude_from_bad_frac below.
        auto_bp_weight_session_thresh = 0.3,
        # auto_bp_weight_lo/_hi: linear taper bounds on the FRACTION OF
        #   SESSIONS affected (see auto_bp_weight_session_thresh) above.
        #   <= lo -> untouched (weight 1.0); >= hi -> weight hits
        #   auto_bp_weight_floor; linear in between. lo=0.10 (~2/21
        #   sessions) filters one-off flukes; hi=0.35 (~7/21 sessions) is
        #   comfortably below "bad in most sessions" (which feature_bad_bp_
        #   thresh[_with_visibility]'s hard-drop gate, above, already
        #   handles).
        auto_bp_weight_lo      = 0.10,
        auto_bp_weight_hi      = 0.35,
        # auto_bp_weight_floor: minimum auto-computed weight (never fully
        #   zeroes a bodypart out via this path -- full removal is
        #   feature_bad_bp_thresh[_with_visibility]'s job, above).
        auto_bp_weight_floor   = 0.35,
        # turned_away_exclude_from_bad_frac: when True (default), each
        #   bodypart's per-session bad-frame fraction (used by both the
        #   FEAT-DROP hard-drop gate and auto-weighting above) is recomputed
        #   excluding frames already flagged turned-away-from-camera, before
        #   either gate sees it. Raw per-frame likelihood naturally drops
        #   for face/forepaw bodyparts during turned-away moments -- they're
        #   genuinely out of camera view -- but those exact frames are
        #   already excluded from UMAP/HDBSCAN training separately (Step 3),
        #   so counting them as "bad tracking" here double-penalises the
        #   bodypart for something that isn't chronic mistracking. False
        #   reverts to the raw (uncorrected) fraction -- also the
        #   compat_mode="legacy_v2" default, since this changes what
        #   FEAT-DROP drops (pre-existing behaviour, not new this session).
        turned_away_exclude_from_bad_frac = True,
        # ── Adaptive visibility / occlusion features (issue 2) ────────────────
        # visibility_features_enabled: ON by default (unlike bodypart_weights)
        #   — this is the direct fix for turned-away/occluded frames polluting
        #   real clusters, of the same "always-on diagnostic" kind as the
        #   existing f_withinbin/f_persist blocks.  False reproduces the
        #   pre-2.2 feature layout exactly (legacy reproducibility escape
        #   hatch, same pattern as compat_mode/angular_fallback).
        visibility_features_enabled = True,
        # visibility_adaptive_pct: per-bodypart/per-session percentile floor
        #   (see compute_adaptive_visibility_threshold) layered on top of the
        #   existing global likelihood_thresh constant.  Always active
        #   whenever the visibility feature block runs (no separate toggle —
        #   it is a pure function of each session's own likelihood
        #   distribution, so gating it independently would add a no-benefit
        #   toggle).
        visibility_adaptive_pct = 10,
        # visibility_feature_weight: multiplier applied to the visibility
        #   block's columns AFTER StandardScaler (so it stacks on top of the
        #   scaler's own per-column unit-variance normalisation) and BEFORE
        #   PCA/UMAP, at both training (BSoidEngine.run()) and inference
        #   (predict_labels()) -- these two call sites MUST stay in sync, same
        #   requirement as visibility_features_enabled/visibility_adaptive_pct
        #   above. 1.0 (default) is a true no-op: every column, kinematic or
        #   visibility, keeps the scaler's plain unit variance, byte-identical
        #   to pre-2026-09-18 behaviour. >1.0 gives the visibility block
        #   deliberately more pull on UMAP's distance geometry than an
        #   ordinary feature column gets, so turned-away frames separate more
        #   reliably from real behaviour clusters instead of blending in when
        #   their visibility signature alone is a weak, noisy signal (added
        #   alongside auto_flag_impure_clusters defaulting on, as a way to
        #   fix contamination AT the clustering stage rather than only
        #   relabeling it after the fact).
        # 2.0 (2026-09-18, user request): give turned-away/occlusion signal
        #   deliberately more geometric pull than the default no-op weight.
        visibility_feature_weight = 2.0,
        # face_limb_proximity_feature_weight: same post-StandardScaler,
        #   pre-PCA/UMAP multiplier as visibility_feature_weight above, but
        #   applied to the nose/lower_jaw-to-nearest-paw proximity columns
        #   from _floor_reference_feature_block's proximity_targets loop
        #   (face-to-limb contact/closeness, both the elevation-gated and
        #   body-length-adaptive variants -- see floor_features_enabled's
        #   own docstring) instead of the visibility block. Same
        #   train/inference sync requirement (BSoidEngine.run() /
        #   predict_labels() must be passed the identical value). 1.0 is a
        #   true no-op; 2.0 gives these columns more pull on UMAP's distance
        #   geometry, so face-to-limb-contact postures separate more
        #   reliably from other stationary postures instead of competing on
        #   equal footing with every other feature column.
        face_limb_proximity_feature_weight = 2.0,
        # isolated_limb_feature_weight: same post-StandardScaler,
        #   pre-PCA/UMAP multiplier as the two weights above, but applied to
        #   _floor_reference_feature_block's own trailing 2 columns: the
        #   single-limb-elevated-with-others-grounded duty-cycle and its
        #   sustained-hold (>= sustained_single_limb_elevation_min_dur_s,
        #   default 0.75s) variant. Same train/inference sync requirement.
        #   1.0 is a true no-op; 1.5 gives these two columns more pull on
        #   UMAP's distance geometry.
        isolated_limb_feature_weight = 1.5,
        # ── Turned-away-from-camera detection/exclusion (v3, validated against
        #    real DLC data + human video review this session) ─────────────────
        # exclude_turned_away: ON by default — bins where the animal is judged
        #   turned away from the camera (see detect_turned_away_bins) are
        #   excluded from UMAP/HDBSCAN training and given a dedicated "Turned
        #   Away" label instead of being force-classified into a real
        #   behaviour cluster.  False disables the exclusion/dedicated-label
        #   behaviour (falls back to the pre-existing visibility-feature-only
        #   handling — HDBSCAN may or may not naturally separate these bins on
        #   its own, no forced intervention); this is the GUI-exposed escape
        #   hatch and, at False, reproduces pre-existing clustering output
        #   exactly (true no-op path, same pattern as bodypart_weights={}).
        exclude_turned_away     = True,
        # turned_away_conf_thresh: (v4, 2026-09-18 -- confidence-based
        #   generalization) repurposed as face_majority_frac -- the fraction
        #   of the 7 face points (nose/upper_jaw/lower_jaw/mouth_end_left+
        #   right/left_eye/right_eye) that must each individually clear their
        #   OWN per-bodypart/per-session adaptive threshold for a bin to
        #   become a turned-away candidate. Replaces the old v3 "Head/Mouth-
        #   region aggregate frac_low_conf + nose-alone-decides" design,
        #   which was defeated on real data by DLC hallucinating a single
        #   confident-but-wrong nose position during genuine occlusion (see
        #   the cluster_15/turned-around-animal investigation, 2026-09-18).
        #   0.5 (majority vote) was validated against real annotated turn-
        #   away clips on two independently-collected datasets (Dam_Xenium,
        #   TMZ7) with ZERO per-dataset retuning -- see turned_away_
        #   adaptive_pct below for why that generalizes. GUI-editable.
        turned_away_conf_thresh = 0.5,
        # turned_away_adaptive_pct: (v4, 2026-09-18) per-bodypart/per-session
        #   percentile-rank floor (same formula as compute_adaptive_
        #   visibility_threshold: max(likelihood_thresh, percentile(ll, pct)))
        #   used ONLY for turned-away detection's own face-point majority
        #   vote -- deliberately separate from visibility_adaptive_pct (which
        #   stays at its own default and continues to control the unrelated
        #   visibility FEATURE block) so this doesn't silently change the
        #   feature vector's scale for anything else. 30 (raised from
        #   visibility_adaptive_pct's 10) was needed to catch genuine but
        #   moderate-confidence occlusion (DLC reporting 0.3-0.6 "murky
        #   middle" likelihood on an invisible face rather than a clean
        #   near-zero) -- validated cold (no retuning) on TMZ7 as well as
        #   Dam_Xenium, which is the actual generalization claim: the
        #   PERCENTILE RANK is a proportion of each session's own
        #   distribution, not a fixed likelihood/pixel value, so it re-
        #   derives appropriately per camera/rig rather than being baked to
        #   one dataset's calibration.
        turned_away_adaptive_pct = 30.0,
        # turned_away_min_window_s: (v4, 2026-09-18) sustained-window
        #   duration floor (seconds) below which a flagged run of bins is
        #   treated as jitter (e.g. a transient face-tracking dropout during
        #   fast locomotion) and dropped, rather than a genuine turn-away.
        #   Raised from 0.4 -> 1.0: validated on real data that shorter
        #   floors let a ~1s locomotion-driven confidence dip get flagged as
        #   turned-away. Not GUI-exposed (validated value); editable via
        #   engine_cfg for advanced use.
        turned_away_min_window_s = 1.0,
        # turned_away_merge_gap_s: two flagged windows separated by a gap of
        #   at most this many seconds are merged into one window before the
        #   min-window-s floor is applied — bridges brief drop-outs within a
        #   single sustained turn-away.  Not GUI-exposed (validated value);
        #   editable via engine_cfg for advanced use.
        turned_away_merge_gap_s = 0.5,
        # auto_flag_impure_clusters: briefly defaulted ON (2026-09-18, user
        #   request -- real-data cases like a wholly-turned-around animal
        #   being left as its own real cluster instead of being folded into
        #   "Turned Away" were judged worse than the false-positive risk
        #   below), then reverted back to OFF the same day after a real-data
        #   false positive: on D:\Dam_Xenium\CUBE results 2026-09-18_00-16-18,
        #   a genuine rearing-against-the-wall cluster (silhouette=0.150,
        #   just under the 0.2 default threshold) was silently folded into
        #   "Turned Away" for 46% of that session's turned-away display time
        #   -- confirmed via the frame-label CSV's raw_label/turned_away_reason
        #   columns (raw_label stayed the real cluster id; only the display
        #   copy was overwritten). This is exactly the false-positive risk
        #   already documented below ("cannot distinguish a genuine artifact
        #   cluster ... from a real but naturally diverse behaviour that
        #   legitimately has a mediocre silhouette"), now confirmed on real
        #   data rather than just anticipated. Deliberately opt-in, unlike
        #   most refinement passes in this file; enable via engine_cfg
        #   (pass auto_flag_impure_clusters=True) only after inspecting the
        #   specific flagged cluster(s)' example clips for a given dataset.
        #   After split/merge refinement + rare-cluster pruning, when enabled, any real
        #   cluster whose mean per-bin silhouette (in the primary UMAP
        #   embedding) is STILL below auto_flag_impure_silhouette_thresh is
        #   folded into the same reserved "Turned Away" display id as
        #   exclude_turned_away's confidence-based detector, instead of being
        #   presented as a real behaviour. Catches the case
        #   split_impure_clusters can't: a heterogeneous catch-all cluster
        #   that (a) split was never attempted on -- e.g.
        #   consensus_clustering_enabled=True with consensus_refine_enabled=
        #   False skips the whole split/merge pass for consensus labels (see
        #   the _consensus_used branch above run()) -- or (b) split WAS
        #   attempted but no stable local sub-partition was found, so the
        #   impure cluster was left untouched by design (split never forces a
        #   split).
        #   Why opt-in: this is a purely GEOMETRIC check (cluster shape in
        #   the embedding) and cannot distinguish a genuine artifact cluster
        #   (what it's meant to catch -- e.g. animal turned away but
        #   paws/tail stay confidently tracked, so the confidence-based
        #   turned-away detector's Head/Mouth-region likelihood never drops
        #   enough to trip turned_away_conf_thresh) from a real but
        #   naturally diverse behaviour that legitimately has a mediocre
        #   silhouette. Auto-relabeling the latter as "Turned Away" would
        #   silently discard real data. GUI-exposed under Advanced Settings;
        #   inspect a flagged cluster's example clips before trusting the
        #   label. Bins are excluded from the UMAP/transition plots and
        #   dwell-time stats the same way confidence-based turned-away bins
        #   are, but are NOT excluded from MLP training (unlike confidence-
        #   based turned-away bins) -- the cluster stays a real, consistently
        #   -predicted class internally; only the DISPLAY id is remapped, per
        #   session, at export time. No-op (and skips the whole pass, with a
        #   log line) when exclude_turned_away=False, since there is no
        #   reserved id to route into.
        auto_flag_impure_clusters = False,
        # auto_flag_impure_silhouette_thresh: mean-silhouette cutoff for the
        #   post-hoc flagging pass above. Falls back to
        #   hdbscan_split_silhouette_thresh (the same quality bar split
        #   candidacy uses) when left at its default 0 -- set explicitly to
        #   decouple the two thresholds.
        auto_flag_impure_silhouette_thresh = 0.0,
        # ── Hierarchical/consensus refinement (issue 4 — bidirectional) ───────
        # hdbscan_merge_thresh: condensed-tree sibling-merge persistence-
        #   fraction cutoff.  0.08 (default, on) merges sibling clusters that
        #   split at <=8% of the tree's max lambda_val (i.e. barely-separated
        #   siblings — the code's own docstring calls 0.05 "barely
        #   separated"; 0.08 gives a little more headroom given the
        #   over-fragmentation seen in practice, e.g. a single "licking"
        #   behaviour split across 3 clusters, "sniffing" across 7, in run
        #   cube_results_20260618_015149 which had this pass disabled).  Set
        #   to 0.0 to fully disable (hard no-op), or pass compat_mode=
        #   "legacy_v2" to reproduce pre-refinement runs exactly.
        hdbscan_merge_thresh    = 0.08,
        # hdbscan_leaf_bonus: added to every leaf-method candidate's score
        #   ONLY once hdbscan_merge_thresh > 0 (leaf's extra fragmentation is
        #   then self-corrected by the merge pass).  Never applied when the
        #   merge pass is off — eom/leaf selection is then byte-for-byte
        #   unchanged from pre-issue-4 behaviour.
        hdbscan_leaf_bonus      = 0.03,
        # hdbscan_fine_bias: only active once hdbscan_merge_thresh > 0 (same
        #   gate as hdbscan_leaf_bonus). Nudges auto-mode candidate selection
        #   toward the finer end of [preferred_clusters_lo, preferred_
        #   clusters_hi] instead of always settling on the coarsest DBCV
        #   peak in range — biases toward "enough clusters to separate
        #   distinct behaviours, let the merge pass consolidate near-
        #   duplicates afterward" rather than "fewest clusters that still
        #   score well". Never applied when the merge pass is off.
        hdbscan_fine_bias       = 0.05,
        # hdbscan_split_silhouette_thresh: mean per-cluster silhouette below
        #   which a cluster is a candidate for local re-clustering (impurity
        #   fix).  0.2 (default, on) only catches clusters well below a
        #   healthy silhouette (the same run above reported an *aggregate*
        #   silhouette of ~0.49 with ARI 0.59 seed-instability, so 0.2 is
        #   conservative — it targets clearly-impure clusters, not ones
        #   merely below average).  None fully disables the split pass
        #   (hard no-op).
        hdbscan_split_silhouette_thresh = 0.2,
        # hdbscan_split_feat_silhouette_thresh (2026-09-06, OR-gated alongside
        #   hdbscan_split_silhouette_thresh, added per the B-SoiD-standalone-
        #   improvement investigation): mean per-cluster silhouette computed
        #   on the SCALED FEATURE space instead of the UMAP embedding -- a
        #   cluster is now a split candidate if EITHER this OR the embedding-
        #   space threshold flags it. Motivated by a real, dataset-confirmed
        #   blind spot: a cluster can be embedding-compressed-artificially-
        #   tight (passes the embedding check) while genuinely diffuse in the
        #   real feature space (fails this one), or vice versa -- neither
        #   signal was found to be a strict universal upgrade over the other
        #   (embedding silhouette correlated better with true purity on one
        #   real dataset, feature-space silhouette on another), so this adds
        #   feature-space as a second, independent check rather than
        #   replacing the existing one. 0.0 (falsy) is a hard no-op --
        #   byte-identical to pre-2026-09-06 behavior until explicitly turned
        #   on; not yet validated as a default, so it ships off.
        hdbscan_split_feat_silhouette_thresh = 0.0,
        # hdbscan_split_longwindow_silhouette_thresh (2026-09-06, BSOID_
        #   IMPROVEMENT_BASELINE_AND_EXPERIMENT_PLAN.md Experiment #3 +
        #   2026-09-06 local-re-embed follow-up): a THIRD OR-gated split-
        #   trigger signal, mean per-cluster silhouette computed on a
        #   separate ~750ms-smoothed pairwise-distance+velocity block
        #   (compute_longwindow_split_feats(), cfg["hdbscan_split_
        #   longwindow_win_sec"]) that NEVER enters feats_sc/embedding or a
        #   local re-embed's own feature space -- only decides which
        #   clusters attempt a (kinematics-only, unchanged) local re-split.
        #   Real, dataset-general evidence motivates the TRIGGER use
        #   specifically: this long-timescale signal gives a broad
        #   separability win in raw feature space (+0.03-0.14 BalAcc on 15
        #   of 16 real behavior pairs, EPM+OFT, zero regressions incl.
        #   already-well-separated pairs) but was already shown to hurt once
        #   added to the primary UMAP feature space (HEAD_DIP_FEATURE_
        #   EMBEDDING_INVESTIGATION_2026-09-03.md Experiment 3: -16.5% local-
        #   neighbourhood ratio post-UMAP), and a follow-up local-re-embed
        #   injection test found no clean real split either (EPM: only a
        #   ~5% minority-behavior splinter; OFT: no split at all). 0.0
        #   (falsy) is a hard no-op -- byte-identical to pre-2026-09-06
        #   behavior; not yet validated end-to-end on a full production run
        #   (only via the classifier-level/local-re-embed premise checks
        #   above), so it ships off pending that validation.
        hdbscan_split_longwindow_silhouette_thresh = 0.0,
        # hdbscan_split_longwindow_win_sec: boxcar smoothing window (seconds)
        #   for compute_longwindow_split_feats(); 0.75s is the exact value
        #   validated in the 2026-09-06 experiment above.
        hdbscan_split_longwindow_win_sec = 0.75,
        # ── SPLIT_ELIGIBILITY_IMPROVEMENT_PLAN.md (2026-09-24) ─────────────
        #   Originally 4 independent, additively-gated split-eligibility
        #   techniques; real-data validation (nn20/nn60/nn_auto34, all 3
        #   real cached datasets) kept only technique 1 (feature-space
        #   multimodality) -- it found a real additional dump-cluster split
        #   beyond the default silhouette-gated mechanism on all 3 datasets,
        #   never regressed. Techniques 2 (bout-recurrence acceptance bar),
        #   3 (kinetic-coherence primary trigger), and 4 (locally-adaptive
        #   n_neighbors) were discarded entirely after this validation: 3
        #   was a byte-identical no-op on all 3 datasets; 4 never changed
        #   dump-cluster outcome and regressed once (nn60); 2 helped on 2/3
        #   datasets but caused a real, large regression on the third (a
        #   fallback-preemption interaction bug), with no fix in hand.
        # hdbscan_split_multimodality_enabled (technique 1): a NEW,
        #   embedding-independent split-trigger signal, parallel to (not a
        #   replacement for) the existing embed/feat/longwindow silhouette
        #   triggers -- 1- vs 2-component GMM-BIC comparison on the leading
        #   PCA axis of a candidate cluster's own rows of feats_sc (never
        #   the UMAP embedding), so it's structurally immune to
        #   umap_n_neighbors/UMAP-projection distortion. 0.0 bic_margin
        #   (below) is a true no-op regardless of this flag.
        hdbscan_split_multimodality_enabled = True,  # default ON 2026-09-25 -- see below
        # hdbscan_split_multimodality_pca_dims: PCA dimensionality before
        #   the GMM-BIC fit (fit on PC1 only) -- enough to capture a real
        #   mixture without re-introducing curse-of-dimensionality noise on
        #   a local-sized candidate.
        hdbscan_split_multimodality_pca_dims = 5,
        # hdbscan_split_multimodality_bic_margin: bic_1 - bic_2 must clear
        #   this margin to flag a cluster as a multimodality-split
        #   candidate. 0.0 would be a true no-op regardless of the enabled
        #   flag above -- default changed 2026-09-25 to 20.0, the exact
        #   value real-data-validated across nn20/nn60/nn_auto34 (all 3 real
        #   Dam_Xenium 2D datasets): real BIC margins on genuine dump-
        #   cluster candidates ranged 22.6-337.7, well clear of 20.0, while
        #   never producing a false-positive trigger on any of the ~15-22
        #   other real clusters checked per run. Comfortably below the
        #   synthetic 2-blob true-positive range (tens-to-low-hundreds, see
        #   test_split_multimodality.py) and the real known-broken nn=20
        #   dump cluster's own ~124.6 score.
        hdbscan_split_multimodality_bic_margin = 20.0,
        # hdbscan_split_multimodality_min_points: minimum candidate-cluster
        #   size before a GMM-BIC fit is even attempted (matches this
        #   codebase's general small-sample-size skepticism for a PCA/GMM
        #   fit -- see hdbscan_split_min_points's own, much larger, floor
        #   for the actual re-embed/re-cluster step this only decides
        #   whether to TRIGGER).
        hdbscan_split_multimodality_min_points = 20,
        # hdbscan_split_multimodality_direct_fit_enabled (2026-09-25 follow-
        #   up to technique 1): real nn20/nn60 end-to-end validation found
        #   the multimodality trigger correctly identifies real bimodal
        #   feature-space structure (BIC margins 61.8/217.6, both well over
        #   the 20.0 threshold) but the actual split attempt -- both the
        #   normal UMAP re-embed AND the direct-global-embedding fallback --
        #   still failed to find any stable sub-structure on both real
        #   candidates. Root cause: the trigger's evidence lives in PCA-
        #   reduced feats_sc space, but every existing split attempt path
        #   re-tests it in UMAP-embedding space, which is exactly the
        #   distortion-prone geometry the trigger was built to route around.
        #   When True, a multimodality-flagged candidate that BOTH other
        #   paths reject gets one more attempt: HDBSCAN fit directly on the
        #   SAME PCA-reduced feats_sc space _feature_space_multimodality_
        #   score() used to detect the bimodality (never a fresh UMAP fit).
        #   Same acceptance bar as every other path (_evaluate_and_merge) --
        #   never held to a looser bar. Default changed to True 2026-09-25:
        #   real nn20 end-to-end re-run confirmed it rescues a genuine split
        #   (cluster #14, 2 sub-clusters, DBCV=0.194) that both other paths
        #   had rejected -- the first and only mechanism in this whole
        #   investigation to create a real NEW split on real production
        #   data. Honest limit: it did not rescue every candidate tried
        #   (nn60 cluster #13 remained unsplit even with this on) -- a real,
        #   partial improvement, not a complete fix.
        hdbscan_split_multimodality_direct_fit_enabled = True,
        # hdbscan_split_recurrence_accept_enabled (technique 2, revived
        #   2026-09-25 with the fallback-preemption bug fixed -- see
        #   _attempt_split()'s own comment for the mechanism, and the plan
        #   doc's status line for the discard-then-revive history). For a
        #   real (>=2 sub-cluster) local-split candidate whose DBCV falls
        #   short of hdbscan_split_min_dbcv, ALSO accepts it if every
        #   proposed sub-cluster recurs as its own real bouts -- an OR with
        #   DBCV now, not a replacement (the original version's REPLACE
        #   semantics is what let a weak-DBCV/recurrence-accepted result
        #   pre-empt the direct-global-embedding fallback). Reuses this
        #   codebase's standing "recurrence, not separation, is the
        #   trustworthy signal for CUBE's internally-cohesive-cluster goal"
        #   precedent (medoid-vs-DBCV, rare_cluster_survival_criteria=
        #   "occurrence_persistence") applied here as an ACCEPTANCE bar.
        #   Does not touch the separate hdbscan_split_accept_partial_noise
        #   (1-sub-cluster+noise) branch, which already has its own
        #   occurrence-based accept logic. Default False -> true no-op.
        hdbscan_split_recurrence_accept_enabled = False,
        # hdbscan_split_recurrence_min_occurrences: bouts each proposed sub-
        #   cluster must clear. Falls back to the run's own min_occurrences
        #   when unset (no separate calibration needed to start).
        hdbscan_split_recurrence_min_occurrences = 3,
        # hdbscan_split_recurrence_min_bout_bins: minimum consecutive
        #   original bin positions for one bout to count -- the same "a
        #   single-bin blip is noise" floor already used by _prune_rare_
        #   clusters()/seed_sweep_stability()'s own bout counting and by
        #   this function's pre-existing partial-noise-path occurrence
        #   count (see _bout_counts_by_subid()'s docstring).
        hdbscan_split_recurrence_min_bout_bins = 2,
        # hdbscan_split_posture_entropy_veto_enabled (technique 5, 2026-09-24
        #   -- prompted by cross-referencing this session's own exploratory
        #   Dynamical_Systems_Attractor_Posture_Findings_2026-09-24.md
        #   quadrant framework: STEREOTYPED / FROZEN POSTURE / GATEWAY /
        #   NOISE-JUNK, from postural-conservation x basin-entropy). A
        #   real-data false-positive check found the EXISTING split
        #   mechanism -- independent of ANY of techniques 1-4 -- can accept
        #   a locally-separable-looking split (DBCV=0.081, just above the
        #   0.08 floor) on a cluster independently confirmed (video review +
        #   dynamical/postural analysis) to be a single real coherent
        #   behavior (licking; "GATEWAY" quadrant -- posturally diffuse but
        #   dynamically convergent). When True, vetoes ANY split attempt
        #   (from any trigger) on a candidate whose PARENT cluster clears AT
        #   LEAST ONE of two axes: dynamical convergence (reuses the
        #   already-committed _kinetic_coherence_score()'s own
        #   coherence_score -- no new dynamical machinery) -- but see
        #   _posture_entropy_split_veto()'s own docstring: the decision is
        #   now CONSERVATION-ONLY (2026-09-25, after two same-day revisions),
        #   protecting STEREOTYPED and FROZEN POSTURE (both have real
        #   postural conservation) but never GATEWAY on coherence alone,
        #   since a real GATEWAY cluster (nn_auto34 #17) was video-confirmed
        #   to be a genuine 2-behavior mixture despite high coherence.
        #   coherence_score is kept as a parameter for signature
        #   compatibility and its own None-check, but no longer drives the
        #   accept/reject decision itself. NOW WIRED into BSoidEngine.run()'s
        #   live pipeline (2026-09-25, both the primary/medoid path via
        #   _pre_refine_posture_entropy_scores() and the consensus path via
        #   refine_consensus_clusters()) -- confirmed firing on real data in
        #   both. Either score unavailable for a candidate (e.g. too few
        #   bouts) vetoes conservatively (matches crash-protection
        #   convention). Briefly changed to True 2026-09-25 (confirmed
        #   firing correctly on real data through both remedy paths: medoid,
        #   9 real vetoes on one dataset; consensus, 1-4 vetoes across
        #   nn20/nn60/nn_auto34; decision rule calibrated against two real,
        #   video-reviewed ground-truth cases), then REVERTED to False the
        #   same day once a full (not split/merge-scoped) test-suite run
        #   surfaced a real, unaudited side effect: defaulting this on makes
        #   _pre_refine_posture_entropy_scores() -- and therefore
        #   _kinetic_coherence_score() -- run unconditionally on every real
        #   (non-consensus) run(), which broke an unrelated Phase-5-
        #   embedding-stability-retry test's call-count isolation assumption
        #   and touched several other kinetic-adjacent integration tests not
        #   yet individually triaged. The underlying mechanism itself is
        #   still believed correct (the extra calls are to a read-only
        #   diagnostic function that never mutates labels) -- this is a
        #   scope/audit gap, not a known correctness bug -- but shipping a
        #   default-on flip without full-suite-clean verification would
        #   repeat exactly the mistake this codebase's own history warns
        #   against. Root cause fully characterized (2026-09-25, same day):
        #   exactly 3 tests affected, all in TestPhase5EmbeddingStabilityRetry
        #   (test_algorithm_stages.py), all spying on call-counts to the
        #   read-only, label-mutating-never _kinetic_coherence_score() --
        #   not a real behavior bug. Fixed the correct way (matching that
        #   suite's own pre-existing convention for the identical issue with
        #   kinetic_coherence_enabled/kinetic_split_trigger_enabled/
        #   kinetic_flow_field_enabled, all also default-True): added this
        #   flag (and the merge-guard one) to that suite's own P5_BASE_CFG
        #   isolation list, rather than reverting the feature. Re-confirmed
        #   default True with a full (non-scoped) test-suite run clean of
        #   this issue before shipping.
        hdbscan_split_posture_entropy_veto_enabled = True,
        # hdbscan_split_posture_entropy_coherence_thresh: coherence_score
        #   (from _kinetic_coherence_score(), 0..1-ish, higher = more
        #   dynamically convergent) at or above which a candidate is
        #   protected via the entropy axis alone. Reasoned starting value
        #   (matches kinetic_split_trigger_threshold's pre-2026-09-02 default
        #   before that key's own auto-baseline was added) -- not yet
        #   independently calibrated; real data (the 8-cluster quadrant
        #   table) showed this axis carries most of the real discriminating
        #   power between quadrants (entropy range 0.025-0.325 vs.
        #   conservation's much more compressed 0.301-0.473), so this
        #   threshold matters more than the conservation one below.
        hdbscan_split_posture_entropy_coherence_thresh = 0.25,
        # hdbscan_split_posture_entropy_conservation_thresh: postural-
        #   conservation score (0..1, higher = more consistent pose across
        #   representative bouts) at or above which a candidate is protected
        #   via the conservation axis alone. Reasoned starting value only --
        #   real data from the exploratory doc's own 8-cluster table showed
        #   this axis separates real quadrants much more weakly within one
        #   dataset (STEREOTYPED/FROZEN POSTURE/GATEWAY all in 0.301-0.473;
        #   NOISE/JUNK's own 0.362 sits in the MIDDLE of that range, not
        #   clearly below it) -- a fixed cross-dataset threshold here is
        #   less trustworthy than the entropy one; a future adaptive
        #   (within-run median/z-score) version, matching this codebase's
        #   own min_occurrence_persistence_mode="adaptive_zscore" precedent,
        #   is a more promising direction than tuning this fixed number
        #   further. Flagged here rather than silently shipped as if solid.
        hdbscan_split_posture_entropy_conservation_thresh = 0.4,
        # hdbscan_merge_posture_entropy_guard_enabled (technique 5,
        #   merge side, 2026-09-24): reuses the SAME pre-refine posture/
        #   entropy scores the split veto consumes (computed once in
        #   BSoidEngine.run() by _pre_refine_posture_entropy_scores(), before
        #   split/merge refinement runs) inside merge_similar_clusters() to
        #   do two things: (1) refuse a persistence-confirmed merge between
        #   two INDEPENDENTLY coherent clusters (each clears at least one
        #   axis on its own) so two real, distinct stereotyped behaviors
        #   never get silently blended together; (2) consolidate two
        #   clusters that BOTH fail every axis (NOISE/JUNK) whenever they're
        #   closer than the median inter-cluster centroid distance, even
        #   when merge_thresh's own condensed-tree persistence criterion
        #   alone wouldn't have flagged them -- attacking fragmentation from
        #   the opposite direction technique 1's split trigger does. Default
        #   False -> true no-op (unchanged output) even when a real
        #   posture_entropy_veto dict is supplied. NOT YET real-data
        #   validated end-to-end (wired into BSoidEngine.run() the same day
        #   as this key was added) -- ship default-off pending that pass,
        #   same convention as every other technique in this plan.
        hdbscan_merge_posture_entropy_guard_enabled = False,
        # export_posture_conservation_quadrant (technique 5 diagnostic,
        #   default True): exports posture_conservation_vs_convergence.png
        #   + .csv -- the same quadrant scatter (postural conservation vs.
        #   dynamical convergence, median-split lines, 4 labeled regions)
        #   validated in this session's own exploratory Dynamical_Systems_
        #   Attractor_Posture_Findings_2026-09-24.md, now a standard CUBE
        #   output. Purely additive/informational -- like kinetic_
        #   coherence.csv, computing and plotting this never changes any
        #   cluster label or feeds any split/merge/prune decision by
        #   itself (hdbscan_split_posture_entropy_veto_enabled is the
        #   separate, opt-in, default-off mechanism that actually acts on
        #   these two scores). Silently produces nothing (WARN-logged, run
        #   continues) if kinetic coherence or bout/pose data isn't
        #   available this run -- matches every other optional plot's
        #   crash-protection convention at this call site.
        export_posture_conservation_quadrant = True,
        # hdbscan_split_max_subclusters: hard cap on how many sub-clusters a
        #   single split_impure_clusters() candidate may accept in one pass
        #   (also used as the local re-clustering's preferred_clusters_hi,
        #   see split_impure_clusters -- the whole-session preferred range
        #   and fine_bias are deliberately NOT inherited for this local
        #   call). Kept deliberately low (3): a split is meant to resolve
        #   the handful (typically 2-3) of genuinely distinct sub-behaviours
        #   mixed into one impure cluster, not fragment it extensively --
        #   without this cap, a single cluster could split into 20-30+ tiny
        #   fragments in one pass (seen in practice on real data once
        #   fine_bias was pushing local selection toward a whole-session-
        #   scale cluster count).
        hdbscan_split_max_subclusters = 3,
        # hdbscan_split_min_points: minimum points a candidate cluster must
        #   have before a local split re-embedding is even attempted.  Not
        #   a flat legacy value (20) -- sized at 5x the PCA floor (50
        #   components, see run_umap) that a high-dimensional local subset
        #   would be reduced to, since a sample/feature ratio below ~5 is
        #   the same curse-of-dimensionality regime run_umap's own auto-PCA
        #   trigger is built to avoid. Feature counts routinely exceed
        #   500-900 dims (more bodyparts -> quadratically more pairwise-
        #   distance features), so a flat 20-point floor let splits run on
        #   90-300 point subsets in practice -- far too few to trust the
        #   resulting sub-clusters or local DBCV score.
        hdbscan_split_min_points = 250,
        # ── Split-pass performance bounds (Aug 2026) ──────────────────────────
        # split_impure_clusters() used to run a full 40-step x 2-method
        # HDBSCAN sweep per impure-cluster candidate -- fine for one candidate,
        # combinatorially expensive when a partition has many (confirmed on
        # real data: one seed took 25+ min vs 1-2 min for others). These three
        # keys bound that cost; see split_impure_clusters()'s docstring.
        # hdbscan_split_max_candidates: hard ceiling on candidates attempted
        #   per refinement iteration (worst-silhouette-first).
        # hdbscan_split_candidate_cutoff: 0/unset = auto (split_silhouette_
        #   thresh / 2) -- a stricter silhouette bar than the base split gate,
        #   applied before the max_candidates ceiling. Only clusters at or
        #   below this silhouette attempt a split by default.
        # hdbscan_split_sweep_n_steps: mcs steps for each candidate's LOCAL
        #   sweep (default 12, vs 40 for the primary whole-session sweep) --
        #   a few-hundred-point local subset doesn't need fine resolution to
        #   find 2-3 sub-clusters. hdbscan_method is also forced to "eom"
        #   only for these local sweeps (skips the "leaf" pass).
        # hdbscan_split_n_jobs: parallel workers for the (independent,
        #   disjoint-point) candidate loop. -1 = auto-managed (see System
        #   Resources block below; falls back to literal "all cores" when
        #   auto_resource_management is off); 1 = sequential (exact
        #   pre-Aug-2026 candidate-processing order, minus the other two
        #   bounds above).
        hdbscan_split_max_candidates    = 10,
        hdbscan_split_candidate_cutoff  = 0,
        hdbscan_split_sweep_n_steps     = 12,
        hdbscan_split_n_jobs            = -1,
        # ── Region-aware cluster refinement (v1, opt-in, Region_Aware_
        # Refinement_Implementation_Plan.md) ───────────────────────────────
        # hdbscan_region_split_enabled: master switch, default OFF -- a true
        #   no-op when False: compute_bin_region_labels() is never even
        #   called (zero per-session cost for users who never opt in), and
        #   split_region_impure_clusters() is never invoked. Independent of
        #   env_features_enabled -- reads env_arena_cfg directly so a user
        #   can opt into region-aware splitting without also paying for the
        #   post-hoc session_env_context.json/bout-enrichment machinery.
        # hdbscan_region_split_signal: list of per-bin signal names to use
        #   for impurity scoring. v1 only implements the categorical-entropy
        #   scorer for "current_region" -- other entries are accepted by the
        #   schema (forward compatibility) but not yet scored.
        # hdbscan_region_split_impurity_thresh: normalized Shannon entropy
        #   (0=single region, 1=maximally mixed) at/above which a cluster is
        #   a region-split candidate. Documented starting point, not an
        #   empirically validated final value -- see the plan's Risk
        #   assessment.
        # hdbscan_region_split_min_minority_frac: every non-dominant region
        #   in a candidate cluster must represent at least this fraction of
        #   the cluster's bins, or the cluster is not split (avoids forcing
        #   noise-level region contamination into its own tiny fragment).
        # hdbscan_region_split_max_subclusters / _max_candidates: mirror
        #   hdbscan_split_max_subclusters / hdbscan_split_max_candidates for
        #   the region-impurity candidate pool.
        # region_split_pre_reduction_pct: 0.0 (off) = no effect. When set
        #   (e.g. 0.7) AND hdbscan_region_split_enabled=True, multiplies the
        #   PRIMARY sweep's preferred_clusters_lo/hi by this fraction for
        #   that sweep only -- a one-shot, clearly-logged convenience, not a
        #   closed-loop cluster-count-targeting mechanism. See Design
        #   decision 4 in the plan for scoping.
        hdbscan_region_split_enabled           = False,
        hdbscan_region_split_signal            = ["current_region"],
        hdbscan_region_split_impurity_thresh   = 0.5,
        hdbscan_region_split_min_minority_frac = 0.15,
        hdbscan_region_split_max_subclusters   = 3,
        hdbscan_region_split_max_candidates    = 10,
        region_split_pre_reduction_pct         = 0.0,
        # hdbscan_seed_sweep_n_steps / hdbscan_consensus_sweep_n_steps
        #   (Option 4, HDBSCAN sweep perf, Aug 2026): 0 (default) = inherit
        #   hdbscan_sweep_n_steps (the primary sweep's own 40-step grid) for
        #   seed_sweep_stability()'s and consensus_cluster()'s per-seed
        #   run_hdbscan() calls, respectively -- a true no-op until explicitly
        #   set to a nonzero coarser (or finer) value. Kept as two separate
        #   keys rather than one shared override since seed-stability and
        #   consensus are different call sites that may want independently
        #   tunable sweep density. Does NOT touch run_hdbscan()'s own primary-
        #   sweep grid construction, so the shipped clustering result is
        #   unaffected regardless of this key's value.
        hdbscan_seed_sweep_n_steps      = 0,
        hdbscan_consensus_sweep_n_steps = 0,
        # recluster_max_iterations: cap on the split -> merge -> repeat
        #   refinement loop (both passes are individually gated above).
        #   2 = one split pass to resolve impurity, one merge pass to
        #   consolidate resulting fragmentation / pre-existing near-
        #   duplicates.
        recluster_max_iterations = 2,

        # ── System Resources (Aug 2026 perf fix) ───────────────────────────────
        # The primary HDBSCAN min_cluster_size sweep (run_hdbscan, ~40 steps x
        # up to 2 methods) used to run as a plain sequential loop -- most cores
        # sat idle for the majority of a run's wall-clock time. These keys make
        # it (and hdbscan_split_n_jobs / seed_sweep_n_jobs above/below) adaptive:
        # -1 on any of those three now means "auto-managed" rather than literal
        # "all cores" -- resolved once per run via compute_adaptive_n_jobs(),
        # which targets system_resource_target_pct of logical cores, hard-capped
        # at system_resource_cap_pct, and shrinks further if RAM is already
        # under pressure. Explicit non--1 values on those three keys (1 =
        # sequential, or a user-pinned count) are unaffected -- this only
        # changes the *default*/auto behaviour.
        auto_resource_management        = True,
        # system_resource_target_pct/cap_pct lowered 2026-09-01 (from
        #   0.65/0.80) -- see compute_adaptive_n_jobs()'s own docstring for
        #   the real-crash investigation (recurring WHEA Event 19 "Corrected
        #   Machine Check, Internal parity error" on an i9-14900K, a CPU
        #   model with a documented voltage-driven core-degradation issue
        #   under sustained heavy multi-threaded load) that motivated this.
        system_resource_target_pct      = 0.50,   # reduced sustained ceiling
        system_resource_cap_pct         = 0.65,   # hard ceiling, never exceeded
        # hdbscan_sweep_n_jobs: default changed -1 -> 1 (sequential) Aug 2026
        # after a real crash_diagnostics.log capture of this exact call site
        # (run_hdbscan's primary sweep, not seed_sweep/consensus) faulting with
        # "Windows fatal exception: code 0xc0000374" (heap corruption) despite
        # the _numba_single_thread/_blas_single_thread_for_dispatch
        # oversubscription guards around _fit_one. seed_sweep_n_jobs and
        # consensus_n_jobs were already made sequential for the identical
        # crash signature -- this brings the primary sweep in line with those
        # two rather than leaving it as the one remaining parallel call site
        # with the same underlying hazard (joblib threading backend + numba
        # JIT + HDBSCAN's Cython core all contending under threads on
        # Windows). Not reliably reproducible on demand, so this is a safety
        # margin rather than a pinned-down fix, matching the rationale
        # already applied to seed_sweep_n_jobs/consensus_n_jobs.
        # 2026-09-18: reverted back to -1 (auto) at explicit user request,
        # accepting the reintroduced crash risk documented above in exchange
        # for full parallelism. seed_sweep_n_jobs/consensus_n_jobs below were
        # changed the same day for consistency (all three were flipped to 1
        # together for the identical crash signature, so they're reverted
        # together too).
        hdbscan_sweep_n_jobs            = -1,

        # ── 2D orientation-robustness fixes (LR_ORIENTATION_FIX_PLAN.md,
        #   2026-09-18) -- correctness fixes for a real, diagnosed heading-
        #   direction clustering confound on D:\Dam_Xenium data: nose-ear
        #   pairwise distance flipped 104.6px<->90.1px purely based on which
        #   way the head turned (near/far-side self-occlusion under an
        #   oblique camera), and frac_facing_right correlated -0.75 with the
        #   per-cluster L/R eye-confidence gap across 20 clusters (7 mutual
        #   mirror-image cluster pairs found). Both default True: unlike a
        #   speculative technique (order_shape_features_enabled), these fix a
        #   real diagnosed artifact, matching this codebase's precedent for
        #   "fix a real problem" flags shipping default-on (e.g.
        #   dlc_3d_hard_bone_length_gate, dlc_3d_ray_temporal_fallback,
        #   paw_floor_features_enabled). 2D-only (extract_features_v2) --
        #   extract_features_3d's true world coordinates have no equivalent
        #   perspective-driven asymmetry, so this is not wired there.
        # lr_symmetrize_features_enabled (Option B): symmetrizes L/R-paired
        #   dist100/dist200/disp100/accel100/disp200 columns (see
        #   LR_BODYPART_PAIRS/_lr_mirror_permutation/_lr_symmetrize_columns)
        #   into (mean, |diff|) pairs so a bilaterally-paired bodypart's
        #   column pair no longer encodes which side of the animal currently
        #   faces the camera. Deferred (not yet in scope): the angular block
        #   and the floor/_floor_reference_feature_block -- both are also
        #   L/R-paired but need their own column-layout investigation first.
        lr_symmetrize_features_enabled = True,
        # withinbin_variance_rotation_invariant (Option C): collapses
        #   f_withinbin's per-point x-variance/y-variance columns into one
        #   rotation-invariant Var(x)+Var(y) column (trace of the 2D
        #   covariance matrix) instead of keeping them as two separate,
        #   non-rotation-invariant columns.
        withinbin_variance_rotation_invariant = True,
        # egocentric_alignment_enabled (2026-09-25 experiment, DEFAULT ON):
        #   adds egocentrically-aligned raw bodypart coordinates as an
        #   ADDITIVE feature block -- never a replacement for CUBE/B-SOiD's
        #   existing relative-distance/angle features -- testing whether
        #   clustering benefits from also seeing absolute/aligned pose the
        #   way VAME and keypoint-MoSeq do (both confirmed via their own
        #   papers to feed egocentrically-aligned coordinates directly into
        #   their models, unlike CUBE/B-SOiD's relative-geometry-only
        #   design). Each frame is centered on the nose-tailbase midpoint
        #   and rotated so that axis points along +X (same convention VAME's
        #   own preprocessing uses), then bin-averaged. Wired into BOTH 2D
        #   (extract_features_v2, x/y aligned) and 3D (extract_features_3d,
        #   _egocentric_alignment_feature_block_3d -- x/y aligned, Z left
        #   ABSOLUTE, matching _compute_cluster_posture_data's own existing
        #   "Z must stay ABSOLUTE" convention for is_3d handling).
        #
        #   REAL-DATA RESULT (real OFT, 20 fully-labeled sessions, reduced-
        #   but-real settings, egocentric_on vs. baseline, Coverage/Leakage/
        #   Ratio + purity-gated, top-quartile-mean-purity per this
        #   codebase's own BSOID_IMPROVEMENT_BASELINE_AND_EXPERIMENT_PLAN.md
        #   section 5.2 methodology): a genuine, real, MIXED trade-off, not
        #   a clean win -- Supported Coverage 15.0%->23.2% (Ratio 0.36->
        #   0.56), Unsupported Coverage 7.5%->11.3% (Ratio 0.12->0.18) both
        #   real improvements; Grooming Coverage 58.1%->42.6% (Ratio 0.66->
        #   0.48, purity-gated) a real regression; Jumping flat (noise-level,
        #   n=16 real occurrences). Purity unaffected by any measure checked
        #   (flat mean, >=50%/>=70% count, top-quartile mean all ~unchanged;
        #   0% of clusters clear 70% purity on OFT either way -- a known,
        #   pre-existing property of this dataset, not caused by this
        #   feature). Mechanistically sensible: Supported/Unsupported are
        #   genuinely absolute-posture-defined categories (what egocentric
        #   alignment captures); Grooming is already well-described by
        #   existing relative/velocity features and gets diluted by the
        #   extra columns (cluster count rose 15->21 on the same run).
        #   Shipped default ON per explicit instruction despite the mixed
        #   result -- the net effect across the 4 tracked OFT behaviors is
        #   positive on 2/4 (both meaningfully), flat on 1/4, negative on
        #   1/4 -- not evidence-free, but also not the clean multi-dataset
        #   validation this codebase's OTHER default flips required before
        #   shipping; a Damien-data comparison run (no manual labels, CUBE-
        #   internal metrics only) is the natural next real-data check.
        egocentric_alignment_enabled = True,
        # egocentric_alignment_pca_dims: currently a no-op (kept for future
        #   use) -- see _egocentric_alignment_feature_block()'s own
        #   docstring for why per-session PCA reduction is deliberately NOT
        #   done inside that function (would give each session an
        #   incomparable component basis once pooled for clustering).
        egocentric_alignment_pca_dims = 10,
    )
    # camera_view is NOT a cfg key -- it's auto-detected per run from the
    # bodypart schema itself (_camera_view_from_schema(), below), not a
    # manual setting. See that function's docstring for why.

    # Pre-2.1 numeric defaults, restored when cfg["compat_mode"] == "legacy_v2"
    # for keys the caller did not set explicitly.  Keep in sync with the
    # corrected DEFAULTS above.
    _LEGACY_V2_DEFAULTS = dict(
        umap_min_dist         = 0.0,
        hdbscan_mcs_anchor    = "full",
        angular_fallback      = True,
        # Split/merge refinement was added after v2.1 and defaulted to off;
        # legacy_v2 reproduces pre-refinement runs exactly unless the caller
        # explicitly overrides these.
        hdbscan_merge_thresh             = 0.0,
        hdbscan_split_silhouette_thresh  = None,
        # Automatic confidence-based bodypart weighting was added after v2.1
        # and defaulted to off in earlier runs; same reproducibility escape
        # hatch as above.
        auto_bodypart_weighting          = False,
        # Turned-away-frame exclusion from bad-frame-fraction stats changes
        # what the pre-existing FEAT-DROP hard-drop gate drops; keep it off
        # so legacy_v2 reproduces older runs' drop decisions exactly.
        turned_away_exclude_from_bad_frac = False,
        # auto_flag_impure_clusters defaulted to off before 2026-09-18; keep
        # legacy_v2 reproducing that (no post-hoc silhouette-based
        # cluster-to-"Turned Away" relabeling) unless overridden explicitly.
        auto_flag_impure_clusters         = False,
        # visibility_feature_weight/face_limb_proximity_feature_weight both
        # defaulted to 1.0 (true no-op) before 2026-09-18; legacy_v2
        # reproduces that plain-equal-weight feature geometry.
        visibility_feature_weight         = 1.0,
        face_limb_proximity_feature_weight  = 1.0,
        isolated_limb_feature_weight        = 1.0,
    )

    def __init__(self, csv_folder, video_folder=None,
                 output_dir="bsoid_output", fps=None,
                 logger=None, progress_cb=None, stage_cb=None, cfg=None):
        # Accept csv_folder as a single path OR a list of paths (combined analysis)
        if isinstance(csv_folder, (str, Path)):
            self._csv_folders = [Path(csv_folder)]
        else:
            self._csv_folders = [Path(f) for f in csv_folder]
        self.csv_folder = self._csv_folders[0]   # backward-compat alias

        # Accept video_folder as a single path OR a list of paths
        if video_folder is None:
            self._vid_folders = []
            self.video_folder = None
        elif isinstance(video_folder, (str, Path)):
            self._vid_folders = [Path(video_folder)]
            self.video_folder = self._vid_folders[0]
        else:
            self._vid_folders = [Path(f) for f in video_folder if f is not None]
            self.video_folder = self._vid_folders[0] if self._vid_folders else None

        self.output_dir   = Path(output_dir)
        self._fps_arg     = fps
        self._log         = logger or print
        self._prog        = progress_cb or (lambda c, t: None)
        _orig_stage_cb    = stage_cb or (lambda s, d="": None)
        # Phase-timing instrumentation (2026-08-31): every major phase
        # boundary in run() already calls self._stage(name, detail) to
        # drive the GUI's progress display -- wrapping it here piggybacks
        # real wall-clock timing onto those same, already-existing call
        # sites (~30 of them) for free, with zero new call sites to
        # maintain. A phase's duration is measured from its own _stage()
        # call to the NEXT _stage() call with a different name, so entries
        # naturally aggregate across per-session sub-calls that repeat the
        # same name (e.g. "2/7 — Loading DLC files" called once per
        # session, "7/7 — Predicting & exporting" likewise) -- exactly the
        # granularity useful for "which phase is slow" profiling, not
        # per-session noise. Exported as model/phase_timings.json and
        # logged as a summary table at the end of run() (see the "Done"
        # stage call).
        self._phase_timings: list = []
        self._phase_timings_cur = {"name": None, "t0": time.time()}

        def _stage_with_timing(name, detail=""):
            _now = time.time()
            _prev = self._phase_timings_cur
            if _prev["name"] is not None and name != _prev["name"]:
                self._phase_timings.append(
                    {"phase": _prev["name"], "duration_s": round(_now - _prev["t0"], 2)})
                self._phase_timings_cur = {"name": name, "t0": _now}
            elif _prev["name"] is None:
                self._phase_timings_cur = {"name": name, "t0": _now}
            _orig_stage_cb(name, detail)

        self._stage = _stage_with_timing
        self._cfg         = {**self.DEFAULTS, **(cfg or {})}
        # Which keys the caller explicitly passed (vs. inherited from
        # DEFAULTS) -- used by compat_mode="legacy_v2" below, and by the
        # consensus-clustering auto-trigger (Aug 2026) to distinguish a
        # deliberate consensus_clustering_enabled=False opt-out from just
        # never having set it.
        self._explicit_cfg_keys = set((cfg or {}).keys())
        # Reproducibility: in legacy mode, revert v2.1 numeric changes for any
        # key the caller did not pass explicitly (explicit overrides win).
        if self._cfg.get("compat_mode") == "legacy_v2":
            for _k, _v in self._LEGACY_V2_DEFAULTS.items():
                if _k not in self._explicit_cfg_keys:
                    self._cfg[_k] = _v

        # sub-dirs
        self._out_bouts  = self.output_dir / "bout_lengths"
        self._out_model  = self.output_dir / "model"
        self._out_plots  = self.output_dir / "plots"
        self._out_videos = self.output_dir / "videos"
        for d in (self._out_bouts, self._out_model,
                  self._out_plots, self._out_videos):
            d.mkdir(parents=True, exist_ok=True)

    def _mem_checkpoint(self, label: str):
        """gc.collect() + psutil RSS sample at a pipeline stage boundary.
        Tracks a running peak in self._peak_rss_gb (psutil's RSS captures real
        process memory including numpy/BLAS/native temporaries, unlike the
        tracemalloc-based peak_memory_gb metric in run(), which only sees the
        Python heap). Purely diagnostic + cleanup -- never affects results."""
        gc.collect()
        try:
            import psutil
            rss_gb = psutil.Process().memory_info().rss / 1e9
            self._peak_rss_gb = max(getattr(self, "_peak_rss_gb", 0.0), rss_gb)
            self._log(f"  [MEMORY] {label}: RSS={rss_gb:.2f} GB "
                      f"(peak {self._peak_rss_gb:.2f} GB)")
        except Exception:
            pass

    #   main entry point

    def run(self) -> dict:
        """Run the full V2 pipeline. Returns a results dict. (Thin wrapper: guarantees the guided-labelling
        constraint context never outlives a run, whatever happens inside _run_core.)"""
        try:
            return self._run_core()
        finally:
            try:
                from cube_guided_constraints import clear as _guided_clear
                _guided_clear()
            except Exception:
                pass

    def _run_core(self) -> dict:
        """Run the full V2 pipeline. Returns a results dict."""
        # Track total wall-clock runtime and peak memory for the publication
        # benchmark metrics (Section 3.2: Runtime Efficiency + Peak Memory).
        import tracemalloc as _tm
        _tm.start()
        _run_t0 = time.perf_counter()

        # Apply plot theme before any figure is drawn (updates _BG/_PANEL/_TEXT_COL/_TICK_COL)
        _apply_plot_theme(self._cfg.get("plot_theme", "light"))

        self._log("=" * 64)
        self._log(f"  CUBE Engine  v{VERSION}")
        self._log("=" * 64)

        # ── System resources: detect once, report the resolved parallelism
        # budget for the HDBSCAN-side stages (sweep/split/seed-sweep). Actual
        # resolution happens per-call via resolve_n_jobs()/compute_adaptive_
        # n_jobs() -- this is a preview so the auto-managed behaviour is
        # visible rather than silent, and each heavy stage re-checks RAM
        # pressure independently right before it dispatches.
        self._peak_rss_gb = 0.0
        try:
            _res = detect_system_resources()
            self._log(f"\n[SYSTEM] {_res['cpu_count']} logical cores  |  "
                      f"RAM {_res['available_ram_gb']:.1f}/{_res['total_ram_gb']:.1f} GB "
                      f"available ({_res['ram_used_pct']:.0f}% used)")
            if bool(self._cfg.get("auto_resource_management", True)):
                _budget = compute_adaptive_n_jobs(self._cfg, log_fn=self._log)
                self._log(f"  [SYSTEM] auto-managed parallel budget: {_budget} "
                          f"worker(s)  (target "
                          f"{float(self._cfg.get('system_resource_target_pct', 0.50)):.0%}"
                          f" of cores, cap "
                          f"{float(self._cfg.get('system_resource_cap_pct', 0.65)):.0%})"
                          f"  — applies to the HDBSCAN sweep/split/seed-sweep "
                          f"stages; UMAP embedding stays single-threaded for "
                          f"reproducibility.")
            else:
                self._log("  [SYSTEM] auto_resource_management is OFF — "
                          "using explicit *_n_jobs cfg values as-is.")
        except Exception:
            self._log("  [SYSTEM] resource detection unavailable (psutil "
                      "missing?) — falling back to explicit *_n_jobs cfg values.")

        # ── Key parameters for this run ─────────────────────────────────────
        self._log("\n[CONFIG] Key parameters")
        _mlp_classifier = str(self._cfg.get("mlp_classifier", "random_forest"))
        if _mlp_classifier == "mlp":
            self._log(f"  classifier        : MLPClassifier(hidden="
                      f"{self._cfg.get('mlp_hidden', '100,50')})")
        else:
            self._log(f"  classifier        : RandomForest(class_weight="
                      f"{self._cfg.get('rf_class_weight', 'balanced')!r})")
        self._log(f"  likelihood_thresh : {self._cfg.get('likelihood_thresh')}")
        _nn = int(self._cfg.get("umap_n_neighbors", 0) or 0)
        self._log(f"  umap_n_neighbors  : {'auto (resolved from recording length below)' if _nn <= 0 else _nn}")
        self._log(f"  umap_n_components : {self._cfg.get('umap_n_components')}")
        self._log(f"  train_frac        : {self._cfg.get('train_frac')}")
        self._log(f"  umap_min_dist     : {self._cfg.get('umap_min_dist')}")
        self._log(f"  hdbscan_mcs_anchor: {self._cfg.get('hdbscan_mcs_anchor')}"
                  f"  |  sweep {self._cfg.get('hdbscan_pct_lo') or 'auto'}–"
                  f"{self._cfg.get('hdbscan_pct_hi')} (0.1%-of-N units), "
                  f"min_samples=max(5, mcs//5)")
        self._log(f"  analysis_version  : {ANALYSIS_VERSION}  "
                  f"(compat_mode={self._cfg.get('compat_mode', 'current')})")
        _bn  = self._cfg.get("body_normalise", False)
        self._log(f"  Feature engine    : V2  (fps-adaptive scales, "
                  f"body_normalise={_bn}, angular)")

        _validation: dict = {}

        # 1. Discover & pair files  (all csv/video folders combined)
        self._log("\n[1/7]  Discovering files...")
        self._stage("1/7 — Discovering files")

        # Collect DLC files from every csv folder (combined multi-group analysis)
        dlc_files: list = []
        for _csv_dir in self._csv_folders:
            dlc_files.extend(find_dlc_files(_csv_dir))
        # Deduplicate by resolved path (in case folders overlap)
        _seen_dlc: set = set()
        _uniq_dlc: list = []
        for _f in dlc_files:
            _key = str(_f.resolve())
            if _key not in _seen_dlc:
                _seen_dlc.add(_key)
                _uniq_dlc.append(_f)
        dlc_files = _uniq_dlc

        # Collect videos from every video folder
        vid_dict: dict = {}
        for _vid_dir in self._vid_folders:
            vid_dict.update(find_videos(_vid_dir))

        pairs    = pair_files(dlc_files, vid_dict)
        n_paired = sum(1 for _, v in pairs if v)
        self._log(f"  {len(self._csv_folders)} csv folder(s), "
                  f"{len(dlc_files)} DLC file(s), {len(vid_dict)} video(s), "
                  f"{n_paired} paired")
        if not dlc_files:
            raise FileNotFoundError(
                f"No BSOID-ready files found in: "
                f"{', '.join(str(d) for d in self._csv_folders)}")
        if dlc_files and n_paired == 0 and (self._cfg.get("save_videos")
                and (self._cfg.get("save_example_clips")
                     or self._cfg.get("save_labeled_video"))):
            # Not fatal (the clustering/CSV outputs are independent of
            # video), but silent otherwise: every session's `vp` stays None,
            # so example-clip/labeled-video export is skipped for the ENTIRE
            # run with no further signal anywhere else in the log. Confirmed
            # as a real failure mode (2026-09-07, F:\DAM EXP3 GQ run) where
            # a 3D DLC quad-video export step's output went unlogged (a
            # separate GUI logger-swap bug, now fixed) and this stage then
            # completed "successfully" with zero example clips and no
            # indication why.
            self._log(f"  [WARN] 0 of {len(dlc_files)} DLC file(s) paired "
                      f"with a video (video folders: {len(self._vid_folders)}, "
                      f"videos found: {len(vid_dict)}) — example clips and "
                      f"labeled videos will be skipped for EVERY session "
                      f"this run. Check that the video output actually "
                      f"exists (e.g. a 3D DLC run's per-session quad "
                      f"composite / BSOID_Project_Ready/videos copy) before "
                      f"trusting this run's video-dependent outputs.")

        # Validation gate 1: DLC quality
        try:
            _validation["dlc_quality"] = validate_dlc_quality(
                dlc_files, self._cfg["likelihood_thresh"])
            for w in _validation["dlc_quality"]["warnings"]:
                self._log(f"  [VALID-WARN] {w}")
        except Exception as e:
            self._log(f"  [VALID] DLC quality check failed: {e}")

        # Detect 3D mode. A pooled/prep folder can contain a mix of the final
        # 3D-triangulated H5 (world xyz) alongside leftover per-camera 2D H5s
        # (pixel xy) from the same 3D-DLC session output dir (e.g. the
        # cam0_..._superanimal...h5 DLC-Zoo output that dlc_3d_delete_cam_h5s
        # leaves behind by default) — those aren't independent sessions and
        # can't share a feature space with 3D data (different column count
        # per bodypart: 3 vs 2), so checking only pairs[0][0] silently mixed
        # them and crashed deep inside extract_features_3d on a column-count
        # mismatch. Check every file and drop whichever modality is the
        # minority instead.
        _file_is_3d = [_h5_has_z(p) for p, _ in pairs] if pairs else []
        _is_3d = any(_file_is_3d)
        if _is_3d and not all(_file_is_3d):
            _mismatched = [p.name for (p, _), z in zip(pairs, _file_is_3d) if not z]
            self._log(f"  [WARN] {len(_mismatched)} DLC file(s) are 2D (pixel-space, "
                      f"per-camera) and cannot be pooled with the 3D (world-space) "
                      f"files found alongside them — excluding: "
                      f"{', '.join(_mismatched)}")
            pairs = [(p, v) for (p, v), z in zip(pairs, _file_is_3d) if z]
            dlc_files = [p for p in dlc_files if any(p == pp for pp, _ in pairs)]
        if _is_3d:
            self._log("  [3D] Detected 3D H5 files — using 3D feature extraction "
                      "(true Euclidean distances + velocities in world space)")
        _nc = 3 if _is_3d else 2   # columns per bodypart: 3 for xyz, 2 for xy

        # 2. Load & smooth
        self._log("\n[2/7]  Loading & smoothing...")
        self._stage("2/7 — Loading DLC files", f"0/{len(pairs)}")
        all_xy, all_names, all_fps_list, all_bps, all_vpaths = [], [], [], [], []
        all_groups: list = []   # input folder each session came from (for export coverage)
        all_bp_bad_fracs: dict = {}  # bodypart -> list of per-session bad-frame fracs
        all_flat_held: list = []     # per-session per-bodypart flat-held masks (list[list[np.ndarray]])
        all_ll: list = []            # per-session raw per-frame likelihood arrays (issue 2 visibility features)
        # v6 part 2 (Environmental_Context_v6_Implementation_Plan.md Step 3):
        # index-aligned to pairs/all_xy, exactly like all_vpaths. One shared
        # env_arena_cfg dict per project (one traced arena, applied per-video
        # via its own per_video/role_overrides sub-keys) -- not a per-stem
        # lookup, since Step 1's schema defines a single arena config, not a
        # dict keyed by stem. None whenever env_features_enabled is False or
        # no arena has been configured, so downstream Step 4/6/7 calls are
        # unconditionally no-ops in that state.
        all_env_cfg: list = []

        def _group_key(_fp: Path) -> str:
            # Which uploaded csv folder does this DLC file belong to?  Used so the
            # UMAP-evolution export can guarantee at least one video per folder.
            try:
                _fpr = _fp.resolve()
                for _cd in self._csv_folders:
                    _cdr = Path(_cd).resolve()
                    if _cdr == _fpr or _cdr in _fpr.parents:
                        return str(_cdr)
            except Exception:
                pass
            return str(_fp.parent)

        for i, (fp, _vp) in enumerate(pairs):
            self._log(f"  [{i+1}/{len(pairs)}]  {fp.name}")
            self._stage("2/7 — Loading DLC files", f"{i+1}/{len(pairs)}: {fp.name}")
            try:
                _gap_fps = float(self._fps_arg or 30.0)
                _max_gap = int(round(_gap_fps * float(
                    self._cfg.get("max_interp_gap_sec", 0.5))))
                xy, bps, fps_hint, ll_fracs, _flat_held, _ll = load_dlc_file(
                    fp, self._cfg["likelihood_thresh"],
                    max_interp_gap_frames=_max_gap, log_fn=self._log,
                    return_quality=True, include_z=_is_3d)
                for _bp, _frac in ll_fracs.items():
                    all_bp_bad_fracs.setdefault(_bp, []).append(_frac)
                fps = fps_hint or self._fps_arg or 30.0
                xy  = smooth_boxcar(xy, fps, self._cfg["boxcar_win_sec"])
                all_xy.append(xy)
                all_names.append(fp.stem)
                all_fps_list.append(float(fps))
                all_bps.append(bps)
                all_vpaths.append(str(_vp) if _vp else None)
                all_groups.append(_group_key(fp))
                all_flat_held.append(_flat_held)
                all_ll.append(_ll)
                all_env_cfg.append(
                    self._cfg.get("env_arena_cfg")
                    if bool(self._cfg.get("env_features_enabled", False)) else None)
            except Exception:
                self._log(f"  [WARN] Skipping {fp.name}:\n"
                          f"  {traceback.format_exc()}")
            self._prog(i + 1, len(pairs))

        if not all_xy:
            raise RuntimeError("No files could be loaded.")

        # Resolve a common bodypart set — intersection of all files, preserving
        # the order from the first file.  Needed when groups have different
        # tracked keypoints (e.g. female 22 bp vs male 28 bp).
        bps_sets   = [set(b) for b in all_bps]
        common_set = bps_sets[0].intersection(*bps_sets[1:]) if len(bps_sets) > 1 else bps_sets[0]
        bps_ref    = [bp for bp in all_bps[0] if bp in common_set]  # stable order
        n_dropped  = len(all_bps[0]) - len(bps_ref)
        if n_dropped:
            self._log(f"  [INFO] Bodypart intersection: {len(bps_ref)} common "
                      f"bodyparts across all files ({n_dropped} dropped from "
                      f"reference set that were absent in some files).")
            # Identify which file(s) caused the largest drop so the user knows
            # which group's tracking limited the shared feature space.
            _worst_n = -1
            _worst_nm = None
            for _nm_k, _bps_k in zip(all_names, all_bps):
                _lost = sum(1 for bp in all_bps[0] if bp not in set(_bps_k))
                if _lost > _worst_n:
                    _worst_n, _worst_nm = _lost, _nm_k
            if _worst_nm is not None and _worst_n > 0:
                self._log(f"  [INFO] Smallest-keypoint session: '{_worst_nm}' "
                          f"(missing {_worst_n} of the reference bodyparts).")
        # Quality gate: a tiny shared keypoint set produces an impoverished
        # feature space (few pairwise distances) and unreliable clustering.
        _min_keep = int(self._cfg.get("bodypart_min_keep", 6))
        if len(bps_ref) < _min_keep:
            self._log(f"  [VALID-WARN] Only {len(bps_ref)} bodyparts shared "
                      f"across all sessions (< {_min_keep}). Feature space is "
                      f"impoverished; clustering/DBCV may be unreliable. Improve "
                      f"DLC tracking or relax the conservation policy (median "
                      f"metric, lower min-session-fraction) in DLC & Prep "
                      f"settings.")
            self._stage("VALIDATION WARN",
                        f"only {len(bps_ref)} shared bodyparts — "
                        f"impoverished feature space")
        # Filter every xy array to the common bodypart columns
        for k, (bps_k, xy_k) in enumerate(zip(all_bps, all_xy)):
            if bps_k != bps_ref:
                col_idx = []
                for bp in bps_ref:
                    if bp in bps_k:
                        j = bps_k.index(bp)
                        col_idx.extend([_nc * j + c for c in range(_nc)])
                all_xy[k] = xy_k[:, col_idx]
                # Mirror the same filtering on the raw likelihood arrays (1 col
                # per bodypart, not _nc-per-bodypart) so all_ll stays column-
                # aligned with bps_ref for the visibility feature block (issue 2).
                if k < len(all_ll) and all_ll[k] is not None and all_ll[k].size:
                    _ll_idx = [bps_k.index(bp) for bp in bps_ref if bp in bps_k]
                    all_ll[k] = all_ll[k][:, _ll_idx]

        # Exclude turned-away-from-camera frames from all_bp_bad_fracs before
        # it feeds either the FEAT-DROP gate (_agg, below) or the auto-weight
        # block further down. all_bp_bad_fracs is raw per-frame-likelihood
        # based (built in Step 2, load_dlc_file) and knows nothing about
        # turned-away frames -- detect_turned_away_bins only runs later, in
        # Step 3, purely for exclusion-from-training/labelling. A bodypart
        # that's only invisible DURING turned-away moments (jaws, forepaws)
        # isn't actually chronically mistracked -- those exact frames are
        # already excluded from UMAP/HDBSCAN training separately, so counting
        # them here just double-penalises the bodypart, and with a single
        # high-turned-away session can make an otherwise well-tracked
        # bodypart look bad enough to trigger both FEAT-DROP and
        # auto-weighting (confirmed on real data: jaw/forepaw bodyparts
        # flagged by auto-weighting turned out to be driven by one session
        # with 34.7% turned-away time, not chronic mistracking). Recompute
        # each bodypart's per-session bad-frame fraction using only
        # non-turned-away frames. Gated so compat_mode="legacy_v2"
        # reproduces older runs exactly (FEAT-DROP's drop set is pre-existing
        # behaviour, not new this session).
        if (bool(self._cfg.get("turned_away_exclude_from_bad_frac", True))
                and not _is_3d
                and all_bp_bad_fracs and "nose" in [str(b).lower() for b in bps_ref]):
            _ta_adaptive_pct_early = float(self._cfg.get("turned_away_adaptive_pct", 30.0))
            _ta_conf_thresh = float(self._cfg.get("turned_away_conf_thresh", 0.5))
            _ta_min_window_s = float(self._cfg.get("turned_away_min_window_s", 1.0))
            _ta_merge_gap_s = float(self._cfg.get("turned_away_merge_gap_s", 0.5))
            _ll_thresh = float(self._cfg["likelihood_thresh"])
            _n_corrected = 0
            for k in range(len(all_ll)):
                _llk = all_ll[k]
                if _llk is None or not getattr(_llk, "size", 0):
                    continue
                _fps_k = float(all_fps_list[k]) if k < len(all_fps_list) else 30.0
                try:
                    _ta_bin_mask = detect_turned_away_bins(
                        _llk, bps_ref, _fps_k, _ll_thresh, _ta_adaptive_pct_early,
                        _ta_conf_thresh, _ta_min_window_s, _ta_merge_gap_s)
                except Exception:
                    continue
                if _ta_bin_mask.size == 0 or not _ta_bin_mask.any():
                    continue
                _win = max(1, int(round(_fps_k / 10)))
                _ta_frame_mask = np.repeat(_ta_bin_mask, _win)
                # Pad (trailing partial-bin remainder frames, treated as not
                # turned-away) or truncate to exactly match _llk's frame
                # count -- np.repeat's length is n_bins*_win, which can be
                # shorter OR longer than _llk.shape[0] depending on rounding.
                if _ta_frame_mask.shape[0] < _llk.shape[0]:
                    _ta_frame_mask = np.concatenate([
                        _ta_frame_mask,
                        np.zeros(_llk.shape[0] - _ta_frame_mask.shape[0], dtype=bool)])
                else:
                    _ta_frame_mask = _ta_frame_mask[:_llk.shape[0]]
                _keep = ~_ta_frame_mask
                if not _keep.any():
                    continue
                for j, bp in enumerate(bps_ref):
                    if bp not in all_bp_bad_fracs or k >= len(all_bp_bad_fracs[bp]):
                        continue
                    all_bp_bad_fracs[bp][k] = float(np.mean(_llk[_keep, j] < _ll_thresh))
                    _n_corrected += 1
            if _n_corrected:
                self._log(
                    f"  [TURNED-AWAY-CORRECT] adjusted bad-frame fraction for "
                    f"{_n_corrected} bodypart-session pair(s) to exclude "
                    f"turned-away frames (prevents turned-away spikes from "
                    f"masquerading as chronic mistracking).")

        # Drop chronically occluded bodyparts from the feature space.
        # At this point all_xy[k] columns are ordered by bps_ref, so we can
        # index directly.  Bodyparts whose mean bad-frame fraction across
        # sessions meets or exceeds feature_bad_bp_thresh are removed; they
        # contribute flat-interpolated artefacts (identical feature vectors)
        # that inflate HDBSCAN noise and cause DBCV to become non-finite.
        # When visibility_features_enabled=True (default), the much higher
        # feature_bad_bp_thresh_with_visibility bar applies instead -- with
        # visibility features on, transient/periodic occlusion (e.g. limb
        # joints during normal movement, animal turned away from camera) is
        # isolated via the visibility feature block rather than requiring
        # wholesale bodypart removal, so only near-unusable bodyparts need
        # dropping here. See DEFAULTS for the calibration rationale.
        _vis_enabled_for_drop = bool(self._cfg.get("visibility_features_enabled", True))
        _feat_thresh = float(self._cfg.get(
            "feature_bad_bp_thresh_with_visibility" if _vis_enabled_for_drop
            else "feature_bad_bp_thresh",
            0.70 if _vis_enabled_for_drop else 0.40))
        if all_bp_bad_fracs:
            _agg = {bp: float(np.mean(all_bp_bad_fracs.get(bp, [0.0])))
                    for bp in bps_ref}
        else:
            _agg = {}
        if _feat_thresh > 0 and _agg:
            _drop = [bp for bp in bps_ref if _agg.get(bp, 0.0) >= _feat_thresh]
            if _drop:
                self._log(
                    f"  [FEAT-DROP] {len(_drop)} bodypart(s) excluded from "
                    f"feature extraction (mean bad-frame frac >= "
                    f"{_feat_thresh*100:.0f}% across sessions): {_drop}")
                _keep_pos = [i for i, bp in enumerate(bps_ref)
                             if bp not in set(_drop)]
                bps_ref = [bps_ref[i] for i in _keep_pos]
                _col_idx = []
                for i in _keep_pos:
                    _col_idx.extend([_nc * i + c for c in range(_nc)])
                for k in range(len(all_xy)):
                    all_xy[k] = all_xy[k][:, _col_idx]
                for k in range(len(all_ll)):
                    if all_ll[k] is not None and all_ll[k].size:
                        all_ll[k] = all_ll[k][:, _keep_pos]
                _agg = {bp: _agg[bp] for bp in bps_ref}

        # Automatic confidence-based bodypart down-weighting (data-driven,
        # complements the hard FEAT-DROP gate above). Bodyparts that survive
        # the drop but are still chronically unreliable still contribute
        # flat-interpolated, near-duplicate feature vectors at full weight,
        # which is exactly what pushes HDBSCAN noise up and DBCV toward
        # degenerate -- FEAT-DROP alone only catches the most extreme cases
        # (default threshold 0.70 with visibility features on). This tapers
        # weight continuously instead of a second hard cutoff, so
        # moderately-bad bodyparts are down-weighted rather than either
        # fully trusted or fully discarded.
        #
        # Uses the fraction of SESSIONS a bodypart is genuinely bad in
        # ("chronic" = affects a recurring subset of sessions), NOT the mean
        # used by the FEAT-DROP gate above and NOT a percentile-of-magnitude
        # statistic. A bodypart that is severely bad (e.g. 50-67%) in a
        # handful of sessions but fine in most others has its MEAN diluted
        # below any reasonable threshold -- observed in practice on real
        # data: the exact bodyparts named as the worst-tracked in individual
        # sessions (back_right_knee, back_middle, throat_base/end, etc.)
        # never appeared in the [AUTO-WEIGHT] line at all, because their
        # session-mean landed under auto_bp_weight_lo even though specific
        # sessions were badly affected. A percentile-of-magnitude statistic
        # (e.g. max) "fixes" that but over-corrects: with ~20 sessions,
        # almost every bodypart has at least one session with a bad-frame
        # spike (often driven by turned-away moments, though that specific
        # confound is now handled upstream via
        # turned_away_exclude_from_bad_frac), so a max-based stat flags most
        # bodyparts rather than the genuinely chronic ones (confirmed on
        # real data: 16 of 22 bodyparts flagged, mostly jaws/paws driven by
        # a single high-turned-away session). Counting SESSIONS AFFECTED
        # (bad_frac > auto_bp_weight_session_thresh in that session) instead
        # of a magnitude statistic is robust to both problems: a bodypart
        # bad in only 1-2 sessions (a fluke) stays under auto_bp_weight_lo
        # untouched, while one bad in a recurring subset of sessions still
        # crosses it regardless of how many other sessions are clean.
        #
        # An explicit user-set entry in bodypart_weights (e.g. via the GUI's
        # Body-Region Weights panel) always wins for that bodypart -- this
        # only fills in bodyparts the user has not already customised.
        _auto_on = bool(self._cfg.get("auto_bodypart_weighting", True))
        if _auto_on and all_bp_bad_fracs:
            _sess_thresh = float(self._cfg.get("auto_bp_weight_session_thresh", 0.3))
            _agg_auto = {bp: float(np.mean([1.0 if f > _sess_thresh else 0.0
                                             for f in all_bp_bad_fracs.get(bp, [0.0])]))
                         for bp in bps_ref}
            _lo    = float(self._cfg.get("auto_bp_weight_lo", 0.10))
            _hi    = float(self._cfg.get("auto_bp_weight_hi", 0.35))
            _floor = float(self._cfg.get("auto_bp_weight_floor", 0.35))
            _user_bpw = dict(self._cfg.get("bodypart_weights") or {})
            _auto_bpw = {}
            if _hi > _lo:
                for bp, frac in _agg_auto.items():
                    if bp in _user_bpw or frac <= _lo:
                        continue
                    _t = min(1.0, (frac - _lo) / (_hi - _lo))
                    _auto_bpw[bp] = round(1.0 - _t * (1.0 - _floor), 3)
            if _auto_bpw:
                _preview = ", ".join(f"{bp}={w:.2f}" for bp, w in
                                     sorted(_auto_bpw.items(), key=lambda kv: kv[1])[:6])
                _more = f", +{len(_auto_bpw) - 6} more" if len(_auto_bpw) > 6 else ""
                self._log(
                    f"  [AUTO-WEIGHT] {len(_auto_bpw)} bodypart(s) down-weighted "
                    f"(affected in {_lo:.0%}-{_hi:.0%} of sessions -> "
                    f"weight 1.00-{_floor:.2f}): {_preview}{_more}")
                self._cfg["bodypart_weights"] = {**_auto_bpw, **_user_bpw}

        fps = float(pd.Series(all_fps_list).mode()[0])
        self._log(f"  FPS = {fps}  |  bodyparts = {len(bps_ref)}")

        # all_flat_held stays as per-bp lists (one bool array per bodypart per
        # session) — the bin-mask block below uses them directly with the
        # fraction threshold so dropped bodyparts cannot inflate exclusion counts.

        if self._cfg["save_plots"]:
            try:
                plot_likelihood_qc(dlc_files,
                                   self._out_plots / "likelihood_qc.png")
            except Exception:
                self._log(f"  [WARN] likelihood_qc plot: "
                          f"{traceback.format_exc()}")

        # 3. Features — dispatch to 3D or V2 extractor based on input format
        _body_norm    = bool(self._cfg.get("body_normalise",  False))
        _long_lag     = bool(self._cfg.get("long_lag_drift",  False))
        _long_scales  = bool(self._cfg.get("long_scale_bins", False))
        # v2.1: skip the angular block when no spine landmarks match by keyword
        # (legacy mode keeps the evenly-spaced fallback).  Used for every feature
        # call in this run so training and inference stay dimensionally aligned.
        _ang_fb = bool(self._cfg.get("angular_fallback", True))
        if _is_3d:
            # 3D world-coordinate data: body normalisation (pixel-space nose-to-tail)
            # is not meaningful; skip the 2D-only checks.
            if _body_norm:
                self._log("  [INFO] 3D mode: body_normalise ignored "
                          "(world-coordinate distances are already scale-invariant).")
            _3d_scales = (("50/" if fps >= 60 else "") + "100/200"
                          + ("/500/1000" if _long_scales else "") + " ms")
            _3d_lag = "5/10" + ("/20/30-bin" if _long_lag else "-bin") + " lag drift"
            self._log(f"\n[3/7]  Extracting 3D features  "
                      f"({_3d_scales} · true Euclidean distances + velocities · {_3d_lag})...")
            self._stage("3/7 — Extracting 3D features", f"scale={_3d_scales}")
        else:
            # If body normalisation is requested but no nose/tail spine landmarks are
            # present, extract_features_v2 silently skips it — warn so the user knows
            # spatial features stay in raw pixels (scale-variant across sessions).
            if _body_norm and _find_spine_indices(bps_ref) == (None, None):
                self._log("  [VALID-WARN] body_normalise is ON but no head/tail spine "
                          "landmarks were found among the shared bodyparts — "
                          "normalisation will be skipped and spatial features remain "
                          "in raw pixels (sensitive to camera distance / body size).")
            _scale_desc = ("50/100/200 ms" if fps >= 60 else "100/200 ms")
            _lag_desc = "long-lag" if _long_lag else "std-lag"
            self._log(f"\n[3/7]  Extracting V2 features  "
                      f"({_scale_desc} + angular, body_normalise={_body_norm}, {_lag_desc})...")
            self._stage("3/7 — Extracting V2 features", f"scale={_scale_desc}")
        # Phase 2 (TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md): order-sensitive
        # shape features. Resolved ONCE here and reused verbatim at every
        # inference-time re-extraction call site below (predict_labels / the
        # no-MLP fallback) -- same "MUST be applied identically" discipline
        # as bodypart_weights/visibility features just below.
        _order_shape_enabled = bool(self._cfg.get("order_shape_features_enabled", False))
        # Floor-referenced posture features (paw elevation/duty-cycle for
        # guarding, back/neck/nose elevation for rearing, mouth-to-paw
        # proximity for licking/grooming) -- see _floor_reference_feature_
        # block's docstring. Resolved once here, reused verbatim at every
        # inference-time re-extraction call site, same discipline as
        # order-shape/bodypart_weights/visibility above. Unlike order-shape,
        # this block is NOT split off after extraction -- it's a normal
        # primary feature block, folded into the same embedding UMAP/HDBSCAN
        # train on.
        _floor_features_enabled = bool(self._cfg.get("paw_floor_features_enabled", True))
        # Additional posture/kinematic per-bin dimensions -- real-data-
        # validated criteria (see _floor_reference_feature_block's own
        # docstring), nested under paw_floor_features_enabled (inert
        # without it); on by default.
        _behavior_indicators_enabled = bool(self._cfg.get("behavior_indicators_enabled", True))
        # LR_ORIENTATION_FIX_PLAN.md: correctness fixes for a real, diagnosed
        # heading-direction clustering confound (see cube_core.py's
        # LR_BODYPART_PAIRS / _lr_symmetrize_columns / f_withinbin docs).
        # Resolved once here, reused verbatim at every inference-time
        # re-extraction call site below, same "MUST be passed identically"
        # discipline as order_shape/floor/bodypart_weights above.
        _lr_symmetrize = bool(self._cfg.get("lr_symmetrize_features_enabled", True))
        _withinbin_rot_inv = bool(self._cfg.get("withinbin_variance_rotation_invariant", True))
        _egocentric_alignment_enabled = bool(self._cfg.get("egocentric_alignment_enabled", False))
        _egocentric_alignment_pca_dims = int(self._cfg.get("egocentric_alignment_pca_dims", 10) or 10)
        _order_shape_channel_set = str(self._cfg.get("order_shape_channel_set", "limb_velocity_direction"))
        _order_shape_depth = int(self._cfg.get("order_shape_depth", 2))
        _order_shape_window_ms = float(self._cfg.get("order_shape_window_ms", 100))
        _order_shape_window_mode = str(self._cfg.get("order_shape_window_mode", "fixed_short"))
        if _order_shape_enabled and _order_shape_window_mode == "fps_adaptive":
            # 2026-08-30 decision: frame-count-first, not ms-first -- a
            # window must span at least 10 raw frames to be trusted as a
            # real order signal rather than noise (some behaviors are
            # noisy enough that fewer frames can't reliably establish
            # order), with 50ms kept as a hard floor for now (not yet
            # re-derived from a biological minimum, just a placeholder so
            # a very-high-fps rig doesn't get an unreasonably short
            # window). At CUBE's real ~30fps this resolves to 333ms, not
            # the untested 100ms fixed_short default.
            _fps_adaptive_ms = max(50.0, float(np.ceil(10000.0 / max(fps, 1e-6))))
            self._log(f"  [order-shape] fps_adaptive window: {_fps_adaptive_ms:.1f}ms "
                      f"(10 frames at {fps:.1f}fps, 50ms floor)")
            _order_shape_window_ms = _fps_adaptive_ms
        elif _order_shape_enabled and _order_shape_window_mode == "bout_calibrated":
            _prior_bout_csvs = []
            if self._out_bouts.exists():
                _prior_bout_csvs = sorted(self._out_bouts.glob("*_bout_lengths_hmm.csv"))
                if not _prior_bout_csvs:
                    _prior_bout_csvs = sorted(self._out_bouts.glob("*_bout_lengths.csv"))
            _min_ms = 2000.0 / fps   # floor: >= 2 raw frames per window
            _resolved_ms = (_bout_calibrated_window_ms(_prior_bout_csvs, fps, pct=15.0, min_ms=_min_ms)
                            if _prior_bout_csvs else None)
            if _resolved_ms is not None:
                self._log(f"  [order-shape] bout_calibrated window: {_resolved_ms:.1f}ms "
                          f"(15th pct of {len(_prior_bout_csvs)} prior bout file(s))")
                _order_shape_window_ms = _resolved_ms
            else:
                self._log("  [order-shape] bout_calibrated mode requested but no prior "
                          f"bout-duration data found under {self._out_bouts} — falling back "
                          f"to fixed_short window_ms={_order_shape_window_ms:.1f}")
        # order_shape_extra_bodyparts (2026-08-30 decision): lower_jaw
        # always, upper_jaw conditionally -- resolved ONCE per run (never
        # per-session) from the aggregate tracked fraction across every
        # session, so the resulting feature width stays identical
        # everywhere it's used (training here, inference-time
        # re-extraction below, and _order_shape_block_width's column-count
        # math for Phase 6's flow field).
        _order_shape_extra_bps: list = []
        if _order_shape_enabled:
            _order_shape_extra_bps = _resolve_order_shape_head_bodyparts(
                bps_ref, all_ll, ll_gate=float(self._cfg.get("likelihood_thresh", 0.3) or 0.3))
            if _order_shape_extra_bps:
                self._log(f"  [order-shape] extra head channel(s): "
                          f"{', '.join(_order_shape_extra_bps)}")
        # 2026-08-30 fix (real-data regression check found order-shape was
        # NOT actually excluded from the primary UMAP/HDBSCAN embedding,
        # contradicting handoff-report decision #1 "order should be a
        # tie-breaker only" — order_shape_on alone, flow field off,
        # reproduced Phase 8's old-architecture 14-cluster/ARI=0.317
        # destabilization instead of true baseline's 16 clusters). Root
        # cause: order_shape_enabled was threaded straight into
        # extract_features_v2/_3d and the returned (order-shape-included)
        # array was used directly as the UMAP/HDBSCAN/MLP training matrix —
        # nothing ever stripped it back out before the primary embedding.
        # _n_order_shape_cols is now resolved ONCE, here, before the
        # per-session extraction loop, so the loop can split each session's
        # order-shape block off immediately (see all_order_shape below) —
        # right after extraction, BEFORE the visibility block gets appended
        # (compute_session_visibility_block/_append_visibility_block run
        # AFTER order-shape in this loop, so the true trailing block once
        # visibility is on, the default, is visibility — not order-shape;
        # the old code's "order-shape is always the trailing block" premise
        # was already false whenever visibility_features_enabled=True).
        # Tracking it by explicit split at the true insertion point (rather
        # than a "last N columns of some later, bigger matrix" assumption)
        # sidesteps that ordering bug too, and sidesteps a further
        # pre-existing bug where PCA pre-reduction (auto-triggers whenever
        # sample/feature ratio < 5, the common case) would have scrambled
        # any later "trailing N columns" assumption anyway, since PCA mixes
        # every input dimension into new components.
        _n_order_shape_cols = 0
        if _order_shape_enabled:
            _n_order_shape_cols = _order_shape_block_width(
                bps_ref, len(bps_ref or []), 3 if _is_3d else 2,
                int(self._cfg.get("order_shape_depth", 2)),
                extra_bodyparts=_order_shape_extra_bps)
        all_order_shape: list = []   # per-session (n_order_shape_cols, n_bins),
                                      # retained ONLY for Tier 3b (flow field)
        # Issue 1b (body-region weighting) / issue 2 (visibility features):
        # MUST be applied identically here (training) and at inference-time
        # re-extraction (predict_labels / the no-MLP fallback below) — a
        # mismatch silently desyncs the MLP's expected feature layout.
        _bp_weights = self._cfg.get("bodypart_weights") or None
        _vis_enabled = bool(self._cfg.get("visibility_features_enabled", True))
        _vis_pct     = float(self._cfg.get("visibility_adaptive_pct", 10))
        # n_vis_cols/weight for _scale_visibility_block (visibility_feature_
        # weight) below -- computed once here, reused at feats_sc scaling
        # time and passed through to every predict_labels() call site so
        # training/inference apply the identical post-scaler multiplier.
        _n_vis_cols  = len(visibility_feature_names(bps_ref)) if _vis_enabled else 0
        _vis_weight  = float(self._cfg.get("visibility_feature_weight", 1.0))
        # face_limb_proximity_feature_weight: n_proximity_cols is 2 (distance +
        # closure-rate) per proximity_targets entry ("nose", "lower_jaw" --
        # _floor_reference_feature_block's own hardcoded default, unchanged
        # by any caller here) that's actually present in bps_ref -- those are
        # the trailing columns of the floor block, itself the trailing block
        # of `f` once order-shape is stripped and before visibility is
        # vstacked on (see _scale_visibility_block's tail_offset docstring).
        # Approximates "floor block produced output" as "floor enabled AND a
        # paw bodypart exists" rather than actually calling
        # _floor_reference_feature_block here -- matches _n_vis_cols' own
        # "enabled implies present" approximation just above.
        # +1 more col/target when a spine reference (head+tailbase) is also
        # available, for _floor_reference_feature_block's own
        # face_limb_proximity_body_frac adaptive-threshold, no-elevation-gate
        # duty-cycle column (internal default 0.22, always on when floor
        # features are) -- see that block's own docstring.
        _prox_targets = ("nose", "lower_jaw")
        _has_paw_bp   = any("paw" in bp.lower() for bp in bps_ref)
        _bps_ref_lower = [b.lower() for b in bps_ref]
        _has_spine_ref = (any(kw in b for b in _bps_ref_lower for kw in ("nose", "snout", "head", "neck", "rostral"))
                          and any(kw in b for b in _bps_ref_lower for kw in ("tailbase", "tail_base")))
        _cols_per_prox_target = 3 if _has_spine_ref else 2
        _n_prox_cols  = (_cols_per_prox_target * sum(1 for t in _prox_targets if t in bps_ref)
                         if _floor_features_enabled and _has_paw_bp else 0)
        _prox_weight  = float(self._cfg.get("face_limb_proximity_feature_weight", 1.0))
        # isolated-limb + sustained-isolated-limb duty-cycles:
        # _floor_reference_feature_block's own true trailing 2 columns
        # (appended after the proximity family specifically so they sit
        # immediately before the visibility block -- see that function's
        # own docstring); same "enabled implies present" approximation.
        _n_isolated_limb_cols = (2 if (_floor_features_enabled and _behavior_indicators_enabled
                                       and _has_paw_bp) else 0)
        _isolated_limb_weight = float(self._cfg.get("isolated_limb_feature_weight", 1.0))
        # Turned-away-from-camera detection (v3, validated) — always computed
        # regardless of visibility_features_enabled, so the overlay video/log
        # can show detected windows even if the visibility feature BLOCK
        # itself is disabled.  Uses the same likelihood_thresh/adaptive_pct
        # machinery as the visibility features, plus its own GUI-editable
        # confidence threshold and (non-GUI) debounce windows.
        _ta_conf_thresh = float(self._cfg.get("turned_away_conf_thresh", 0.5))
        _ta_adaptive_pct = float(self._cfg.get("turned_away_adaptive_pct", 30.0))
        _ta_min_window_s = float(self._cfg.get("turned_away_min_window_s", 1.0))
        _ta_merge_gap_s  = float(self._cfg.get("turned_away_merge_gap_s", 0.5))
        # hdbscan_split_longwindow_silhouette_thresh (2026-09-06): computed
        # only when the split-trigger threshold is actually on, so an
        # opted-out user pays zero per-session cost -- same gating
        # convention as region-aware refinement above. Mirrors
        # all_order_shape's own "computed per-session, split off, retained
        # ONLY for one optional downstream use, never joins feats_cat" shape.
        _split_lw_thresh = float(self._cfg.get("hdbscan_split_longwindow_silhouette_thresh", 0) or 0)
        _split_lw_win_sec = float(self._cfg.get("hdbscan_split_longwindow_win_sec", 0.75) or 0.75)
        all_longwindow: list = []   # per-session (n_lw_cols, n_bins), split-trigger use only
        _lw_ok = True   # False on any per-session failure -- disables the WHOLE run's
                        # longwindow split-trigger rather than risk a partial/misaligned array
        all_feats = []
        all_vis: list = []   # per-session (n_bins, n_vis_cols) — for cluster_confidence.csv
        all_turned_away: list = []   # per-session (n_bins,) bool mask
        _ta_3d_skip_logged = False
        for i, (xy, name) in enumerate(zip(all_xy, all_names)):
            if _is_3d:
                self._stage("3/7 — Extracting 3D features",
                            f"{i+1}/{len(all_xy)}: {name}")
                f = extract_features_3d(xy, fps, bps_ref,
                                        long_lag_drift=_long_lag,
                                        long_scale_bins=_long_scales,
                                        bodypart_weights=_bp_weights,
                                        order_shape_enabled=_order_shape_enabled,
                                        order_shape_window_ms=_order_shape_window_ms,
                                        order_shape_channel_set=_order_shape_channel_set,
                                        order_shape_depth=_order_shape_depth,
                                        order_shape_extra_bodyparts=_order_shape_extra_bps,
                                        floor_features_enabled=_floor_features_enabled,
                                        behavior_indicators_enabled=_behavior_indicators_enabled,
                                        egocentric_alignment_enabled=_egocentric_alignment_enabled)
            else:
                self._stage("3/7 — Extracting V2 features",
                            f"{i+1}/{len(all_xy)}: {name}")
                # Frame-level turned-away mask, computed here (ahead of the
                # session's "official" bin-level detect_turned_away_bins call
                # further below, which needs f's own bin count first) purely
                # to feed _floor_reference_feature_block's isolated-limb/
                # sustained-isolated-limb duty-cycle columns -- see turned_away_frame_mask's own
                # docstring on extract_features_v2/_floor_reference_feature_
                # block for why. A second, cheap detect_turned_away_bins call
                # on the same session, not a restructure of the existing
                # pass -- negligible cost (plain array math over one
                # session), deliberately kept independent of the later call's
                # own bookkeeping (all_turned_away, exclude_mask, etc.).
                _ta_frame_mask_pre = None
                if (_floor_features_enabled and i < len(all_ll) and all_ll[i] is not None
                        and getattr(all_ll[i], "size", 0) and "nose" in [str(b).lower() for b in bps_ref]):
                    try:
                        _ta_bin_mask_pre = detect_turned_away_bins(
                            all_ll[i], bps_ref, fps, float(self._cfg["likelihood_thresh"]),
                            _ta_adaptive_pct, _ta_conf_thresh, _ta_min_window_s, _ta_merge_gap_s)
                        _ta_frame_mask_pre = _expand_bin_mask_to_frames(
                            _ta_bin_mask_pre, fps, xy.shape[0])
                    except Exception:
                        _ta_frame_mask_pre = None
                f = extract_features_v2(xy, fps, bps_ref, body_normalise=_body_norm,
                                        angular_fallback=_ang_fb,
                                        long_lag_drift=_long_lag,
                                        long_scale_bins=_long_scales,
                                        bodypart_weights=_bp_weights,
                                        order_shape_enabled=_order_shape_enabled,
                                        order_shape_window_ms=_order_shape_window_ms,
                                        order_shape_channel_set=_order_shape_channel_set,
                                        order_shape_depth=_order_shape_depth,
                                        order_shape_extra_bodyparts=_order_shape_extra_bps,
                                        floor_features_enabled=_floor_features_enabled,
                                        behavior_indicators_enabled=_behavior_indicators_enabled,
                                        turned_away_frame_mask=_ta_frame_mask_pre,
                                        lr_symmetrize_features_enabled=_lr_symmetrize,
                                        withinbin_variance_rotation_invariant=_withinbin_rot_inv,
                                        egocentric_alignment_enabled=_egocentric_alignment_enabled,
                                        egocentric_alignment_pca_dims=_egocentric_alignment_pca_dims)
            # Split the order-shape block off HERE, immediately after
            # extraction and BEFORE visibility is appended below — this is
            # the one point where it truly is f's trailing block (see the
            # comment above _n_order_shape_cols for why "trailing block of
            # some later matrix" is not reliable). f becomes primary-only
            # from here on for every downstream consumer (visibility
            # append, all_feats, feats_cat, UMAP/HDBSCAN/MLP training);
            # the removed block is kept only for optional Tier 3b use.
            if _order_shape_enabled and _n_order_shape_cols > 0 and f.shape[0] > _n_order_shape_cols:
                all_order_shape.append(f[-_n_order_shape_cols:, :])
                f = f[:-_n_order_shape_cols, :]
            if _split_lw_thresh and _lw_ok:
                try:
                    _lw = compute_longwindow_split_feats(xy, fps, win_sec=_split_lw_win_sec)
                    if _lw.shape[1] != f.shape[1]:
                        _n_copy_lw = min(_lw.shape[1], f.shape[1])
                        _lw = _lw[:, :_n_copy_lw]
                    all_longwindow.append(_lw)
                except Exception:
                    self._log(f"  [WARN] {name}: longwindow split-trigger feature "
                              f"computation failed -- disabling this signal for the "
                              f"whole run:\n  {traceback.format_exc()}")
                    _lw_ok = False
                    all_longwindow = []
            _vis = None
            if _vis_enabled and i < len(all_ll):
                _vis = compute_session_visibility_block(
                    all_ll[i], bps_ref, fps,
                    float(self._cfg["likelihood_thresh"]), _vis_pct)
            if _vis is not None:
                all_vis.append(_vis)
                f = _append_visibility_block(f, _vis)
            _n_bins_i = f.shape[1]
            if _is_3d:
                # detect_turned_away_bins was built and validated against a
                # single 2D camera's own raw likelihood, where a confidence
                # dip genuinely means "the camera can't see the face". For
                # calibrated multi-camera triangulation (this branch — has a
                # real 'z' coordinate, distinct from the 2-3 camera
                # homography-fusion path below which stays 2D/no-z and keeps
                # this detector on), `ll` here is instead the POST-
                # TRIANGULATION combined likelihood (dlc_3d_ll_agg, nanmin/
                # mean/max over cameras clearing dlc_3d_ll_gate, forced to 0
                # on a degenerate <2-camera triangulation) — a dip there far
                # more often means "not enough cameras resolved this point
                # this frame" (motion blur, a chronically weak bodypart,
                # transient camera dropout) than "turned away from every
                # camera simultaneously", which is what "turned away" is
                # supposed to mean with the animal surrounded by cameras.
                # Root-caused on a real 4-camera TMZ7 run flagging 24.7% of
                # bins as turned-away — implausibly high for a genuine
                # head-buried/facing-away behavior. Always all-False here;
                # never excludes 3D bins from training on this basis.
                _ta_mask = np.zeros(_n_bins_i, dtype=bool)
                if not _ta_3d_skip_logged:
                    self._log("  [TURNED-AWAY] skipped for triangulated 3D "
                              "data (combined post-triangulation likelihood "
                              "isn't a facing-direction signal) — 2-3 camera "
                              "homography-fusion output is unaffected and "
                              "keeps this detector.")
                    _ta_3d_skip_logged = True
            elif i < len(all_ll) and all_ll[i] is not None and getattr(all_ll[i], "size", 0):
                if "nose" not in [str(b).lower() for b in bps_ref]:
                    self._log(f"  [WARN] {name}: turned-away detection skipped "
                              f"— no 'nose' bodypart in the shared bodypart set.")
                _ta_mask = detect_turned_away_bins(
                    all_ll[i], bps_ref, fps,
                    float(self._cfg["likelihood_thresh"]), _ta_adaptive_pct,
                    _ta_conf_thresh, _ta_min_window_s, _ta_merge_gap_s)
            else:
                _ta_mask = np.zeros(0, dtype=bool)
            # Align to this session's actual bin count (defensive — should
            # already match since both derive from the same fps/win binning).
            if _ta_mask.shape[0] != _n_bins_i:
                _tmp = np.zeros(_n_bins_i, dtype=bool)
                _n_copy = min(_ta_mask.shape[0], _n_bins_i)
                _tmp[:_n_copy] = _ta_mask[:_n_copy]
                _ta_mask = _tmp
            all_turned_away.append(_ta_mask)
            _n_ta = int(_ta_mask.sum())
            if _n_ta:
                self._log(f"  [TURNED-AWAY] {name}: {_n_ta}/{_n_bins_i} bins "
                          f"({100 * _n_ta / max(1, _n_bins_i):.1f}%) flagged "
                          f"turned-away from camera.")
            all_feats.append(f)
            self._log(f"  {name}: {f.shape[0]} features x {f.shape[1]} bins")
            self._prog(i + 1, len(all_xy))

        if self._cfg["save_plots"]:
            try:
                plot_feature_quality(all_feats, all_names,
                                     self._out_plots / "feature_quality.png")
            except Exception:
                pass

        # Validation gate 2: feature consistency across sessions
        try:
            _validation["feature_consistency"] = validate_feature_consistency(
                all_feats, all_names)
            for w in _validation["feature_consistency"]["warnings"]:
                self._log(f"  [VALID-WARN] {w}")
        except Exception as e:
            self._log(f"  [VALID] Feature consistency check failed: {e}")

        # vis_cat: bin-aligned with feats_cat's columns (same session-concat
        # order) — kept separate from feats_cat (which already has the vis
        # block folded in) purely so compute_cluster_confidence_profile can
        # slice it directly later without needing to know feats_cat's exact
        # column layout.
        _vis_col_names = visibility_feature_names(bps_ref) if _vis_enabled else []
        vis_cat = (np.vstack(all_vis)
                  if (_vis_enabled and all_vis and len(all_vis) == len(all_feats))
                  else None)

        feats_cat = np.hstack(all_feats)   # (n_feat, total_bins) — order-shape-free
        # order_shape_cat: (n_order_shape_cols, total_bins), column-aligned
        # with feats_cat (same per-session hstack order, same per-session
        # bin counts — splitting order-shape off f above never changed a
        # session's bin count). None whenever order-shape is off or every
        # session's block came back empty. Retained ONLY for optional Tier
        # 3b use (see the flow-field call site below) — never touches
        # feats_cat/feats_good/feats_sub/feats_sc, so it cannot shape the
        # primary embedding.
        order_shape_cat = (np.hstack(all_order_shape)
                           if all_order_shape and _n_order_shape_cols > 0 else None)
        # longwindow_cat: (n_lw_cols, total_bins), column-aligned with feats_cat
        # exactly like order_shape_cat above -- split-trigger use only (see
        # compute_longwindow_split_feats()'s own docstring), never joins
        # feats_cat/feats_good/feats_sub/feats_sc, so it cannot shape the
        # primary embedding. None whenever the threshold is off or any
        # session's computation failed (_lw_ok).
        longwindow_cat = (np.hstack(all_longwindow)
                          if (_split_lw_thresh and _lw_ok and all_longwindow
                              and all_longwindow[0].shape[0] == all_longwindow[-1].shape[0])
                          else None)
        if longwindow_cat is not None and longwindow_cat.shape[1] != feats_cat.shape[1]:
            self._log(f"  [WARN] longwindow split-trigger feature matrix bin-count mismatch "
                      f"({longwindow_cat.shape[1]} vs {feats_cat.shape[1]}) — disabling for this run.")
            longwindow_cat = None
        n_bins    = feats_cat.shape[1]
        rng       = np.random.default_rng(int(self._cfg["umap_random_state"]))

        # Build a per-bin boolean mask for bins where a MAJORITY of kept bodyparts
        # are simultaneously flat-held — indicating whole-animal dropout rather than
        # normal single-camera occlusion of individual limbs.  Only those bins are
        # excluded from UMAP/HDBSCAN training; the MLP still infers labels for them
        # at Step 7.  Natural single-camera occlusion (1–4 of 21 bodyparts, ~15–20%
        # fraction) falls well below the 0.5 default threshold and is left in training.
        _win100 = max(1, int(round(fps / 10)))
        _flat_held_bp_frac = float(self._cfg.get("flat_held_bp_frac_thresh", 0.5))
        _n_bps_ref = max(1, len(bps_ref))
        _flat_bin_masks: list = []
        for _k, _per_bp in enumerate(all_flat_held):
            _bps_k = all_bps[_k]
            _nb_k  = all_feats[_k].shape[1]
            if _nb_k == 0:
                _flat_bin_masks.append(np.array([], dtype=bool))
                continue
            _need = _nb_k * _win100
            _flat_count = np.zeros(_nb_k, dtype=float)
            for _bp in bps_ref:
                try:
                    _bp_idx = _bps_k.index(_bp)
                    if _bp_idx < len(_per_bp):
                        _bp_mask = _per_bp[_bp_idx]
                        _bp_arr  = (_bp_mask[:_need] if len(_bp_mask) >= _need
                                    else np.pad(_bp_mask, (0, _need - len(_bp_mask))))
                        _flat_count += _bp_arr.reshape(_nb_k, _win100).any(axis=1).astype(float)
                except ValueError:
                    pass
            _flat_bin_masks.append((_flat_count / _n_bps_ref) >= _flat_held_bp_frac)
        flat_held_bin_mask = (np.concatenate(_flat_bin_masks)
                              if _flat_bin_masks else np.zeros(n_bins, dtype=bool))
        n_flat = int(flat_held_bin_mask.sum())

        # Turned-away-from-camera bins (v3, computed per-session above,
        # always — independent of visibility_features_enabled). Combined with
        # flat_held_bin_mask into a single training-exclusion mask ONLY when
        # exclude_turned_away=True. At False, turned_away_bin_mask is still
        # available below (dedicated label / video overlay) but is NOT folded
        # into the training exclusion mask — exclude_mask then reduces to
        # exactly flat_held_bin_mask, which is the byte-identical, true no-op
        # path back to pre-existing (pre-turned-away-feature) clustering
        # output — the GUI escape hatch.
        turned_away_bin_mask = (np.concatenate(all_turned_away)
                                if all_turned_away else np.zeros(n_bins, dtype=bool))
        if turned_away_bin_mask.shape[0] != n_bins:
            # Defensive re-align — should already match exactly since both are
            # derived from the same per-session bin counts as feats_cat.
            _tmp_ta = np.zeros(n_bins, dtype=bool)
            _n_copy_ta = min(turned_away_bin_mask.shape[0], n_bins)
            _tmp_ta[:_n_copy_ta] = turned_away_bin_mask[:_n_copy_ta]
            turned_away_bin_mask = _tmp_ta
        n_turned_away = int(turned_away_bin_mask.sum())
        _exclude_turned_away = bool(self._cfg.get("exclude_turned_away", True))
        _orig_ta_global = turned_away_bin_mask.copy()        # before any guided rescue (poor-tracking stratum)

        # Guided labelling: a turned-away bin the USER labelled is ground truth, so it is un-flagged here and
        # takes part in clustering like any other bin (same for the final labels: every downstream turned-away
        # use reads all_turned_away). Inert unless a labels file is attached (cfg guided_labels_path) and the
        # kill switch guided_constraints_enabled / guided_rescue_turned_away are on; flat-held (occlusion)
        # exclusion is unchanged. Labels are loaded once here and reused by the context built further below.
        self._guided_preloaded = None
        self._guided_dyn_pack = None
        try:
            if str(self._cfg.get("guided_labels_path", "") or "").strip():
                from cube_guided_constraints import load_global_rows as _g_load
                _g_ranges, _g_off = {}, 0
                for _nm_g, _ft_g in zip(all_names, all_feats):
                    _g_ranges[_nm_g] = (_g_off, _g_off + _ft_g.shape[1])
                    _g_off += _ft_g.shape[1]
                _g_got = _g_load(self._cfg, _g_ranges,
                                 {nm_: float(fp_) for nm_, fp_ in zip(all_names, all_fps_list)}, n_bins, self._log)
                if _g_got is not None:
                    self._guided_preloaded = _g_got
                    try:
                        from cube_guided_report import snapshot_before as _g_snap
                        _g_snap(self.output_dir, self._log)
                    except Exception:
                        pass
                    _g_lab = np.array([v is not None for v in _g_got[0]], dtype=bool)
                    _g_rescue = (turned_away_bin_mask & _g_lab
                                 if (_exclude_turned_away and n_turned_away > 0
                                     and bool(self._cfg.get("guided_rescue_turned_away", True)))
                                 else np.zeros(n_bins, dtype=bool))
                    if _g_rescue.any():
                        _g_off = 0
                        for _i_g, _ft_g in enumerate(all_feats):
                            _nb_g = _ft_g.shape[1]
                            all_turned_away[_i_g] = np.asarray(all_turned_away[_i_g], dtype=bool) & \
                                ~_g_rescue[_g_off:_g_off + _nb_g]
                            _g_off += _nb_g
                        turned_away_bin_mask = turned_away_bin_mask & ~_g_rescue
                        self._log(f"  [GUIDED] {int(_g_rescue.sum())} user-labelled bin(s) inside turned-away "
                                  f"stretches rescued: treated as ground truth and clustered like any other bin "
                                  f"(not excluded, not relabelled 'Turned Away').")
                        n_turned_away = int(turned_away_bin_mask.sum())
        except Exception as _g_e:
            self._log(f"  [GUIDED] WARN: turned-away rescue skipped ({_g_e}).")

        exclude_mask = ((flat_held_bin_mask | turned_away_bin_mask)
                        if _exclude_turned_away else flat_held_bin_mask)
        n_excl = int(exclude_mask.sum())
        n_good = n_bins - n_excl
        if n_excl > 0 and n_good < 10:
            self._log(f"  [WARN] Only {n_good} good bins after flat-held/"
                      f"turned-away exclusion — disabling exclusion for this run.")
            exclude_mask = np.zeros(n_bins, dtype=bool)
            flat_held_bin_mask = np.zeros(n_bins, dtype=bool)
            n_flat, n_excl, n_good = 0, 0, n_bins
        feats_good = feats_cat[:, ~exclude_mask] if n_excl > 0 else feats_cat
        order_shape_good = (order_shape_cat[:, ~exclude_mask] if order_shape_cat is not None and n_excl > 0
                            else order_shape_cat)
        longwindow_good = (longwindow_cat[:, ~exclude_mask] if longwindow_cat is not None and n_excl > 0
                           else longwindow_cat)
        if n_flat > 0:
            self._log(f"  [OCCLUSION] {n_flat}/{n_bins} bins "
                      f"({100 * n_flat / n_bins:.1f}%) with ≥{100*_flat_held_bp_frac:.0f}% "
                      f"bodyparts simultaneously flat-held — excluded from UMAP/"
                      f"HDBSCAN training; MLP infers labels for these at Step 7.")
        if n_turned_away > 0:
            self._log(
                f"  [TURNED-AWAY] {n_turned_away}/{n_bins} bins "
                f"({100 * n_turned_away / n_bins:.1f}%) flagged turned-away from "
                f"camera across all sessions"
                + (" — excluded from UMAP/HDBSCAN training; will receive a "
                   "dedicated 'Turned Away' label."
                   if _exclude_turned_away else
                   " — NOT excluded from training (exclude_turned_away=False); "
                   "HDBSCAN may or may not separate them naturally."))

        # Record which contiguous slice of the full feature matrix belongs to
        # each session so the UMAP evolution video export can slice the saved
        # umap_embedding.npy to get session-specific 3-D coordinates.
        # Format: { "session_name": [start, end, "/path/to/video_or_null"], ... }
        try:
            _sbr: dict = {}
            _off = 0
            for _name, _feat, _vpath in zip(all_names, all_feats, all_vpaths):
                _nb = _feat.shape[1]
                _sbr[_name] = [_off, _off + _nb, _vpath]
                _off += _nb
            _sbr["_total_bins"] = n_bins
            (self._out_model / "session_bin_ranges.json").write_text(
                json.dumps(_sbr, indent=2))
        except Exception:
            pass

        # Region-aware cluster refinement (v1, opt-in -- Region_Aware_
        # Refinement_Implementation_Plan.md Phase 2). compute_bin_region_labels()
        # is a much smaller, EARLIER sibling of compute_session_env_context()
        # (below): it runs here, in the SAME per-session loop that builds
        # session_bin_ranges.json, well before HDBSCAN/refinement, whereas
        # compute_session_env_context() itself is not moved (see the plan's
        # "Pipeline ordering" section). Hard-gated on
        # hdbscan_region_split_enabled -- False (default) means this block
        # does not even call compute_bin_region_labels(), so opted-out users
        # pay zero per-session cost. Reads env_arena_cfg directly (not
        # all_env_cfg, which is forced to None per-session whenever
        # env_features_enabled is False) since region-aware refinement is
        # gated by its OWN flag, independent of env_features_enabled.
        region_per_bin: "list | None" = None
        if bool(self._cfg.get("hdbscan_region_split_enabled", False)):
            try:
                _arena_cfg = self._cfg.get("env_arena_cfg")
                _region_chunks = []
                for _nm, _xy_k, _fps_k, _feat_k in zip(
                        all_names, all_xy, all_fps_list, all_feats):
                    _nb_k = _feat_k.shape[1]
                    _labels_k = compute_bin_region_labels(
                        _arena_cfg, _nm, _xy_k[:, 0::2], _xy_k[:, 1::2],
                        bps_ref, _fps_k) or []
                    if len(_labels_k) < _nb_k:
                        _labels_k = list(_labels_k) + [None] * (_nb_k - len(_labels_k))
                    elif len(_labels_k) > _nb_k:
                        _labels_k = list(_labels_k)[:_nb_k]
                    _region_chunks.append(_labels_k)
                _region_per_bin_flat = [v for chunk in _region_chunks for v in chunk]
                if len(_region_per_bin_flat) != n_bins:
                    # Defensive: length mismatch against the global feature
                    # matrix -- disable rather than risk misaligned indexing
                    # downstream (mirrors the turned_away_bin_mask re-align
                    # pattern above, but here correctness matters more than
                    # salvaging a partial array).
                    self._log("  [WARN] region_per_bin length mismatch "
                               f"({len(_region_per_bin_flat)} vs {n_bins} bins) "
                               "-- disabling region-aware splitting for this run.")
                elif any(v is not None for v in _region_per_bin_flat):
                    region_per_bin = _region_per_bin_flat
                # else: every bin is None (no arena traced / no session had
                # traced shapes) -- region_per_bin stays the None SENTINEL,
                # not a same-length all-None list, so refine_clusters_iterative()'s
                # "region_per_bin is not None" gate stays a true hard no-op
                # (matching its documented contract) instead of running a
                # full, silently-inert split/merge loop with log noise for a
                # user who enabled the flag but hasn't traced anything yet.
            except Exception:
                self._log(f"  [WARN] region_per_bin computation failed:\n"
                          f"  {traceback.format_exc()}")
                region_per_bin = None

        # Audit-trail accumulator (Design decision 5): how many clusters
        # were CREATED by region-aware splitting specifically, across
        # however many refinement iterations/passes run (primary and/or
        # consensus). Threaded into refine_clusters_iterative()/
        # refine_consensus_clusters() as an out-parameter rather than
        # changing either function's return type (both already have
        # existing callers -- seed_sweep_stability(), tests -- that expect
        # a bare ndarray back). Recorded into validation_report.json below.
        _region_split_stats: dict = {}

        # Split-event audit trail (parent id/size -> child id/size, for
        # BOTH the silhouette-based (split_impure_clusters) and region-aware
        # (split_region_impure_clusters) criteria, across whichever
        # refinement path actually runs -- primary refine_clusters_iterative()
        # or consensus's own refine_consensus_clusters()). Each event's
        # children carry a transient "bin_idx" list (dropped after
        # resolution below) so the FINAL cluster id/size each child bin
        # ended up as -- after every later merge/split/prune/remap -- can be
        # looked up once hdb_labels is truly final, instead of trusting a
        # snapshot that later passes silently invalidate. Written to
        # model/split_merge_log.json; empty list if no split ever fires.
        _split_events: list = []

        # v6 part 2 (Environmental_Context_v6_Implementation_Plan.md Step 5):
        # session_env_context.json -- NOT written at all when
        # env_features_enabled is False (not even empty), matching the
        # "Opt-in guarantee" section's requirement that a user who never
        # opens EnvContextWindow sees zero new files in model/. When the flag
        # IS on, per-session entries are still {} for any session lacking
        # traced shapes (env_arena_cfg unset or no reference_shapes) -- the
        # flag-on-but-empty no-op case produces an (almost) empty JSON file,
        # not a crash and not a skipped write.
        # _env_ctx is defined unconditionally (empty dict) so Step 6's bout-
        # enrichment loop further below can safely look it up per session
        # regardless of env_features_enabled -- when the flag is False this
        # stays {} and compute_session_env_context() is never called, per
        # the opt-in guarantee.
        _env_ctx: dict = {}
        if bool(self._cfg.get("env_features_enabled", False)):
            try:
                for _nm, _xy_k, _fps_k, _envcfg in zip(
                        all_names, all_xy, all_fps_list, all_env_cfg):
                    _env_ctx[_nm] = compute_session_env_context(
                        _envcfg, _nm, _xy_k[:, 0::2], _xy_k[:, 1::2], bps_ref,
                        _fps_k,
                        interaction_threshold=self._cfg.get("env_interaction_threshold"))
                (self._out_model / "session_env_context.json").write_text(
                    json.dumps(_env_ctx, indent=2, default=str))
            except Exception:
                self._log(f"  [WARN] session_env_context.json export failed:\n"
                          f"  {traceback.format_exc()}")

        # Use the full dataset when it is small enough (avoids UMAP over-smoothing
        # caused by a large n_neighbors/N_sample ratio); subsample only for large
        # recordings where UMAP runtime becomes a bottleneck.
        umap_full_thresh = int(self._cfg.get("umap_full_thresh", 10_000))
        order_shape_sub = None
        longwindow_sub = None
        if n_good <= umap_full_thresh:
            n_samp    = n_good
            feats_sub = feats_good
            order_shape_sub = order_shape_good
            longwindow_sub = longwindow_good
        else:
            n_samp    = max(1000, int(n_good * float(self._cfg["train_frac"])))
            # Sorted (2026-08-31, was raw rng.choice() order): UMAP/HDBSCAN
            # treat rows as an unordered point set, so sorting costs nothing
            # there, but it's required for the session-boundary
            # reconstruction below (and therefore every kinetic-coherence/
            # flow-field mechanism, which assumes adjacent array rows are
            # adjacent in TIME) to work at all once train_frac subsampling
            # fires. Root-caused via a real run
            # (D:\CUBE_Pipeline\Time_CUBE\out_consensus): EVERY cluster's
            # kinetic_coherence_score came back exactly 0.0 (bout_count=0 for
            # all 18) because the unsorted rng.choice() order made "lag-1
            # transitions"/"velocity" get computed between temporally-
            # unrelated random bin pairs -- self_transition_vs_chance tracked
            # cluster POPULATION SIZE (the two largest clusters scored
            # highest), exactly what a random shuffle produces, not genuine
            # temporal persistence. Raising train_frac alone does NOT fix
            # this: rng.choice(..., replace=False) still returns a shuffled
            # (not identity) order even at train_frac=1.0 whenever this
            # `else` branch is taken at all (n_good > umap_full_thresh) --
            # confirmed against a prior real attempt to fix this purely by
            # raising train_frac, which measurably did not help.
            #
            # subsample_strategy (BLOCK_BOOTSTRAP_SUBSAMPLING_PLAN.md,
            # opt-in, default "iid" = today's exact behavior unchanged):
            # "block" draws contiguous session-bounded chunks instead of
            # individual i.i.d. bins, so a short real bout's sampled bins
            # land next to each other in feature space instead of scattered
            # — fixes short/rare-behavior loss under i.i.d. subsampling.
            # Must be explicitly requested (cfg/GUI); never auto-selected.
            _subsample_strategy = str(self._cfg.get("subsample_strategy", "iid")).lower()
            if _subsample_strategy == "block":
                _good_session_ranges = _remap_session_ranges(_sbr, ~exclude_mask)
                _block_len = int(self._cfg.get("subsample_block_len_bins", 17))
                idx = _block_bootstrap_idx(n_good, n_samp, rng, _good_session_ranges, _block_len)
                if idx.size != n_samp:
                    self._log(f"  [subsample_strategy=block] block accumulation "
                              f"landed on {idx.size} bins (requested {n_samp}) — "
                              f"whole blocks are never truncated, see "
                              f"BLOCK_BOOTSTRAP_SUBSAMPLING_PLAN.md.")
                n_samp = int(idx.size)
            else:
                idx = _iid_subsample_idx(n_good, n_samp, rng)
            # Guided labelling: a user-labelled bin is ground truth and must never be lost to train_frac
            # subsampling -- add every labelled good bin to the sample (a few hundred rows at most).
            _gp = getattr(self, "_guided_preloaded", None)
            if _gp is not None:
                try:
                    from cube_guided_constraints import labelled_good_positions as _g_pos
                    _lab_pos = _g_pos(_gp[0], exclude_mask)
                    _n_missing = int(np.setdiff1d(_lab_pos, idx).size)
                    if _n_missing:
                        idx = np.union1d(idx, _lab_pos)
                        n_samp = int(idx.size)
                        self._log(f"  [GUIDED] {_n_missing} user-labelled bin(s) added to the training "
                                  f"subsample (never lost to train_frac).")
                except Exception as _g_e2:
                    self._log(f"  [GUIDED] WARN: could not force labelled bins into the sample ({_g_e2}).")
            feats_sub = feats_good[:, idx]
            if order_shape_good is not None:
                order_shape_sub = order_shape_good[:, idx]
            if longwindow_good is not None:
                longwindow_sub = longwindow_good[:, idx]

        self._log(f"  Total bins: {n_bins}  -> UMAP sample: {n_samp} "
                  f"({100 * n_samp / n_bins:.0f} %)")

        # Phase 3 (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md): per-session bin
        # boundaries in the SAME index space as the labels that get pruned
        # (n_samp-length, i.e. feats_sub's column order), for
        # rare_cluster_survival_criteria="occurrence_persistence"'s
        # session-boundary-aware bout counting AND (2026-08-31) every
        # kinetic-coherence/flow-field mechanism below, both of which assume
        # adjacent array rows are adjacent in time.
        #
        # Generalized 2026-08-31 to also work when train_frac subsampling
        # fired (previously abandoned entirely in that case -- see the git
        # history/CLAUDE.md for the real-data bug this caused). Now that
        # `idx` above is sorted rather than raw rng.choice() order,
        # feats_sub/hdb_labels rows stay in true relative temporal order --
        # sparser (gaps where a bin wasn't sampled), never reordered. `_keep`
        # composes BOTH exclusion steps (flat-held/turned-away bins removed
        # by exclude_mask, then a further train_frac subset via `idx`) into
        # one boolean mask over the ORIGINAL n_bins positions, so the same
        # cumsum-based per-session range remap handles the exclude-only and
        # exclude+subsample cases uniformly. Sessions stay contiguous ranges
        # in the final (kept) index space precisely because both exclusion
        # steps are order-preserving.
        #
        # Caveat (real, not fully eliminated): a "lag-1" pair in the
        # subsampled sequence can span a genuine time gap (an intervening
        # bin that wasn't sampled) -- this is an APPROXIMATION of true
        # frame-adjacency, not exact, and will somewhat undercount real bout
        # persistence at aggressive train_frac values. It is a categorical
        # improvement over the prior fully-random-shuffle behavior (which
        # was not an approximation of temporal structure at all, just noise)
        # but not a full restoration of frame-exact temporal fidelity.
        #
        # None (reconstruction failure only, now) means "treat as one
        # session" in every downstream consumer -- callers that need to
        # distinguish "genuinely unknown ordering" from "single real
        # session" should additionally check _bins_temporally_ordered below.
        _session_boundaries = None
        # SPLIT_ELIGIBILITY_IMPROVEMENT_PLAN.md technique 5: for each
        # training row (feats_sub/hdb_labels order), its ORIGINAL pooled-bin
        # index -- lets _pre_refine_posture_entropy_scores() (below,
        # pre-refinement) recover real per-session frame ranges for a
        # training-row bout without depending on any other run()-local
        # variable (idx/_good_idx_full get reused/shadowed many times later
        # in this large function). Captured here, once, under a name unique
        # to this purpose. Only trustworthy when _bins_temporally_ordered
        # (below) is True -- callers must check that, same as every other
        # session_boundaries-consuming mechanism in this function.
        _train_orig_bin_idx = None
        try:
            _good_idx_full = np.flatnonzero(~exclude_mask) if n_excl > 0 else np.arange(n_bins)
            _train_orig_bin_idx = (_good_idx_full[idx] if n_samp != n_good
                                    else _good_idx_full)
            _keep = np.zeros(n_bins, dtype=bool)
            _keep[_train_orig_bin_idx] = True
            # Shared with the block-bootstrap chunk construction above
            # (BLOCK_BOOTSTRAP_SUBSAMPLING_PLAN.md Phase 2) rather than a
            # second copy of the same cumsum-remap arithmetic.
            _ranges = _remap_session_ranges(_sbr, _keep)
            if _ranges:
                _session_boundaries = sorted(_ranges)
        except Exception:
            _session_boundaries = None
            _train_orig_bin_idx = None

        # Guided labelling (GUIDED_LABELLING_PLAN.md, P4): constraints from the user's labels. Inert unless
        # cfg["guided_labels_path"] names a usable labels file AND cfg["guided_constraints_enabled"] is True
        # (kill switch). A missing / corrupt / inconsistent file logs a WARN and the run stays blind.
        self._guided_ctx = None
        try:
            from cube_guided_constraints import build_context as _g_build, set_active as _g_set, clear as _g_clear
            _g_clear()
            _g_ctx = _g_build(
                self._cfg, {k: (int(v[0]), int(v[1])) for k, v in _sbr.items() if k != "_total_bins"},
                {nm: float(fp_) for nm, fp_ in zip(all_names, all_fps_list)}, n_bins,
                _train_orig_bin_idx, n_samp, log=self._log,
                preloaded=getattr(self, "_guided_preloaded", None))
            if _g_ctx is not None:
                _g_set(_g_ctx)
                self._guided_ctx = _g_ctx
        except Exception as _g_e:
            self._log(f"  [GUIDED] WARN: constraint setup failed ({_g_e}) -- running blind.")
            self._guided_ctx = None

        # Whether adjacent rows of feats_sub/hdb_labels are genuinely
        # (at least approximately, per the caveat above) adjacent in time --
        # False only when _session_boundaries reconstruction itself failed
        # (an exception above), since that's the only remaining case where
        # ordering can't be youched for. Every kinetic-coherence/flow-field
        # call site below is gated on this so a reconstruction failure
        # degrades to an explicit skip+WARN instead of silently computing a
        # misleading population-artifact score the way the pre-fix code did.
        _bins_temporally_ordered = _session_boundaries is not None or len(_sbr) <= 1
        if not _bins_temporally_ordered and any(
                bool(self._cfg.get(k, False)) for k in (
                    "kinetic_coherence_enabled", "kinetic_flow_field_enabled")):
            self._log(
                "  [WARN] kinetic-coherence/flow-field mechanisms are DISABLED "
                "for this run: session-boundary reconstruction failed, so "
                "temporal adjacency can't be verified for the training "
                "sample. See the exception logged just above, if any.")

        # Tiny per-sample jitter before standardisation breaks any remaining
        # exact-duplicate feature vectors among the good (non-flat-held) bins.
        _feat_jitter = float(self._cfg.get("feature_dedup_jitter", 1e-4))
        if _feat_jitter > 0:
            feats_sub = feats_sub + rng.normal(0, _feat_jitter, feats_sub.shape)

        from sklearn.preprocessing import StandardScaler
        scaler   = StandardScaler()
        feats_sc = scaler.fit_transform(feats_sub.T).T   # (n_feat, n_samp) — primary only
        feats_sc = _scale_visibility_block(feats_sc, _n_vis_cols, _vis_weight,
                                            features_on_axis0=True)
        feats_sc = _scale_visibility_block(feats_sc, _n_isolated_limb_cols, _isolated_limb_weight,
                                            features_on_axis0=True, tail_offset=_n_vis_cols)
        feats_sc = _scale_visibility_block(feats_sc, _n_prox_cols, _prox_weight,
                                            features_on_axis0=True,
                                            tail_offset=_n_vis_cols + _n_isolated_limb_cols)
        # order_shape_rows_sc: order-shape block scaled with its OWN
        # StandardScaler (equivalent to scaling it jointly with feats_sub —
        # StandardScaler standardises each column/feature independently, so
        # fitting separately changes nothing numerically), retained purely
        # for optional Tier 3b (kinetic flow field) use below. Never joins
        # feats_sc/feats_sub, so it cannot reach PCA, UMAP, HDBSCAN, or MLP
        # training — satisfies handoff-report decision #1 ("order should be
        # a tie-breaker only... must not shape the primary embedding").
        order_shape_rows_sc = (StandardScaler().fit_transform(order_shape_sub.T).T
                               if order_shape_sub is not None else None)
        # longwindow_rows_sc: the long-window split-trigger block, scaled
        # with its own StandardScaler (same reasoning as order_shape_rows_sc
        # above -- per-column standardisation, so fitting separately changes
        # nothing numerically). Never joins feats_sc/feats_sub. Passed to
        # BSoidEngine.run()'s primary refine_clusters_iterative() call only
        # (see hdbscan_split_longwindow_silhouette_thresh in DEFAULTS).
        longwindow_rows_sc = (StandardScaler().fit_transform(longwindow_sub.T).T
                              if longwindow_sub is not None else None)
        # Keep the pre-PCA standardised features so UMAP trustworthiness is
        # measured against the actual feature space, not the PCA-reduced one.
        feats_sc_prepca = feats_sc

        # ── Debug capture checkpoint (opt-in, Sep 2026) ─────────────────────
        # Saves exactly the state an exploration script needs to re-run PCA/
        # UMAP/HDBSCAN/consensus_cluster() ad-hoc against THIS real dataset+
        # cfg's actual training-stage feature matrix -- without re-paying
        # feature extraction on every call. True no-op (not even the numpy
        # copy/pickle cost) unless cfg["_debug_capture_path"] is explicitly
        # set; every normal run is unaffected. global_bin_idx (training row i
        # -> its bin index in session_bin_ranges.json's own pooled space) is
        # the piece that's easy to get wrong by hand -- it's exactly `_keep`
        # from the temporal-ordering reconstruction just above, so a caller
        # can map any real manual-label timestamp straight to a training row
        # (or discover it was never trained at all) without re-deriving the
        # exclude_mask/idx bookkeeping itself.
        _debug_capture_path = self._cfg.get("_debug_capture_path")
        if _debug_capture_path:
            try:
                with open(_debug_capture_path, "wb") as _f:
                    pickle.dump(dict(
                        feats_sc_prepca=feats_sc_prepca, feats_sub=feats_sub,
                        # every bin's raw features (turned-away / flat-held included) + the training scaler, so an
                        # offline tool can score or train on bins the clustering excluded (guided labelling)
                        feats_all=np.asarray(feats_cat), exclude_mask=np.asarray(exclude_mask),
                        train_scaler=scaler,
                        global_bin_idx=np.flatnonzero(_keep),
                        session_bin_ranges=dict(_sbr), n_bins=n_bins,
                        n_good=n_good, n_samp=n_samp,
                        session_boundaries=_session_boundaries,
                        bins_temporally_ordered=_bins_temporally_ordered,
                        cfg=dict(self._cfg),
                        # order_shape_rows_sc (Experiment 2 "Order In", 2026-09-04):
                        # the same order-shape block computed above, standardised
                        # and column-aligned to feats_sub/feats_sc_prepca's own
                        # n_samp ordering -- otherwise discarded after this point
                        # (only used transiently for Tier 3b flow-field, when that
                        # runs). Saved here purely so an exploration script can
                        # test "order-shape included in the primary matrix" ad-hoc
                        # without re-deriving extraction. None when order-shape is
                        # disabled or unavailable -- callers must check for that.
                        order_shape_rows_sc=order_shape_rows_sc,
                    ), _f)
                self._log(f"  [DEBUG-CAPTURE] saved training-stage state -> {_debug_capture_path}")
                if bool(self._cfg.get("_debug_capture_abort", False)):
                    raise _DebugCaptureAbort(
                        f"debug capture saved to {_debug_capture_path}; aborting "
                        f"the rest of this run by request (_debug_capture_abort=True)")
            except _DebugCaptureAbort:
                raise
            except Exception:
                self._log(f"  [WARN] _debug_capture_path save failed:\n{traceback.format_exc()}")

        # Optional PCA pre-reduction.  Auto-triggers when n_features >= n_samples/5
        # to keep the nearest-neighbour graph reliable for UMAP.
        pca_model = None
        pca_mode  = str(self._cfg.get("pca_pre_reduce", "auto")).lower()
        n_feat_orig, n_samp_umap = feats_sc.shape
        ratio = n_samp_umap / max(1, n_feat_orig)
        _do_pca = (pca_mode == "on") or (pca_mode == "auto" and ratio < 5.0)
        if _do_pca:
            from sklearn.decomposition import PCA
            _pca_n_mode = str(self._cfg.get("pca_n_components_mode", "heuristic")).lower()
            if _pca_n_mode == "mle":
                # Minka's MLE (2000): estimates the number of components via
                # probabilistic-PCA model selection on this dataset's own
                # eigenvalue spectrum, instead of guessing from sample count
                # alone -- only supported by svd_solver="full", and the
                # resulting count (n_components_) isn't known until after fit.
                pca_model = PCA(n_components="mle", svd_solver="full",
                                random_state=int(self._cfg["umap_random_state"]))
                feats_sc  = pca_model.fit_transform(feats_sc.T).T
                n_pca     = pca_model.n_components_
            else:
                n_pca = min(n_feat_orig - 1,
                            max(50, int(n_samp_umap ** 0.75)))
                pca_model = PCA(n_components=n_pca,
                                random_state=int(self._cfg["umap_random_state"]))
                feats_sc  = pca_model.fit_transform(feats_sc.T).T
            var_kept  = pca_model.explained_variance_ratio_.sum() * 100
            self._log(f"  PCA pre-reduction ({_pca_n_mode}): {n_feat_orig} → {n_pca} dims "
                      f"({var_kept:.1f} % variance, sample/feature ratio "
                      f"was {ratio:.1f})")
            self._stage("3/7 — PCA done",
                        f"{n_feat_orig}→{n_pca} dims · {var_kept:.1f}% variance")
            if ratio < 2.0:
                self._log("  [VALID-WARN] sample/feature ratio < 2 even after "
                          "PCA — recording may be too short for reliable analysis")
                self._stage("VALIDATION WARN",
                            "sample/feature ratio < 2 — recording may be too short")

        # 4. UMAP
        # Adaptive n_neighbors: publication default 60 is calibrated to ~1200-bin
        # (2-min) sessions. n_bins is fps-independent (both 30fps and 60fps 2-min
        # videos give ~1200 bins because win100 = fps/10).
        # Formula: clip(avg_session_bins / 20, 30, 90)
        #   ~600 bins/sess  (1 min) → 30   floor -- see floor rationale below
        #   ~1200 bins/sess (2 min) → 60   matches publication default
        #   ~1800 bins/sess (3 min) → 90   smoother manifold for longer recordings
        #   >1800 bins/sess         → 90   capped; higher values give diminishing returns
        # Using per-session average rather than total bins means the value stays
        # calibrated to recording length regardless of how many sessions are pooled.
        # User can override by setting umap_n_neighbors > 0 in cfg.
        #
        # Floor raised 15 -> 30 (Aug 2026): a short-session real dataset (avg
        # ~333 training bins/session, well under the 600-bin reference point)
        # auto-set to 16 under the old floor and showed severe UMAP embedding
        # seed-instability -- a 6-seed sweep gave cluster counts ranging 1-25
        # (mean pairwise ARI 0.31, one seed collapsing to a single cluster).
        # Small neighborhoods make UMAP's stochastic optimization far more
        # sensitive to its random seed's local minimum; this is a general
        # property of UMAP, not specific to that dataset. Forcing the SAME
        # feature matrix through n_neighbors=30 instead of the auto 16 raised
        # mean pairwise ARI to 0.57 (n_neighbors=40 was worse, 0.43 -- 30 is
        # not just "higher is better", it was the tested sweet spot for that
        # dataset). Only validated against one dataset so far; if a future
        # short-session dataset still shows low seed_sweep_stability ARI even
        # at this floor, prefer raising umap_n_neighbors explicitly over
        # raising this floor again without new evidence.
        _nn_cfg = int(self._cfg.get("umap_n_neighbors", 0))
        if _nn_cfg <= 0:
            _n_sessions  = max(1, len(all_feats))
            _avg_bins    = n_samp // _n_sessions   # use training sample, not total bins
            _nn_adaptive = max(30, min(90, _avg_bins // 20))
            self._cfg["umap_n_neighbors"] = _nn_adaptive
            self._log(f"  [UMAP] n_neighbors auto-set to {_nn_adaptive} "
                      f"(avg_training_bins={_avg_bins}, {_n_sessions} session(s), "
                      f"formula=clip(avg_bins/20, 30, 90); "
                      f"set umap_n_neighbors>0 to override)")
        self._mem_checkpoint("3/7 feature extraction done")
        self._log("\n[4/7]  Running UMAP  "
                  f"(n_components={self._cfg['umap_n_components']}, "
                  f"n_neighbors={self._cfg['umap_n_neighbors']})...")
        self._stage("4/7 — UMAP embedding",
                    f"n_components={self._cfg['umap_n_components']} · "
                    f"n_neighbors={self._cfg['umap_n_neighbors']} · "
                    f"N={n_samp} pts — may take several minutes…")
        umap_model, embedding = run_umap(feats_sc.T, self._cfg)
        self._log(f"  Embedding: {embedding.shape}")
        self._stage("4/7 — UMAP done", f"embedding shape {embedding.shape}")
        self._mem_checkpoint("4/7 UMAP embedding done")

        # Build the full-size embedding (n_bins rows) for umap_embedding.npy so
        # that session_bin_ranges.json slice indices remain valid.  Bins that
        # were not part of the UMAP training sample — flat-held bins, and any
        # good bins left out by train_frac subsampling — are projected via
        # umap_model.transform() for visualisation.  Bins that WERE part of
        # the training sample reuse the exact fit `embedding` at their
        # original positions rather than being re-projected: UMAP's
        # out-of-sample transform() is measurably less tight than the fit it
        # approximates, and previously this branch re-transformed every good
        # bin (including the trained ones) whenever subsampling and flat-held
        # exclusion were both active, silently degrading the saved embedding
        # used by cube_analyser's UMAP/Energy-Landscape views.
        try:
            embedding_save = np.empty((n_bins, embedding.shape[1]), dtype=float)
            _good_positions = (np.where(~exclude_mask)[0] if n_excl > 0
                                else np.arange(n_bins))
            if n_samp == n_good:
                embedding_save[_good_positions] = embedding
            else:
                embedding_save[_good_positions[idx]] = embedding
                _held_out = np.ones(n_good, dtype=bool)
                _held_out[idx] = False
                if _held_out.any():
                    _feats_ho_sc = scaler.transform(feats_good[:, _held_out].T)
                    if pca_model is not None:
                        _feats_ho_sc = pca_model.transform(_feats_ho_sc)
                    embedding_save[_good_positions[_held_out]] = \
                        umap_model.transform(_feats_ho_sc)
            if n_excl > 0:
                _feats_excl_sc = scaler.transform(feats_cat[:, exclude_mask].T)
                if pca_model is not None:
                    _feats_excl_sc = pca_model.transform(_feats_excl_sc)
                embedding_save[exclude_mask] = umap_model.transform(_feats_excl_sc)
        except Exception:
            self._log(f"  [WARN] Could not build full embedding for save: "
                      f"{traceback.format_exc()}")
            embedding_save = embedding

        # Validation gate 3: UMAP trustworthiness
        try:
            _validation["umap_trustworthiness"] = validate_umap_trustworthiness(
                feats_sc_prepca.T, embedding)
            for w in _validation["umap_trustworthiness"]["warnings"]:
                self._log(f"  [VALID-WARN] {w}")
        except Exception as e:
            self._log(f"  [VALID] Trustworthiness check failed: {e}")

        # 5. HDBSCAN
        self._log("\n[5/7]  HDBSCAN clustering  "
                  "(adaptive sweep, DBCV criterion)...")
        self._stage("5/7 — HDBSCAN clustering",
                    f"sweeping min_cluster_size over {n_samp} bins…")
        # region_split_pre_reduction_pct (Region_Aware_Refinement_
        # Implementation_Plan.md Design decision 4): a one-shot, clearly-
        # logged convenience, NOT a closed-loop cluster-count-targeting
        # mechanism -- only multiplies preferred_clusters_lo/hi for THIS
        # primary sweep call, using a temporary cfg copy so self._cfg (and
        # every other reader of preferred_clusters_lo/hi -- local
        # re-clustering in split_impure_clusters()/split_region_impure_
        # clusters(), which already ignore the global range entirely, GUI
        # labels, etc.) is completely unaffected. 0.0 (default) or
        # hdbscan_region_split_enabled=False is a true no-op: _sweep_cfg
        # stays identical to self._cfg (same object, not even a copy).
        _orig_pref_lo = int(self._cfg.get("preferred_clusters_lo", 12) or 12)
        _orig_pref_hi = int(self._cfg.get("preferred_clusters_hi", 20) or 20)
        _pre_reduction_pct = float(self._cfg.get("region_split_pre_reduction_pct", 0.0) or 0.0)
        _region_split_master = bool(self._cfg.get("hdbscan_region_split_enabled", False))
        _sweep_cfg = self._cfg
        if _region_split_master and _pre_reduction_pct > 0:
            _reduced_lo = max(2, round(_orig_pref_lo * _pre_reduction_pct))
            _reduced_hi = max(2, round(_orig_pref_hi * _pre_reduction_pct))
            _sweep_cfg = dict(self._cfg)
            _sweep_cfg["preferred_clusters_lo"] = _reduced_lo
            _sweep_cfg["preferred_clusters_hi"] = _reduced_hi
            self._log(
                f"  [region-split] pre-reduction: preferred_clusters "
                f"{_orig_pref_lo}-{_orig_pref_hi} -> {_reduced_lo}-{_reduced_hi} "
                f"({_pre_reduction_pct:.0%}) for this sweep only -- region-"
                f"aware splitting is expected to bring the final count back "
                f"up; see the before/after log line after refinement.")
        hdb_clf, hdb_labels, hdb_score, hdb_score_label = run_hdbscan(
            embedding, _sweep_cfg, n_total=n_samp, log_fn=self._log,
            feats_sc_T=feats_sc.T, fps=fps, win100=_win100,
            session_boundaries=_session_boundaries)
        # §0a row 4f / Experiment 18 ("Free Seed Zero", HEAD_DIP_FEATURE_
        # EMBEDDING_INVESTIGATION_2026-09-03.md): seed_sweep_stability()'s
        # and consensus_cluster()'s own seed lists always start at
        # cfg["umap_random_state"] -- the SAME random state this primary fit
        # was just computed with, on the same feats_sc.T -- so that one seed
        # is, by construction, a full duplicate of the fit above. Captured
        # here as RAW (pre-floor) labels specifically because consensus_
        # cluster()'s per-seed dispatch never applies the confidence floor
        # to any seed (see _consensus_one_seed's docstring) -- feeding it an
        # already-floored array would silently diverge from a genuine per-
        # seed fit whenever the floor is >0. seed_sweep_stability()'s own
        # reuse path re-applies the floor itself regardless (idempotent, so
        # raw-vs-floored input makes no difference there), so one dict
        # safely serves both consumers. Verified byte-identical to a real
        # re-fit, Experiment 18 (embedding max abs diff=0, exact label
        # array equality, ARI=1.000000).
        _primary_fit_for_reuse = dict(
            umap_model=umap_model, embedding=embedding, clf=hdb_clf,
            labels=hdb_labels.copy(), dbcv=hdb_score,
            seed=int(self._cfg.get("umap_random_state", 42)))
        # Tracks whichever fit is CURRENTLY valid for reuse as this run()
        # call progresses -- reassigned to the embedding-retry's own fit if
        # that retry is accepted (superseding this one). KINETIC_REWEIGHT_
        # POST_DECISION_PLAN.md (2026-09-06): Phase 6/7's kinetic reweight
        # now runs strictly AFTER the medoid/consensus decision (every
        # seed_sweep_stability()/consensus_cluster() call that could offer
        # this variable as `primary_fit` has already run by then), so there
        # is no longer a later reuse site left for a reweighted partition to
        # silently corrupt -- the old "cleared to None once Phase 7 fires"
        # step (and the _tier3b_reweight_applied guard that gated it) was
        # removed as dead code. Every seed_sweep_stability()/
        # consensus_cluster() call in this function should offer THIS
        # variable, not _primary_fit_for_reuse directly.
        _current_fit_for_reuse = _primary_fit_for_reuse
        # Phase 4b (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md): applied here,
        # right after the primary run_hdbscan() fit and BEFORE any split/
        # merge refinement (which can create new cluster ids hdb_clf knows
        # nothing about) -- floor<=0 (default) is a true no-op.
        hdb_labels = _apply_membership_confidence_floor(
            hdb_clf, hdb_labels,
            float(self._cfg.get("hdbscan_membership_confidence_floor", 0.0) or 0.0),
            log_fn=self._log)
        # Original HDBSCAN output labels, kept so approximate_predict's
        # fallback inference path (which re-queries hdb_clf directly and gets
        # back ORIGINAL ids) can still be mapped to the final id space after
        # split/merge refinement + rare-cluster pruning (see _hdb_remap below).
        _orig_hdb_labels = hdb_labels.copy()
        n_cl      = len(set(hdb_labels[hdb_labels >= 0]))
        noise     = (hdb_labels < 0).sum()
        noise_pct = 100 * noise / max(1, len(hdb_labels))
        _raw_primary_n_cl = n_cl
        self._log(f"  {n_cl} clusters, {noise} noise points "
                  f"({noise_pct:.1f} %), "
                  f"{hdb_score_label}={hdb_score:.3f}")
        self._stage("5/7 — HDBSCAN done",
                    f"{n_cl} clusters · {noise_pct:.0f}% noise · {hdb_score_label}={hdb_score:.3f}")

        # _phase2_os_weight: resolved here purely to keep passing a value
        # into seed_sweep_stability()'s/consensus_cluster()'s
        # order_shape_weight= parameter below -- that parameter (along with
        # order_shape_rows_sc/n_order_shape_cols/bins_temporally_ordered/
        # feats_prepca) has been an accepted-but-unused, true no-op in both
        # functions since Option C's retirement (2026-09-06,
        # KINETIC_REWEIGHT_POST_DECISION_PLAN.md) -- the value computed here
        # has zero effect on this run()'s output. Left in place (kept for
        # signature compatibility, smaller diff than stripping the params)
        # rather than removed.
        _phase2_os_weight = 1.0
        if (bool(self._cfg.get("order_shape_features_enabled", False))
                and order_shape_rows_sc is not None and _n_order_shape_cols > 0):
            if bool(self._cfg.get("kinetic_flow_field_exclude_order_shape_terms", False)):
                _phase2_os_weight = 0.0
            else:
                _phase2_os_weight = float(self._cfg.get(
                    "kinetic_flow_field_order_shape_weight", 0.1) or 0.0)

        # ── Cluster-stability seed sweep ────────────────────────────────────────
        # Moved here (Aug 2026, was after refinement/pruning below) so its
        # mean_ari can inform the consensus-clustering auto-trigger just
        # below, instead of only being logged as an after-the-fact warning
        # once the primary partition was already exported. Re-run UMAP+
        # HDBSCAN over several seeds to measure how reproducible the
        # PARTITION is (the internal quality gates only measure cluster
        # tightness, not reproducibility).
        # _consensus_forced: consensus is being run unconditionally (not via
        # the auto-trigger below, which itself needs _sweep to decide) --
        # in that case the standalone sweep's only purpose (deciding WHETHER
        # to trigger consensus) is already moot, so skip it and let
        # consensus_cluster() report its own per-seed stability stats for
        # free instead (see the block right after the consensus call below).
        _consensus_forced = bool(self._cfg.get("consensus_clustering_enabled", False))
        _n_sweep = int(self._cfg.get("seed_sweep_n", 0) or 0)
        _sweep = None
        if _n_sweep >= 2 and not _consensus_forced:
            try:
                self._log(f"\n[STABILITY]  Seed sweep ({_n_sweep} seeds) — "
                          f"assessing cluster-count / partition stability...")
                self._stage("Cluster-stability seed sweep",
                            f"{_n_sweep} seeds — re-running UMAP+HDBSCAN")
                _sweep = seed_sweep_stability(
                    feats_sc.T, self._cfg, _n_sweep, log_fn=self._log,
                    session_boundaries=_session_boundaries,
                    order_shape_rows_sc=order_shape_rows_sc,
                    n_order_shape_cols=_n_order_shape_cols,
                    order_shape_weight=_phase2_os_weight,
                    bins_temporally_ordered=_bins_temporally_ordered,
                    feats_prepca=feats_sc_prepca,
                    fps=fps, win100=_win100,
                    primary_fit=_current_fit_for_reuse,
                    retain_fits_for_reuse=bool(self._cfg.get(
                        "consensus_reuse_seed_sweep_fits", False)))
                if _sweep:
                    _sc = _sweep.get('stable_counts', _sweep['counts'])
                    self._log(f"  Mean pairwise ARI = {_sweep['mean_ari']:.3f} "
                              f"(cluster counts {min(_sc)}–{max(_sc)} across "
                              f"seeds used in the mean; full sweep range "
                              f"{min(_sweep['counts'])}–{max(_sweep['counts'])})")
                    _dbcv = [d for d in _sweep.get('dbcv', []) if d == d]  # drop NaN
                    if _dbcv:
                        self._log(f"  Per-seed DBCV: "
                                  f"{', '.join(f'{d:.3f}' for d in _dbcv)} "
                                  f"(mean {np.mean(_dbcv):.3f}, "
                                  f"range {min(_dbcv):.3f}–{max(_dbcv):.3f})")
            except Exception:
                self._log(f"  [WARN] seed sweep: {traceback.format_exc()}")
        elif _consensus_forced:
            self._log("\n[STABILITY]  Seed sweep skipped: "
                      "consensus_clustering_enabled=True already forces "
                      "consensus clustering on, so the standalone sweep's "
                      "only purpose (deciding whether to trigger it) is "
                      "moot -- stability stats will be reported from "
                      "consensus clustering's own per-seed partitions instead.")

        # ── Phase 5 (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md): adaptive
        # embedding-stability retry ──────────────────────────────────────
        # Gated by embedding_stability_retry_enabled (default False, true
        # no-op). Runs here -- right after the standalone diagnostic sweep
        # computes _sweep/mean_ari, BEFORE the medoid/consensus
        # _auto_triggered decision below -- so that decision (and everything
        # downstream) sees the post-retry _sweep/hdb_labels/embedding when a
        # retry is accepted. Exactly one retry, ever, per run() call --
        # structurally guaranteed by this being a single straight-line block
        # (never looped), not by a separate guard flag.
        if bool(self._cfg.get("embedding_stability_retry_enabled", False)) and _sweep:
            _retry_threshold = float(
                self._cfg.get("embedding_stability_retry_threshold", 0.55) or 0)
            _old_mean_ari = _sweep.get("mean_ari", 1.0)
            if _retry_threshold > 0 and _old_mean_ari < _retry_threshold:
                try:
                    # 5.1 cap formula -- scales with dataset size, not a
                    # borrowed constant (no B-SOiD-anchored absolute ceiling;
                    # see the plan's Background for why n_neighbors=60 was
                    # considered and rejected as a ceiling).
                    _cur_nn = int(self._cfg.get("umap_n_neighbors", 30) or 30)
                    _boosted_nn, _nn_cap, _frac_cap, _bout_cap = \
                        _embedding_retry_boosted_n_neighbors(
                            _cur_nn, n_samp, self._cfg, fps=fps, win100=_win100)

                    self._log(f"  [EMBED-RETRY] mean ARI {_old_mean_ari:.3f} < "
                              f"{_retry_threshold} -- retrying once with "
                              f"umap_n_neighbors {_cur_nn} -> {_boosted_nn} "
                              f"(cap {_nn_cap} = min(frac_cap={_frac_cap}, "
                              f"bout_cap={_bout_cap}))")

                    # Quality probes computed regardless of
                    # rare_cluster_survival_criteria's actual setting -- this
                    # is a quality PROBE, not a pruning decision (Phase 3's
                    # occurrence_persistence criteria is reused here purely
                    # as an over-smoothing detector).
                    _probe_cfg = dict(self._cfg)
                    _probe_cfg["rare_cluster_survival_criteria"] = "occurrence_persistence"
                    _, _, _pre_prune_info = _prune_rare_clusters(
                        hdb_labels, feats_sc.T, _probe_cfg, n_samp, fps=fps,
                        win100=_win100, session_boundaries=_session_boundaries)
                    _pre_survivor_count = _pre_prune_info["n_cl"]
                    _pre_dbcv = _dbcv_feature_space(feats_sc.T, hdb_labels)

                    # Phase 5, TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md:
                    # Tier 2 -- optional fourth gate condition (kinetic-
                    # coherence non-regression), gated by
                    # embedding_stability_retry_kinetic_gate_enabled
                    # (default False -> _cond_iv stays True, a true no-op).
                    # Computed here (pre-retry) so it's available alongside
                    # the other pre-retry probes below.
                    _kinetic_gate_on = (bool(self._cfg.get(
                        "embedding_stability_retry_kinetic_gate_enabled", False))
                        and _bins_temporally_ordered)
                    _pre_coherence = (
                        _kinetic_coherence_score(
                            hdb_labels, feats_sc.T, fps, _win100,
                            session_boundaries=_session_boundaries
                        )["whole_partition"]["mean_coherence_score"]
                        if _kinetic_gate_on else None)

                    _retry_cfg = dict(self._cfg)
                    _retry_cfg["umap_n_neighbors"] = _boosted_nn
                    with _numba_single_thread():
                        _new_embedding_model, _new_embedding = run_umap(feats_sc.T, _retry_cfg)
                        _new_clf, _new_labels, _new_score, _new_score_label = run_hdbscan(
                            _new_embedding, _retry_cfg, n_total=n_samp, log_fn=None)
                    # §0a row 4f / Experiment 18: this re-fit is itself the
                    # exact seed=base_seed (umap_random_state unchanged by
                    # the retry, only umap_n_neighbors was) that _new_sweep's
                    # own per-seed dispatch would otherwise recompute --
                    # captured RAW (pre-floor), same reasoning as the
                    # primary fit's own _primary_fit_for_reuse above.
                    _retry_fit_for_reuse = dict(
                        umap_model=_new_embedding_model, embedding=_new_embedding,
                        clf=_new_clf, labels=_new_labels.copy(), dbcv=_new_score,
                        seed=int(_retry_cfg.get("umap_random_state", 42)))
                    _new_labels = _apply_membership_confidence_floor(
                        _new_clf, _new_labels,
                        float(self._cfg.get(
                            "hdbscan_membership_confidence_floor", 0.0) or 0.0))
                    _new_sweep = seed_sweep_stability(
                        feats_sc.T, _retry_cfg, _n_sweep, log_fn=None,
                        primary_fit=_retry_fit_for_reuse,
                        session_boundaries=_session_boundaries,
                        order_shape_rows_sc=order_shape_rows_sc,
                        n_order_shape_cols=_n_order_shape_cols,
                        order_shape_weight=_phase2_os_weight,
                        bins_temporally_ordered=_bins_temporally_ordered,
                        feats_prepca=feats_sc_prepca,
                        fps=fps, win100=_win100,
                        retain_fits_for_reuse=bool(self._cfg.get(
                            "consensus_reuse_seed_sweep_fits", False)))
                    _new_mean_ari = (_new_sweep.get("mean_ari", 0.0)
                                     if _new_sweep else 0.0)

                    _post_dbcv = _dbcv_feature_space(feats_sc.T, _new_labels)
                    _, _, _post_prune_info = _prune_rare_clusters(
                        _new_labels, feats_sc.T, _probe_cfg, n_samp, fps=fps,
                        win100=_win100, session_boundaries=_session_boundaries)
                    _post_survivor_count = _post_prune_info["n_cl"]

                    _quality_tol = float(self._cfg.get(
                        "embedding_stability_retry_quality_tolerance", 0.05) or 0.05)
                    # 5.2 four-part independent accept/reject gate -- NOT
                    # mean_ari alone (over-smoothing can RAISE seed agreement
                    # by erasing genuine structure; see the plan's rationale).
                    # Do not simplify to fewer conditions or merge them into
                    # one combined score -- same explicit instruction this
                    # codebase already gave itself for the original
                    # three-part gate (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md).
                    _cond_i = _new_mean_ari >= _old_mean_ari + 0.02
                    _dbcv_both_finite = (_pre_dbcv == _pre_dbcv and _post_dbcv == _post_dbcv)
                    _cond_ii = (not _dbcv_both_finite) or (_post_dbcv >= _pre_dbcv - _quality_tol)
                    _cond_iii = _post_survivor_count >= _pre_survivor_count
                    # Condition (iv), Tier 2 (Phase 5 of TRAJECTORY_SHAPE_
                    # AND_KINETIC_FLOW_PLAN.md): whole-partition kinetic-
                    # coherence must not regress. Uses its OWN dedicated
                    # tolerance (embedding_stability_retry_kinetic_tolerance,
                    # 2026-08-30 decision) rather than reusing condition
                    # (ii)'s embedding_stability_retry_quality_tolerance --
                    # coherence (dynamical consistency) and DBCV (spatial
                    # separation) measure different things with no reason to
                    # share an acceptable-regression magnitude. Default
                    # (0.05) is a starting point, not yet independently
                    # calibrated -- see the simplified natural-seed-variance
                    # test in Experiment Plan Section G. True (accepting)
                    # when the gate is off, or when either coherence value
                    # is non-finite (degenerate partition -- no meaningful
                    # comparison possible).
                    if _kinetic_gate_on:
                        _kinetic_tol = float(self._cfg.get(
                            "embedding_stability_retry_kinetic_tolerance", 0.05) or 0.05)
                        _post_coherence = _kinetic_coherence_score(
                            _new_labels, feats_sc.T, fps, _win100,
                            session_boundaries=_session_boundaries
                        )["whole_partition"]["mean_coherence_score"]
                        _coherence_both_finite = (
                            _pre_coherence == _pre_coherence and _post_coherence == _post_coherence)
                        _cond_iv = (not _coherence_both_finite) or (
                            _post_coherence >= _pre_coherence - _kinetic_tol)
                    else:
                        _post_coherence = None
                        _cond_iv = True
                    _accept = _cond_i and _cond_ii and _cond_iii and _cond_iv

                    if _accept:
                        embedding = _new_embedding
                        # Required for Phase 6/7 of TRAJECTORY_SHAPE_AND_
                        # KINETIC_FLOW_PLAN.md, which reuses umap_model.graph_
                        # -- must be the model whose .graph_ actually matches
                        # `embedding` (this was a latent gap before that plan:
                        # nothing previously read umap_model again after a
                        # retry, so it silently went stale).
                        umap_model = _new_embedding_model
                        hdb_clf, hdb_labels = _new_clf, _new_labels
                        hdb_score, hdb_score_label = _new_score, _new_score_label
                        _sweep = _new_sweep
                        # §0a row 4f / Experiment 18: the retry's own fit is
                        # now "the" current partition -- any later reuse
                        # (medoid-fallback sweep, consensus_cluster()) must
                        # offer THIS fit, not the superseded pre-retry one.
                        _current_fit_for_reuse = _retry_fit_for_reuse
                        self._cfg["umap_n_neighbors"] = _boosted_nn
                        _kc_log = (f", kinetic-coherence {_pre_coherence:.3f} -> "
                                   f"{_post_coherence:.3f}"
                                   if _kinetic_gate_on and _post_coherence is not None
                                   and _post_coherence == _post_coherence else "")
                        self._log(f"  [EMBED-RETRY] accepted -- mean ARI "
                                  f"{_old_mean_ari:.3f} -> {_new_mean_ari:.3f}, "
                                  f"feature-space DBCV {_pre_dbcv:.3f} -> "
                                  f"{_post_dbcv:.3f}, rare-cluster survivors "
                                  f"{_pre_survivor_count} -> {_post_survivor_count}"
                                  f"{_kc_log}")
                    else:
                        _failed_bits = []
                        if not _cond_i:
                            _failed_bits.append(
                                f"mean ARI improved ({_old_mean_ari:.3f}->"
                                f"{_new_mean_ari:.3f}) but below the +0.02 "
                                f"deadband" if _new_mean_ari > _old_mean_ari else
                                f"mean ARI did not improve ({_old_mean_ari:.3f}"
                                f"->{_new_mean_ari:.3f})")
                        if not _cond_ii:
                            _failed_bits.append(
                                f"feature-space DBCV regressed "
                                f"({_pre_dbcv:.3f}->{_post_dbcv:.3f})")
                        if not _cond_iii:
                            _failed_bits.append(
                                f"rare-cluster survivors dropped "
                                f"{_pre_survivor_count}->{_post_survivor_count} "
                                f"(likely over-smoothing)")
                        if not _cond_iv:
                            _failed_bits.append(
                                f"kinetic-coherence regressed "
                                f"({_pre_coherence:.3f}->{_post_coherence:.3f})")
                        self._log(f"  [EMBED-RETRY] rejected -- "
                                  f"{'; '.join(_failed_bits)}; reverting to "
                                  f"original embedding")
                except Exception:
                    self._log(f"  [WARN] embedding-stability retry failed: "
                              f"{traceback.format_exc()}")

        # ── Consensus/co-association clustering ─────────────────────────────
        # Replaces the single primary seed's HDBSCAN partition with one built
        # from agreement across several independent seeds -- see
        # consensus_cluster()'s docstring for the Aug 2026 investigation that
        # motivated this (UMAP embedding topology itself was seed-unstable on
        # a real dataset; no HDBSCAN sweep/selection tuning fixed it, but
        # consensus clustering did). Costs roughly consensus_n_seeds x the
        # primary UMAP+HDBSCAN runtime, so it only runs when explicitly
        # requested (consensus_clustering_enabled=True) OR auto-triggered:
        # the seed sweep above came back below consensus_auto_threshold
        # (default 0.5 -- clearly unstable, distinct from the existing 0.7
        # "pass" bar used elsewhere for cluster_stability's warn-only gate)
        # AND the caller did not explicitly set consensus_clustering_enabled
        # =False (a deliberate opt-out is always respected -- auto-trigger
        # only fills in when the caller never expressed a preference).
        _explicit_off = ("consensus_clustering_enabled" in self._explicit_cfg_keys
                          and not self._cfg.get("consensus_clustering_enabled"))
        _auto_threshold = float(self._cfg.get("consensus_auto_threshold", 0.55) or 0)
        _auto_triggered = (not self._cfg.get("consensus_clustering_enabled", False)
                            and not _explicit_off
                            and _auto_threshold > 0
                            and _sweep and _sweep.get("mean_ari", 1.0) < _auto_threshold)
        if _auto_triggered:
            self._log(f"  [CONSENSUS-AUTO] seed sweep mean ARI "
                      f"{_sweep['mean_ari']:.3f} < {_auto_threshold} — "
                      f"partition is seed-unstable, auto-enabling consensus "
                      f"clustering (set consensus_clustering_enabled=False "
                      f"explicitly to opt out of this auto-trigger).")
        _consensus_used = False
        _medoid_used = False
        # MEDOID_CONSENSUS_COMPOSITE_METRIC (2026-09-06): initialized here
        # (unconditionally, before the remedy block below) rather than only
        # inside it, so later code (the cluster_stability.png plot and its
        # validation-report entry) can always reference these safely even
        # on a run where no remedy was ever triggered at all -- matches the
        # existing _consensus_used/_medoid_used convention immediately
        # above. NaN here means "never evaluated," not "evaluated and
        # missing" -- the plot/report distinguish the two.
        _medoid_dbcv_fs = float("nan")
        _primary_dbcv_fs = float("nan")
        _medoid_dbcv_tolerance = float(
            self._cfg.get("medoid_dbcv_tolerance", 0.15) or 0.15)
        _medoid_dbcv_regressed = False
        # Populated only when cluster_reclaim_enabled and consensus actually
        # runs -- the co-association matrix consensus_cluster() builds
        # internally, otherwise discarded after that call returns (it's a
        # purely local variable there). Needed by the cross-cluster reclaim
        # pass below, which has no other way to get consensus-flavor
        # per-point agreement data.
        _co_assoc_for_reclaim = None

        def _run_consensus_remedy(_cn_seeds):
            # Single shared invocation helper (MEDOID_CONSENSUS_SELECTION_
            # PLAN.md Phase 3): called both by the explicit
            # partition_remedy_method="consensus" override AND by medoid's
            # own escalation path, so the two can never drift apart from
            # each other. Byte-identical to the pre-Phase-3 inline block --
            # only extracted into a function, no logic changed.
            nonlocal hdb_labels, _orig_hdb_labels, hdb_score, hdb_score_label
            nonlocal n_cl, noise, noise_pct, _consensus_used, _sweep
            nonlocal _co_assoc_for_reclaim
            # Adaptive-aware announcement (Sep 2026): the old unconditional
            # "{_cn_seeds}-seed" wording was actively misleading once
            # consensus_adaptive_enabled could stop after far fewer seeds --
            # a real run's log showed "Building 8-seed..." immediately
            # followed by "running 3 seeds sequentially", reading like a
            # contradiction rather than the intended behavior. Now states the
            # true plan up front: the starting batch size and the ceiling
            # it may escalate to, not just the ceiling alone.
            _adaptive_on = bool(self._cfg.get("consensus_adaptive_enabled", False))
            _adaptive_min = int(self._cfg.get("consensus_adaptive_min_seeds", 3) or 3)
            if _adaptive_on and _cn_seeds > _adaptive_min:
                _seed_plan_desc = (f"{_adaptive_min} seeds first (adaptive -- "
                                    f"escalates up to {_cn_seeds} only if needed)")
            else:
                _seed_plan_desc = f"{_cn_seeds} seeds"
            self._log(f"\n[CONSENSUS]  Building co-association consensus partition "
                      f"({_seed_plan_desc})...")
            self._stage("5/7 — Consensus clustering",
                        f"{_seed_plan_desc} — co-association + Ward linkage")
            # Use a SEPARATE stats dict for this attempt, only merged into
            # the shared _region_split_stats accumulator if consensus
            # actually succeeds and is kept below. Otherwise a discarded
            # attempt (exception anywhere in consensus_cluster(), including
            # AFTER its own internal refine_consensus_clusters() already
            # mutated stats) would leak touched-bin/cluster-count data from
            # labels that were never used into the primary path's own
            # audit trail / dendrogram star markers.
            _consensus_region_split_stats: dict = {}
            # Same "attempt in a separate list, merge only on success" pattern
            # as _consensus_region_split_stats above -- a discarded attempt
            # (exception anywhere in consensus_cluster()) must not leak split
            # events from labels that were never actually used.
            _consensus_split_events: list = []
            # consensus_noise_recovery_enabled (Phase 2, 2026-09-08) needs
            # co_assoc too -- OR'd in here so enabling it alone (without also
            # enabling cluster_reclaim_enabled) doesn't silently leave
            # co_assoc uncomputed and the new recovery step with nothing to
            # work with.
            _want_co_assoc = (bool(self._cfg.get("cluster_reclaim_enabled", False))
                               or bool(self._cfg.get("consensus_noise_recovery_enabled", False)))
            # consensus_reuse_seed_sweep_fits (Sep 2026): only offer _sweep's
            # already-fit seeds to consensus_cluster() when every condition
            # that could make a sweep-time fit diverge from a genuine
            # consensus-time fit is verified false. Any single mismatch here
            # disables reuse entirely for this call -- consensus_cluster()
            # then simply fits every seed fresh, exactly as it always has
            # (this is purely an optimization; getting the gate wrong must
            # never change the delivered partition, only the time it takes).
            _reuse_seed_fits = None
            if (bool(self._cfg.get("consensus_reuse_seed_sweep_fits", False))
                    and _sweep and _sweep.get("seed_fits")
                    and float(self._cfg.get(
                        "hdbscan_membership_confidence_floor", 0.0) or 0.0) <= 0.0
                    and float(self._cfg.get(
                        "seed_sweep_train_frac", 1.0) or 1.0) >= 1.0
                    and int(self._cfg.get("hdbscan_seed_sweep_n_steps", 0) or 0)
                        == int(self._cfg.get("hdbscan_consensus_sweep_n_steps", 0) or 0)):
                _reuse_seed_fits = _sweep["seed_fits"]
            try:
                _cons = consensus_cluster(feats_sc.T, self._cfg, _cn_seeds,
                                          log_fn=self._log, embedding=embedding,
                                          region_per_bin=region_per_bin,
                                          region_split_stats=_consensus_region_split_stats,
                                          split_events=_consensus_split_events,
                                          session_boundaries=_session_boundaries,
                                          return_co_assoc=_want_co_assoc,
                                          fps=fps, win100=_win100,
                                          order_shape_rows_sc=order_shape_rows_sc,
                                          n_order_shape_cols=_n_order_shape_cols,
                                          order_shape_weight=_phase2_os_weight,
                                          bins_temporally_ordered=_bins_temporally_ordered,
                                          feats_prepca=feats_sc_prepca,
                                          umap_model=umap_model,
                                          primary_fit=_current_fit_for_reuse,
                                          precomputed_seed_fits=_reuse_seed_fits,
                                          train_orig_bin_idx=_train_orig_bin_idx,
                                          session_bin_ranges=_sbr,
                                          all_xy=all_xy, all_names=all_names,
                                          bps_ref=bps_ref, is_3d=_is_3d,
                                          all_ll=all_ll)
            except Exception:
                _cons = None
                self._log(f"  [WARN] consensus clustering failed: "
                          f"{traceback.format_exc()}")
            if _cons is not None:
                _region_split_stats["clusters_created"] = (
                    _region_split_stats.get("clusters_created", 0)
                    + _consensus_region_split_stats.get("clusters_created", 0))
                _region_split_stats.setdefault("touched_bin_idx", []).extend(
                    _consensus_region_split_stats.get("touched_bin_idx", []))
                _split_events.extend(_consensus_split_events)
                hdb_labels, _cons_quality = _cons
                _co_assoc_for_reclaim = _cons_quality.get("co_assoc")
                _orig_hdb_labels = hdb_labels.copy()
                hdb_score = _cons_quality["separation_ratio"]
                hdb_score_label = "consensus separation ratio"
                n_cl      = len(set(hdb_labels[hdb_labels >= 0]))
                noise     = (hdb_labels < 0).sum()
                noise_pct = 100 * noise / max(1, len(hdb_labels))
                _consensus_used = True
                # Adaptive-status suffix (Sep 2026): makes this one summary
                # line self-contained -- previously a reader had to scroll
                # back to the earlier [consensus-adaptive] decision line (or
                # infer it from n_seeds_used alone) to know whether this
                # result came from stopping early or a full/escalated run.
                if _cons_quality.get("adaptive_enabled"):
                    _adaptive_suffix = (" [adaptive: escalated to full seed count]"
                                         if _cons_quality.get("adaptive_escalated")
                                         else " [adaptive: stopped early, cohesion "
                                              "score cleared the escalate threshold]")
                else:
                    _adaptive_suffix = ""
                self._log(f"  Consensus: {n_cl} clusters, {noise} noise points "
                          f"({noise_pct:.1f} %), separation_ratio="
                          f"{hdb_score:.2f}x (within- vs between-cluster mean "
                          f"co-association across {_cons_quality['n_seeds_used']} "
                          f"seeds; per-seed counts={_cons_quality['per_seed_counts']})"
                          f"{_adaptive_suffix}")
                self._log(f"  [feature-space] DBCV="
                          f"{_cons_quality.get('dbcv_feature_space')}  "
                          f"silhouette={_cons_quality.get('silhouette_feature_space')} "
                          f"(comparable across configs, unlike separation_ratio)")
                self._stage("5/7 — Consensus done",
                            f"{n_cl} clusters · {noise_pct:.0f}% noise · "
                            f"separation={hdb_score:.2f}x")
                # Standalone sweep was skipped above (_consensus_forced) --
                # consensus_cluster() computed the same seeds/counts/ari/
                # mean_ari stats for free from its own per-seed partitions
                # (see consensus_cluster()'s "Derived seed-stability stats"
                # block); wire them into _sweep here so cluster_stability.png
                # and _validation["cluster_stability"] below work completely
                # unmodified -- they only ever read _sweep's keys, not which
                # code path produced it.
                if _consensus_forced and _sweep is None and "mean_ari" in _cons_quality:
                    _sweep = {k: _cons_quality[k] for k in
                              ("seeds", "counts", "ari", "mean_ari", "stable_counts")
                              if k in _cons_quality}
                    _sc = _sweep.get('stable_counts', _sweep['counts'])
                    self._log(f"  Mean pairwise ARI = {_sweep['mean_ari']:.3f} "
                              f"(cluster counts {min(_sc)}–{max(_sc)} across "
                              f"seeds used in the mean; full sweep range "
                              f"{min(_sweep['counts'])}–{max(_sweep['counts'])}) "
                              f"[derived from consensus clustering's own "
                              f"per-seed partitions, unrefined -- not directly "
                              f"comparable to standalone seed-sweep values]")
            else:
                self._log("  [WARN] consensus clustering produced no usable "
                          "result (too few seeds succeeded) — falling back to "
                          "the primary single-seed HDBSCAN result.")

        if self._cfg.get("consensus_clustering_enabled", False) or _auto_triggered:
            _cn_seeds = int(self._cfg.get("consensus_n_seeds", 8) or 8)
            _partition_remedy_method = str(
                self._cfg.get("partition_remedy_method", "medoid")).lower().strip()

            if _partition_remedy_method == "consensus":
                # Explicit override -- exactly today's behavior, unchanged,
                # byte-identical forever (non-negotiable safety invariant #2
                # in the plan). No medoid attempt, no escalation logic.
                _run_consensus_remedy(_cn_seeds)
            else:
                # "medoid" (new default): try the seed most representative
                # of the stability sweep first; escalate to full consensus
                # only if that seed's own agreement with the rest of the
                # sweep is itself too low, or the sweep collapsed entirely.
                if _sweep is None:
                    # The standalone sweep above was skipped because
                    # consensus_clustering_enabled=True forced this block
                    # open without ever running it (see _consensus_forced) --
                    # medoid selection needs per-seed partitions to choose
                    # from, so run one now. Mirrors _consensus_forced's own
                    # skip logic: seed_sweep_n's configured value, or
                    # consensus_n_seeds's value as a fallback if
                    # seed_sweep_n < 2.
                    _medoid_sweep_n = _n_sweep if _n_sweep >= 2 else _cn_seeds
                    self._log(f"\n[MEDOID]  Running a {_medoid_sweep_n}-seed "
                              f"stability sweep now -- it was skipped above "
                              f"because consensus_clustering_enabled=True "
                              f"forced this block open without ever running "
                              f"it, but medoid selection needs per-seed "
                              f"partitions to choose from.")
                    self._stage("Cluster-stability seed sweep (for medoid)",
                                f"{_medoid_sweep_n} seeds — re-running UMAP+HDBSCAN")
                    try:
                        _sweep = seed_sweep_stability(
                            feats_sc.T, self._cfg, _medoid_sweep_n, log_fn=self._log,
                            session_boundaries=_session_boundaries,
                            order_shape_rows_sc=order_shape_rows_sc,
                            n_order_shape_cols=_n_order_shape_cols,
                            order_shape_weight=_phase2_os_weight,
                            bins_temporally_ordered=_bins_temporally_ordered,
                            feats_prepca=feats_sc_prepca,
                            fps=fps, win100=_win100,
                            primary_fit=_current_fit_for_reuse,
                            retain_fits_for_reuse=bool(self._cfg.get(
                                "consensus_reuse_seed_sweep_fits", False)))
                    except Exception:
                        _sweep = None
                        self._log(f"  [WARN] medoid seed sweep: "
                                  f"{traceback.format_exc()}")

                _medoid_escalation_threshold = float(
                    self._cfg.get("medoid_escalation_threshold", 0.35) or 0)
                _medoid_pos = _sweep.get("medoid_seed_pos") if _sweep else None
                _medoid_mean_ari = _sweep.get("medoid_mean_ari") if _sweep else None
                # MEDOID_CONSENSUS_COMPOSITE_METRIC (2026-09-06): computed
                # unconditionally alongside the ARI values above (not lazily
                # inside the elif chain below) so both are available to the
                # composite-gate elif branch AND to the final [MEDOID]
                # adoption log line, without a second, divergent computation.
                # Only actually computed (a real cost -- _dbcv_feature_space's
                # MST step is O(n^2), capped via its own max_n=5000 subsample)
                # when there IS a medoid candidate to evaluate; None sweep or
                # a degenerate (no medoid_seed_pos) sweep skips this entirely,
                # same short-circuit the existing NaN/degenerate checks below
                # already rely on. medoid_dbcv_tolerance's own DEFAULTS
                # docstring has the full design rationale (mirrors
                # embedding_stability_retry's ARI+DBCV AND-gate).
                # _medoid_dbcv_tolerance already resolved above, before this
                # remedy block, so it's available even on a no-remedy run.
                _medoid_dbcv_min_samples = int(
                    self._cfg.get("medoid_dbcv_min_samples", 500) or 500)
                if _medoid_pos is not None and n_samp >= _medoid_dbcv_min_samples:
                    _medoid_dbcv_fs = _dbcv_feature_space(
                        feats_sc.T, np.asarray(_sweep["labels"][_medoid_pos]),
                        log_fn=self._log)
                    _primary_dbcv_fs = _dbcv_feature_space(
                        feats_sc.T, np.asarray(_primary_fit_for_reuse["labels"]))
                    _dbcv_both_finite = (_medoid_dbcv_fs == _medoid_dbcv_fs
                                         and _primary_dbcv_fs == _primary_dbcv_fs)
                    # NaN-safe by construction (matches embedding_stability_
                    # retry's own _dbcv_both_finite convention exactly): if
                    # either DBCV is unmeasurable, this stays False -- the
                    # composite gate never blocks adoption on a quantity it
                    # couldn't compute, silently degrading to the pre-
                    # existing ARI-only decision.
                    _medoid_dbcv_regressed = (
                        _dbcv_both_finite
                        and _medoid_dbcv_fs < _primary_dbcv_fs - _medoid_dbcv_tolerance)
                else:
                    # Either no medoid candidate yet (degenerate-sweep branch
                    # handles that separately below), or n_samp is below
                    # medoid_dbcv_min_samples -- too little data for a
                    # feature-space DBCV comparison to be more signal than
                    # noise (see medoid_dbcv_min_samples's own DEFAULTS
                    # docstring). Either way: skip the composite check
                    # entirely, never compute an unreliable number just to
                    # ignore it.
                    _medoid_dbcv_fs = float("nan")
                    _primary_dbcv_fs = float("nan")
                    _medoid_dbcv_regressed = False

                if _medoid_pos is None:
                    # Degenerate sweep (fewer than 2 stable seeds) -- there is
                    # no medoid row-mean ARI to evaluate at all. Escalate
                    # straight to consensus rather than silently falling back
                    # to the already-known-unstable primary partition (see
                    # the plan's Design decisions section).
                    self._log(f"  [MEDOID→CONSENSUS] seed sweep degenerate "
                              f"(fewer than 2 stable seeds) -- no medoid seed "
                              f"to adopt, escalating to full consensus.")
                    _run_consensus_remedy(_cn_seeds)
                elif _medoid_mean_ari != _medoid_mean_ari:   # NaN check (NaN != NaN)
                    # Every pairwise ARI touching this seed came back NaN
                    # (e.g. adjusted_rand_score failed for every comparison)
                    # -- `NaN < threshold` is always False in Python/NumPy,
                    # which would otherwise silently fall through to ADOPT an
                    # unmeasured (not merely low-quality) partition. Treat
                    # exactly like the degenerate-sweep case: escalate.
                    self._log(f"  [MEDOID→CONSENSUS] medoid seed's own mean "
                              f"ARI is NaN (every pairwise comparison failed) "
                              f"-- cannot be evaluated, escalating to full "
                              f"consensus.")
                    _run_consensus_remedy(_cn_seeds)
                elif _medoid_mean_ari < _medoid_escalation_threshold:
                    self._log(f"  [MEDOID→CONSENSUS] medoid seed's own mean "
                              f"ARI {_medoid_mean_ari:.3f} < "
                              f"medoid_escalation_threshold "
                              f"{_medoid_escalation_threshold} -- the most "
                              f"representative seed of a sweep that doesn't "
                              f"agree with itself is still not trustworthy; "
                              f"escalating to full consensus.")
                    _run_consensus_remedy(_cn_seeds)
                elif _medoid_dbcv_regressed:
                    # MEDOID_CONSENSUS_COMPOSITE_METRIC (2026-09-06): second,
                    # independent condition -- see medoid_dbcv_tolerance's
                    # own DEFAULTS docstring for the full rationale (mirrors
                    # embedding_stability_retry's ARI+DBCV AND-gate exactly,
                    # values computed just above this if/elif chain). High
                    # cross-seed agreement alone is not trusted if the
                    # agreed-upon partition's own feature-space cohesion/
                    # separation is meaningfully worse than what the
                    # PRE-remedy primary partition already had -- that
                    # pattern (high agreement, poor absolute quality) is
                    # exactly the over-smoothing signature the retry gate
                    # was built to catch, applied here to the medoid
                    # candidate instead of a re-embedded retry.
                    self._log(f"  [MEDOID→CONSENSUS] medoid candidate's own "
                              f"feature-space DBCV {_medoid_dbcv_fs:.3f} is "
                              f"below the pre-remedy primary partition's "
                              f"{_primary_dbcv_fs:.3f} by more than "
                              f"medoid_dbcv_tolerance {_medoid_dbcv_tolerance} "
                              f"-- high seed agreement alone isn't trusted "
                              f"(agreement can be inflated by over-smoothing); "
                              f"escalating to full consensus.")
                    _run_consensus_remedy(_cn_seeds)
                elif len(_sweep["labels"][_medoid_pos]) != n_samp:
                    # seed_sweep_train_frac < 1.0 (opt-in, default a true
                    # no-op) subsamples bins INSIDE seed_sweep_stability(),
                    # independent of the primary path's own train_frac --
                    # _sweep["labels"][pos] could then have fewer rows than
                    # the primary hdb_labels/embedding/feats_sc. Every other
                    # consumer of _sweep before this plan only read summary
                    # statistics (ari/mean_ari), never the labels array
                    # itself, so this shape mismatch was latent and harmless
                    # until medoid adoption became the first real consumer.
                    # Adopting a shorter array here would silently corrupt
                    # every downstream index-aligned array (feats_sc,
                    # embedding, region_per_bin, timestamps, ...) rather than
                    # failing loudly -- escalate instead.
                    self._log(f"  [MEDOID→CONSENSUS] medoid seed's partition "
                              f"has {len(_sweep['labels'][_medoid_pos])} bins, "
                              f"expected {n_samp} (seed_sweep_train_frac < 1.0 "
                              f"subsamples independently of the primary fit) "
                              f"-- cannot safely adopt, escalating to full "
                              f"consensus.")
                    _run_consensus_remedy(_cn_seeds)
                else:
                    hdb_labels = np.asarray(_sweep["labels"][_medoid_pos])
                    # HDB_CLF_MEDOID_CONSISTENCY_FIX (2026-09-06): adopt the
                    # medoid seed's OWN classifier and raw (pre-refinement)
                    # labels together with its labels/embedding/umap_model,
                    # instead of leaving hdb_clf pointing at the PRIMARY
                    # seed's classifier -- a real, if previously harmless,
                    # mismatch (hdb_clf's raw output no longer corresponded
                    # to hdb_labels/_orig_hdb_labels at all once medoid
                    # adopted a different seed). _orig_hdb_labels must equal
                    # what hdb_clf itself actually produces (see
                    # seed_sweep_stability()'s medoid_raw_labels docstring
                    # comment) for the _hdb_remap/approximate_predict
                    # fallback path to remain valid if it's ever reached
                    # after a medoid run. Defensive fallback (medoid_clf/
                    # medoid_raw_labels missing or length-mismatched, e.g. a
                    # test double or a legacy sweep dict predating this fix)
                    # keeps the OLD behavior -- hdb_clf untouched,
                    # _orig_hdb_labels = hdb_labels.copy() -- logged so a
                    # silent regression in the fallback path is at least
                    # visible, rather than crashing this well-tested,
                    # already-shipping adoption path outright.
                    _medoid_clf = _sweep.get("medoid_clf")
                    _medoid_raw_labels = _sweep.get("medoid_raw_labels")
                    if _medoid_clf is not None and _medoid_raw_labels is not None \
                            and len(_medoid_raw_labels) == len(hdb_labels):
                        hdb_clf = _medoid_clf
                        _orig_hdb_labels = np.asarray(_medoid_raw_labels).copy()
                    else:
                        self._log(
                            "  [WARN] medoid seed's own classifier/raw labels "
                            "unavailable or length-mismatched -- hdb_clf "
                            "still reflects the PRIMARY seed's fit, not the "
                            "adopted medoid seed's (see HDB_CLF_MEDOID_"
                            "CONSISTENCY_FIX, KINETIC_REWEIGHT_POST_DECISION_"
                            "PLAN.md); the approximate_predict fallback path "
                            "would be unreliable if reached for this run.")
                        _orig_hdb_labels = hdb_labels.copy()
                    # EMBEDDING_UMAP_MODEL_MEDOID_CONSISTENCY_FIX (2026-09-07):
                    # reassign the SHARED `embedding`/`umap_model` variables
                    # themselves -- not just a call-site-local copy -- to the
                    # medoid seed's own fit, mirroring the exact convention
                    # embedding_stability_retry already established a few
                    # hundred lines above ("`embedding` (this was a latent gap
                    # before that plan: nothing previously read umap_model
                    # again after a retry, so it silently went stale)").
                    # Each seed in the sweep genuinely re-runs run_umap() with
                    # its own umap_random_state (_seed_sweep_one_seed sets
                    # c2["umap_random_state"] = s), so the medoid seed's
                    # embedding is a GENUINELY DIFFERENT geometric space from
                    # the primary fit's, not just a different HDBSCAN
                    # clustering of the same points. Before this fix, every
                    # consumer of the bare `embedding`/`umap_model` variables
                    # AFTER this point -- validate_clustering(), plot_cluster_
                    # validity/plot_umap/plot_state_space_trajectory/plot_
                    # split_merge_refinement, the UMAP-evolution video export
                    # (embedding[sb:se] paired with hdb_labels[sb:se]), and
                    # the umap_model pickled into bsoid_model.pkl for future
                    # out-of-sample visualization -- silently kept using the
                    # PRIMARY seed's embedding/model while hdb_labels already
                    # held the medoid seed's partition, producing spatially
                    # incoherent plots/exports and a saved umap_model that
                    # doesn't correspond to the shipped clusters, on every
                    # medoid-adopted run (the DEFAULT partition_remedy_method
                    # branch, not a rare case). The two narrowly-scoped local
                    # workarounds added alongside HDB_CLF_MEDOID_CONSISTENCY_
                    # FIX (`_refine_embedding` below, `_phase67_embedding`/
                    # `_phase67_umap_model` further down) only covered their
                    # own two call sites and are now redundant no-ops given
                    # this global fix (kept as-is rather than stripped --
                    # smaller diff, and their own fallback-on-missing-data
                    # logging stays a real safety net if this fix's own
                    # defensive branch below is ever hit).
                    _medoid_emb_fix = _sweep.get("medoid_embedding")
                    _medoid_um_fix = _sweep.get("medoid_umap_model")
                    if _medoid_emb_fix is not None and _medoid_um_fix is not None \
                            and len(_medoid_emb_fix) == len(hdb_labels):
                        embedding = _medoid_emb_fix
                        umap_model = _medoid_um_fix
                    else:
                        self._log(
                            "  [WARN] medoid seed's own embedding/umap_model "
                            "unavailable or length-mismatched -- embedding/"
                            "umap_model still reflect the PRIMARY seed's fit, "
                            "not the adopted medoid seed's; downstream plots/"
                            "validation/the saved model for this run may be "
                            "spatially inconsistent with the shipped clusters.")
                    n_cl      = len(set(hdb_labels[hdb_labels >= 0]))
                    noise     = (hdb_labels < 0).sum()
                    noise_pct = 100 * noise / max(1, len(hdb_labels))
                    _medoid_used = True
                    # UNIFIED_POST_DECISION_REFINEMENT_PLAN.md (2026-09-06):
                    # no per-seed merge-in needed here anymore -- seeds are
                    # never refined now (medoid_region_split_stats/
                    # medoid_split_events are always {}/[]), so the
                    # dendrogram's/split_merge_refinement.png's split/merge
                    # audit trail instead comes entirely from the NEW unified
                    # post-decision refinement call below (it writes directly
                    # into these same _region_split_stats/_split_events
                    # accumulators).
                    _dbcv_composite_note = (
                        f"feature-space DBCV = {_medoid_dbcv_fs:.3f} vs. "
                        f"primary's {_primary_dbcv_fs:.3f} (composite gate "
                        f"passed)"
                        if _medoid_dbcv_fs == _medoid_dbcv_fs  # finite -> was evaluated
                        else "composite DBCV gate skipped (n_samp below "
                             "medoid_dbcv_min_samples or DBCV unmeasurable)")
                    self._log(f"  [MEDOID] adopting seed {_sweep['medoid_seed']}'s "
                              f"partition as the final result -- mean ARI to "
                              f"the other stable seeds = {_medoid_mean_ari:.3f} "
                              f"(>= medoid_escalation_threshold "
                              f"{_medoid_escalation_threshold}), "
                              f"{_dbcv_composite_note}: {n_cl} clusters, "
                              f"{noise} noise points ({noise_pct:.1f} %)")
                    self._stage("5/7 — Medoid adopted",
                                f"seed {_sweep['medoid_seed']} · {n_cl} clusters · "
                                f"{noise_pct:.0f}% noise · "
                                f"mean ARI={_medoid_mean_ari:.2f}")

        # ── UNIFIED_POST_DECISION_REFINEMENT_PLAN.md (2026-09-06): ONE
        # refine_clusters_iterative() (split + merge) call, run exactly once
        # here -- right after the medoid/consensus decision resolves, before
        # Phase 6/7 -- instead of the old two call sites (every seed inside
        # _seed_sweep_one_seed(), unconditionally, PLUS a separate post-
        # decision call that only ever fired for "no remedy"). Consensus is
        # untouched -- it never used per-seed refinement and keeps its own
        # aggregate-level consensus_refine_enabled split+merge
        # (merge_by_coassociation(), not condensed-tree based) -- so this
        # call is gated on `not _consensus_used`, covering BOTH "no remedy"
        # (primary partition kept) and "medoid adopted": for "no remedy",
        # embedding/hdb_clf are the primary fit's own, exactly as before;
        # for medoid, hdb_clf was already reassigned to the medoid seed's
        # own classifier above (HDB_CLF_MEDOID_CONSISTENCY_FIX), so
        # `embedding` must be swapped the same way here -- the split step's
        # local re-embedding and the merge step's condensed_tree_ read both
        # assume embedding/clf/labels all come from the SAME fit. Falls back
        # to the primary embedding (logged) if the medoid seed's own
        # embedding wasn't retained (defensive, mirrors the hdb_clf fallback
        # above) -- refinement would silently operate on a mismatched fit
        # otherwise rather than failing loudly.
        # Snapshot for the before/after diagnostic plot below — isolates the
        # refinement pass's own effect from the separate rare-cluster-pruning
        # renumbering that happens afterward (see split_merge_refinement.png
        # call site further down).
        _pre_refine_labels = hdb_labels.copy()
        # SPLIT_ELIGIBILITY_IMPROVEMENT_PLAN.md technique 5, live wiring
        # (2026-09-24): computed once here, on the pre-refine partition,
        # so BOTH the split veto (inside split_impure_clusters()/
        # split_kinetically_incoherent_clusters()) and the merge guard/
        # consolidation (inside merge_similar_clusters(), via
        # refine_clusters_iterative()) see the SAME real scores. {} (not
        # None) when either flag is off, or when the pre-req data isn't
        # available this run -- both a true no-op and a real degrade-to-skip,
        # never a crash. Skipped entirely for consensus (matches the
        # existing "this pass skipped for consensus labels" scope limit
        # just below -- consensus's own native split/merge pass doesn't
        # consume this dict).
        _posture_entropy_scores = {}
        if not _consensus_used and (
                bool(self._cfg.get("hdbscan_split_posture_entropy_veto_enabled", False))
                or bool(self._cfg.get("hdbscan_merge_posture_entropy_guard_enabled", False))):
            try:
                _posture_entropy_scores = _pre_refine_posture_entropy_scores(
                    _pre_refine_labels, feats_sc.T, fps, _win100,
                    _session_boundaries, _train_orig_bin_idx, _sbr,
                    all_xy, all_names, bps_ref, is_3d=_is_3d, all_ll=all_ll,
                    camera_view=_camera_view_from_schema(bps_ref),
                    log_fn=self._log)
            except Exception:
                self._log(f"  [WARN] posture-entropy pre-refine scores: "
                          f"{traceback.format_exc()}")
                _posture_entropy_scores = {}
        if _consensus_used:
            self._log("  [refine] this pass skipped for consensus labels "
                      "(condensed-tree merge criterion doesn't apply; see "
                      "consensus_refine_enabled for consensus's own native "
                      "split/merge pass, run internally before this point)")
        else:
            _refine_embedding = embedding
            if _medoid_used:
                _refine_embedding = _sweep.get("medoid_embedding") if _sweep else None
                if _refine_embedding is None:
                    self._log(
                        "  [WARN] medoid seed's own embedding unavailable -- "
                        "falling back to the primary fit's embedding for "
                        "post-decision refinement (may mismatch hdb_clf, "
                        "see HDB_CLF_MEDOID_CONSISTENCY_FIX)")
                    _refine_embedding = embedding
            hdb_labels = refine_clusters_iterative(
                feats_sc, _refine_embedding, hdb_labels, hdb_clf, self._cfg,
                log_fn=self._log, region_per_bin=region_per_bin,
                region_split_stats=_region_split_stats,
                split_events=_split_events,
                longwindow_feats_sc=longwindow_rows_sc,
                fps=fps, win100=_win100,
                posture_entropy_veto=_posture_entropy_scores or None)

        # ── KINETIC_REWEIGHT_POST_DECISION_PLAN.md (2026-09-06): Tiers 3a/3b
        # now run HERE, once, against whichever partition the medoid/
        # consensus decision above actually shipped -- superseding the
        # earlier pre-decision placement (medoid/consensus used to REPLACE
        # hdb_labels wholesale with an independently-derived partition,
        # silently discarding whatever Phase 6/7 had just computed on the
        # pre-decision single-seed fit -- the documented "helps consensus,
        # hurts medoid" asymmetry). Cross-seed agreement (ARI in
        # seed_sweep_stability(), co-association in consensus_cluster()) is
        # measured on the raw spatial UMAP+HDBSCAN structure -- what seed-
        # stability is actually testing -- never on a per-seed
        # kinetically-reweighted partition (the old per-seed mechanism,
        # "Option C", was retired the same day this moved -- see
        # _seed_sweep_one_seed()/_consensus_one_seed()'s own comments).
        #
        # Geometric substrate selection (plan step 3): the flow field needs
        # ONE fitted UMAP model (for its .graph_) and ONE embedding (for
        # spatial distances) that actually correspond to hdb_labels as it
        # stands right now.
        #   - No remedy fired (primary partition kept) -> the primary
        #     embedding/umap_model already in scope.
        #   - Medoid -> the medoid seed's OWN embedding/umap_model (Step 2
        #     retains both alongside seed_sweep_stability()'s existing
        #     medoid_region_split_stats/medoid_split_events convention) --
        #     a different fit than the primary, but the one that actually
        #     produced hdb_labels.
        #   - Consensus -> no single seed's fit corresponds to consensus's
        #     co-association labels; the PRIMARY seed's embedding/
        #     umap_model.graph_ is reused as the geometric substrate for
        #     reweighting consensus's labels. Documented scope decision,
        #     not an oversight -- logged explicitly below.
        # Gated by kinetic_flow_field_enabled -- same as Phase 6/7 below --
        # so this stays a true no-op (no wasted computation, no log lines)
        # for the common case where the feature is off entirely, and so a
        # test asserting "kinetic_reweight_strength=0 -> no [KINETIC-
        # REWEIGHT]-tagged log line" isn't broken by an unrelated,
        # unconditional substrate-selection message. Tagged [FLOW-FIELD]
        # (not [KINETIC-REWEIGHT]) since Phase 6's diagnostic is the first,
        # unconditional consumer of this substrate -- Phase 7 only reuses
        # it when kinetic_reweight_strength > 0 as well.
        if bool(self._cfg.get("kinetic_flow_field_enabled", False)):
            if _medoid_used:
                _phase67_umap_model = _sweep.get("medoid_umap_model") if _sweep else None
                _phase67_embedding = _sweep.get("medoid_embedding") if _sweep else None
                if _phase67_umap_model is None or _phase67_embedding is None:
                    self._log(
                        "  [FLOW-FIELD] medoid seed's own embedding/umap_model "
                        "unavailable -- falling back to the primary fit's "
                        "embedding/umap_model as the geometric substrate")
                    _phase67_umap_model, _phase67_embedding = umap_model, embedding
            elif _consensus_used:
                self._log(
                    "  [FLOW-FIELD] consensus partition has no single seed's "
                    "own fit -- using the PRIMARY seed's embedding/"
                    "umap_model.graph_ as the geometric substrate for "
                    "reweighting consensus's labels (documented scope "
                    "decision, not an oversight)")
                _phase67_umap_model, _phase67_embedding = umap_model, embedding
            else:
                _phase67_umap_model, _phase67_embedding = umap_model, embedding
        else:
            _phase67_umap_model, _phase67_embedding = umap_model, embedding

        # ── Phase 6, TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md: Tier 3a --
        # continuous kinetic flow field + boundary-alignment diagnostic.
        # Structurally guaranteed single invocation per run() call: this is
        # one straight-line block (never looped), the same pattern
        # embedding_stability_retry itself already uses.
        _flow_field_result = None
        if bool(self._cfg.get("kinetic_flow_field_enabled", False)) and not _bins_temporally_ordered:
            self._log("  [WARN] kinetic_flow_field_enabled is on but bins are "
                      "not verifiably temporally ordered this run (see the "
                      "WARN above) -- skipping flow-field construction.")
        if bool(self._cfg.get("kinetic_flow_field_enabled", False)) and _bins_temporally_ordered:
            try:
                _os_weight = 1.0
                _os_presmooth = 0
                # 2026-08-30 fix: order_shape_rows_sc (retained separately,
                # never part of feats_sc — see the split at feats_sub/
                # feats_sc construction above) is reattached HERE, as its
                # own explicit trailing block on feats_sc_prepca (the
                # primary, PRE-PCA scaled matrix), instead of the old
                # "assume the last n_order_shape_cols columns of feats_sc
                # are order-shape" approach. That old approach was already
                # unreliable two ways: (1) feats_sc may be PCA-reduced by
                # this point (PCA auto-triggers whenever sample/feature
                # ratio < 5, the common case), which mixes every input
                # dimension into new components — there is no longer a
                # meaningful "last N columns"; (2) even pre-PCA, the true
                # trailing block of the per-session feature array is
                # visibility (appended AFTER order-shape whenever
                # visibility_features_enabled=True, the default), not
                # order-shape. Building the matrix explicitly here avoids
                # both.
                _feats_for_flow = feats_sc_prepca
                if (bool(self._cfg.get("order_shape_features_enabled", False))
                        and order_shape_rows_sc is not None
                        and _n_order_shape_cols > 0):
                    # Legacy hard-exclusion override (explicit True) always
                    # wins -- kept for backward-compat with saved session
                    # JSON predating the weight dial below. Default is now
                    # the continuous weight, not full exclusion -- see
                    # kinetic_flow_field_order_shape_weight's own DEFAULTS
                    # docstring for why the default is small-but-nonzero,
                    # not 0.0.
                    if bool(self._cfg.get(
                            "kinetic_flow_field_exclude_order_shape_terms", False)):
                        _os_weight = 0.0
                    else:
                        _os_weight = float(self._cfg.get(
                            "kinetic_flow_field_order_shape_weight", 0.1) or 0.0)
                    _os_presmooth = int(self._cfg.get(
                        "kinetic_flow_field_order_shape_presmooth_window", 7) or 0)
                    _feats_for_flow = np.vstack([feats_sc_prepca, order_shape_rows_sc])
                _flow_field_result = _compute_kinetic_flow_field(
                    _feats_for_flow.T, _phase67_umap_model, hdb_labels, self._cfg,
                    session_boundaries=_session_boundaries,
                    n_order_shape_cols=(_n_order_shape_cols
                                        if _feats_for_flow is not feats_sc_prepca else 0),
                    order_shape_weight=_os_weight,
                    order_shape_presmooth_window=_os_presmooth)
                _n_boundaries = len(_flow_field_result["boundary_alignment"])
                self._log(f"  [FLOW-FIELD] spectral gap="
                          f"{_flow_field_result['spectral_gap']:.4f}, "
                          f"{_n_boundaries} adjacent cluster-pair boundary "
                          f"alignment score(s) computed"
                          + (f" (order-shape columns: weight={_os_weight:.2f}, "
                             f"presmooth_window={_os_presmooth})"
                             if _n_order_shape_cols > 0 else ""))
                if self._cfg.get("save_plots", True):
                    try:
                        plot_kinetic_flow_field(
                            _flow_field_result,
                            self._out_plots / "kinetic_flow_field_boundary_alignment.png")
                        self._log("  [PLOT] kinetic_flow_field_boundary_alignment.png saved")
                    except Exception:
                        self._log(f"  [WARN] kinetic flow-field plot failed: "
                                  f"{traceback.format_exc()}")
            except Exception:
                self._log(f"  [WARN] kinetic flow-field construction failed: "
                          f"{traceback.format_exc()}")

        # ── Phase 7, TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md: Tier 3b --
        # kinetically-reweighted density re-clustering. Same fixed insertion
        # point as Phase 6 immediately above -- reuses Phase 6's flow field,
        # built from the ORIGINAL unweighted embedding/graph, never
        # recomputed here (the plan's circularity-prevention requirement).
        # Gated by BOTH kinetic_flow_field_enabled and kinetic_reweight_
        # strength != 0 -- at strength=0.0 (explicit) this whole block is
        # skipped entirely (not merely a numeric no-op), so the pipeline
        # never pays for or risks an extra HDBSCAN pass when the feature is
        # deliberately off. "auto" (the default since 2026-09-07) always
        # attempts this block -- whether it ends up a near-no-op or a real
        # correction is decided per-dataset by _kinetic_reweighted_hdbscan_
        # auto()'s own boundary-alignment-driven guess, not by this gate.
        _kinetic_reweight_strength_raw = self._cfg.get("kinetic_reweight_strength", 0.0)
        _kinetic_reweight_is_auto = (isinstance(_kinetic_reweight_strength_raw, str)
                                      and _kinetic_reweight_strength_raw.strip().lower() == "auto")
        _kinetic_reweight_gate = (_kinetic_reweight_is_auto
                                   or float(_kinetic_reweight_strength_raw or 0.0) > 0)
        if (bool(self._cfg.get("kinetic_flow_field_enabled", False))
                and _kinetic_reweight_gate and _flow_field_result is not None):
            try:
                _kr = _kinetic_reweighted_hdbscan_auto(
                    _phase67_embedding, hdb_labels, hdb_clf, self._cfg, n_samp,
                    _flow_field_result, log_fn=self._log)
                # Auditability record for validation_report.json, mirroring
                # the [KINETIC-REWEIGHT] log line below -- so a resolved
                # "auto" strength (and whether it backed off) is visible
                # without having to grep the run log.
                _validation["kinetic_reweight"] = {
                    "resolved_strength": _kr["resolved_strength"],
                    "auto_used": _kr["auto_used"],
                    "auto_worst_boundary_align": (
                        None if np.isnan(_kr["auto_worst_boundary_align"])
                        else _kr["auto_worst_boundary_align"]),
                    "auto_initial_guess": _kr["auto_initial_guess"],
                    "auto_backoff_applied": _kr["auto_backoff_applied"],
                    "reassigned_frac": _kr["reassigned_frac"],
                    "aborted_reason": _kr["aborted_reason"],
                }
                if _kr["aborted_reason"]:
                    self._log(f"  [KINETIC-REWEIGHT] aborted -- "
                              f"{_kr['aborted_reason']}; keeping the "
                              f"spatial-only partition")
                else:
                    self._log(f"  [KINETIC-REWEIGHT] strength="
                              f"{_kr['resolved_strength']:.2f}"
                              + (" (auto"
                                 + (f", backed off from {_kr['auto_initial_guess']:.2f}"
                                    if _kr['auto_backoff_applied'] else "")
                                 + ")" if _kr["auto_used"] else "")
                              + f" -- {_kr['reassigned_frac']*100:.2f}% of "
                              f"points reassigned ({len(_kr['assignment_diff'])} "
                              f"point(s))")
                    if bool(self._cfg.get("kinetic_reweight_log_assignment_diff", True)) \
                            and _kr["assignment_diff"]:
                        try:
                            pd.DataFrame(_kr["assignment_diff"]).to_csv(
                                str(self._out_model / "kinetic_reweight_assignment_diff.csv"),
                                index=False)
                            self._log(f"  [KINETIC-REWEIGHT] full before/after "
                                      f"assignment diff -> "
                                      f"model/kinetic_reweight_assignment_diff.csv")
                        except Exception:
                            self._log(f"  [WARN] kinetic_reweight_assignment_diff.csv "
                                      f"export failed: {traceback.format_exc()}")
                    # Kinetic flow-field overview plots (2026-09-25) -- reuse
                    # _kr["assignment_diff"] directly rather than reading the
                    # CSV just written above back off disk. hdb_labels here
                    # is still the PRE-reweight array (the reassignment to
                    # _kr["labels"] happens a few lines below, at
                    # "hdb_labels, hdb_clf = _kr['labels'], _kr['clf']") and
                    # _kr["labels"] is the POST-reweight array, so both
                    # pre/post label arrays are available directly without
                    # any diff-reconstruction trick.
                    if (self._cfg.get("save_plots", True) and _kr["assignment_diff"]):
                        try:
                            plot_kinetic_flow_field_overview(
                                _phase67_embedding, hdb_labels, _kr["labels"],
                                _kr["assignment_diff"],
                                self._out_plots / "kinetic_flow_field_overview.png")
                            self._log("  [PLOT] kinetic_flow_field_overview.png saved")
                        except Exception:
                            self._log(f"  [WARN] kinetic flow-field overview plot "
                                      f"failed: {traceback.format_exc()}")
                        try:
                            plot_kinetic_flow_field_vs_standard_umap(
                                _phase67_embedding, _kr["labels"],
                                self._out_plots / "kinetic_flow_field_vs_standard.png")
                            self._log("  [PLOT] kinetic_flow_field_vs_standard.png saved")
                        except Exception:
                            self._log(f"  [WARN] kinetic flow-field vs standard UMAP "
                                      f"plot failed: {traceback.format_exc()}")
                    # Per-cluster-relative restability trigger (2026-08-30
                    # decision, option A -- a flat percentage of the WHOLE
                    # dataset is a poor proxy when the affected cluster is
                    # large -- a big cluster losing a large fraction of
                    # ITSELF can look small against the total point count.
                    # Computed from the PRE-reweight labels (hdb_labels,
                    # still unmodified at this point -- whichever partition
                    # medoid/consensus/primary handed to this block) so each
                    # affected cluster's own size is the real denominator.
                    _pre_reweight_labels = hdb_labels
                    _restability_pct = float(self._cfg.get(
                        "kinetic_reweight_restability_pct", 25.0) or 25.0)
                    _per_cluster_reassigned: dict = {}
                    for _d in _kr["assignment_diff"]:
                        _oid = _d["old_id"]
                        _per_cluster_reassigned[_oid] = _per_cluster_reassigned.get(_oid, 0) + 1
                    _cluster_sizes = {
                        int(cid): int(np.count_nonzero(_pre_reweight_labels == cid))
                        for cid in _per_cluster_reassigned}
                    _max_cluster_frac = 0.0
                    _max_cluster_id = None
                    for cid, n_reassigned in _per_cluster_reassigned.items():
                        csize = _cluster_sizes.get(cid, 0)
                        if csize <= 0:
                            continue
                        frac = n_reassigned / csize
                        if frac > _max_cluster_frac:
                            _max_cluster_frac, _max_cluster_id = frac, cid

                    hdb_labels, hdb_clf = _kr["labels"], _kr["clf"]
                    hdb_score, hdb_score_label = _kr["score"], _kr["score_label"]
                    _orig_hdb_labels = hdb_labels.copy()
                    # Step 4: re-run the restability recheck against
                    # whichever partition this call just modified, so the
                    # final result (post medoid/consensus AND post reweight)
                    # is still re-validated rather than left as an unchecked
                    # last word. _sweep already reflects whichever remedy
                    # path was taken (primary standalone sweep, medoid's own
                    # sweep, or consensus's derived stats) -- re-sweeping
                    # here keeps cluster_stability.png/the validation report
                    # honest about the TRULY final partition, not a
                    # pre-reweight snapshot of it.
                    #
                    # kinetic_reweight_restability_resweep_enabled (Sep 2026,
                    # default False): this re-sweep NEVER changes hdb_labels/
                    # n_cl/which clustering wins -- by this point medoid/
                    # consensus/reweight have already decided the final
                    # partition. Its only consumers are cluster_stability.png
                    # and _validation["cluster_stability"]'s reported mean_
                    # ari/dbcv/pass-warn status, i.e. reporting freshness, not
                    # correctness. Off by default so a restability trip
                    # doesn't unconditionally cost an extra seed_sweep_n-seed
                    # UMAP+HDBSCAN pass; a trip is still logged either way.
                    _kr_resweep_on = bool(self._cfg.get(
                        "kinetic_reweight_restability_resweep_enabled", False))
                    if _max_cluster_frac >= (_restability_pct / 100.0) and _sweep and not _kr_resweep_on:
                        self._log(f"  [KINETIC-REWEIGHT] cluster {_max_cluster_id} "
                                  f"lost {_max_cluster_frac*100:.2f}% of its own "
                                  f"points (>= {_restability_pct:.2f}% per-cluster "
                                  f"threshold) -- restability re-sweep is off "
                                  f"(kinetic_reweight_restability_resweep_enabled) -- "
                                  f"cluster_stability.png/validation report will "
                                  f"reflect the pre-reweight sweep stats")
                    if _max_cluster_frac >= (_restability_pct / 100.0) and _sweep and _kr_resweep_on:
                        self._log(f"  [KINETIC-REWEIGHT] cluster {_max_cluster_id} "
                                  f"lost {_max_cluster_frac*100:.2f}% of its own "
                                  f"points (>= {_restability_pct:.2f}% per-cluster "
                                  f"threshold) -- re-running seed_sweep_stability() "
                                  f"on the reweighted partition")
                        # consensus_reuse_seed_sweep_fits (Sep 2026): same
                        # reuse + safety gating as _run_consensus_remedy's own
                        # copy -- kinetic reweight never touches feats_sc.T/
                        # self._cfg, only final label assignments, so a seed
                        # already fit by the earlier standalone sweep is
                        # exactly reproducible here and safe to reuse as-is.
                        _kr_reuse_seed_fits = None
                        if (bool(self._cfg.get(
                                    "consensus_reuse_seed_sweep_fits", False))
                                and _sweep.get("seed_fits")
                                and float(self._cfg.get(
                                    "hdbscan_membership_confidence_floor", 0.0) or 0.0) <= 0.0
                                and float(self._cfg.get(
                                    "seed_sweep_train_frac", 1.0) or 1.0) >= 1.0):
                            _kr_reuse_seed_fits = _sweep["seed_fits"]
                        _new_kr_sweep = seed_sweep_stability(
                            feats_sc.T, self._cfg, _n_sweep, log_fn=self._log,
                            session_boundaries=_session_boundaries,
                            order_shape_rows_sc=order_shape_rows_sc,
                            n_order_shape_cols=_n_order_shape_cols,
                            order_shape_weight=_phase2_os_weight,
                            bins_temporally_ordered=_bins_temporally_ordered,
                            feats_prepca=feats_sc_prepca,
                            fps=fps, win100=_win100,
                            primary_fit=_current_fit_for_reuse,
                            precomputed_seed_fits=_kr_reuse_seed_fits,
                            retain_fits_for_reuse=bool(self._cfg.get(
                                "consensus_reuse_seed_sweep_fits", False)))
                        if _new_kr_sweep:
                            _sweep = _new_kr_sweep
                            # Mirrors the main [STABILITY] sweep's own
                            # summary line (mean ARI + per-seed DBCV) --
                            # this re-sweep previously ran with log_fn=None,
                            # so it produced no per-seed progress/heartbeat
                            # output and no summary at all, unlike every
                            # other seed_sweep_stability() call site in this
                            # function.
                            _kr_sc = _new_kr_sweep.get('stable_counts', _new_kr_sweep['counts'])
                            self._log(f"  [KINETIC-REWEIGHT] restability re-sweep: "
                                      f"mean pairwise ARI = {_new_kr_sweep['mean_ari']:.3f} "
                                      f"(cluster counts {min(_kr_sc)}–{max(_kr_sc)} across "
                                      f"seeds used in the mean; full sweep range "
                                      f"{min(_new_kr_sweep['counts'])}–"
                                      f"{max(_new_kr_sweep['counts'])})")
                            _kr_dbcv = [d for d in _new_kr_sweep.get('dbcv', []) if d == d]
                            if _kr_dbcv:
                                self._log(f"  Per-seed DBCV: "
                                          f"{', '.join(f'{d:.3f}' for d in _kr_dbcv)} "
                                          f"(mean {np.mean(_kr_dbcv):.3f}, "
                                          f"range {min(_kr_dbcv):.3f}–{max(_kr_dbcv):.3f})")
                        else:
                            self._log("  [WARN] [KINETIC-REWEIGHT] restability "
                                      "re-sweep returned no usable result -- "
                                      "keeping the pre-reweight sweep stats.")
            except Exception:
                self._log(f"  [WARN] kinetic reweighted re-clustering failed: "
                          f"{traceback.format_exc()}")

        # Free Phase 6/7's large intermediate arrays now that both have
        # fully resolved (whether or not either actually ran) -- none of
        # feats_sc_prepca/order_shape_rows_sc/_feats_for_flow/
        # _flow_field_result's own array fields, or order_shape_cat/
        # order_shape_good/order_shape_sub, are read again anywhere below
        # this point (Phase 6/7 -- now positioned after the medoid/consensus
        # decision -- was their last consumer, same as before this plan
        # moved them). Dropping the reference here (reassign to None, NOT
        # `del locals()[name]` -- locals() inside a function is a snapshot
        # dict in CPython, so mutating it silently does nothing to the real
        # variable binding; plain assignment always succeeds whether the
        # name existed before or not) lets the existing gc.collect() a
        # little further down actually reclaim this memory before the heavy
        # MLP-training/per-session-export stages that follow.
        feats_sc_prepca = None
        order_shape_rows_sc = None
        _feats_for_flow = None
        _flow_field_result = None
        order_shape_cat = None
        order_shape_good = None
        order_shape_sub = None

        # ── Phase 4, TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md: Tier 1
        # kinetic-coherence trigger for local re-clustering. Gated by
        # kinetic_split_trigger_enabled (default False -> true no-op).
        # Runs after the primary split/merge loop above (on whatever
        # partition that loop produced, including the consensus/medoid
        # skip case) so it never duplicates split_impure_clusters()'s own
        # work -- only clusters that already LOOK acceptable spatially are
        # eligible here. embedding/feats_sc/_win100/_session_boundaries are
        # all still the ones this run's HDBSCAN fit actually used.
        if bool(self._cfg.get("kinetic_split_trigger_enabled", False)) and not _bins_temporally_ordered:
            self._log("  [WARN] kinetic_split_trigger_enabled is on but bins "
                      "are not verifiably temporally ordered this run (see "
                      "the WARN above) -- skipping the kinetic split trigger.")
        if bool(self._cfg.get("kinetic_split_trigger_enabled", False)) and _bins_temporally_ordered:
            hdb_labels = split_kinetically_incoherent_clusters(
                feats_sc, embedding, hdb_labels, self._cfg, fps, _win100,
                session_boundaries=_session_boundaries,
                log_fn=self._log, split_events=_split_events,
                posture_entropy_veto=_posture_entropy_scores or None)

        # ── Final region-purity re-screen (opt-in via hdbscan_region_split_
        # enabled) ───────────────────────────────────────────────────────────
        # Both refinement paths above interleave split(region) BEFORE that
        # same iteration's merge step (merge_similar_clusters for primary,
        # merge_by_coassociation for consensus) -- and merge has no region
        # signal at all, only kinematic/co-association similarity. That
        # means a cluster can pass the region-purity screen mid-loop and
        # still end up folded back together with a region-different cluster
        # by the very next merge, with no further check ever re-examining
        # the state that actually ships. Confirmed on a real run: the
        # largest delivered cluster (5265 bins) sat at region entropy 0.687
        # against a 0.5 threshold, 18.3% minority against a 0.15 floor --
        # comfortably past both gates -- while the region-splitter reported
        # zero splits that run.
        #
        # This closes that gap with one more split(region) pass here, AFTER
        # every split/merge iteration has finished and BEFORE rare-cluster
        # pruning -- deliberately with NO merge afterward. That asymmetry is
        # intentional, not an oversight: a user who opted into region-aware
        # splitting is explicitly asking for region identity to win over
        # kinematic-similarity merging for clusters that are still
        # region-mixed once everything else has settled. Letting a merge
        # run after this pass would just re-erase it and reproduce the exact
        # bug being fixed. Same thresholds as the interleaved pass
        # (hdbscan_region_split_impurity_thresh/min_minority_frac/
        # max_subclusters/max_candidates) -- that calibration already looked
        # reasonable against the real entropy distribution above; the bug
        # was structural (never re-checked), not a threshold miscalibration.
        _region_rescreen_on = (bool(self._cfg.get("hdbscan_region_split_enabled", False))
                                and region_per_bin is not None)
        _final_region_split_new_ids: set = set()
        if _region_rescreen_on:
            _before_rescreen = hdb_labels.copy()
            _ids_before_rescreen = set(int(c) for c in set(_before_rescreen) if c >= 0)
            _ev_n0 = len(_split_events)
            hdb_labels = split_region_impure_clusters(
                feats_sc, embedding, hdb_labels, region_per_bin, self._cfg,
                log_fn=self._log, region_split_stats=_region_split_stats,
                split_events=_split_events)
            for _ev in _split_events[_ev_n0:]:
                _ev["phase"] = "final_region_rescreen"
                _ev["iteration"] = None
            if not np.array_equal(_before_rescreen, hdb_labels):
                _final_region_split_new_ids = (
                    set(int(c) for c in set(hdb_labels) if c >= 0) - _ids_before_rescreen)
                self._log(
                    f"  [region-split] final re-screen (post-merge, pre-prune): "
                    f"{len(_final_region_split_new_ids)} new cluster(s) split out of "
                    f"region-impure survivors of the split/merge loop -- no merge "
                    f"follows this pass, so these stay split in the delivered "
                    f"partition (may still be removed by rare-cluster pruning "
                    f"below if too small; see that section's log for a note if so).")
            else:
                self._log("  [region-split] final re-screen: no region-impure "
                          "clusters remained in the delivered partition.")

        n_cl      = len(set(hdb_labels[hdb_labels >= 0]))
        noise     = (hdb_labels < 0).sum()
        noise_pct = 100 * noise / max(1, len(hdb_labels))
        _post_refine_labels = hdb_labels.copy()

        # ── Cross-cluster reclaim (opt-in, 2026-08-31) -- MOVED BEFORE rare-
        # cluster pruning (2026-09-01 fix, real-data investigation: see
        # ORDER_AWARE_DISCARD_HANDOFF_2026-09-01.md's follow-up discussion).
        # Previously ran strictly after pruning, so reclaim_leaked_points()
        # -- which explicitly never touches noise points -- had no chance to
        # rescue any of a large-but-partially-salvageable cluster's genuinely
        # reassignable points before pruning threw the whole thing away
        # (confirmed on real data: consensus's own internal pruning pass
        # removed a 42%-of-training-sample cluster that failed the
        # occurrence_persistence silhouette floor, with zero opportunity for
        # any of its points to be individually judged against every OTHER
        # cluster first). Running reclaim first lets each point be rescued on
        # its own merits if it genuinely belongs elsewhere; only the
        # remainder that reclaim couldn't place better is left for the
        # persistence check to prune -- cluster_reclaim_max_frac_per_cluster
        # still caps how much of any one cluster can move in a single pass,
        # so a genuine dump cluster can't be reclaimed away entirely, and the
        # persistence check still gets a real, meaningful remainder to judge.
        # See reclaim_leaked_points()'s docstring for the method (co-
        # association in consensus mode, feature-space nearest-centroid
        # otherwise) and cluster_reclaim_enabled's DEFAULTS comment for the
        # original real-data motivation (clusters #13/#17,
        # D:\CUBE_Pipeline\Time_CUBE\out_consensus).
        #
        # Correctness note: this reorder does NOT require re-deriving a
        # remap composition here -- the _comprehensive_remap step further
        # below recomputes _hdb_remap FRESH by directly comparing
        # _orig_hdb_labels (truly original HDBSCAN output ids, untouched by
        # either reclaim or pruning) against whatever hdb_labels ends up as
        # the TRULY FINAL, delivered partition -- correct regardless of
        # which order reclaim/pruning ran in, since it only depends on the
        # start and end states, not the intermediate remap bookkeeping.
        if bool(self._cfg.get("cluster_reclaim_enabled", False)):
            hdb_labels, _reclaim_info, _ = reclaim_leaked_points(
                feats_sc.T, hdb_labels, self._cfg,
                co_assoc=_co_assoc_for_reclaim, prior_remap=None,
                log_fn=self._log, session_boundaries=_session_boundaries)
            if _reclaim_info["moved_total"]:
                n_cl = len(set(hdb_labels[hdb_labels >= 0]))
                noise = int((hdb_labels < 0).sum())
                noise_pct = 100 * noise / max(1, len(hdb_labels))
                try:
                    (self._out_model / "reclaim_log.json").write_text(
                        json.dumps(_reclaim_info, indent=2))
                    self._log(f"  [reclaim-log] {_reclaim_info['moved_total']} "
                              f"point(s) reassigned (pre-prune) -> "
                              f"model/reclaim_log.json")
                except Exception:
                    self._log(f"  [WARN] reclaim_log.json export failed: "
                              f"{traceback.format_exc()}")
                self._stage("5/7 — Cross-cluster reclaim",
                            f"{_reclaim_info['moved_total']} point(s) reassigned · "
                            f"{n_cl} clusters · {noise_pct:.0f}% noise")

        # ── Rare-cluster pruning ──────────────────────────────────────────────
        # Drop clusters that fail the configured survival criteria (default
        # "population_fraction": below min_cluster_freq's fraction of total
        # bins -- such clusters represent behaviours so infrequent relative
        # to the whole recording session that they are likely noise
        # fragments, not true states). Pruned labels are reassigned to noise
        # (-1) and the remaining cluster IDs are renumbered contiguously
        # before MLP training. Phase 3.0 (CLUSTER_QUALITY_IMPROVEMENTS_PLAN.md)
        # consolidation: shared with consensus_cluster()'s own pruning block
        # via _prune_rare_clusters() -- renumber_if_unpruned=False preserves
        # this call site's own pre-existing behavior of leaving hdb_labels
        # completely untouched when nothing is pruned. Now runs on the
        # POST-reclaim partition (see the reorder note above) -- any point
        # reclaim already rescued is no longer eligible to be pruned as part
        # of its old (possibly-failing) cluster.
        # _hdb_remap: maps original HDBSCAN cluster IDs → renumbered IDs used in
        # hdb_labels (and therefore in the trained MLP).  Needed to keep the
        # fallback approximate_predict path in sync when pruning has occurred.
        hdb_labels, _hdb_remap, _prune_info = _prune_rare_clusters(
            hdb_labels, feats_sc.T, self._cfg, n_samp, fps=fps,
            win100=_win100, session_boundaries=_session_boundaries,
            renumber_if_unpruned=False, log_fn=self._log)
        _pruned_ids = _prune_info["pruned_ids"]
        if _pruned_ids:
            n_cl = _prune_info["n_cl"]
            noise = _prune_info["noise"]
            noise_pct = _prune_info["noise_pct"]
            if _prune_info["criteria"] == "occurrence_persistence":
                self._log(
                    f"  [rare-cluster prune] Removed {len(_pruned_ids)} cluster(s) "
                    f"failing occurrence/persistence criteria (< {self._cfg.get('min_occurrences', 3)} "
                    f"bouts and/or below min_occurrence_persistence) "
                    f"({', '.join(f'#{i}' for i in _pruned_ids)}) → "
                    f"{n_cl} clusters remain, {noise_pct:.1f}% noise"
                )
                # Per-cluster breakdown (Aug 2026 follow-up): the summary
                # line above can't distinguish "one dominant cluster failed
                # persistence" from "several small clusters failed for an
                # unrelated reason" -- a real 80.9%-final-noise case on real
                # data traced entirely to ONE cluster covering 57.9% of the
                # dataset and required an ad-hoc instrumented script to find,
                # even though every number here was already computed for the
                # pruning decision itself. Sorted biggest-contributor-first.
                _used_floor = _prune_info.get("min_occurrence_persistence_used")
                _floor_label = (f"{_used_floor:.3f}" if _used_floor is not None
                                else f"{float(self._cfg.get('min_occurrence_persistence', 0.0) or 0.0):.3f}")
                for _d in _prune_info["survival_detail"]:
                    _bout_tag = "ok" if _d["bout_ok"] else f"FAIL, need >={self._cfg.get('min_occurrences', 3)}"
                    _sil_tag = "ok" if _d["sil_ok"] else f"FAIL, floor {_floor_label}"
                    self._log(
                        f"    #{_d['cid']}: {_d['frac_pct']:.1f}% of data, "
                        f"{_d['bout_count']} bout(s) ({_bout_tag}), "
                        f"silhouette {_d['silhouette']:.3f} ({_sil_tag})"
                    )
            else:
                _min_freq_pct = _prune_info["min_freq_pct"]
                self._log(
                    f"  [rare-cluster prune] Removed {len(_pruned_ids)} cluster(s) "
                    f"below {_min_freq_pct:.2f}% of total bins "
                    f"({', '.join(f'#{i}' for i in _pruned_ids)}) → "
                    f"{n_cl} clusters remain, {noise_pct:.1f}% noise"
                )
                # Region-rescreen splits are deliberately never re-merged (see
                # that pass's own comment above) -- pruning is left as the
                # ONLY thing allowed to remove one, so a user who wants to
                # keep a small-but-region-distinct cluster the rescreen just
                # carved out has a direct, actionable knob for next time
                # rather than silently losing it with no explanation.
                _pruned_rescreen_ids = _final_region_split_new_ids & set(_pruned_ids)
                if _pruned_rescreen_ids:
                    self._log(
                        f"  [rare-cluster prune] {len(_pruned_rescreen_ids)} of "
                        f"those ({', '.join(f'#{i}' for i in sorted(_pruned_rescreen_ids))}) "
                        f"came from the final region-purity re-screen above -- "
                        f"they were too small to survive min_cluster_freq="
                        f"{_min_freq_pct:.2f}%. Lower min_cluster_freq on the next "
                        f"run if you want region-distinct clusters this small to "
                        f"be kept instead of pruned.")
            self._stage("5/7 — HDBSCAN done",
                        f"{n_cl} clusters (after rare-cluster prune) · "
                        f"{noise_pct:.0f}% noise")

        # (Cross-cluster reclaim now runs BEFORE rare-cluster pruning above --
        # see that reordered block's own comment for the 2026-09-01 fix
        # rationale. This is intentionally no longer a second pass here.)

        # ── Quality-gated noise recovery (opt-in, consensus mode only) ──────
        # Runs AFTER reclaim+prune above -- operates on the fully-final label
        # set, and (deliberately) gets a chance to redistribute salvageable
        # points out of a cluster _prune_rare_clusters() just wholesale-
        # converted to noise (the real-data scenario that motivated this
        # feature: a genuinely large cluster pruned for failing a silhouette
        # floor). The confidence+margin+quality gate should reject most of a
        # genuinely-incoherent pruned cluster's points (no strong
        # co-association to any ONE surviving cluster) while still rescuing
        # individually-salvageable ones -- but this specific pruned-cluster
        # interaction was not covered by the standalone diagnostic that
        # validated this feature's defaults (it only ever saw a single
        # seed's raw noise, not consensus's own final noise including
        # pruned-cluster points), so treat real-run results here as still
        # being validated, not assumed safe by extrapolation.
        #
        # Must run before the _comprehensive_remap / split-event audit
        # sections below, which need to see the TRULY final hdb_labels.
        # Never creates or empties a cluster id (only moves a point from
        # noise into an ALREADY-existing real cluster), so it needs no
        # remap contribution of its own -- _comprehensive_remap's own
        # before/after diff (using _orig_hdb_labels vs. hdb_labels) already
        # covers it correctly.
        if _consensus_used and bool(self._cfg.get("consensus_noise_recovery_enabled", False)):
            if _co_assoc_for_reclaim is None:
                self._log("  [WARN] consensus_noise_recovery_enabled=True but "
                          "no co-association matrix is available for this run "
                          "-- skipping quality-gated noise recovery.")
            else:
                hdb_labels, _recovery_info = recover_consensus_noise(
                    hdb_labels, _co_assoc_for_reclaim, self._cfg, log_fn=self._log)
                if _recovery_info["recovered_total"]:
                    n_cl = len(set(hdb_labels[hdb_labels >= 0]))
                    noise = int((hdb_labels < 0).sum())
                    noise_pct = 100 * noise / max(1, len(hdb_labels))
                    try:
                        (self._out_model / "noise_recovery_log.json").write_text(
                            json.dumps(_recovery_info, indent=2))
                        self._log(f"  [noise-recovery-log] "
                                  f"{_recovery_info['recovered_total']} point(s) "
                                  f"recovered from noise -> "
                                  f"model/noise_recovery_log.json")
                    except Exception:
                        self._log(f"  [WARN] noise_recovery_log.json export "
                                  f"failed: {traceback.format_exc()}")
                    self._stage("5/7 — Noise recovery",
                                f"{_recovery_info['recovered_total']} point(s) "
                                f"recovered · {n_cl} clusters · {noise_pct:.0f}% noise")

        # Guided labelling: poorly tracked / turned-away bins reclustered among themselves (labels prove purity).
        _g_groups = _g_names = None
        _gctx_p = getattr(self, "_guided_ctx", None)
        if (_gctx_p is not None and bool(self._cfg.get("guided_poor_recluster_enabled", True))
                and _train_orig_bin_idx is not None):
            try:
                self._stage("5/7 ? Applying your labels", "reclustering poorly tracked / turned-away bins?")
                from cube_guided_poor import poor_tracking_mask as _pt_mask, recluster_poor as _pt_recluster
                from cube_guided_dynamics import win100_for as _w100
                _pt_g = _pt_mask(all_ll, [f.shape[1] for f in all_feats], [_w100(f) for f in all_fps_list],
                                 _orig_ta_global, float(self._cfg.get("guided_poor_quantile", 0.2)))
                hdb_labels, _pt_info = _pt_recluster(
                    hdb_labels, feats_sc.T, _pt_g[np.asarray(_train_orig_bin_idx)], _gctx_p, log=self._log)
                if not _pt_info.get("ran"):
                    self._log(f"  [GUIDED] poor-tracking recluster not applied: {_pt_info.get('reason', '')}")
                if _pt_info.get("moved"):
                    n_cl = len(set(hdb_labels[hdb_labels >= 0]))
                    noise = int((hdb_labels < 0).sum())
                try:
                    (self._out_model / "guided_poor_recluster.json").write_text(
                        json.dumps(_pt_info, indent=2, default=str))
                except Exception:
                    pass
            except Exception as _pt_e:
                self._log(f"  [GUIDED] WARN: poor-tracking recluster skipped ({_pt_e}).")

        if _gctx_p is not None and bool(self._cfg.get("guided_labelled_plots_enabled", True)):
            try:
                from cube_guided_report import behaviour_groups as _bgrp, cluster_names as _cnames
                _g_groups = _bgrp(_gctx_p, hdb_labels) or None
                _g_names = _cnames(_g_groups) if _g_groups else None
                if _g_groups:
                    _multi_b = {b: c for b, c in _g_groups.items() if len(c) > 1}
                    self._log(f"  [GUIDED] behaviour groups from your labels: {len(_g_groups)} behaviour(s), "
                              f"{sum(len(c) for c in _g_groups.values())} cluster(s)"
                              + (f"; made of several clusters: {_multi_b}" if _multi_b else "."))
            except Exception as _gn_e:
                self._log(f"  [GUIDED] WARN: behaviour naming skipped ({_gn_e}).")

        # region_split_pre_reduction_pct audit line (Design decision 4): a
        # clear before/after report so a user can see how close the organic
        # split-driven result landed to their real target, without the
        # pipeline pretending to guarantee a specific final count. Only
        # logged when region-aware splitting is actually active -- silent
        # otherwise, matching every other opt-in diagnostic in this pipeline.
        _region_split_clusters_created = int(_region_split_stats.get("clusters_created", 0))
        if _region_split_master:
            _post_refine_n_cl = len(set(_post_refine_labels[_post_refine_labels >= 0]))
            self._log(
                f"  [region-split] cluster-count trace: "
                f"{_raw_primary_n_cl} raw (primary sweep) -> "
                f"{_post_refine_n_cl} after split/merge refinement -> "
                f"{n_cl} final (after rare-cluster prune) "
                f"[original preferred_clusters range: {_orig_pref_lo}-{_orig_pref_hi}"
                + (f", pre-reduced to {round(max(2, _orig_pref_lo * _pre_reduction_pct))}-"
                   f"{round(max(2, _orig_pref_hi * _pre_reduction_pct))} for the primary sweep only]"
                   if _pre_reduction_pct > 0 else "]"))
            self._log(
                f"  [region-split] {_region_split_clusters_created} cluster(s) "
                f"created by region-aware splitting this run"
                + (f" -- some may have since been merged and/or pruned below "
                   f"(final count reflects that, but which specific ids were "
                   f"region-split in origin is not tracked past this point)"
                   if _region_split_clusters_created > 0 else "."))

        # Compose a comprehensive ORIGINAL-hdbscan-id -> final-id remap when
        # split/merge refinement and/or rare-cluster pruning changed anything,
        # so the approximate_predict fallback path (which only ever sees
        # hdb_clf's ORIGINAL output ids) stays correctly mapped end-to-end.
        # NOTE: split_impure_clusters can in principle send different points
        # of one original cluster to different final ids; this 1:1 remap uses
        # one representative point per original id (exact for merge/prune,
        # which always move a whole cluster together — the overwhelmingly
        # common case since the fallback path only runs when mlp_clf is None,
        # i.e. < 2 clusters were found, leaving little room for split/merge to
        # act in the first place).
        if not np.array_equal(_orig_hdb_labels, hdb_labels) or _hdb_remap:
            _comprehensive_remap = {}
            for _oid in sorted(set(int(x) for x in _orig_hdb_labels if x >= 0)):
                _pos = np.flatnonzero(_orig_hdb_labels == _oid)
                if _pos.size:
                    _comprehensive_remap[_oid] = int(hdb_labels[_pos[0]])
            _hdb_remap = _comprehensive_remap

        # ── Split-event audit trail: resolve to FINAL ids/sizes, export ────
        # hdb_labels is now truly final (post split/merge refinement, post
        # rare-cluster pruning, post remap) -- exactly the array
        # cluster_validity.png/cluster_hierarchy_*.png/umap_embedding.png
        # etc. are about to be drawn from below. Each event's children were
        # recorded against the (working-id, but same bin-index-space)
        # labels array at split time; look each child's bins up against
        # hdb_labels NOW so a child that was later merged into another
        # cluster, re-split again, pruned to noise, or simply renumbered is
        # reported as what it actually became, not a stale snapshot.
        if _split_events:
            for _ev in _split_events:
                for _child in _ev.get("children", []):
                    _bidx = _child.pop("bin_idx", [])
                    if _bidx:
                        _final_lbls = hdb_labels[np.array(_bidx, dtype=int)]
                        _fu, _fc = np.unique(_final_lbls, return_counts=True)
                        _child["final"] = [
                            {"id": int(f), "count": int(c)}
                            for f, c in zip(_fu.tolist(), _fc.tolist())]
                    else:
                        _child["final"] = []
            try:
                (self._out_model / "split_merge_log.json").write_text(
                    json.dumps(_split_events, indent=2))
                self._log(f"  [split-log] {len(_split_events)} split event(s) "
                          f"(parent -> children, before/after sizes) -> "
                          f"model/split_merge_log.json")
            except Exception:
                self._log(f"  [WARN] split_merge_log.json export failed: "
                          f"{traceback.format_exc()}")

        # ── Split lineage for the dendrogram (general CUBE feature) ─────────
        # {final_child_id: "{tag}{parent_id}"} -- e.g. {18: "T17", 21: "T17"}
        # means clusters #18/#21 were split off from #17 for a Temporal
        # reason. Built from the SAME final-id-resolved _split_events used
        # for split_merge_log.json above, so it's automatically correct
        # regardless of any later renumbering/pruning. Only the NEW child
        # id(s) of a split are tagged -- never the child that kept the
        # parent's own id (tagging a cluster with its own id would be
        # redundant noise, not information). A child whose bins ended up
        # split across multiple final ids (rare -- e.g. later merged
        # piecemeal) is attributed to whichever final id holds the most of
        # its bins.
        _SPLIT_SOURCE_TAG = {"silhouette": "S", "region": "R",
                              "kinetic_coherence": "T"}
        _split_lineage: dict = {}
        if _split_events:
            for _ev in _split_events:
                _tag = _SPLIT_SOURCE_TAG.get(_ev.get("source"), "?")
                _parent = int(_ev.get("parent_id"))
                for _child in _ev.get("children", []):
                    _final_list = _child.get("final") or []
                    if not _final_list:
                        continue
                    _final_id = int(max(_final_list, key=lambda f: f["count"])["id"])
                    if _final_id == _parent or _final_id < 0:
                        continue
                    _split_lineage[_final_id] = f"{_tag}{_parent}"

        # ── Auto-flag unresolved impure clusters ────────────────────────────
        # Runs on the FINAL (post-refinement, post-pruning) hdb_labels, in the
        # PRIMARY embedding -- the same embedding/labels split_impure_clusters
        # itself scores candidates in, so this uses an identical yardstick.
        # Deliberately does NOT touch hdb_labels/n_cl/_hdb_remap (the cluster
        # stays real for MLP training) -- see auto_flag_impure_clusters'
        # DEFAULTS docstring for why this is a display-layer remap, applied
        # per session below, not a training-time exclusion.
        _auto_impure_ids: set = set()
        if bool(self._cfg.get("auto_flag_impure_clusters", True)) and n_cl >= 2:
            if not _exclude_turned_away:
                self._log("  [IMPURE] auto_flag_impure_clusters=True but "
                          "exclude_turned_away=False -- no reserved display id "
                          "to route into, skipping.")
            else:
                _impure_thresh = float(
                    self._cfg.get("auto_flag_impure_silhouette_thresh", 0.0) or 0.0)
                if _impure_thresh <= 0:
                    _impure_thresh = float(
                        self._cfg.get("hdbscan_split_silhouette_thresh", 0.0) or 0.0)
                if _impure_thresh > 0:
                    _, _impure_sil_means = _mean_silhouette_per_cluster(
                        embedding, hdb_labels)
                    # Worst-first: sorted by silhouette ascending, so a
                    # forced cap below (the <2-real-clusters safety margin)
                    # keeps the WORST offenders and spares the least-bad
                    # ones, rather than an arbitrary id-order truncation.
                    _candidates = sorted(
                        (c for c, m in _impure_sil_means.items() if m < _impure_thresh),
                        key=lambda c: _impure_sil_means[c])
                    # Never flag away every real cluster (or down to fewer
                    # than 2) -- leaves the MLP with < 2 classes to train on,
                    # a hard failure elsewhere in run(). Same safety margin
                    # as the "< 2 clusters" guards already used around
                    # HDBSCAN/consensus. Cap to the worst offenders instead
                    # of skipping the whole pass when ALL candidates would
                    # breach the floor -- e.g. 3 clusters, 2 flagged as
                    # impure: flag just the worse of the two rather than
                    # flagging neither.
                    _gq = guided_active()
                    if _gq is not None and _candidates:
                        # guided labelling: a cluster with real user-labelled evidence is never relabelled
                        # "low quality" (that would overwrite the user's ground truth in the exported labels)
                        _prot_g = _gq.protected_clusters(hdb_labels)
                        _kept_g = [c for c in _candidates if int(c) not in _prot_g]
                        if len(_kept_g) != len(_candidates):
                            _skipped_g = [int(c) for c in _candidates if int(c) in _prot_g]
                            self._log(f"  [IMPURE] cluster(s) {_skipped_g} spared: they carry user-labelled "
                                      f"evidence (guided labels).")
                            _gq.note("impure_flag_skipped", clusters=_skipped_g)
                        _candidates = _kept_g
                    _max_flaggable = max(0, n_cl - 2)
                    if _candidates and _max_flaggable == 0:
                        self._log(
                            f"  [WARN] {len(_candidates)} cluster(s) below the "
                            f"impure-cluster threshold, but this run only has "
                            f"{n_cl} real cluster(s) total -- flagging any "
                            f"would leave < 2 real clusters, skipping "
                            f"auto-flag entirely for this run.")
                    elif _candidates:
                        _capped = len(_candidates) > _max_flaggable
                        if _capped:
                            self._log(
                                f"  [WARN] {len(_candidates)} cluster(s) below "
                                f"the impure-cluster threshold, but flagging "
                                f"all of them would leave < 2 real clusters -- "
                                f"flagging only the worst {_max_flaggable} "
                                f"(by silhouette) and leaving the rest as real "
                                f"clusters.")
                        _flag_ids = _candidates[:_max_flaggable]
                        _auto_impure_ids = set(_flag_ids)
                        self._log(
                            f"  [IMPURE] cluster(s) "
                            f"{', '.join(f'#{c} (silhouette={_impure_sil_means[c]:.3f})' for c in _flag_ids)} "
                            f"remain below the impure-cluster threshold "
                            f"({_impure_thresh}) after refinement -- auto-"
                            f"flagging as low-quality and folding into the "
                            f"'Turned Away' display bucket "
                            f"(auto_flag_impure_clusters=True). These stay "
                            f"real classes in the trained MLP; only the "
                            f"per-session CSV/plot labels are remapped.")

        # Feature-space DBCV/silhouette (Aug 2026): computed on the FINAL
        # (post-refinement, post-pruning) hdb_labels -- matches
        # consensus_cluster()'s own feature-space scoring, which (as of this
        # same change) is also computed on ITS final post-refinement/pruning
        # labels, not an intermediate candidate -- so the two numbers
        # describe the actual DELIVERED partition in both cases and are
        # directly comparable, unlike separation_ratio vs. embedding-space
        # DBCV. Skipped here for consensus mode: already computed and logged
        # right after consensus_cluster() returned (same final labels --
        # nothing between there and here changes them, the rare-cluster
        # pruning above is a no-op re-application for consensus, which
        # already pruned with the same min_cluster_freq/denominator).
        if _consensus_used:
            self._log("  [feature-space] DBCV/silhouette already reported "
                      "above (consensus_cluster()'s own final-partition score)")
        else:
            try:
                _dbcv_fs = _dbcv_feature_space(feats_sc.T, hdb_labels, log_fn=self._log)
                _sil_fs  = validate_clustering(feats_sc.T, hdb_labels).get("silhouette_score")
                self._log(f"  [feature-space] DBCV={_dbcv_fs}  silhouette={_sil_fs} "
                          f"(comparable across configs, incl. consensus mode)")
            except Exception:
                self._log(f"  [WARN] feature-space DBCV/silhouette: "
                          f"{traceback.format_exc()}")

        # Validation gate 4: clustering quality (silhouette)
        # Skipped for consensus OR medoid mode: silhouette here is computed
        # against the PRIMARY single-seed embedding, which neither consensus
        # nor medoid labels are derived from (consensus: co-association
        # across many seeds' independent embeddings; medoid: one OTHER
        # seed's own independent embedding) -- that mismatch produces a
        # misleading low score even when the actual partition is fine. Not a
        # meaningful check for either path, so skip rather than report a
        # number that doesn't mean what it normally means.
        if _consensus_used or _medoid_used:
            _remedy_label = "consensus" if _consensus_used else "medoid"
            self._log(f"  [VALID] clustering-quality gate skipped for "
                      f"{_remedy_label} mode (see separation_ratio / mean "
                      f"ARI above instead)")
        else:
            try:
                _validation["clustering"] = validate_clustering(embedding,
                                                                hdb_labels)
                for w in _validation["clustering"]["warnings"]:
                    lvl = "[VALID-BLOCK]" if _validation["clustering"]["blocked"] \
                          else "[VALID-WARN]"
                    self._log(f"  {lvl} {w}")
                if _validation["clustering"].get("blocked"):
                    self._stage("VALIDATION BLOCK",
                                f"clustering quality: {_validation['clustering']['warnings'][0]}"
                                if _validation["clustering"]["warnings"] else "silhouette < 0")
                elif _validation["clustering"]["warnings"]:
                    self._stage("VALIDATION WARN",
                                f"clustering: {_validation['clustering']['warnings'][0]}")
            except Exception as e:
                self._log(f"  [VALID] Clustering validation failed: {e}")

        # ── Cluster validity diagnostic plot (issue 3) ─────────────────────────
        if self._cfg["save_plots"]:
            try:
                plot_cluster_validity(embedding, hdb_labels, feats_sc.T,
                                      self._out_plots / "cluster_validity.png",
                                      hdb_clf=hdb_clf)
                self._log("  [PLOT] cluster_validity.png saved")
            except Exception:
                self._log(f"  [WARN] cluster_validity plot: "
                          f"{traceback.format_exc()}")

            if self._cfg.get("cluster_hierarchy_enabled", True):
                # Always save BOTH theme variants regardless of this run's
                # active plot_theme -- unlike every other plot in the suite
                # (which only ever needs to match the GUI's current theme),
                # this one is meant to be pulled into external docs/talks in
                # whichever theme fits the destination, so it saves both up
                # front rather than requiring a full re-run to get the other.
                _hierarchy_theme_before = str(self._cfg.get("plot_theme", "dark"))
                # region_composition (Phase 7): None whenever region_per_bin
                # was never computed (hdbscan_region_split_enabled=False,
                # the default) -- a true no-op, byte-identical dendrogram to
                # pre-Phase-7 output in that case.
                _region_composition = compute_cluster_region_composition(
                    hdb_labels, region_per_bin)
                # Which FINAL cluster ids trace back to a successful region-
                # aware split this run (any of their bins came from a
                # candidate cluster split() actually accepted) -- computed
                # at the bin level via region_split_stats["touched_bin_idx"]
                # (populated inside split_region_impure_clusters(), see its
                # call to _local_recluster_and_assign) so it stays correct
                # regardless of subsequent merges/renumbering, which only
                # ever move bins between id VALUES, never between rows.
                # None whenever region-aware splitting never ran.
                _region_split_marked_ids = None
                if _region_split_stats.get("touched_bin_idx"):
                    _touched_mask = np.zeros(hdb_labels.shape[0], dtype=bool)
                    _touched_mask[np.array(_region_split_stats["touched_bin_idx"], dtype=int)] = True
                    _region_split_marked_ids = set(
                        int(c) for c in sorted(set(hdb_labels[hdb_labels >= 0]))
                        if _touched_mask[hdb_labels == c].any())
                try:
                    for _theme_name in ("dark", "light"):
                        _apply_plot_theme(_theme_name)
                        plot_cluster_hierarchy(
                            feats_sc.T, hdb_labels,
                            self._out_plots / f"cluster_hierarchy_{_theme_name}.png",
                            linkage_method=str(self._cfg.get("cluster_hierarchy_linkage", "ward")),
                            centroid_out_path=(
                                self._out_model / "cluster_feature_centroids.npz"
                                if _theme_name == "dark" else None),
                            region_composition=_region_composition,
                            region_split_marked_ids=_region_split_marked_ids,
                            split_lineage=_split_lineage,
                            auto_impure_ids=_auto_impure_ids,
                            cluster_names=_g_names, behaviour_groups=_g_groups)
                    self._log("  [PLOT] cluster_hierarchy_dark.png + "
                              "cluster_hierarchy_light.png saved")
                    self._log("  [PLOT] cluster_feature_centroids.npz saved")
                except Exception:
                    self._log(f"  [WARN] cluster_hierarchy plot: "
                              f"{traceback.format_exc()}")
                finally:
                    _apply_plot_theme(_hierarchy_theme_before)

            # Split/merge before/after diagnostic — only when refinement
            # actually changed something (skip a no-op plot when the pass
            # was off, or ran but converged with zero changes). Uses the
            # pre-/post-refinement snapshots, NOT the final (post-pruning)
            # hdb_labels, so this isolates split/merge + everything between
            # the unified post-decision refinement call and rare-cluster
            # pruning from that separate renumbering. UNIFIED_POST_DECISION_
            # REFINEMENT_PLAN.md (2026-09-06): _pre_refine_labels is now
            # snapshotted BEFORE Phase 6/7 (the refinement call moved ahead
            # of the flow-field/kinetic-reweight stage, matching consensus's
            # own earlier-refinement timing) -- so this diff now also
            # reflects Phase 6/7's kinetic reweighting and the Phase 4
            # kinetic-split-trigger pass, not split/merge refinement alone.
            # Still real and still useful (it shows every change made to the
            # partition between the decision and rare-cluster pruning), just
            # a wider window than before this plan.
            if not np.array_equal(_pre_refine_labels, _post_refine_labels):
                try:
                    plot_split_merge_refinement(
                        embedding, _pre_refine_labels, _post_refine_labels,
                        self._out_plots / "split_merge_refinement.png")
                    self._log("  [PLOT] split_merge_refinement.png saved")
                except Exception:
                    self._log(f"  [WARN] split_merge_refinement plot: "
                              f"{traceback.format_exc()}")
                try:
                    plot_split_merge_zoom_insets(
                        embedding, _pre_refine_labels, _post_refine_labels,
                        self._out_plots / "split_merge_zoom_insets.png")
                    self._log("  [PLOT] split_merge_zoom_insets.png saved")
                except Exception:
                    self._log(f"  [WARN] split_merge_zoom_insets plot: "
                              f"{traceback.format_exc()}")
                try:
                    plot_split_merge_sankey(
                        _pre_refine_labels, _post_refine_labels,
                        self._out_plots / "split_merge_sankey.html")
                    self._log("  [PLOT] split_merge_sankey.html saved")
                except Exception:
                    self._log(f"  [WARN] split_merge_sankey plot: "
                              f"{traceback.format_exc()}")

        # ── Cluster-stability validation + plot ─────────────────────────────
        # _sweep was already computed earlier (before the consensus-clustering
        # decision, which needs mean_ari) -- just report/plot it here now that
        # self._out_plots exists. See the seed-sweep block above for the
        # actual UMAP+HDBSCAN re-runs (not duplicated here).
        if _sweep:
            try:
                _validation["cluster_stability"] = {
                    "stage": "cluster_stability", "status":
                        "pass" if _sweep["mean_ari"] >= 0.7 else "warn",
                    "mean_ari": round(_sweep["mean_ari"], 4),
                    "cluster_counts": _sweep["counts"],
                    "dbcv_scores": [round(d, 4) if d == d else None
                                    for d in _sweep.get("dbcv", [])],
                    "warnings": ([] if _sweep["mean_ari"] >= 0.7 else
                                 [f"Mean ARI {_sweep['mean_ari']:.3f} < 0.7: "
                                  "cluster partition is seed-sensitive."
                                  + (" Consensus clustering was auto-enabled "
                                     "for this run to compensate."
                                     if _auto_triggered else "")]),
                    # MEDOID_CONSENSUS_COMPOSITE_METRIC (2026-09-06): surface
                    # the second (feature-space DBCV) condition of the
                    # medoid-adopt-vs-escalate composite gate in the
                    # machine-readable report too, not just the log line --
                    # only meaningful when medoid was actually the path
                    # evaluated (None fields otherwise, e.g. straight
                    # consensus via partition_remedy_method="consensus").
                    "medoid_composite_gate": (
                        {"medoid_dbcv_fs": round(_medoid_dbcv_fs, 4) if _medoid_dbcv_fs == _medoid_dbcv_fs else None,
                         "primary_dbcv_fs": round(_primary_dbcv_fs, 4) if _primary_dbcv_fs == _primary_dbcv_fs else None,
                         "tolerance": _medoid_dbcv_tolerance,
                         "regressed": _medoid_dbcv_regressed,
                         "adopted": bool(_medoid_used)}
                        if _medoid_dbcv_fs == _medoid_dbcv_fs or _medoid_used or _consensus_used
                        else None),
                }
                if self._cfg["save_plots"]:
                    plot_cluster_stability(
                        _sweep, self._out_plots / "cluster_stability.png",
                        medoid_dbcv_fs=_medoid_dbcv_fs, primary_dbcv_fs=_primary_dbcv_fs,
                        medoid_dbcv_tolerance=_medoid_dbcv_tolerance,
                        medoid_used=bool(_medoid_used), consensus_used=bool(_consensus_used))
                    plot_cluster_volatility(
                        _sweep, self._out_plots / "cluster_volatility.png")
            except Exception:
                self._log(f"  [WARN] cluster-stability plot/validation: "
                          f"{traceback.format_exc()}")

        # 2D and 3D UMAP plots are generated after inference (below) so that
        # they can be filtered to show only clusters actually predicted by the
        # MLP on these sessions — keeping the cluster count consistent across
        # umap_embedding.png, umap_3d.*, and dwell_time_distributions.png.

        # Save UMAP embedding + cluster labels as numpy arrays so cube_analyser
        # can display before/after UMAP views when the user recombines clusters.
        # embedding_save is full-size (n_bins rows); excluded bins (flat-held
        # and/or turned-away) projected via transform() so
        # session_bin_ranges.json slice indices remain valid.
        # hdb_labels_all expands hdb_labels to n_bins with -1 for excluded bins.
        if n_samp == n_good and n_excl == 0:
            # All bins were used for UMAP/HDBSCAN training — lengths already match.
            hdb_labels_all = hdb_labels
        else:
            # Either flat-held/turned-away bins were excluded, or train_frac
            # subsampling occurred (or both) — map each label back to its
            # original bin position so umap_labels.npy stays the same length
            # as umap_embedding.npy (n_bins). Untrained positions (held-out
            # good bins, excluded bins) get -1 (noise) since HDBSCAN never
            # clustered them.
            hdb_labels_all = np.full(n_bins, -1, dtype=int)
            _good_positions = (np.where(~exclude_mask)[0] if n_excl > 0
                                else np.arange(n_bins))
            if n_samp == n_good:
                hdb_labels_all[_good_positions] = hdb_labels
            else:
                hdb_labels_all[_good_positions[idx]] = hdb_labels
        try:
            np.save(str(self._out_model / "umap_embedding.npy"), embedding_save)
            np.save(str(self._out_model / "umap_labels.npy"),    hdb_labels_all)
            # Feature-space cache (2026-09-06): the scaled feature matrix
            # aligned to hdb_labels_all, same n_bins-length/NaN-fill
            # expansion convention used for hdb_labels_all itself above --
            # lets an offline audit (e.g. comparing the split-trigger's
            # embedding-space silhouette against a feature-space signal, see
            # the B-SoiD-standalone-improvement investigation) reuse the
            # real production feature matrix directly instead of re-running
            # DLC feature extraction from scratch. feats_sc is (n_features,
            # n_samp) here (transposed storage convention throughout this
            # module); n_samp is the count HDBSCAN actually clustered
            # (train_frac-subsampled and/or exclude_mask-filtered relative
            # to n_bins), same as hdb_labels before its n_bins expansion.
            if n_samp == n_good and n_excl == 0:
                feats_sc_all = feats_sc.T.astype(np.float32)
            else:
                feats_sc_all = np.full((n_bins, feats_sc.shape[0]), np.nan, dtype=np.float32)
                if n_samp == n_good:
                    feats_sc_all[_good_positions] = feats_sc.T
                else:
                    feats_sc_all[_good_positions[idx]] = feats_sc.T
            # Full-coverage companion (guided labelling): the same transform applied to EVERY bin, including the
            # turned-away / flat-held bins excluded from training and the train_frac held-out ones, which are
            # NaN rows in feats_sc above. Lets the Guided tab label and train on those bins. Only written when
            # some rows were NaN-filled; training rows are identical to feats_sc (the 1e-4 dedup jitter aside).
            _feats_all = None
            if not (n_samp == n_good and n_excl == 0):
                try:
                    _fa = scaler.transform(feats_cat.T).T
                    _fa = _scale_visibility_block(_fa, _n_vis_cols, _vis_weight, features_on_axis0=True)
                    _fa = _scale_visibility_block(_fa, _n_isolated_limb_cols, _isolated_limb_weight,
                                                  features_on_axis0=True, tail_offset=_n_vis_cols)
                    _fa = _scale_visibility_block(_fa, _n_prox_cols, _prox_weight, features_on_axis0=True,
                                                  tail_offset=_n_vis_cols + _n_isolated_limb_cols)
                    if pca_model is not None:
                        _fa = pca_model.transform(_fa.T).T
                    _feats_all = _fa.T.astype(np.float32)
                except Exception:
                    _feats_all = None
            np.savez_compressed(str(self._out_model / "feats_sc_cache.npz"),
                                 feats_sc=feats_sc_all,
                                 **({"feats_all": _feats_all} if _feats_all is not None else {}))
        except Exception:
            pass

        # Cluster centroids (issue 1a) — mean embedding coordinate per cluster,
        # used to pick example clips by embedding proximity instead of nearest-
        # to-median-duration (see attach_centroid_distance / create_example_clips
        # below), and reused by the merge pass above.
        _cluster_centroids = compute_cluster_centroids(embedding_save, hdb_labels_all)
        self._mem_checkpoint("5/7 HDBSCAN clustering done")

        # NOTE: the user-facing kinetic_coherence.csv/.png export used to be
        # computed HERE, on the pre-MLP/pre-HMM `hdb_labels` training
        # partition. That materially overstated real-world bout recurrence
        # (e.g. a real run showed bout_count=481 for a cluster whose actual
        # post-HMM *_bout_lengths_hmm.csv files across all sessions totalled
        # 8 bouts) because hdb_labels is never what ends up in the
        # user-facing *_bout_lengths_hmm.csv / *_frame_labels_hmm.csv /
        # ethogram / example-clip outputs -- those are all post-MLP+HMM.
        # The export has been MOVED to just after the per-session
        # inference+HMM loop below (search for "kinetic-coherence (post-HMM)"),
        # where all_hmm_labels/all_fps_list are available, so it now scores
        # the same post-HMM per-session labels the rest of the pipeline's
        # user-facing output is built from. hdb_labels itself is still used,
        # unchanged, by the OTHER _kinetic_coherence_score() call sites
        # (Phase 4 split-trigger, Phase 5 embedding-stability retry) that
        # run before MLP/HMM exist and are intentionally pre-HMM,
        # clustering-time diagnostics -- only this end-user export moved.

        # 6. MLP (frame-generalization classifier -- default RandomForest since
        # 2026-09-07, see train_mlp() docstring; "mlp_clf" name kept for
        # API/pkl-key compatibility regardless of which classifier it holds)
        _clf_kind = str(self._cfg.get("mlp_classifier", "random_forest"))
        _clf_desc = (f"hidden={self._cfg['mlp_hidden']}" if _clf_kind == "mlp"
                     else f"RandomForest n_estimators={self._cfg.get('rf_n_estimators', 300)} "
                          f"class_weight={self._cfg.get('rf_class_weight', 'balanced')}")
        self._log(f"\n[6/7]  Training frame-generalization classifier  ({_clf_desc})...")
        self._stage("6/7 — Training classifier", f"{_clf_desc} · {n_cl} classes")
        mlp_clf, cv_scores = train_mlp(feats_sc, hdb_labels, self._cfg)
        if mlp_clf is not None:
            self._log(f"  CV accuracy: {cv_scores.mean():.3f} "
                      f"+/- {cv_scores.std():.3f}")
            self._log("  [NOTE] CV accuracy measures how separable the HDBSCAN "
                      "clusters are in feature space (classifier self-consistency), "
                      "NOT behavioral validity. It is computed on non-noise bins "
                      "only; it does not validate the noise fraction or the "
                      "biological meaning of clusters.")
            self._stage("6/7 — MLP done",
                        f"CV accuracy {cv_scores.mean():.3f} "
                        f"± {cv_scores.std():.3f}")
            # Validation gate 5: classifier accuracy
            try:
                _validation["mlp_accuracy"] = validate_mlp_accuracy(cv_scores)
                for w in _validation["mlp_accuracy"]["warnings"]:
                    lvl = "[VALID-BLOCK]" if _validation["mlp_accuracy"][
                        "blocked"] else "[VALID-WARN]"
                    self._log(f"  {lvl} {w}")
                if _validation["mlp_accuracy"].get("blocked"):
                    self._stage("VALIDATION BLOCK",
                                f"MLP accuracy {cv_scores.mean():.3f} — at-chance performance")
                elif _validation["mlp_accuracy"]["warnings"]:
                    self._stage("VALIDATION WARN",
                                f"MLP accuracy {cv_scores.mean():.3f} — marginal classifier")
            except Exception as e:
                self._log(f"  [VALID] MLP accuracy check failed: {e}")
            if self._cfg["save_plots"]:
                try:
                    plot_confusion(mlp_clf, feats_sc, hdb_labels,
                                   self._out_plots / "confusion_matrix.png")
                    plot_cv_scores(cv_scores,
                                   self._out_plots / "cv_accuracy.png")
                except Exception:
                    pass
        else:
            self._log("  [WARN] < 2 clusters — MLP not trained.")
            self._stage("6/7 — MLP skipped", "< 2 clusters found")

        # Save model (includes bodyparts for V2 prediction consistency)
        model_path = self._out_model / "bsoid_model.pkl"
        with open(str(model_path), "wb") as fh:
            pickle.dump(dict(
                umap_model  = umap_model,
                hdb_clf     = hdb_clf,
                mlp_clf     = mlp_clf,
                scaler      = scaler,
                pca_model   = pca_model,
                cv_scores   = cv_scores.tolist(),
                fps         = fps,
                cfg         = self._cfg,
                bodyparts   = bps_ref,
                n_clusters  = int(n_cl),
                feature_ver = "v2",
                analysis_version = ANALYSIS_VERSION,
                compat_mode = self._cfg.get("compat_mode", "current"),
                created     = datetime.now().isoformat(),
            ), fh)
        self._log(f"  Model saved -> {model_path}")

        (self._out_model / "feature_config.json").write_text(
            json.dumps(dict(fps=fps, bodyparts=bps_ref,
                            boxcar_win_sec=self._cfg["boxcar_win_sec"],
                            n_features=int(feats_cat.shape[0]),
                            feature_version="v3d" if _is_3d else "v2",
                            analysis_version=ANALYSIS_VERSION,
                            compat_mode=self._cfg.get("compat_mode", "current"),
                            pca_n_components=(int(pca_model.n_components_)
                                              if pca_model is not None else None),
                            lr_symmetrize_features_enabled=_lr_symmetrize,
                            withinbin_variance_rotation_invariant=_withinbin_rot_inv),
                       indent=2))

        self._mem_checkpoint("6/7 MLP training + model save done")

        # 7. Predict & export
        self._log("\n[7/7]  Predicting & exporting...")
        self._stage("7/7 — Predicting & exporting", f"0/{len(pairs)} sessions")
        bout_paths, frame_paths, all_epochs, all_frame_labels = [], [], [], []
        # _need_bin_detail: True when B.2 (bin-level HMM smoothing) or B.1
        # (soft-probability HMM emissions) needs predict_labels()'s new
        # per-bin detail (see predict_labels' return_proba docstring). False
        # (both new modes off, the default) means predict_labels() is called
        # exactly as before -- same call, same single-array return type.
        _hmm_smoothing_level = str(self._cfg.get("hmm_smoothing_level", "frame"))
        _hmm_emission_mode   = str(self._cfg.get("hmm_emission_mode", "categorical"))
        _need_bin_detail = (_hmm_smoothing_level == "bin"
                            or _hmm_emission_mode == "soft")
        all_bin_labels: list = []   # per-bin (pre-expansion) label sequences, one per session
        all_bin_proba:  list = []   # per-bin per-class probability matrices, one per session
        all_bin_win:    list = []   # win (frames-per-bin) used for each session's expansion
        # Collect example-clip tasks to write after the main loop so they can
        # be shuffled for an even cross-animal mix per cluster.
        _clip_tasks: list = []   # (vp, epochs_df, file_fps, animal_id)
        # Collect labeled-video tasks to render after the main loop, in
        # parallel (video_export_n_jobs) -- each is fully independent so,
        # unlike _clip_tasks above, order/shuffling doesn't matter here.
        _labeled_video_tasks: list = []   # (vp, frame_labels, file_fps, banner_mask)

        # Keypoint-overlay bodypart subset (labeled_video_keypoint_overlay):
        # drop SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS the same way the
        # homography-fusion path already does -- these are poorly-tracked/
        # redundant points for a mouse (mouth corners, throat, antler bases,
        # body-middle duplicates, ...) that sit almost on top of a real,
        # well-tracked point (e.g. mouth_end_left/right vs nose) and render
        # as what looks like duplicated keypoints on a small animal. `xy`'s
        # columns are assumed to already align positionally with bps_ref
        # (the same assumption create_labeled_video's own pose_xy/bp_colors_bgr
        # zip already makes) -- this only narrows that same selection further.
        _kp_keep_idx = [_i for _i, _bp in enumerate(bps_ref)
                        if _bp not in SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS]
        _kp_bps      = [bps_ref[_i] for _i in _kp_keep_idx]
        _kp_col_idx  = np.array([_c for _i in _kp_keep_idx for _c in (2 * _i, 2 * _i + 1)],
                                 dtype=int)

        for i, ((fp, vp), (xy, name, file_fps)) in enumerate(
                zip(pairs, zip(all_xy, all_names, all_fps_list))):

            self._log(f"  [{i+1}/{len(pairs)}]  {name}")
            self._stage("7/7 — Predicting & exporting",
                        f"{i+1}/{len(pairs)}: {name}")

            # Session bin width — needed both by the no-MLP fallback below and
            # by attach_centroid_distance (issue 1a) after epochs are built.
            win = max(1, int(round(file_fps / 10)))
            _ll_session = all_ll[i] if i < len(all_ll) else None

            if mlp_clf is not None:
                if _need_bin_detail:
                    frame_labels, _bl, _bp = predict_labels(
                        xy, umap_model, mlp_clf, scaler, file_fps,
                        bodyparts=bps_ref, body_normalise=_body_norm,
                        pca_model=pca_model,
                        min_confidence=float(self._cfg.get("mlp_confidence_thresh", 0.0)),
                        angular_fallback=_ang_fb, is_3d=_is_3d,
                        long_lag_drift=_long_lag, long_scale_bins=_long_scales,
                        bodypart_weights=_bp_weights,
                        ll=_ll_session,
                        visibility_features_enabled=_vis_enabled,
                        visibility_adaptive_pct=_vis_pct,
                        visibility_feature_weight=_vis_weight,
                        face_limb_proximity_feature_weight=_prox_weight,
                        isolated_limb_feature_weight=_isolated_limb_weight,
                        likelihood_thresh=float(self._cfg["likelihood_thresh"]),
                        order_shape_enabled=_order_shape_enabled,
                        order_shape_window_ms=_order_shape_window_ms,
                        order_shape_channel_set=_order_shape_channel_set,
                        order_shape_depth=_order_shape_depth,
                        order_shape_extra_bodyparts=_order_shape_extra_bps,
                        floor_features_enabled=_floor_features_enabled,
                        behavior_indicators_enabled=_behavior_indicators_enabled,
                        turned_away_conf_thresh=_ta_conf_thresh,
                        turned_away_adaptive_pct=_ta_adaptive_pct,
                        turned_away_min_window_s=_ta_min_window_s,
                        turned_away_merge_gap_s=_ta_merge_gap_s,
                        lr_symmetrize_features_enabled=_lr_symmetrize,
                        withinbin_variance_rotation_invariant=_withinbin_rot_inv,
                        egocentric_alignment_enabled=_egocentric_alignment_enabled,
                        egocentric_alignment_pca_dims=_egocentric_alignment_pca_dims,
                        return_proba=True)
                    all_bin_labels.append(_bl)
                    all_bin_proba.append(_bp)
                    all_bin_win.append(win)
                else:
                    frame_labels = predict_labels(
                        xy, umap_model, mlp_clf, scaler, file_fps,
                        bodyparts=bps_ref, body_normalise=_body_norm,
                        pca_model=pca_model,
                        min_confidence=float(self._cfg.get("mlp_confidence_thresh", 0.0)),
                        angular_fallback=_ang_fb, is_3d=_is_3d,
                        long_lag_drift=_long_lag, long_scale_bins=_long_scales,
                        bodypart_weights=_bp_weights,
                        ll=_ll_session,
                        visibility_features_enabled=_vis_enabled,
                        visibility_adaptive_pct=_vis_pct,
                        visibility_feature_weight=_vis_weight,
                        face_limb_proximity_feature_weight=_prox_weight,
                        isolated_limb_feature_weight=_isolated_limb_weight,
                        likelihood_thresh=float(self._cfg["likelihood_thresh"]),
                        order_shape_enabled=_order_shape_enabled,
                        order_shape_window_ms=_order_shape_window_ms,
                        order_shape_channel_set=_order_shape_channel_set,
                        order_shape_depth=_order_shape_depth,
                        order_shape_extra_bodyparts=_order_shape_extra_bps,
                        floor_features_enabled=_floor_features_enabled,
                        behavior_indicators_enabled=_behavior_indicators_enabled,
                        turned_away_conf_thresh=_ta_conf_thresh,
                        turned_away_adaptive_pct=_ta_adaptive_pct,
                        turned_away_min_window_s=_ta_min_window_s,
                        turned_away_merge_gap_s=_ta_merge_gap_s,
                        lr_symmetrize_features_enabled=_lr_symmetrize,
                        withinbin_variance_rotation_invariant=_withinbin_rot_inv,
                        egocentric_alignment_enabled=_egocentric_alignment_enabled,
                        egocentric_alignment_pca_dims=_egocentric_alignment_pca_dims)
            else:
                # Fallback: no MLP → use HDBSCAN approximate_predict on V2/3D feats
                try:
                    import hdbscan as _hdb
                    if _is_3d:
                        f = extract_features_3d(xy, file_fps, bps_ref,
                                                long_lag_drift=_long_lag,
                                                long_scale_bins=_long_scales,
                                                bodypart_weights=_bp_weights,
                                                order_shape_enabled=_order_shape_enabled,
                                                order_shape_window_ms=_order_shape_window_ms,
                                                order_shape_channel_set=_order_shape_channel_set,
                                                order_shape_depth=_order_shape_depth,
                                                order_shape_extra_bodyparts=_order_shape_extra_bps,
                                                floor_features_enabled=_floor_features_enabled,
                                                behavior_indicators_enabled=_behavior_indicators_enabled,
                                                egocentric_alignment_enabled=_egocentric_alignment_enabled)
                    else:
                        _ta_frame_mask_pre = None
                        if (_floor_features_enabled and _ll_session is not None
                                and getattr(_ll_session, "size", 0)
                                and "nose" in [str(b).lower() for b in bps_ref]):
                            try:
                                _ta_bin_mask_pre = detect_turned_away_bins(
                                    _ll_session, bps_ref, file_fps,
                                    float(self._cfg["likelihood_thresh"]), _vis_pct,
                                    _ta_conf_thresh, _ta_min_window_s, _ta_merge_gap_s)
                                _ta_frame_mask_pre = _expand_bin_mask_to_frames(
                                    _ta_bin_mask_pre, file_fps, xy.shape[0])
                            except Exception:
                                _ta_frame_mask_pre = None
                        f = extract_features_v2(xy, file_fps, bps_ref,
                                                body_normalise=_body_norm,
                                                angular_fallback=_ang_fb,
                                                long_lag_drift=_long_lag,
                                                long_scale_bins=_long_scales,
                                                bodypart_weights=_bp_weights,
                                                order_shape_enabled=_order_shape_enabled,
                                                order_shape_window_ms=_order_shape_window_ms,
                                                order_shape_channel_set=_order_shape_channel_set,
                                                order_shape_depth=_order_shape_depth,
                                                order_shape_extra_bodyparts=_order_shape_extra_bps,
                                                floor_features_enabled=_floor_features_enabled,
                                                behavior_indicators_enabled=_behavior_indicators_enabled,
                                                turned_away_frame_mask=_ta_frame_mask_pre,
                                                lr_symmetrize_features_enabled=_lr_symmetrize,
                                                withinbin_variance_rotation_invariant=_withinbin_rot_inv,
                                                egocentric_alignment_enabled=_egocentric_alignment_enabled,
                                                egocentric_alignment_pca_dims=_egocentric_alignment_pca_dims)
                    # 2026-08-30 fix -- same order-shape strip as
                    # predict_labels(): scaler was fit without these
                    # columns (see the training-loop split above), so this
                    # independent re-extraction must strip them too, at the
                    # same point (before visibility is appended).
                    if _order_shape_enabled and _n_order_shape_cols > 0 and f.shape[0] > _n_order_shape_cols:
                        f = f[:-_n_order_shape_cols, :]
                    if _vis_enabled and _ll_session is not None:
                        _vis_f = compute_session_visibility_block(
                            _ll_session, bps_ref, file_fps,
                            float(self._cfg["likelihood_thresh"]), _vis_pct)
                        f = _append_visibility_block(f, _vis_f)
                    _fb_n_vis_cols = (_n_vis_cols if _vis_enabled and _ll_session is not None
                                      else 0)
                    sc   = scaler.transform(f.T)
                    sc   = _scale_visibility_block(sc, _fb_n_vis_cols, _vis_weight,
                                                    features_on_axis0=False)
                    sc   = _scale_visibility_block(
                        sc, _n_isolated_limb_cols, _isolated_limb_weight,
                        features_on_axis0=False, tail_offset=_fb_n_vis_cols)
                    sc   = _scale_visibility_block(
                        sc, _n_prox_cols, _prox_weight,
                        features_on_axis0=False,
                        tail_offset=_fb_n_vis_cols + _n_isolated_limb_cols)
                    if pca_model is not None:
                        sc = pca_model.transform(sc)
                    emb  = umap_model.transform(sc)
                    soft, _ = _hdb.approximate_predict(hdb_clf, emb)
                    # approximate_predict returns the original HDBSCAN cluster IDs
                    # (before split/merge refinement, rare-cluster pruning, and
                    # renumbering).  Apply the same remap applied to hdb_labels
                    # so the fallback cluster IDs match those used in the plots.
                    if _hdb_remap:
                        _remapped = np.full_like(soft, -1, dtype=int)
                        for _orig, _new in _hdb_remap.items():
                            _remapped[soft == _orig] = _new
                        soft = _remapped
                    fl   = np.repeat(soft.astype(int), win)
                    n_f  = xy.shape[0]
                    if len(fl) < n_f:
                        fl = np.pad(fl, (0, n_f - len(fl)), mode="edge")
                    frame_labels = fl[:n_f]
                except Exception:
                    frame_labels = np.zeros(xy.shape[0], dtype=int)

            all_frame_labels.append(frame_labels)

            # Turned-away dedicated label (v3): a reserved cluster id one
            # above the highest real HDBSCAN id (0..n_cl-1), so it never
            # collides with a real cluster.  Only overrides the DISPLAY copy
            # used for CSV/plot export — the raw `frame_labels` appended
            # above stays untouched so HMM training (below) never sees an
            # out-of-range observation id (hmmlearn's CategoricalHMM is fit
            # with n_clusters categories; feeding it n_cl would raise/corrupt
            # the emission matrix).  Only applied when exclude_turned_away is
            # True — at False this is a pure no-op (_display_labels ==
            # frame_labels exactly), matching the GUI escape hatch.
            _ta_id = int(n_cl)
            # Auto-flagged impure clusters get their OWN reserved id
            # (n_cl+1), separate from genuine confidence-based turned-away
            # (n_cl) -- found on real data (D:\Dam_Xenium, 2026-09-18) that
            # sharing one id/name meant a real, distinct behaviour cluster
            # (rearing, silhouette 0.150) auto-flagged as "impure" got
            # displayed as "Turned Away" even though the animal was never
            # judged low-confidence/occluded that whole time -- misleading
            # for anyone reading the ethogram/CSV without cross-referencing
            # turned_away_reason. Kept as a distinct id+name ("Low-Quality
            # Cluster") so the two causes are visually distinguishable
            # everywhere a display label is shown, not just in the CSV's
            # turned_away_reason column.
            _impure_id = int(n_cl) + 1
            _ta_bin_mask = (all_turned_away[i] if i < len(all_turned_away)
                            else np.zeros(0, dtype=bool))
            _ta_frame_mask = _expand_bin_mask_to_frames(
                _ta_bin_mask, file_fps, xy.shape[0])
            _display_labels = frame_labels.copy()
            # turned_away_reason: per-frame provenance for WHY a frame was
            # relabeled into a reserved display id, so it's still possible to
            # tell "genuinely occluded/turned away" (id _ta_id) apart from
            # "auto-flagged impure cluster" (id _impure_id) after the fact.
            _reason = np.full(len(_display_labels), "", dtype=object)
            if _exclude_turned_away and _ta_frame_mask.any():
                _display_labels[_ta_frame_mask] = _ta_id
                _reason[_ta_frame_mask] = "confidence"
            # Auto-flagged impure clusters (see auto_flag_impure_clusters
            # above) fold into their OWN reserved id (_impure_id, never
            # _ta_id -- see comment above) -- frame_labels (the raw MLP
            # prediction, untouched) still carries the real cluster id, so
            # this only ever affects the DISPLAY copy, same guarantee as the
            # confidence-based override just above.
            if _auto_impure_ids:
                _impure_mask = np.isin(frame_labels, sorted(_auto_impure_ids))
                if _impure_mask.any():
                    _display_labels[_impure_mask] = _impure_id
                    _reason[_impure_mask] = "auto_impure_cluster"

            # Same-label gap bridging (default on -- see
            # bout_gap_bridging_enabled's DEFAULTS comment): merges brief
            # sub-floor interruptions back into their surrounding bout BEFORE
            # bout-ification, so bursty-but-coherent behaviours (e.g.
            # licking) aren't shredded by the min-duration floor below.
            # Applied after the turned-away/auto-impure overrides above --
            # deliberately, so a brief low-quality blip inside a real bout
            # gets subsumed too (see the DEFAULTS comment for the rationale).
            if bool(self._cfg.get("bout_gap_bridging_enabled", True)):
                _bridge_max_gap = max(1, int(round(
                    float(self._cfg.get("bout_gap_bridging_max_gap_s", 0.3))
                    * file_fps)))
                _display_labels = bridge_short_bouts(_display_labels, _bridge_max_gap)

            # Bout CSV (exact B-SOiD GUI format -- fixed 3-column schema,
            # no raw-label/reason columns here since one bout can span
            # frames whose ORIGINAL cluster/reason differ once merged into
            # the same Turned-Away run; see the frame-label CSV instead for
            # per-frame provenance).
            bout_df = labels_to_bouts(_display_labels)
            bout_p  = self._out_bouts / f"{name}_bout_lengths.csv"
            bout_df.to_csv(str(bout_p), index=False)
            bout_paths.append(bout_p)

            # Frame-label CSV. raw_label preserves the real, un-relabeled
            # predicted cluster id for EVERY frame (identical to `label`
            # except where a Turned-Away override fired) -- so cube_analyser.py
            # or any future stage can still recover which real cluster a
            # given Turned-Away frame originally came from, filter it back
            # in, or audit an auto-flag decision, without needing to rerun
            # the pipeline. turned_away_reason is "" for frames never
            # overridden, "confidence" for the existing likelihood-based
            # detector, "auto_impure_cluster" for auto_flag_impure_clusters.
            frame_df = pd.DataFrame({
                "frame":               np.arange(len(_display_labels)),
                "time_s":              np.arange(len(_display_labels)) / file_fps,
                "label":               _display_labels,
                "raw_label":           frame_labels,
                "turned_away_reason":  _reason,
            })
            frame_p = self._out_bouts / f"{name}_frame_labels.csv"
            frame_df.to_csv(str(frame_p), index=False)
            frame_paths.append(frame_p)

            # Epoch CSV (filtered by user-set min/max bout duration)
            epochs = bouts_to_epochs(
                bout_df, file_fps,
                min_dur=float(self._cfg["min_epoch_dur_s"]),
                max_dur=float(self._cfg["max_epoch_dur_s"]))
            # Attach embedding-space distance-to-centroid (issue 1a) so
            # create_example_clips can select clips by embedding proximity
            # instead of nearest-to-median-duration.
            try:
                _bin_offset = int(_sbr.get(name, [0])[0])
                epochs = attach_centroid_distance(
                    epochs, embedding_save, hdb_labels_all,
                    _cluster_centroids, bin_offset=_bin_offset, win=win)
            except Exception:
                pass
            epochs.to_csv(
                str(self._out_bouts / f"{name}_epochs.csv"), index=False)
            epoch_stats(epochs).to_csv(
                str(self._out_bouts / f"{name}_epoch_stats.csv"), index=False)
            all_epochs.append((epochs, name))

            # Clip-generation epochs use a SEPARATE label array that skips
            # the auto-impure-cluster override (confidence-based turned-away
            # still applies) -- example clips are for VISUAL review, and
            # folding an auto-flagged cluster's clips into the same
            # cluster_{n_cl} "Turned Away" folder as genuine turned-away
            # clips in the video explorer would make it impossible to
            # eyeball whether the auto-flag call was actually correct. Real
            # cluster ids stay real here; the bout/frame CSVs, ethogram, and
            # all quantitative exports above/below are unaffected (still use
            # `epochs`/`_display_labels`).
            if _auto_impure_ids:
                _clip_labels = frame_labels.copy()
                if _exclude_turned_away and _ta_frame_mask.any():
                    _clip_labels[_ta_frame_mask] = _ta_id
                _clip_epochs = bouts_to_epochs(
                    labels_to_bouts(_clip_labels), file_fps,
                    min_dur=float(self._cfg["min_epoch_dur_s"]),
                    max_dur=float(self._cfg["max_epoch_dur_s"]))
                try:
                    _bin_offset = int(_sbr.get(name, [0])[0])
                    _clip_epochs = attach_centroid_distance(
                        _clip_epochs, embedding_save, hdb_labels_all,
                        _cluster_centroids, bin_offset=_bin_offset, win=win)
                except Exception:
                    pass
            else:
                _clip_epochs = epochs

            _ta_names = {_ta_id: "Turned Away"} if _exclude_turned_away else None
            if _ta_names is not None and _auto_impure_ids:
                _ta_names[_impure_id] = "Low-Quality Cluster"
            # cluster_durations_*/cluster_stats_* are per-cluster QUANTITATIVE
            # summaries (unlike the ethogram timeline above, which explicitly
            # LABELS turned-away/low-quality frames via cluster_names rather
            # than hiding them) -- an unlabeled sentinel id showing up there
            # would look like a real, ordinary behaviour cluster with its own
            # duration statistics. Drop sentinel ids (>= n_cl) for these two
            # plots only; `epochs` itself (and the *_epochs*.csv/all_epochs
            # exports/combine derived from it) is left untouched.
            _epochs_no_sentinel = epochs[epochs["label"] < n_cl]
            if self._cfg["save_plots"] and not epochs.empty:
                try:
                    plot_ethogram(_display_labels, file_fps,
                                  self._out_plots / f"ethogram_{name}.png",
                                  name, cluster_names=_ta_names)
                    if not _epochs_no_sentinel.empty:
                        plot_cluster_durations(
                            _epochs_no_sentinel,
                            self._out_plots / f"cluster_durations_{name}.png",
                            name)
                        plot_cluster_stats(
                            _epochs_no_sentinel,
                            self._out_plots / f"cluster_stats_{name}.png")
                except Exception:
                    pass

            if vp and self._cfg["save_videos"]:
                if self._cfg["save_example_clips"] and not _clip_epochs.empty:
                    # Defer clip writing; process all animals together after the
                    # loop so clips can be shuffled for a cross-animal mix.
                    # Uses _clip_epochs (real cluster ids for auto-flagged
                    # clusters), NOT `epochs` -- see its construction above.
                    _clip_tasks.append(
                        (vp, _clip_epochs.copy(), file_fps, Path(vp).stem))
                if self._cfg["save_labeled_video"]:
                    # Fold auto-impure frames into the same banner mask
                    # as confidence-based turned-away, so the labeled
                    # video's overlay stays consistent with the CSV
                    # export: the "C{lbl}" box still shows the TRUE raw
                    # cluster id either way (create_labeled_video always
                    # labels off `frame_labels`, never `_display_labels`)
                    # -- this only affects whether the amber banner also
                    # appears.
                    _banner_mask = _ta_frame_mask
                    if _auto_impure_ids:
                        _banner_mask = _banner_mask | np.isin(
                            frame_labels, sorted(_auto_impure_ids))
                    # DLC keypoint coordinates (xy) are stored in whatever
                    # resolution/crop DLC actually ran inference on --
                    # cube.py's Step 1a (dlc_scale_mode/dlc_crop_enable)
                    # writes that intermediate video as a SIBLING of the raw
                    # source, {stem}_results/resized_{stem}.mp4, only when a
                    # resize/crop was actually applied. Confirmed via real
                    # data (2026-08-31): drawing raw H5 pose coordinates
                    # directly onto the ORIGINAL raw video places every dot
                    # in the wrong place entirely (pose data was in a
                    # 720x1280 space; the raw video was 2160x3840).
                    # Back-transforming coordinates would need the exact
                    # crop offset/scale DLC used, which isn't reliably
                    # recoverable from inside BSoidEngine.run(). Instead,
                    # mirror the 3D pipeline's own solved approach
                    # (overlay_keypoints_on_video draws on the SAME cropped
                    # video DLC ran on, never the original): if the
                    # resized/cropped sibling still exists on disk, use it
                    # as the labeled video's source instead of the raw
                    # video -- background footage and keypoint coordinates
                    # then agree by construction, since it's literally the
                    # same file DLC saw. Falls back to the raw video when no
                    # such sibling exists (DLC ran on the raw video
                    # directly, so it's already the correct coordinate
                    # space) -- create_labeled_video's own sanity check
                    # additionally guards against any other mismatch.
                    _overlay_vp = vp
                    if vp and bool(self._cfg.get("labeled_video_keypoint_overlay", True)):
                        _resized_sibling = (Path(vp).parent / f"{Path(vp).stem}_results"
                                            / f"resized_{Path(vp).stem}.mp4")
                        if _resized_sibling.exists():
                            _overlay_vp = str(_resized_sibling)
                    # Deferred to after the main loop (video_export_n_jobs,
                    # parallel across sessions) -- see that DEFAULTS key's
                    # comment for why this one is safe to parallelize.
                    # xy/_ll_session (this session's own pose x/y and raw
                    # per-bodypart likelihood, already loaded for feature
                    # extraction/MLP prediction above -- no extra file read)
                    # are captured here too, for the keypoint-dot overlay
                    # (labeled_video_keypoint_overlay).
                    # Trailing `vp` (the ORIGINAL raw video, not _overlay_vp)
                    # is carried through purely so run() can key the
                    # resolved-labeled-video-path lookup by the same vp
                    # _clip_tasks/the UMAP-evolution call site already use --
                    # never passed into the actual render call itself.
                    # Narrow to the well-tracked bodypart subset (_kp_col_idx/
                    # _kp_keep_idx above) so the overlay doesn't draw
                    # SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS points --
                    # guarded by shape in case this session's own xy/_ll_session
                    # has fewer columns than bps_ref (bodypart-count mismatch
                    # across animals, see the intersection logic above).
                    _xy_ov = (xy[:, _kp_col_idx] if _kp_col_idx.size
                              and _kp_col_idx.max(initial=-1) < xy.shape[1] else xy)
                    _ll_ov = (_ll_session[:, _kp_keep_idx]
                              if _ll_session is not None and _kp_keep_idx
                              and max(_kp_keep_idx) < _ll_session.shape[1] else _ll_session)
                    _labeled_video_tasks.append(
                        (_overlay_vp, frame_labels.copy(), file_fps,
                         _banner_mask.copy() if _banner_mask is not None else None,
                         _xy_ov, _ll_ov, vp))

            self._prog(i + 1, len(pairs))

        # ── HMM smoothing pass (post-hoc Multinomial HMM wrapper) ────────────
        all_hmm_labels: list = []
        # all_hmm_display_labels: the DISPLAY copy of each session's post-HMM
        # labels (turned-away / auto-flagged-impure frames overridden to
        # their reserved n_cl/n_cl+1 sentinel ids) -- i.e. exactly what
        # *_bout_lengths_hmm.csv / the ethograms / example clips actually
        # show the user, unlike all_hmm_labels (the pre-override raw HMM
        # output). Used by the post-HMM kinetic_coherence block below so
        # that diagnostic never scores/reports turned-away or low-quality
        # points as if they were real behaviour (user-reported: showing
        # those in any final plot is misleading).
        all_hmm_display_labels: list = []
        hmm_model = None
        # _soft_ok / _bin_level_ok: the requested new mode was possible AND
        # every session actually produced the detail it needs (the no-MLP
        # approximate_predict fallback path above never populates
        # all_bin_labels/all_bin_proba -- if even one session took that
        # path, the bin-level and frame-level sequence lists would desync).
        # Falls back to the unchanged frame-level categorical path with a
        # warning rather than silently mismatching sessions. Soft (B.1)
        # takes priority over bin-level-categorical (B.2) when both happen
        # to be requested together, since soft emissions already operate at
        # bin resolution.
        _soft_ok = (_hmm_emission_mode == "soft"
                   and len(all_bin_proba) == len(all_frame_labels)
                   and len(all_frame_labels) > 0)
        _bin_level_ok = (not _soft_ok and _hmm_smoothing_level == "bin"
                         and len(all_bin_labels) == len(all_frame_labels)
                         and len(all_frame_labels) > 0)
        if _hmm_emission_mode == "soft" and not _soft_ok and all_frame_labels:
            self._log("  [WARN] hmm_emission_mode='soft' requested but not "
                      "every session produced bin-probability detail (e.g. "
                      "the no-MLP approximate_predict fallback was used for "
                      "one or more sessions) -- falling back to categorical "
                      "HMM smoothing for this run.")
        if (_hmm_smoothing_level == "bin" and not _soft_ok and not _bin_level_ok
                and all_frame_labels):
            self._log("  [WARN] hmm_smoothing_level='bin' requested but not "
                      "every session produced bin-level detail (e.g. the "
                      "no-MLP approximate_predict fallback was used for one "
                      "or more sessions) -- falling back to frame-level HMM "
                      "smoothing for this run.")
        # Turned-away-excluded training sequences (transition analysis fix,
        # Aug 2026): HMM training must never learn a transition into/out of a
        # frame the animal was turned away from camera during -- that frame's
        # MLP-predicted "real" cluster is just a best-effort guess on data
        # excluded from UMAP/HDBSCAN training in the first place. Splitting
        # each session at turned-away boundaries (rather than dropping those
        # bins from a single concatenated sequence) is essential -- train_hmm/
        # train_hmm_soft already treat each LIST ELEMENT as an independent
        # sequence (hmmlearn's lengths= mechanism), so more/shorter segments
        # per session is a safe, drop-in substitution: no transition is ever
        # counted across the dropped gap. A pure no-op (identical to the
        # original per-session lists) when exclude_turned_away=False, matching
        # this codebase's existing escape-hatch convention for that flag.
        def _ta_bin_mask_for(hi: int, n_bins: int) -> np.ndarray:
            # Fallback is a FULL-LENGTH all-False mask (nothing excluded),
            # not a zero-length one -- an empty mask would make
            # _mask_out_segments' min(len(seq), len(mask)) truncate the
            # whole session to nothing, silently discarding all of its data
            # from training instead of just skipping the (inapplicable)
            # exclusion. Should only ever be hit defensively; all_turned_away
            # is appended once per session unconditionally in Step 3.
            if hi < len(all_turned_away) and len(all_turned_away[hi]) == n_bins:
                return np.asarray(all_turned_away[hi], dtype=bool)
            return np.zeros(n_bins, dtype=bool)

        def _ta_frame_mask_for(hi: int, fps: float, n_frames: int) -> np.ndarray:
            # Frame-level counterpart of _ta_bin_mask_for. Guards
            # _expand_bin_mask_to_frames against being handed a zero-length
            # bin mask -- np.pad(..., mode="edge") raises ValueError on an
            # empty array, so an all-False, FULL-length frame mask (nothing
            # excluded) is built directly instead of routing through expand
            # in the defensive/missing-entry case.
            if hi < len(all_turned_away) and len(all_turned_away[hi]) > 0:
                return _expand_bin_mask_to_frames(all_turned_away[hi], fps, n_frames)
            return np.zeros(n_frames, dtype=bool)

        _hmm_bin_proba_train = all_bin_proba
        _hmm_bin_labels_train = all_bin_labels
        _hmm_frame_labels_train = all_frame_labels
        if _exclude_turned_away and all_turned_away:
            if _soft_ok:
                _seg_proba, _seg_bin_lbl = [], []
                for _hi in range(len(all_bin_proba)):
                    _ta_m = _ta_bin_mask_for(_hi, len(all_bin_proba[_hi]))
                    _seg_proba.extend(_mask_out_segments(all_bin_proba[_hi], _ta_m))
                    _seg_bin_lbl.extend(_mask_out_segments(all_bin_labels[_hi], _ta_m))
                if _seg_proba:
                    _hmm_bin_proba_train, _hmm_bin_labels_train = _seg_proba, _seg_bin_lbl
                else:
                    self._log("  [WARN] turned-away exclusion left no bins for "
                              "HMM training (entire dataset flagged turned-away?) "
                              "-- falling back to the unsegmented sequences.")
            elif _bin_level_ok:
                _seg_bin_lbl = []
                for _hi in range(len(all_bin_labels)):
                    _ta_m = _ta_bin_mask_for(_hi, len(all_bin_labels[_hi]))
                    _seg_bin_lbl.extend(_mask_out_segments(all_bin_labels[_hi], _ta_m))
                if _seg_bin_lbl:
                    _hmm_bin_labels_train = _seg_bin_lbl
                else:
                    self._log("  [WARN] turned-away exclusion left no bins for "
                              "HMM training (entire dataset flagged turned-away?) "
                              "-- falling back to the unsegmented sequences.")
            else:
                _seg_frame_lbl = []
                for _hi in range(len(all_frame_labels)):
                    _ta_frame_m = _ta_frame_mask_for(
                        _hi, all_fps_list[_hi], len(all_frame_labels[_hi]))
                    _seg_frame_lbl.extend(
                        _mask_out_segments(all_frame_labels[_hi], _ta_frame_m))
                if _seg_frame_lbl:
                    _hmm_frame_labels_train = _seg_frame_lbl
                else:
                    self._log("  [WARN] turned-away exclusion left no frames for "
                              "HMM training (entire dataset flagged turned-away?) "
                              "-- falling back to the unsegmented sequences.")

        if self._cfg.get("hmm_enabled", True) and all_frame_labels and n_cl < 2:
            # Mirrors train_mlp()'s own "< 2 clusters" gate above -- a
            # degenerate 0-or-1-real-cluster partition (e.g. every bin
            # noise) has no meaningful multi-state sequence to smooth, and
            # hmmlearn's own n_components=0 initialization divides by zero
            # (1./self.n_components) rather than raising a clean, catchable
            # message -- confirmed directly via a real degenerate-partition
            # repro. Skip HMM training entirely in this case instead of
            # letting the whole block's try/except silently swallow that
            # crash and leave every *_bout_lengths_hmm.csv unwritten with no
            # actionable log line.
            self._log(f"  [WARN] < 2 clusters ({n_cl}) — HMM smoothing skipped.")
        elif self._cfg.get("hmm_enabled", True) and all_frame_labels:
            try:
                _t0 = time.perf_counter()
                _hmm_n_states = self._cfg.get("hmm_n_states") or None
                if _hmm_n_states is not None:
                    _hmm_n_states = int(_hmm_n_states)
                _g_T = None
                self._guided_dyn_pack = None
                if (getattr(self, "_guided_ctx", None) is not None and getattr(self, "_guided_preloaded", None)
                        and bool(self._cfg.get("guided_dynamics_enabled", True))
                        and _hmm_n_states in (None, int(n_cl))):
                    self._stage("6/7 ? Applying your labels", "HMM transition prior from your labelled bouts?")
                    from cube_guided_dynamics import engine_prior as _g_prior
                    _g_T, _pack = _g_prior(self._guided_ctx, self._guided_preloaded[1], hdb_labels, int(n_cl),
                                           all_fps_list, bool(_soft_ok or _bin_level_ok), self._cfg)
                    self._guided_dyn_pack = _pack if "dyn" in _pack else None
                    if "error" in _pack:
                        self._log(f"  [GUIDED] WARN: label dynamics unavailable ({_pack['error']}).")
                    elif _g_T is None:
                        self._log("  [GUIDED] label dynamics: too few labelled bouts per behaviour "
                                  "(need guided_min_bouts) -- ordinary HMM prior.")
                if _soft_ok:
                    self._log("\n[HMM]  Training soft-emission GaussianHMM "
                              "on MLP per-bin probability vectors "
                              "(hmm_emission_mode='soft')...")
                    hmm_model = train_hmm_soft(
                        _hmm_bin_proba_train,
                        n_clusters=int(n_cl),
                        n_states=_hmm_n_states,
                        n_iter=int(self._cfg.get("hmm_n_iter", 100)),
                        log_fn=self._log,
                        transition_prior=str(self._cfg.get("hmm_transition_prior", "global")),
                        bin_label_sequences=_hmm_bin_labels_train,
                        random_state=int(self._cfg.get("hmm_random_state", 42)),
                        transmat_prior_strength=float(self._cfg.get("hmm_transmat_prior_strength", 10.0)),
                        guided_transmat=_g_T,
                    )
                elif _bin_level_ok:
                    self._log("\n[HMM]  Training Multinomial HMM on MLP "
                              "label sequences (bin-level resolution, "
                              "hmm_smoothing_level='bin')...")
                    hmm_model = train_hmm(
                        _hmm_bin_labels_train,
                        n_clusters=int(n_cl),
                        n_states=_hmm_n_states,
                        n_iter=int(self._cfg.get("hmm_n_iter", 100)),
                        log_fn=self._log,
                        transition_prior=str(self._cfg.get("hmm_transition_prior", "global")),
                        random_state=int(self._cfg.get("hmm_random_state", 42)),
                        transmat_prior_strength=float(self._cfg.get("hmm_transmat_prior_strength", 10.0)),
                        guided_transmat=_g_T,
                    )
                else:
                    self._log("\n[HMM]  Training Multinomial HMM on MLP label sequences...")
                    hmm_model = train_hmm(
                        _hmm_frame_labels_train,
                        n_clusters=int(n_cl),
                        n_states=_hmm_n_states,
                        n_iter=int(self._cfg.get("hmm_n_iter", 100)),
                        log_fn=self._log,
                        transition_prior=str(self._cfg.get("hmm_transition_prior", "global")),
                        random_state=int(self._cfg.get("hmm_random_state", 42)),
                        transmat_prior_strength=float(self._cfg.get("hmm_transmat_prior_strength", 10.0)),
                        guided_transmat=_g_T,
                    )
                self._log(f"  HMM trained in {time.perf_counter() - _t0:.2f} s  "
                          f"({hmm_model.n_components} states, Baum-Welch)")
                for _hi, (_raw, _name, _file_fps) in enumerate(zip(
                        all_frame_labels, all_names, all_fps_list)):
                    # _hmm_labels is decoded from the RAW (unoverridden) MLP
                    # label sequence — hmmlearn's CategoricalHMM was fit with
                    # exactly n_cl categories, so decode_hmm's input/output
                    # here must never contain the reserved turned-away id.
                    # The dedicated-label override is applied afterward, only
                    # to the CSV-export copy, exactly mirroring the raw-output
                    # handling above.
                    if _soft_ok:
                        _decoded_bins = decode_hmm_soft(hmm_model, all_bin_proba[_hi])
                        _win = all_bin_win[_hi]
                        _hmm_labels = np.repeat(_decoded_bins, _win)
                        _n_orig = len(_raw)
                        if len(_hmm_labels) < _n_orig:
                            _hmm_labels = np.pad(
                                _hmm_labels, (0, _n_orig - len(_hmm_labels)),
                                mode="edge")
                        _hmm_labels = _hmm_labels[:_n_orig].astype(int)
                    elif _bin_level_ok:
                        # Decode at bin resolution, then expand back to frame
                        # resolution the SAME way predict_labels() expands
                        # raw bin labels (np.repeat(.., win), edge-pad to the
                        # original frame count) -- so every downstream
                        # consumer (CSV export, labeled video, epochs/bouts)
                        # sees a frame-length array exactly as it does today.
                        _decoded_bins = decode_hmm(hmm_model, all_bin_labels[_hi])
                        _win = all_bin_win[_hi]
                        _hmm_labels = np.repeat(_decoded_bins, _win)
                        _n_orig = len(_raw)
                        if len(_hmm_labels) < _n_orig:
                            _hmm_labels = np.pad(
                                _hmm_labels, (0, _n_orig - len(_hmm_labels)),
                                mode="edge")
                        _hmm_labels = _hmm_labels[:_n_orig].astype(int)
                    else:
                        _hmm_labels = decode_hmm(hmm_model, _raw)
                    all_hmm_labels.append(_hmm_labels)
                    _hmm_ta_bin_mask = (all_turned_away[_hi]
                                        if _hi < len(all_turned_away)
                                        else np.zeros(0, dtype=bool))
                    _hmm_ta_frame_mask = _expand_bin_mask_to_frames(
                        _hmm_ta_bin_mask, _file_fps, len(_hmm_labels))
                    _hmm_display = _hmm_labels.copy()
                    _hmm_reason = np.full(len(_hmm_display), "", dtype=object)
                    if _exclude_turned_away and _hmm_ta_frame_mask.any():
                        _hmm_display[_hmm_ta_frame_mask] = int(n_cl)
                        _hmm_reason[_hmm_ta_frame_mask] = "confidence"
                    # Auto-flagged impure clusters (see auto_flag_impure_clusters
                    # above) must be folded in here too -- cube_analyser.py's
                    # _prefer_hmm() loads these *_hmm files over the raw ones
                    # whenever HMM smoothing is on (the default), so without
                    # this an auto-flagged cluster would still show up as a
                    # real behaviour in exactly the files the analyser
                    # actually reads, defeating the whole point of flagging it.
                    if _auto_impure_ids:
                        _hmm_impure_mask = np.isin(_hmm_labels, sorted(_auto_impure_ids))
                        if _hmm_impure_mask.any():
                            # Own reserved id (n_cl+1), not n_cl -- see the
                            # main display-label block's _impure_id comment
                            # above for why these two causes must not share
                            # a display id/name.
                            _hmm_display[_hmm_impure_mask] = int(n_cl) + 1
                            _hmm_reason[_hmm_impure_mask] = "auto_impure_cluster"
                    # Same-label gap bridging (default on -- see
                    # bout_gap_bridging_enabled's DEFAULTS comment), mirroring
                    # the raw-path injection above. Applied before the
                    # all_hmm_display_labels.append() below so kinetic_coherence
                    # / Sankey / any other consumer of that collected list sees
                    # bridged data too.
                    if bool(self._cfg.get("bout_gap_bridging_enabled", True)):
                        _hmm_bridge_max_gap = max(1, int(round(
                            float(self._cfg.get("bout_gap_bridging_max_gap_s", 0.3))
                            * _file_fps)))
                        _hmm_display = bridge_short_bouts(_hmm_display, _hmm_bridge_max_gap)
                    all_hmm_display_labels.append(_hmm_display)
                    _bout_hmm = labels_to_bouts(_hmm_display)
                    _bout_hmm.to_csv(
                        str(self._out_bouts / f"{_name}_bout_lengths_hmm.csv"),
                        index=False)
                    # v6 K2 sidecar (opt-in, off by default): per-bout
                    # kinematic directedness metrics, written as a SEPARATE
                    # file so the canonical 3-column bout CSV above is never
                    # touched. See kinematic_directedness_enabled in DEFAULTS.
                    _bout_hmm_enriched = None
                    if bool(self._cfg.get("kinematic_directedness_enabled", False)):
                        try:
                            _xy_k = all_xy[_hi]
                            _centroid_xy = np.column_stack([
                                _xy_k[:, 0::2].mean(axis=1),
                                _xy_k[:, 1::2].mean(axis=1)])
                            _bout_hmm_enriched = compute_bout_directedness(
                                _bout_hmm, _centroid_xy, _file_fps)
                        except Exception:
                            self._log(
                                f"  [WARN] kinematic directedness sidecar "
                                f"({_name}): {traceback.format_exc()}")
                            _bout_hmm_enriched = None
                    # v6 part 2 (Environmental_Context_v6_Implementation_Plan.md
                    # Step 6): bout-CSV enrichment, pure reuse of
                    # enrich_bouts_from_bin_source() -- no new join logic here,
                    # just a different source/aggregator set. Shares the same
                    # *_bout_lengths_hmm_enriched.csv sidecar as the kinematics
                    # plan's Step 4 (append if that block already created it
                    # this iteration, else create fresh with just these
                    # columns). Skipped entirely (no file, no crash) whenever
                    # env_features_enabled is False or this session has no
                    # per-bin env-context data (empty/None env_arena_cfg).
                    _env_sec = _env_ctx.get(_name) or {}
                    _env_pb  = _env_sec.get("per_bin") or {}
                    if bool(self._cfg.get("env_features_enabled", False)) and _env_pb:
                        try:
                            _thresh = float(
                                (_env_sec.get("summary") or {}).get(
                                    "interaction_threshold_px", 0.0))
                            _win_bin = max(1, int(round(
                                _file_fps * (_env_sec.get("bin_ms", 100.0) / 1000.0))))
                            _src: dict = {}
                            _agg: dict = {}
                            _names_out: dict = {}

                            _cur_region = np.array(
                                _env_pb.get("current_region") or [], dtype=object)
                            for _rn in sorted(
                                    ((_env_sec.get("summary") or {})
                                     .get("time_in_region_sec") or {}).keys()):
                                _k = f"region__{_rn}"
                                _src[_k] = (_cur_region == _rn).astype(float)
                                _agg[_k] = np.nanmean
                                _names_out[_k] = f"pct_time_in_region_{_rn}"

                            _nose_d = _env_pb.get("dist_to_nearest_object_nose") or {}
                            _paw_d  = _env_pb.get("dist_to_nearest_object_paw") or {}
                            for _on in _nose_d.keys():
                                _nd = np.array(_nose_d.get(_on, []), dtype=float)
                                _pd_ = np.array(_paw_d.get(_on, []), dtype=float)
                                if _nd.size and _pd_.size:
                                    _k = f"objcontact__{_on}"
                                    _src[_k] = ((_nd <= _thresh) | (_pd_ <= _thresh)).astype(float)
                                    _agg[_k] = np.nanmean
                                    _names_out[_k] = f"pct_time_near_object_{_on}"

                            for _on, _hseries in (_env_pb.get(
                                    "heading_angle_to_nearest_object") or {}).items():
                                _k = f"heading__{_on}"
                                _src[_k] = np.array(_hseries, dtype=float)
                                _agg[_k] = np.nanmean
                                _names_out[_k] = f"mean_heading_angle_to_object_{_on}"

                            if _src:
                                _base_df = (_bout_hmm_enriched
                                            if _bout_hmm_enriched is not None
                                            else _bout_hmm)
                                _bout_hmm_enriched = enrich_bouts_from_bin_source(
                                    _base_df, _src, bin_offset=0, win=_win_bin,
                                    agg_fns=_agg, out_col_names=_names_out)
                        except Exception:
                            self._log(
                                f"  [WARN] environmental-context bout "
                                f"enrichment ({_name}): {traceback.format_exc()}")
                    if _bout_hmm_enriched is not None:
                        _bout_hmm_enriched.to_csv(
                            str(self._out_bouts /
                                f"{_name}_bout_lengths_hmm_enriched.csv"),
                            index=False)
                    # v6 part 2 (Environmental_Context_v6_Implementation_Plan.md
                    # Step 7 / Phase 3.5): sequence-plus-tag approach/avoid
                    # detection. Requires BOTH kinematic_directedness_enabled
                    # (straightness_ratio/mean_speed_px_s columns) AND
                    # env_features_enabled + traced shapes -- if either
                    # prerequisite is missing, detect_approach_avoid_events()
                    # itself no-ops (empty DataFrame), and no
                    # approach_events.csv is written at all in that case.
                    if (bool(self._cfg.get("kinematic_directedness_enabled", False))
                            and bool(self._cfg.get("env_features_enabled", False))
                            and _bout_hmm_enriched is not None and _env_pb):
                        try:
                            _win_bin = max(1, int(round(
                                _file_fps * (_env_sec.get("bin_ms", 100.0) / 1000.0))))
                            _approach_df = detect_approach_avoid_events(
                                _bout_hmm_enriched, _env_pb, _file_fps, _win_bin,
                                interaction_threshold_px=float(
                                    (_env_sec.get("summary") or {}).get(
                                        "interaction_threshold_px", 50.0)))
                            if not _approach_df.empty:
                                _approach_df.to_csv(
                                    str(self._out_bouts /
                                        f"{_name}_approach_events.csv"),
                                    index=False)
                        except Exception:
                            self._log(
                                f"  [WARN] approach/avoid detection "
                                f"({_name}): {traceback.format_exc()}")
                    pd.DataFrame({
                        "frame":               np.arange(len(_hmm_display)),
                        "time_s":              np.arange(len(_hmm_display)) / _file_fps,
                        "label":               _hmm_display,
                        "raw_label":           _hmm_labels,
                        "turned_away_reason":  _hmm_reason,
                    }).to_csv(
                        str(self._out_bouts / f"{_name}_frame_labels_hmm.csv"),
                        index=False)
                    _ep_hmm = bouts_to_epochs(
                        _bout_hmm, _file_fps,
                        min_dur=float(self._cfg["min_epoch_dur_s"]),
                        max_dur=float(self._cfg["max_epoch_dur_s"]))
                    _ep_hmm.to_csv(
                        str(self._out_bouts / f"{_name}_epochs_hmm.csv"),
                        index=False)
                    epoch_stats(_ep_hmm).to_csv(
                        str(self._out_bouts / f"{_name}_epoch_stats_hmm.csv"),
                        index=False)
                _hmm_path = self._out_model / "hmm_model.pkl"
                with open(str(_hmm_path), "wb") as _fh:
                    pickle.dump(hmm_model, _fh)
                self._log(f"  HMM model saved -> {_hmm_path}")
            except Exception:
                self._log(f"  [WARN] HMM smoothing failed:\n"
                          f"{traceback.format_exc()}")

        self._mem_checkpoint("7/7 per-session prediction + export done")

        # Labeled videos — each task is fully independent (own input/output
        # file, no shared state), so this batch runs in parallel via
        # video_export_n_jobs (default -1 = auto, memory-aware) instead of
        # the old inline sequential call. Threads, not processes: cv2's
        # VideoCapture/VideoWriter round-trip is C++ decode/encode that
        # releases the GIL, and create_labeled_video() already cleanly
        # releases cap/writer in its own finally blocks regardless of
        # success/failure, so no extra per-task cleanup is needed here.
        if _labeled_video_tasks:
            _lv_n_jobs = resolve_n_jobs(self._cfg, "video_export_n_jobs", log_fn=self._log)
            # Hard cap, independent of compute_adaptive_n_jobs()'s CPU/RAM-
            # based auto-scaling: real-data evidence (2026-08-31) showed 20
            # auto-resolved concurrent workers -- each spawning its own
            # isolated process + its own h264_nvenc ffmpeg encode -- caused
            # 17/21 labeled videos to time out (600s) on their first
            # attempt. compute_adaptive_n_jobs() has no concept of the GPU
            # driver's concurrent NVENC session limit (commonly 2-5 on
            # consumer NVIDIA cards) -- CPU/RAM headroom being available
            # doesn't mean the GPU encoder can actually service that many
            # simultaneous sessions. video_export_max_parallel caps the
            # auto-resolved count at a conservative ceiling regardless of
            # what general resource detection suggests; an explicit
            # positive video_export_n_jobs value (a deliberate user choice)
            # is still honoured uncapped.
            _lv_raw_cfg = int(self._cfg.get("video_export_n_jobs", -1) or -1)
            if _lv_raw_cfg == -1:
                _lv_max_parallel = int(self._cfg.get("video_export_max_parallel", 4) or 4)
                if _lv_n_jobs < 0 or _lv_n_jobs > _lv_max_parallel:
                    self._log(f"  [VIDEO] auto-resolved {_lv_n_jobs if _lv_n_jobs > 0 else 'unbounded'} "
                              f"worker(s) capped to {_lv_max_parallel} (video_export_max_parallel "
                              f"-- GPU NVENC concurrent-session limit, not a CPU/RAM constraint)")
                    _lv_n_jobs = _lv_max_parallel
            self._log(f"  [VIDEO] Rendering {len(_labeled_video_tasks)} labeled "
                      f"video(s) ({_lv_n_jobs if _lv_n_jobs > 0 else 'auto'} worker(s))...")

            # Keypoint-dot overlay setup (labeled_video_keypoint_overlay,
            # 2026-08-31): computed ONCE here, outside the per-session loop
            # above, since bp_colors_bgr is a fixed mapping over _kp_bps
            # (this run's common bodypart schema, minus
            # SUPERANIMAL_QUADRUPED_EXCLUDED_BODYPARTS -- see _kp_keep_idx/
            # _kp_bps above, which xy/_ll_session were already sliced down to
            # when each task was appended), not per-session data.
            _kp_bgr = None
            if bool(self._cfg.get("labeled_video_keypoint_overlay", True)):
                try:
                    _kp_rgba = bodypart_rainbow_colors(_kp_bps)
                    _kp_bgr = [(round(_kp_rgba[bp][2] * 255),
                                round(_kp_rgba[bp][1] * 255),
                                round(_kp_rgba[bp][0] * 255)) for bp in _kp_bps]
                except Exception:
                    _kp_bgr = None
            _kp_dot_radius = int(self._cfg.get("labeled_video_keypoint_dot_radius", 3))
            _kp_ll_gate = float(self._cfg.get("likelihood_thresh", 0.3))
            # 2026-09-01 fix (real-data crash investigation -- see
            # _render_labeled_video_isolated()'s own docstring for the full
            # root-cause writeup): probe the NVENC encoder ONCE, here, in
            # this (parent/orchestrator) process, and pass the resolved
            # string into every isolated child below -- instead of letting
            # each of up to video_export_max_parallel concurrently-spawned
            # children independently re-probe NVENC (a real, transient GPU
            # encode session each time _VIDEO_ENCODER_CACHE starts empty in
            # a freshly-spawned process). Without this, real-data logs
            # showed all 21 labeled-video tasks each logging their own
            # encoder probe, silently allowing concurrent NVENC session
            # count to exceed video_export_max_parallel's own ceiling.
            _lv_encoder = _detect_video_encoder(_get_ffmpeg_exe(), log_fn=self._log)

            def _render_one_labeled_video(_task):
                _vp, _fl, _fps, _mask, _xy, _ll, _orig_vp = _task
                # _render_labeled_video_isolated runs create_labeled_video()
                # in its own OS process with retry -- a native crash there
                # can only kill that one isolated process, never this
                # orchestrator process, regardless of how many of these run
                # concurrently via the outer thread pool below. Returns the
                # resolved output path (str) on success, None on failure --
                # already logs its own WARNs.
                return _render_labeled_video_isolated(
                    _vp, self._out_videos, _fl, _fps,
                    output_fps=int(self._cfg["output_fps"]),
                    mask=_mask, log_fn=self._log,
                    pose_xy=_xy, pose_ll=_ll, bp_colors_bgr=_kp_bgr,
                    dot_radius=_kp_dot_radius, ll_gate=_kp_ll_gate,
                    encoder=_lv_encoder)

            if _lv_n_jobs != 1 and len(_labeled_video_tasks) > 1:
                try:
                    from joblib import Parallel, delayed
                    _lv_results = Parallel(n_jobs=_lv_n_jobs, prefer="threads")(
                        delayed(_render_one_labeled_video)(t) for t in _labeled_video_tasks)
                except Exception:
                    _lv_results = [_render_one_labeled_video(t) for t in _labeled_video_tasks]
            else:
                _lv_results = [_render_one_labeled_video(t) for t in _labeled_video_tasks]
            _lv_n_failed = sum(1 for r in _lv_results if not r)
            if _lv_n_failed:
                self._log(f"  [WARN] {_lv_n_failed}/{len(_lv_results)} labeled "
                          f"video(s) failed after retry (see per-video WARN "
                          f"lines above)")
            # {original raw vp: resolved labeled-video path} -- lets example
            # clips and the UMAP evolution video reuse this already-rendered
            # labeled video (banner/keypoints/turned-away banner burned in,
            # AND already smaller + lower-fps than the raw source) as their
            # own source, instead of re-decoding the raw video from scratch.
            # Built here (before the task list is cleared below), keyed by
            # each task's trailing original-vp field.
            # Keys normalized to str() -- `vp` may be a Path object here but
            # a plain string wherever it's looked up (e.g. all_vpaths casts
            # explicitly via str(_vp)); Path("x") and "x" are never equal/
            # same-hash as dict keys, so an un-normalized key would silently
            # never match at lookup time.
            _labeled_video_paths: dict = {
                str(_task[6]): _path for _task, _path in zip(_labeled_video_tasks, _lv_results)
                if _path
            }
            # Drop references to the (per-session, potentially large)
            # frame_labels/mask arrays now that every task has been
            # dispatched -- mirrors the DLC inference pipeline's own
            # between-camera gc.collect() convention (cube_3d_dlc.py Phase 2)
            # rather than leaving them pinned in _labeled_video_tasks for the
            # rest of this (potentially long) export step.
            _labeled_video_tasks.clear()
            gc.collect()
        else:
            _labeled_video_paths: dict = {}

        # Example clips — written in shuffled animal order so each cluster's
        # quota is filled from a random mix of animals rather than exhausted
        # by whichever animal happens to appear first.
        if _clip_tasks:
            import random as _random
            _random.shuffle(_clip_tasks)
            _clips_per_cluster: dict = {}
            _max_clips = int(self._cfg["max_clips_per_cluster"])
            # Limit each animal to ceil(max_clips / n_animals) clips per cluster
            # so the quota is spread across animals rather than filled by whichever
            # animal happens to appear first in the shuffled order.
            _max_per_call = -(_max_clips // -len(_clip_tasks))  # ceiling division
            _clip_output_fps = int(self._cfg["output_fps"])
            for _vp, _ep, _fps, _aid in _clip_tasks:
                # Reuse the already-rendered labeled video (banner/keypoints/
                # turned-away burned in, AND already smaller + lower-fps
                # than the raw source -- faster to decode) when one exists
                # for this session, instead of re-decoding the raw video.
                # start_frame/end_frame are raw-source-fps frame indices;
                # the labeled video kept only every `step`-th source frame
                # (create_labeled_video's own step = round(_fps/output_fps)),
                # so those columns must be rescaled to the labeled video's
                # OWN frame numbering -- start_sec/duration_sec (seconds,
                # not frame counts) need no change either way.
                _lv_path = _labeled_video_paths.get(str(_vp))
                if _lv_path:
                    _step = max(1, round(_fps / _clip_output_fps))
                    _ep = _ep.copy()
                    # The labeled video only KEPT every _step-th raw frame
                    # (indices 0, _step, 2*_step, ...) -- .round() can round
                    # end_frame UP to a kept frame past the bout's true end
                    # (or start_frame DOWN to one before its true start),
                    # landing on a frame that belongs to the adjacent bout,
                    # which can carry a different cluster label entirely.
                    # Confirmed on real data: a label-2 bout ending at raw
                    # frame 2711 rescaled (via round()) to labeled-frame 904
                    # = raw frame 2712, which is already label 1 -- and short
                    # bouts get looped to pad out the clip, so that one
                    # leaked frame repeated throughout the exported clip.
                    # ceil(start) / floor(end) guarantees every rescaled
                    # frame index's underlying raw frame stays inside
                    # [start_frame, end_frame] -- never spills into a
                    # neighboring bout.
                    _start_r = -(-_ep["start_frame"] // _step)   # ceil division
                    _end_r = _ep["end_frame"] // _step            # floor division
                    # Bout narrower than one labeled-video step (rare, <~100ms):
                    # ceil(start) can exceed floor(end), giving an empty range.
                    # Clamp so the clip still gets at least one valid frame
                    # rather than an inverted (end < start) range.
                    _end_r = _end_r.clip(lower=_start_r)
                    _ep["start_frame"] = _start_r.astype(int)
                    _ep["end_frame"] = _end_r.astype(int)
                    _src_vp, _src_fps = _lv_path, float(_clip_output_fps)
                else:
                    _src_vp, _src_fps = _vp, _fps
                try:
                    create_example_clips(
                        _src_vp, _ep, self._out_videos, _src_fps,
                        output_fps=_clip_output_fps,
                        max_clips=_max_clips,
                        animal_id=_aid,
                        # max_clip_dur_sec must match the GUI's own bout-duration
                        # ceiling (max_epoch_dur_s, the front-panel "max bout
                        # duration" field) -- epochs are already filtered to
                        # that ceiling by bouts_to_epochs(), so a smaller
                        # hardcoded default here would truncate valid, already-
                        # user-approved epochs instead of just capping runaway
                        # ones.
                        max_clip_dur_sec=float(self._cfg["max_epoch_dur_s"]),
                        clips_per_cluster=_clips_per_cluster,
                        max_per_call=_max_per_call,
                        # The labeled-video source already carries its own
                        # "C{lbl} / start-end" banner strip baked in -- drawing
                        # this function's own "Cluster N / t=.. dur=.." box on
                        # top of it would just duplicate the same information.
                        draw_banner=(_lv_path is None))
                except Exception:
                    self._log(f"  [WARN] Clips: {traceback.format_exc()}")

        # Combined epochs across all sessions. `all_epochs` being non-empty
        # only means at least one SESSION produced an epochs DataFrame --
        # every one of those can still be individually .empty (e.g. a
        # session with zero qualifying epochs/bouts), which the inner
        # `if not ep.empty` filter then strips to a fully empty list,
        # crashing pd.concat([]) with "No objects to concatenate". Filter
        # first, check the FILTERED result, matching the same "check what
        # you're about to consume, not merely its unfiltered container"
        # convention used elsewhere in this codebase.
        _epoch_frames = [ep.assign(session=n) for ep, n in all_epochs if not ep.empty]
        if _epoch_frames:
            combined = pd.concat(_epoch_frames, ignore_index=True)
            combined.to_csv(
                str(self.output_dir / "all_epochs_combined.csv"), index=False)

        # Per-cluster kinematic signatures (interpretable descriptors for naming).
        # Uses the turned-away DISPLAY labels (reserved id override applied),
        # built fresh here rather than reusing all_frame_labels (which stays
        # raw/unoverridden throughout — it already fed HMM training above,
        # and hmmlearn's CategoricalHMM would reject/corrupt on an id outside
        # its fitted n_clusters categories) so "Turned Away" gets its own row
        # in cluster_kinematics.csv rather than being folded into whatever
        # real cluster the MLP guessed for those bins.
        if all_frame_labels and all_xy:
            try:
                if _exclude_turned_away:
                    _kin_labels = []
                    for _ki, (_fl, _xy_k, _fps_k) in enumerate(
                            zip(all_frame_labels, all_xy, all_fps_list)):
                        _kin_ta_mask = (all_turned_away[_ki]
                                        if _ki < len(all_turned_away)
                                        else np.zeros(0, dtype=bool))
                        _kin_ta_frame_mask = _expand_bin_mask_to_frames(
                            _kin_ta_mask, _fps_k, _xy_k.shape[0])
                        _disp = _fl.copy()
                        if _kin_ta_frame_mask.any():
                            _n_copy_k = min(len(_disp), len(_kin_ta_frame_mask))
                            _disp[:_n_copy_k][_kin_ta_frame_mask[:_n_copy_k]] = int(n_cl)
                        _kin_labels.append(_disp)
                else:
                    _kin_labels = all_frame_labels
                compute_cluster_kinematics(
                    all_xy, _kin_labels, all_fps_list, bps_ref,
                    self.output_dir / "cluster_kinematics.csv")
                self._log("  [PLOT] cluster_kinematics.csv saved")
            except Exception:
                self._log(f"  [WARN] cluster_kinematics: "
                          f"{traceback.format_exc()}")

        # Sentinel-filtered (turned-away/low-quality dropped) copy of
        # all_epochs for PLOTS ONLY -- all_epochs itself is left untouched
        # since it also feeds all_epochs_combined.csv (a data export, out of
        # scope for this "no final plot should show turned-away/low-quality
        # points as real behaviour" fix -- see the per-session cluster_
        # durations/cluster_stats fix above for the same rationale).
        _all_epochs_plot = [(ep[ep["label"] < n_cl], nm) for ep, nm in all_epochs]

        if self._cfg["save_plots"] and all_frame_labels and all_xy and all_epochs:
            try:
                _cam_view = _camera_view_from_schema(bps_ref)
                _traj_bps = plot_cluster_trajectories(
                    all_xy, all_names, _all_epochs_plot, bps_ref,
                    self._out_plots / "cluster_trajectories_aligned.png",
                    is_3d=_is_3d, align_heading=True, camera_view=_cam_view,
                    all_ll=all_ll, cluster_names=_g_names)
                plot_cluster_trajectories(
                    all_xy, all_names, _all_epochs_plot, bps_ref,
                    self._out_plots / "cluster_trajectories_unaligned.png",
                    is_3d=_is_3d, align_heading=False, camera_view=_cam_view,
                    bodypart_subset=_traj_bps, all_ll=all_ll, cluster_names=_g_names)
                self._log("  [PLOT] cluster_trajectories_aligned.png / "
                          "cluster_trajectories_unaligned.png saved")
                if _g_groups:
                    # one panel per USER BEHAVIOUR (clusters of one behaviour pooled), plots/guided/
                    _gdir = self._out_plots / "guided" / "05_behaviour_trajectories"
                    _gdir.mkdir(parents=True, exist_ok=True)
                    _bid = {b: i for i, b in enumerate(sorted(_g_groups))}
                    _c2b = {c: _bid[b] for b, cl in _g_groups.items() for c in cl}
                    _ep_b = []
                    for _ep, _nm in _all_epochs_plot:
                        _e2 = _ep[_ep["label"].isin(list(_c2b))].copy()
                        _e2["label"] = _e2["label"].map(_c2b).astype(int)
                        _ep_b.append((_e2, _nm))
                    _bnm = {i: f"{b} ({len(_g_groups[b])} cluster{'s' if len(_g_groups[b]) > 1 else ''})"
                            for b, i in _bid.items()}
                    _bt = plot_cluster_trajectories(
                        all_xy, all_names, _ep_b, bps_ref, _gdir / "behaviour_trajectories_aligned.png",
                        is_3d=_is_3d, align_heading=True, camera_view=_cam_view, all_ll=all_ll,
                        cluster_names=_bnm)
                    plot_cluster_trajectories(
                        all_xy, all_names, _ep_b, bps_ref, _gdir / "behaviour_trajectories_unaligned.png",
                        is_3d=_is_3d, align_heading=False, camera_view=_cam_view, all_ll=all_ll,
                        bodypart_subset=_bt, cluster_names=_bnm)
                    self._log("  [PLOT] plots/guided/05_behaviour_trajectories/ saved")
            except Exception:
                self._log(f"  [WARN] cluster_trajectories: "
                          f"{traceback.format_exc()}")

            # SPLIT_ELIGIBILITY_IMPROVEMENT_PLAN.md technique 5 diagnostic
            # (export_posture_conservation_quadrant, default True): purely
            # additive/informational -- see plot_posture_conservation_vs_
            # convergence()'s own docstring. feats_sc/hdb_labels (NOT
            # hdb_labels_all -- same row-count rationale as the trajectory
            # plots just above) are still the training-set arrays this
            # point in run() already uses elsewhere.
            if bool(self._cfg.get("export_posture_conservation_quadrant", True)):
                try:
                    _pcq_scores = plot_posture_conservation_vs_convergence(
                        all_xy, all_names, _all_epochs_plot, bps_ref,
                        hdb_labels, feats_sc.T, fps, _win100,
                        self._out_plots / "posture_conservation_vs_convergence.png",
                        session_boundaries=_session_boundaries, is_3d=_is_3d,
                        camera_view=_camera_view_from_schema(bps_ref),
                        all_ll=all_ll, cluster_names=_g_names)
                    if _pcq_scores:
                        pd.DataFrame(
                            [{"cluster": cid, "postural_conservation": cons,
                              "dynamical_convergence": coh}
                             for cid, (cons, coh) in sorted(_pcq_scores.items())]
                        ).to_csv(self.output_dir / "posture_conservation_convergence.csv",
                                  index=False)
                        self._log("  [PLOT] posture_conservation_vs_convergence.png / "
                                  ".csv saved")
                except Exception:
                    self._log(f"  [WARN] posture_conservation_vs_convergence: "
                              f"{traceback.format_exc()}")

            try:
                # NOTE: must be `hdb_labels`, NOT `hdb_labels_all` -- feats_sc
                # here is the (n_features, n_samp) TRAINING-set array (n_samp
                # = however many bins HDBSCAN actually clustered, after any
                # train_frac subsampling and/or flat-held/turned-away
                # exclusion), while hdb_labels_all is expanded to the full
                # n_bins length (with -1 padding for every excluded/untrained
                # bin) a few hundred lines above. Passing hdb_labels_all here
                # made feats_sc.T's row count and the labels' length agree
                # only when nothing was ever excluded/subsampled -- otherwise
                # this function's own internal shape check
                # (`X.shape[0]==labels.shape[0]` / `X.shape[1]==...` /
                # `else: return`) silently no-ops with no exception and no
                # log line, which is why cluster_hierarchy_postures.png was
                # never actually produced. `hdb_labels` (used by the
                # sibling plot_cluster_hierarchy() dendrogram-only call just
                # above, which already works) is the one that actually
                # matches feats_sc's n_samp length.
                plot_cluster_hierarchy_with_postures(
                    feats_sc.T, hdb_labels, all_xy, all_names, _all_epochs_plot,
                    bps_ref, self._out_plots / "cluster_hierarchy_postures.png",
                    is_3d=_is_3d, all_ll=all_ll,
                    camera_view=_camera_view_from_schema(bps_ref),
                    linkage_method=str(self._cfg.get("cluster_hierarchy_linkage", "ward")),
                    cluster_names=_g_names)
                self._log("  [PLOT] cluster_hierarchy_postures.png saved")
            except Exception:
                self._log(f"  [WARN] cluster_hierarchy_postures: "
                          f"{traceback.format_exc()}")

        # Per-cluster confidence/visibility profile (issue 2) — flags clusters
        # that are mostly "animal turned away / occluded" rather than a real
        # behaviour, so they are not presented to the user as one.
        if vis_cat is not None:
            try:
                compute_cluster_confidence_profile(
                    vis_cat, _vis_col_names, hdb_labels_all,
                    self.output_dir / "cluster_confidence.csv")
                self._log("  [PLOT] cluster_confidence.csv saved")
            except Exception:
                self._log(f"  [WARN] cluster_confidence: "
                          f"{traceback.format_exc()}")

        # ── Consistent cluster set for all downstream plots ───────────────────
        # clusters_seen: cluster IDs actually predicted by the MLP across all
        # sessions that also have at least one epoch surviving the duration
        # filter.  Using this shared set for the 2-D UMAP, 3-D UMAP, and
        # dwell-time violin ensures all three plots show the same number of
        # clusters.
        clusters_seen = sorted(set(
            int(l)
            for ep, _ in all_epochs if not ep.empty
            for l in ep.label.unique()))
        # hdb_labels filtered to clusters_seen — bins whose cluster was not
        # observed in inference (or was entirely filtered by bout duration) are
        # treated as noise so the UMAP reflects the same active cluster set as
        # the dwell-time plot.  Fall back to all valid clusters when
        # clusters_seen is empty (e.g. duration filter rejects every bout).
        if clusters_seen:
            _active_set = set(clusters_seen)
            _hdb_labels_active = hdb_labels.copy()
            _hdb_labels_active[~np.isin(_hdb_labels_active,
                                        sorted(_active_set))] = -1
        else:
            _hdb_labels_active = hdb_labels.copy()

        # Turned-away-excluded sequences for transition-counting plots (same
        # rationale/mechanism as the HMM training segmentation above) --
        # transition_matrix.png and the umap_3d.html transition overlay must
        # not count a transition into/out of a turned-away frame. No-op when
        # exclude_turned_away=False.
        _transition_frame_labels = all_frame_labels
        if _exclude_turned_away and (all_turned_away or _auto_impure_ids) and all_frame_labels:
            _seg_trans = []
            for _hi in range(len(all_frame_labels)):
                _ta_frame_m = _ta_frame_mask_for(
                    _hi, all_fps_list[_hi], len(all_frame_labels[_hi]))
                # Auto-flagged impure clusters (see auto_flag_impure_clusters)
                # are just as behaviourally meaningless for transition
                # counting as confidence-based turned-away bins -- fold their
                # frames into the same exclusion mask so neither shows up as
                # a phantom source/target in transition_matrix.png or the
                # umap_3d.html transition overlay.
                if _auto_impure_ids:
                    _ta_frame_m = _ta_frame_m | np.isin(
                        all_frame_labels[_hi], sorted(_auto_impure_ids))
                _seg_trans.extend(
                    _mask_out_segments(all_frame_labels[_hi], _ta_frame_m))
            if _seg_trans:
                _transition_frame_labels = _seg_trans
            else:
                self._log("  [WARN] turned-away/impure-cluster exclusion left "
                          "no frames for transition-matrix/UMAP-transition "
                          "plots (entire dataset flagged?) -- falling back to "
                          "the unsegmented sequences.")

        if self._cfg["save_plots"] and all_frame_labels:
            try:
                plot_transition_matrix(
                    _transition_frame_labels,
                    self._out_plots / "transition_matrix.png")
            except Exception:
                self._log(f"  [WARN] transition_matrix: "
                          f"{traceback.format_exc()}")
            try:
                plot_umap(embedding, _hdb_labels_active,
                          self._out_plots / "umap_embedding.png")
            except Exception:
                self._log(f"  [WARN] umap_embedding: "
                          f"{traceback.format_exc()}")
            try:
                _tmat, _cids = _tmat_from_labels(_transition_frame_labels)
                plot_umap_3d_transitions(
                    embedding, _hdb_labels_active,
                    tmat=_tmat, cluster_ids=_cids,
                    out_path=self._out_plots / "umap_3d.html",
                    tag="clustering",
                )
            except Exception:
                self._log(f"  [WARN] umap_3d: {traceback.format_exc()}")

        # ── HMM diagnostic plots ──────────────────────────────────────────────
        if self._cfg["save_plots"] and all_hmm_labels:
            try:
                plot_duration_comparison(
                    np.concatenate(all_frame_labels),
                    np.concatenate(all_hmm_labels),
                    fps,
                    self._out_plots / "hmm_duration_comparison.png")
            except Exception:
                self._log(f"  [WARN] hmm_duration_comparison: "
                          f"{traceback.format_exc()}")
            try:
                plot_hmm_transition_matrix(
                    hmm_model,
                    self._out_plots / "hmm_transition_matrix.png")
            except Exception:
                self._log(f"  [WARN] hmm_transition_matrix: "
                          f"{traceback.format_exc()}")
            try:
                for _raw, _hmm_l, _name in zip(
                        all_frame_labels, all_hmm_labels, all_names):
                    plot_dual_ethogram(
                        _raw, _hmm_l, fps,
                        self._out_plots / f"hmm_ethogram_{_name}.png",
                        _name)
            except Exception:
                self._log(f"  [WARN] hmm_ethogram: "
                          f"{traceback.format_exc()}")
            try:
                plot_syntax_network(
                    hmm_model,
                    self._out_plots / "hmm_syntax_network.png",
                    min_prob=float(self._cfg.get("hmm_min_prob", 0.05)))
            except Exception:
                self._log(f"  [WARN] hmm_syntax_network: "
                          f"{traceback.format_exc()}")

        # ── kinetic-coherence (post-HMM) ────────────────────────────────────────
        # Phase 3, TRAJECTORY_SHAPE_AND_KINETIC_FLOW_PLAN.md — MOVED here from
        # the pre-MLP/pre-HMM call site above (see the NOTE left there). Now
        # scores the REAL post-HMM per-session DISPLAY labels
        # (all_hmm_display_labels / all_fps_list -- the exact arrays that
        # feed *_bout_lengths_hmm.csv / *_frame_labels_hmm.csv / the
        # ethograms / example clips), not the pre-HMM HDBSCAN training
        # partition, so kinetic_coherence.csv no longer overstates bout
        # recurrence for clusters the HMM later smooths away. Turned-away
        # (confidence-based) and auto-flagged-impure frames carry the
        # reserved n_cl / n_cl+1 sentinel ids in the display array -- those
        # are remapped to -1 (noise, excluded from the majority vote same as
        # real noise) before downsampling, so no final plot here ever scores
        # or reports a turned-away/low-quality point as if it were a real
        # behaviour cluster. Gated the same way the original call site was:
        # kinetic_coherence_enabled + the _bins_temporally_ordered guard
        # (computed once, earlier in run(), still in scope/unreassigned).
        if bool(self._cfg.get("kinetic_coherence_enabled", False)) and not _bins_temporally_ordered:
            self._log("  [WARN] kinetic_coherence_enabled is on but bins are "
                      "not verifiably temporally ordered this run (see the "
                      "WARN above) -- skipping kinetic_coherence.csv export "
                      "(a value would misleadingly look like a real score).")
        if (bool(self._cfg.get("kinetic_coherence_enabled", False)) and _bins_temporally_ordered
                and all_hmm_display_labels):
            try:
                # Downsample each session's post-HMM per-frame DISPLAY label
                # array back to 100-ms-bin resolution (majority vote, same
                # binning convention extract_features_v2/_3d use -- see
                # _downsample_frame_labels_to_bins), then concatenate in the
                # SAME session order session_bin_ranges.json/_sbr uses --
                # all_hmm_display_labels/all_fps_list already share that
                # order with all_names (same per-session loop, same append
                # order), so no re-sort is needed. Sentinel turned-away/
                # impure ids (>= n_cl) are remapped to -1 first so they're
                # excluded from the vote exactly like real noise, never
                # winning a bin or appearing as a "cluster" in the output.
                def _mask_sentinel_ids(_lab):
                    _lab = np.asarray(_lab).copy()
                    _lab[_lab >= int(n_cl)] = -1
                    return _lab

                _post_hmm_bins_by_session = [
                    _downsample_frame_labels_to_bins(_mask_sentinel_ids(_hl), _fps_s)
                    for _hl, _fps_s in zip(all_hmm_display_labels, all_fps_list)
                ]
                _post_hmm_bins_full = (
                    np.concatenate(_post_hmm_bins_by_session)
                    if _post_hmm_bins_by_session else np.zeros(0, dtype=int))
                # feats_sc.T / _session_boundaries describe the (possibly
                # train_frac-subsampled and/or flat-held/turned-away
                # -excluded) TRAINING subset of n_bins, in n_bins order.
                # `_keep` (computed once, earlier in run(), right alongside
                # _session_boundaries itself) is the boolean mask over the
                # full n_bins space marking exactly that subset. Subsetting
                # the full-length post-HMM array with the same mask keeps it
                # aligned 1:1 with feats_sc.T's rows / _session_boundaries'
                # ranges, exactly the way hdb_labels was.
                if _post_hmm_bins_full.shape[0] == n_bins:
                    _post_hmm_bins_for_kc = _post_hmm_bins_full[_keep]
                else:
                    # Length mismatch against n_bins (e.g. a session's frame
                    # count didn't reconstruct the expected bin count) --
                    # don't risk silently misaligning feats_sc.T's rows.
                    _post_hmm_bins_for_kc = None
                    self._log(
                        "  [WARN] post-HMM bin reconstruction length "
                        f"({_post_hmm_bins_full.shape[0]}) != n_bins "
                        f"({n_bins}) -- skipping post-HMM kinetic_coherence "
                        "export for this run.")
                if _post_hmm_bins_for_kc is not None:
                    _kc = _kinetic_coherence_score(
                        _post_hmm_bins_for_kc, feats_sc.T, fps, _win100,
                        session_boundaries=_session_boundaries,
                        min_epoch_dur_s=float(self._cfg.get("min_epoch_dur_s", 0.0) or 0.0))
                    if _kc["per_cluster"]:
                        _kc_rows = [
                            {"cluster_id": cid, **{k: v for k, v in d.items()}}
                            for cid, d in sorted(_kc["per_cluster"].items())
                        ]
                        pd.DataFrame(_kc_rows).to_csv(
                            str(self._out_model / "kinetic_coherence.csv"), index=False)
                        self._log(f"  [kinetic-coherence] (post-HMM) mean={_kc['whole_partition']['mean_coherence_score']:.3f} "
                                  f"eigengap={_kc['whole_partition']['eigengap']:.3f} "
                                  f"-> kinetic_coherence.csv")
                        if self._cfg.get("save_plots", True):
                            try:
                                plot_kinetic_coherence(
                                    _kc, self._out_plots / "kinetic_coherence.png")
                                self._log("  [PLOT] kinetic_coherence.png saved")
                            except Exception:
                                self._log(f"  [WARN] kinetic_coherence plot failed: "
                                          f"{traceback.format_exc()}")
            except Exception:
                self._log(f"  [WARN] kinetic-coherence (post-HMM) scoring failed: "
                          f"{traceback.format_exc()}")

        # ── Section 2: post-analysis publication plots ────────────────────────
        if self._cfg["save_plots"] and all_frame_labels:
            # Use the DISPLAY label arrays (turned-away / auto-flagged-impure
            # frames already carry their reserved n_cl/n_cl+1 sentinel ids),
            # same rationale as the post-HMM kinetic_coherence block above --
            # no final plot should show a turned-away/low-quality point as if
            # it were real behaviour. Sentinel ids are remapped to -1 here;
            # plot_sankey_sequences drops -1 (noise) frames before building
            # its bout sequences.
            if all_hmm_display_labels:
                _export_labels = [
                    np.where(np.asarray(_l) >= int(n_cl), -1, _l)
                    for _l in all_hmm_display_labels
                ]
            elif all_hmm_labels:
                _export_labels = list(all_hmm_labels)
            else:
                _export_labels = list(all_frame_labels)

            # Dwell-time violin plots. Filter empty per-session epoch frames
            # BEFORE checking whether anything survived to concat -- `all_
            # epochs` being non-empty only means at least one session
            # produced an epochs DataFrame, not that any of them are
            # non-empty (same guard-mismatch class as the all_epochs_
            # combined.csv export above); an all-empty filtered result is a
            # normal "no epochs this run" outcome, not an error worth a WARN.
            _dwell_ep_frames = [ep for ep, _ in _all_epochs_plot if not ep.empty]
            if _dwell_ep_frames:
                try:
                    _comb_ep = pd.concat(_dwell_ep_frames, ignore_index=True)
                    if not _comb_ep.empty:
                        plot_dwell_violin(
                            _comb_ep,
                            self._out_plots / "dwell_time_distributions.png")
                        self._log("  [PLOT] dwell_time_distributions.png saved")
                except Exception:
                    self._log(f"  [WARN] dwell_violin: {traceback.format_exc()}")

            # Sankey behavioral-sequence flow diagram. min_dur_s matches
            # the same user-set floor bouts_to_epochs() applies everywhere
            # else, so a sub-threshold flicker can't occupy its own step
            # here while being invisible from every other bout-based export.
            try:
                plot_sankey_sequences(
                    _export_labels,
                    self._out_plots / "sankey_sequences.png",
                    fps_list=all_fps_list,
                    min_dur_s=float(self._cfg.get("min_epoch_dur_s", 0.0) or 0.0))
                self._log("  [PLOT] sankey_sequences.png saved")
            except Exception:
                self._log(f"  [WARN] sankey_sequences: {traceback.format_exc()}")

            # Continuous state-space projection (UMAP embedding + trajectory)
            try:
                _tag0 = all_names[0] if all_names else ""
                plot_state_space_trajectory(
                    embedding,
                    _hdb_labels_active,
                    fps,
                    self._out_plots / "state_space_projection.png",
                    _tag0)
                self._log("  [PLOT] state_space_projection.png saved")
            except Exception:
                self._log(f"  [WARN] state_space_projection: "
                          f"{traceback.format_exc()}")

        # ── Auto-generate UMAP evolution videos ──────────────────────────────
        _n_ev = int(self._cfg.get("umap_evolution_n", 1))
        if _n_ev > 0:
            try:
                import random as _rnd_ev
                import pandas as _pd_ev
                # Group candidates by their input folder so EVERY uploaded folder
                # gets at least one evolution video (umap_evolution_n is applied
                # per folder, floored at 1).  Without this, a single random draw
                # could leave some folders with no video.
                _cand_by_group: dict = {}
                for _ei, (_nm, _vp) in enumerate(zip(all_names, all_vpaths)):
                    if not (_vp and Path(_vp).is_file()):
                        continue
                    if _ei >= len(frame_paths):
                        continue
                    _sbr_e = _sbr.get(_nm)
                    if not _sbr_e:
                        continue
                    _sb, _se = int(_sbr_e[0]), int(_sbr_e[1])
                    if _se > len(embedding):
                        continue
                    _grp = (all_groups[_ei] if _ei < len(all_groups) else "all")
                    _cand_by_group.setdefault(_grp, []).append(
                        (_nm, _ei, _sb, _se, Path(_vp)))
                if _cand_by_group:
                    _per_group = max(1, _n_ev)
                    _ev_chosen = []
                    for _grp, _cands in _cand_by_group.items():
                        _ev_chosen.extend(
                            _rnd_ev.sample(_cands, min(_per_group, len(_cands))))
                    self._log(
                        f"  [UMAP-EV] Exporting {len(_ev_chosen)} evolution "
                        f"video(s) across {len(_cand_by_group)} folder(s) "
                        f"({_per_group} per folder)...")
                    _ev_out = self.output_dir / "videos" / "umap_evolution"
                    _ev_out.mkdir(parents=True, exist_ok=True)
                    for _ev_nm, _ev_idx, _ev_sb, _ev_se, _ev_vp in _ev_chosen:
                        try:
                            # Prefer HMM-smoothed frame labels when available
                            _hmm_fl_p = (self._out_bouts /
                                         f"{_ev_nm}_frame_labels_hmm.csv")
                            _raw_fl_p = frame_paths[_ev_idx]
                            _fl_p = _hmm_fl_p if _hmm_fl_p.is_file() else _raw_fl_p
                            # These CSVs have a header (frame,time_s,label); read
                            # the 'label' column, not iloc[:,0] (the frame index,
                            # whose header row 'frame' breaks int conversion).
                            _fl_df  = _pd_ev.read_csv(str(_fl_p))
                            _fl_col = ("label" if "label" in _fl_df.columns
                                       else _fl_df.columns[-1])
                            _fl = (_pd_ev.to_numeric(_fl_df[_fl_col],
                                                     errors="coerce")
                                   .dropna().to_numpy(dtype=int))
                            self._log(
                                f"  [UMAP-EV] Rendering '{_ev_nm}' "
                                f"(side-by-side video — this can take 1-2 min)...")
                            # Reuse the already-rendered labeled video (banner/
                            # keypoints/turned-away burned in, AND already
                            # smaller + lower-fps -- faster to decode) for the
                            # left panel instead of the raw source. _fl is a
                            # full per-SOURCE-frame label array; the labeled
                            # video only kept every `step`-th source frame
                            # (create_labeled_video's own convention), so _fl
                            # must be resampled the same way, and the video's
                            # own OUTPUT fps (not the raw source fps) passed
                            # as source_fps for create_umap_evolution_video's
                            # own bin_stride math to stay correct.
                            _ev_session_fps = (all_fps_list[_ev_idx]
                                                if _ev_idx < len(all_fps_list) else fps)
                            _ev_output_fps = float(self._cfg.get("output_fps", 15))
                            _ev_lv_path = _labeled_video_paths.get(str(_ev_vp))
                            if _ev_lv_path:
                                _ev_step = max(1, round(_ev_session_fps / _ev_output_fps))
                                _ev_video_path, _ev_source_fps = _ev_lv_path, _ev_output_fps
                                _ev_fl = _fl[::_ev_step]
                            else:
                                _ev_video_path, _ev_source_fps = _ev_vp, fps
                                _ev_fl = _fl
                            _ev_result = create_umap_evolution_video(
                                video_path=_ev_video_path,
                                embedding=embedding[_ev_sb:_ev_se],
                                umap_labels=hdb_labels[_ev_sb:_ev_se],
                                frame_labels=_ev_fl,
                                source_fps=_ev_source_fps,
                                out_path=_ev_out / f"{_ev_nm}_umap_evolution.mp4",
                                output_fps=_ev_output_fps,
                                draw_cluster_overlay=not bool(_ev_lv_path),
                            )
                            if _ev_result:
                                self._log(
                                    f"  [UMAP-EV] Saved -> {_ev_result}")
                            else:
                                self._log(
                                    f"  [WARN] UMAP evolution video failed: "
                                    f"'{_ev_nm}'")
                        except Exception:
                            self._log(
                                f"  [WARN] UMAP evolution ({_ev_nm}): "
                                f"{traceback.format_exc()}")
                else:
                    self._log(
                        "  [UMAP-EV] Skipped: no sessions have associated "
                        "video files.")
            except Exception:
                self._log(
                    f"  [WARN] UMAP evolution video block: "
                    f"{traceback.format_exc()}")

        # Auto-groups (clusters_seen already computed above)
        groups = {f"C{c}": {"labels": [c], "color": _cmap(c)}
                  for c in clusters_seen}

        # ── Validation report ─────────────────────────────────────────────────
        all_warnings = [w for r in _validation.values()
                        for w in r.get("warnings", [])]
        any_block    = any(r.get("blocked", False)
                          for r in _validation.values())
        val_report   = dict(
            cube_version   = VERSION,
            analysis_version = ANALYSIS_VERSION,
            compat_mode    = self._cfg.get("compat_mode", "current"),
            created        = datetime.now().isoformat(),
            overall_status = "block" if any_block else
                             ("warn" if all_warnings else "pass"),
            stages         = _validation,
            all_warnings   = all_warnings,
        )
        # Region-aware refinement audit trail (Design decision 5): only
        # present when hdbscan_region_split_enabled=True -- absent entirely
        # otherwise, matching the "zero new surface for opted-out users"
        # contract every other opt-in feature in this pipeline follows.
        if _region_split_master:
            val_report["region_split"] = dict(
                enabled                 = True,
                clusters_created        = _region_split_clusters_created,
                raw_primary_sweep_n_cl  = _raw_primary_n_cl,
                post_refinement_n_cl    = _post_refine_n_cl,
                final_n_cl              = n_cl,
                preferred_clusters_range_original = [_orig_pref_lo, _orig_pref_hi],
                pre_reduction_pct       = _pre_reduction_pct,
            )
        (self.output_dir / "validation_report.json").write_text(
            json.dumps(val_report, indent=2))
        if self._cfg["save_plots"]:
            try:
                plot_validation_summary(
                    _validation,
                    self._out_plots / "validation_dashboard.png")
            except Exception:
                self._log(f"  [WARN] validation_dashboard: "
                          f"{traceback.format_exc()}")
        if any_block:
            self._log("\n  [!] VALIDATION BLOCKS DETECTED — see "
                      "validation_report.json")
        elif all_warnings:
            self._log(f"\n  [!] {len(all_warnings)} validation warning(s) — "
                      "see validation_report.json")
        else:
            self._log("\n  [✓] All validation gates passed.")

        # ── Publication benchmark metrics (Section 3.2) ───────────────────────
        _run_elapsed   = time.perf_counter() - _run_t0
        _peak_mem_gb   = _tm.get_traced_memory()[1] / 1e9
        _tm.stop()

        # Total video duration in minutes: sum of bins × 100 ms per bin.
        # all_frame_labels contains per-session HMM/MLP label arrays (1 per bin).
        _total_vid_min = None
        try:
            _total_bins    = sum(len(lbl) for lbl in all_frame_labels)
            _bin_sec       = 0.1   # 100-ms bins throughout CUBE
            _total_vid_min = (_total_bins * _bin_sec) / 60.0
        except Exception:
            pass
        _runtime_min = (_run_elapsed / 60.0) / max(1.0, _total_vid_min or 1.0)

        self._mem_checkpoint("run complete")
        _pub_metrics = dict(
            silhouette      = _validation.get("clustering",  {}).get("silhouette_score"),
            trustworthiness = _validation.get("umap_trustworthiness", {}).get("trustworthiness"),
            mean_ari        = _validation.get("cluster_stability", {}).get("mean_ari"),
            runtime_min     = round(_runtime_min, 4),
            # peak_memory_gb: tracemalloc-based, Python-heap allocations only.
            # peak_rss_gb: psutil-based process RSS, also covers numpy/BLAS/
            # native temporaries (the majority of real usage in this pipeline)
            # -- see _mem_checkpoint(). Both reported; neither replaces the other.
            peak_memory_gb  = round(_peak_mem_gb, 3),
            peak_rss_gb     = round(getattr(self, "_peak_rss_gb", 0.0), 3),
            total_runtime_s = round(_run_elapsed, 1),
            total_video_min = round(_total_vid_min, 2) if _total_vid_min else None,
        )
        self._log(f"\n  [Benchmark] Silhouette={_pub_metrics['silhouette']}  "
                  f"Trust={_pub_metrics['trustworthiness']}  "
                  f"ARI={_pub_metrics['mean_ari']}  "
                  f"Runtime={_pub_metrics['runtime_min']:.3f} min/min  "
                  f"RAM={_pub_metrics['peak_memory_gb']:.2f} GB "
                  f"(peak RSS {_pub_metrics['peak_rss_gb']:.2f} GB)")

        (self.output_dir / "publication_metrics.json").write_text(
            json.dumps(_pub_metrics, indent=2))

        if self._cfg["save_plots"]:
            try:
                plot_publication_metrics(
                    _pub_metrics,
                    self._out_plots / "publication_metrics.png")
            except Exception:
                self._log(f"  [WARN] publication_metrics plot: "
                          f"{traceback.format_exc()}")

        # ── Reorganize plots/ into topic subfolders ─────────────────────────
        # Runs after every plot above has been written, so nothing gets
        # sorted before it exists. Pure file-move, guarded by its own flag
        # (default on) and wrapped so a failure here never affects the run's
        # actual results -- see reorganize_plots_folder() for the layout.
        if self._cfg.get("organize_plots_enabled", True) and self._cfg["save_plots"]:
            try:
                reorganize_plots_folder(self._out_plots, logger=self._log)
            except Exception:
                self._log(f"  [WARN] reorganize_plots_folder failed: "
                          f"{traceback.format_exc()}")

        # ── Summary JSON ──────────────────────────────────────────────────────
        summary = dict(
            cube_version  = VERSION,
            pipeline      = "CUBE: Comprehensive Unsupervised Behavioral Explorer",
            created       = datetime.now().isoformat(),
            fps           = float(fps),
            n_sessions    = len(all_names),
            sessions      = all_names,
            n_clusters    = int(n_cl),
            clusters      = clusters_seen,
            # turned_away_cluster_id: the reserved display id (cube_core.py's
            # own "Turned Away" pseudo-cluster, see exclude_turned_away) used
            # in the exported bout/frame CSVs -- lets cube_analyser.py filter
            # it out of dwell-time/transition/reclustering analysis at load
            # time. None when exclude_turned_away=False (no reserved id used).
            turned_away_cluster_id = int(n_cl) if _exclude_turned_away else None,
            # impure_cluster_display_id: the SEPARATE reserved display id
            # (n_cl+1, distinct from turned_away_cluster_id) that
            # auto_flag_impure_clusters folds low-silhouette clusters into,
            # labeled "Low-Quality Cluster" rather than "Turned Away" -- kept
            # apart from genuine confidence-based turned-away frames since a
            # real, naturally-diverse behaviour with a mediocre silhouette
            # (e.g. rearing) is a different thing from the animal actually
            # being occluded/facing away, and conflating them under one name
            # misled a real read of the exported ethogram/video (see this
            # key's own [IMPURE] log line for each flagged cluster's
            # silhouette). None when the pass didn't fire this run (disabled,
            # no candidates, or exclude_turned_away=False).
            impure_cluster_display_id = (int(n_cl) + 1
                if (_exclude_turned_away and _auto_impure_ids) else None),
            # auto_flagged_impure_cluster_ids: real HDBSCAN/consensus cluster
            # ids (in the pre-remap id space) that auto_flag_impure_clusters
            # folded into impure_cluster_display_id this run -- see the
            # [IMPURE] log line for each one's silhouette. Empty list when
            # the pass didn't fire (disabled, no candidates, or the "don't
            # leave <2 real clusters" guard tripped). Recorded here (not just
            # logged) since the decision isn't reproducible from the saved
            # model alone -- predict_from_saved_model() does NOT re-derive or
            # re-apply it for later inference-only runs.
            auto_flagged_impure_cluster_ids = sorted(int(c) for c in _auto_impure_ids),
            cv_accuracy   = float(cv_scores.mean()) if mlp_clf else None,
            cfg           = self._cfg,
            # guided labelling provenance: ONLY present when a labels context was active (blind runs unchanged)
            **({"guided_labels": {
                    "path": str(self._cfg.get("guided_labels_path", "")),
                    "n_labelled_training_rows": int(self._guided_ctx.n_labelled),
                    "behaviours": self._guided_ctx.behaviour_counts(),
                    "constraint_actions": len(self._guided_ctx.actions)}}
               if getattr(self, "_guided_ctx", None) is not None else {}),
            output_dir    = str(self.output_dir),
            bout_lengths  = [str(p) for p in bout_paths],
            frame_labels  = [str(p) for p in frame_paths],
            model         = str(model_path),
            feature_version = "v2",
            validation    = val_report["overall_status"],
            benchmark     = _pub_metrics,
        )
        (self.output_dir / "bsoid_run_summary.json").write_text(
            json.dumps(summary, indent=2))
        if getattr(self, "_guided_ctx", None) is not None:           # audit trail of every constraint action
            try:
                (self._out_model / "guided_constraints_log.json").write_text(
                    json.dumps(self._guided_ctx.actions, indent=2, default=str))
                self._log(f"  [GUIDED] {len(self._guided_ctx.actions)} constraint action(s) -> "
                          f"model/guided_constraints_log.json")
            except Exception:
                self._log("  [WARN] guided_constraints_log.json export failed")
        if getattr(self, "_guided_ctx", None) is not None and _g_groups:
            try:
                from cube_guided_report import write_mapping_tsv as _wm, write_behaviour_groups_json as _wg
                _wm(self.output_dir / "cluster_behaviour_mapping.tsv", hdb_labels, _g_groups)
                _wg(self.output_dir / "behaviour_groups.json", _g_groups,
                    {"source": "user labels", "labels_path": str(self._cfg.get("guided_labels_path", ""))})
                self._log(f"  [GUIDED] {len(_g_groups)} behaviour group(s) -> cluster_behaviour_mapping.tsv + "
                          f"behaviour_groups.json (the Behaviour Analyser uses these)")
            except Exception as _gm_e:
                self._log(f"  [WARN] guided behaviour-group export failed ({_gm_e})")
        if (getattr(self, "_guided_ctx", None) is not None and getattr(self, "_guided_preloaded", None)
                and bool(self._cfg.get("guided_behaviour_export_enabled", True))
                and (all_hmm_display_labels or all_frame_labels)):
            try:
                self._stage("7/7 ? Guided behaviours", "classifying your behaviours directly from your labels?")
                import cube_guided_behaviour as _gb
                _X_all = np.nan_to_num(scaler.transform(np.asarray(feats_cat).T)).astype(np.float32)
                _rng_g = {k: (int(v[0]), int(v[1])) for k, v in _sbr.items() if k != "_total_bins"}
                _fps_g = {nm: float(fp_) for nm, fp_ in zip(all_names, all_fps_list)}
                _gres = _gb.build_guided_behaviours(
                    _X_all, _rng_g, _fps_g, self._guided_preloaded[1],
                    {nm: np.asarray(l) for nm, l in zip(all_names, (all_hmm_display_labels or all_frame_labels))},
                    {nm: len(l) for nm, l in zip(all_names, (all_hmm_display_labels or all_frame_labels))},
                    self.output_dir.parent / "CUBE 3b - Guided behaviours",
                    stems=_gb.stems_for(self.output_dir / "bout_lengths", all_names),
                    embedding=embedding_save, reserved_ids=[int(n_cl), int(n_cl) + 1], source_run=self.output_dir,
                    min_conf=float(self._cfg.get("guided_behaviour_min_confidence", 0.5)), log=self._log,
                    cluster_gate=bool(self._cfg.get("guided_cluster_gate_enabled", False)),
                    gate_strength=float(self._cfg.get("guided_cluster_gate_strength", 1.0)),
                    gate_prior=float(self._cfg.get("guided_cluster_gate_prior", 5.0)))
                self._log(f"  [GUIDED] guided behaviours -> {self.output_dir.parent / 'CUBE 3b - Guided behaviours'} "
                          f"({len(_gres['groups'])} behaviour(s), "
                          f"{sum(len(c) for c in _gres['groups'].values())} sub-type cluster(s)); the Behaviour "
                          f"Analyser can be pointed at that folder")
            except Exception as _gb_e:
                self._log(f"  [GUIDED] WARN: guided-behaviour export skipped ({_gb_e})")
        if getattr(self, "_guided_dyn_pack", None) and all_hmm_labels:
            try:
                from cube_guided_dynamics import engine_audit as _g_audit
                _ranges_g = {k: v for k, v in _sbr.items() if k != "_total_bins"}
                _rep_g = _g_audit(self._guided_dyn_pack, all_hmm_labels, all_fps_list, all_names, _ranges_g, feats_cat)
                (self._out_model / "guided_dynamics.json").write_text(json.dumps(_rep_g, indent=2, default=str))
                self._log("  [GUIDED] label dynamics audit -> model/guided_dynamics.json")
            except Exception as _g_e:
                self._log(f"  [WARN] guided_dynamics.json export failed ({_g_e})")

        # Delete labeled_videos/ folder — these full-session labeled videos are
        # large and not needed after example clips have been created.
        if bool(self._cfg.get("delete_labeled_videos", True)):
            _lv_dir = self._out_videos / "labeled_videos"
            if _lv_dir.exists():
                try:
                    shutil.rmtree(str(_lv_dir))
                    self._log(f"  [cleanup] Deleted labeled_videos/ folder")
                except Exception as _lv_e:
                    self._log(f"  [cleanup] Could not delete labeled_videos/: {_lv_e}")

        self._log("\n" + "=" * 64)
        self._log(f"  Done!  {n_cl} clusters  |  {len(all_names)} session(s)")
        self._log(f"  Output -> {self.output_dir}")
        self._log("=" * 64 + "\n")
        self._stage("Done",
                    f"{n_cl} clusters · {len(all_names)} session(s) · "
                    f"CV={cv_scores.mean():.3f} · "
                    f"validation={val_report.get('overall_status','?')}")

        # ── Phase-timing summary (2026-08-31) ────────────────────────────────
        # Close out whichever phase was still open when "Done" fired above
        # (every OTHER phase already closed itself out via the next
        # differently-named _stage() call), then log + export a sorted
        # summary -- a permanent, always-on diagnostic for finding which
        # phase of a real run is actually slow, not a one-off for this
        # session's video-export investigation.
        _cur = self._phase_timings_cur
        if _cur["name"] is not None:
            self._phase_timings.append(
                {"phase": _cur["name"], "duration_s": round(time.time() - _cur["t0"], 2)})
        if self._phase_timings:
            _total_s = sum(p["duration_s"] for p in self._phase_timings)
            self._log("\n[PHASE TIMINGS] (sorted slowest first)")
            for _p in sorted(self._phase_timings, key=lambda p: -p["duration_s"]):
                _pct = 100.0 * _p["duration_s"] / _total_s if _total_s > 0 else 0.0
                self._log(f"    {_p['duration_s']:>8.1f}s  ({_pct:4.1f}%)  {_p['phase']}")
            self._log(f"    {'-' * 40}")
            self._log(f"    {_total_s:>8.1f}s  (100.0%)  TOTAL (sum of phases)")
            try:
                (self._out_model / "phase_timings.json").write_text(
                    json.dumps({"phases": self._phase_timings, "total_s": round(_total_s, 2)},
                               indent=2))
            except Exception:
                self._log(f"  [WARN] phase_timings.json export failed: "
                          f"{traceback.format_exc()}")

        return dict(
            bout_lengths_paths = bout_paths,
            frame_label_paths  = frame_paths,
            groups             = groups,
            model_path         = model_path,
            output_dir         = self.output_dir,
            n_clusters         = int(n_cl),
            summary            = summary,
            validation         = val_report,
        )

    #   re-use saved model  

    @classmethod
    def predict_from_saved_model(cls,
                                  model_path,
                                  csv_folder,
                                  video_folder=None,
                                  output_dir="bsoid_predict",
                                  logger=None) -> dict:
        """Load a pkl and predict on new DLC files without retraining."""
        log = logger or print
        log(f"Loading model: {model_path}")
        with open(str(model_path), "rb") as fh:
            m = pickle.load(fh)
        engine = cls(csv_folder=csv_folder, video_folder=video_folder,
                     output_dir=output_dir, fps=m["fps"],
                     logger=logger, cfg=m["cfg"])
        dlc_files = find_dlc_files(csv_folder)
        vid_dict  = find_videos(video_folder) if video_folder else {}
        pairs     = pair_files(dlc_files, vid_dict)
        umap_m, mlp_m, scaler = m["umap_model"], m["mlp_clf"], m["scaler"]
        fps = float(m["fps"])
        bout_paths, frame_paths = [], []
        for fp, vp in pairs:
            try:
                # return_quality=True so the raw per-frame likelihood array
                # (ll) is available for the visibility feature block below —
                # REQUIRED for train/inference symmetry since
                # visibility_features_enabled defaults to True, so most saved
                # models were trained with the visibility block folded into
                # their expected feature layout.
                xy, _, _, _, _, _ll = load_dlc_file(
                    fp, m["cfg"]["likelihood_thresh"], return_quality=True)
                xy = smooth_boxcar(xy, fps, m["cfg"]["boxcar_win_sec"])
            except Exception:
                log(f"  [WARN] Skip {fp.name}: {traceback.format_exc()}")
                continue
            # Pass the saved feature-construction settings so inference features
            # match those the model was trained on.  Older pkls may lack some
            # keys; .get() defaults reproduce their original behaviour.
            _mcfg = m.get("cfg", {}) or {}
            fl    = predict_labels(
                xy, umap_m, mlp_m, scaler, fps,
                bodyparts=m.get("bodyparts"),
                body_normalise=bool(_mcfg.get("body_normalise", False)),
                pca_model=m.get("pca_model"),
                min_confidence=float(_mcfg.get("mlp_confidence_thresh", 0.0)),
                angular_fallback=bool(_mcfg.get("angular_fallback", True)),
                long_lag_drift=bool(_mcfg.get("long_lag_drift", False)),
                long_scale_bins=bool(_mcfg.get("long_scale_bins", False)),
                bodypart_weights=_mcfg.get("bodypart_weights") or None,
                ll=_ll,
                visibility_features_enabled=bool(
                    _mcfg.get("visibility_features_enabled", True)),
                visibility_adaptive_pct=float(
                    _mcfg.get("visibility_adaptive_pct", 10)),
                visibility_feature_weight=float(
                    _mcfg.get("visibility_feature_weight", 1.0)),
                face_limb_proximity_feature_weight=float(
                    _mcfg.get("face_limb_proximity_feature_weight", 1.0)),
                isolated_limb_feature_weight=float(
                    _mcfg.get("isolated_limb_feature_weight", 1.0)),
                likelihood_thresh=float(m["cfg"]["likelihood_thresh"]),
                floor_features_enabled=bool(_mcfg.get("paw_floor_features_enabled", False)),
                behavior_indicators_enabled=bool(_mcfg.get("behavior_indicators_enabled", True)),
                # turned_away_conf_thresh/min_window_s .get() fallbacks stay at
                # the v3 values (0.30/0.4) -- for a model saved before v4
                # (2026-09-18) that never wrote these keys, that reproduces
                # what training actually used. turned_away_adaptive_pct is a
                # brand-new key with no v3 equivalent, so its fallback is the
                # v4 default (no old value to preserve). Note: the DETECTOR
                # ALGORITHM itself (detect_turned_away_bins) changed
                # unconditionally in v4 regardless of these cfg values -- see
                # that function's docstring; a pre-v4 saved model's inference-
                # time turned-away mask can therefore differ slightly from
                # what training saw, a narrow train/inference desync accepted
                # for this upgrade (only affects the floor-referenced block's
                # isolated-limb columns, itself off by default pre-v4).
                turned_away_conf_thresh=float(_mcfg.get("turned_away_conf_thresh", 0.30)),
                turned_away_adaptive_pct=float(_mcfg.get("turned_away_adaptive_pct", 30.0)),
                turned_away_min_window_s=float(_mcfg.get("turned_away_min_window_s", 0.4)),
                turned_away_merge_gap_s=float(_mcfg.get("turned_away_merge_gap_s", 0.5)),
                lr_symmetrize_features_enabled=bool(
                    _mcfg.get("lr_symmetrize_features_enabled", True)),
                withinbin_variance_rotation_invariant=bool(
                    _mcfg.get("withinbin_variance_rotation_invariant", True)),
                egocentric_alignment_enabled=bool(
                    _mcfg.get("egocentric_alignment_enabled", False)),
                egocentric_alignment_pca_dims=int(
                    _mcfg.get("egocentric_alignment_pca_dims", 10) or 10))
            bd    = labels_to_bouts(fl)
            bp    = engine._out_bouts / f"{fp.stem}_bout_lengths.csv"
            bd.to_csv(str(bp), index=False)
            bout_paths.append(bp)
            # v6 K2 sidecar consistency: this path has no _hmm bout variant
            # at all (predict_from_saved_model skips HMM smoothing), so the
            # enriched sidecar pairs with the raw bout CSV above --
            # "<stem>_bout_lengths_enriched.csv", not "..._hmm_enriched.csv".
            _bd_enriched = None
            if bool(_mcfg.get("kinematic_directedness_enabled", False)):
                try:
                    _centroid_xy = np.column_stack([
                        xy[:, 0::2].mean(axis=1), xy[:, 1::2].mean(axis=1)])
                    _bd_enriched = compute_bout_directedness(bd, _centroid_xy, fps)
                except Exception:
                    log(f"  [WARN] kinematic directedness sidecar "
                        f"({fp.stem}): {traceback.format_exc()}")
                    _bd_enriched = None
            # v6 part 2 consistency (Environmental_Context_v6_Implementation
            # _Plan.md Step 6): same "<stem>_bout_lengths_enriched.csv" pairing
            # rule as above -- reads the SAVED model's own env_features_enabled/
            # env_arena_cfg (_mcfg), not any fresh cfg passed to this call.
            if bool(_mcfg.get("env_features_enabled", False)) and _mcfg.get("env_arena_cfg"):
                try:
                    _env_sec = compute_session_env_context(
                        _mcfg.get("env_arena_cfg"), fp.stem,
                        xy[:, 0::2], xy[:, 1::2], m.get("bodyparts") or [], fps,
                        interaction_threshold=_mcfg.get("env_interaction_threshold"))
                    _env_pb = _env_sec.get("per_bin") or {}
                    if _env_pb:
                        _thresh = float((_env_sec.get("summary") or {}).get(
                            "interaction_threshold_px", 0.0))
                        _win_bin = max(1, int(round(
                            fps * (_env_sec.get("bin_ms", 100.0) / 1000.0))))
                        _src, _agg, _names_out = {}, {}, {}
                        _cur_region = np.array(_env_pb.get("current_region") or [], dtype=object)
                        for _rn in sorted(((_env_sec.get("summary") or {})
                                           .get("time_in_region_sec") or {}).keys()):
                            _k = f"region__{_rn}"
                            _src[_k] = (_cur_region == _rn).astype(float)
                            _agg[_k] = np.nanmean
                            _names_out[_k] = f"pct_time_in_region_{_rn}"
                        _nose_d = _env_pb.get("dist_to_nearest_object_nose") or {}
                        _paw_d  = _env_pb.get("dist_to_nearest_object_paw") or {}
                        for _on in _nose_d.keys():
                            _nd = np.array(_nose_d.get(_on, []), dtype=float)
                            _pd_ = np.array(_paw_d.get(_on, []), dtype=float)
                            if _nd.size and _pd_.size:
                                _k = f"objcontact__{_on}"
                                _src[_k] = ((_nd <= _thresh) | (_pd_ <= _thresh)).astype(float)
                                _agg[_k] = np.nanmean
                                _names_out[_k] = f"pct_time_near_object_{_on}"
                        for _on, _hseries in (_env_pb.get(
                                "heading_angle_to_nearest_object") or {}).items():
                            _k = f"heading__{_on}"
                            _src[_k] = np.array(_hseries, dtype=float)
                            _agg[_k] = np.nanmean
                            _names_out[_k] = f"mean_heading_angle_to_object_{_on}"
                        if _src:
                            _base_df = _bd_enriched if _bd_enriched is not None else bd
                            _bd_enriched = enrich_bouts_from_bin_source(
                                _base_df, _src, bin_offset=0, win=_win_bin,
                                agg_fns=_agg, out_col_names=_names_out)
                except Exception:
                    log(f"  [WARN] environmental-context bout enrichment "
                        f"({fp.stem}): {traceback.format_exc()}")
            if _bd_enriched is not None:
                _bd_enriched.to_csv(
                    str(engine._out_bouts / f"{fp.stem}_bout_lengths_enriched.csv"),
                    index=False)
            fd    = pd.DataFrame({"frame": np.arange(len(fl)),
                                  "time_s": np.arange(len(fl)) / fps,
                                  "label": fl})
            fp2   = engine._out_bouts / f"{fp.stem}_frame_labels.csv"
            fd.to_csv(str(fp2), index=False)
            frame_paths.append(fp2)
        return dict(bout_lengths_paths=bout_paths,
                    frame_label_paths=frame_paths,
                    output_dir=engine.output_dir)
